INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Galaxy-Dawn/claude-scholar/Command Development', 'community', 'Galaxy-Dawn', 'claude-scholar', 'Galaxy-Dawn/claude-scholar', 'Command Development', 0, 0, 60, '2026-02-20T04:13:19.578Z', '2026-02-20T04:53:08.032Z', '76014a8e26c35b0f9396ec4ba7531526259d24f5afff13553365a1c5cb03f447', '{"id":"Galaxy-Dawn/claude-scholar/Command Development","name":"Command Development","description":{"zh":"命令开发是 Claude Code 的一个综合配置，用于简化数据科学、AI 研究和学术写作工作流程","ja":"コマンド開発は、データサイエンス、AI 研究、学術論文のワークフローを最適化するための Claude Code 構成です","ko":"명령 개발은 데이터 과학, AI 연구, 학술 저술의 워크플ロー를 간소화하기 위한 Claude Code 구성입니다","es":"El desarrollo de comandos para Claude Code permite crear flujos de trabajo personalizados para la investigación y el desarrollo de IA.","fr":"Le développement de commandes pour Claude Code permet de créer des flux de travail personnalisés pour la recherche et le développement de l''IA.","de":"Die Befehlsentwicklung für Claude Code ermöglicht die Erstellung benutzerdefinierter Workflows für die Forschung und die Entwicklung von KI.","pt":"O desenvolvimento de comandos para Claude Code permite criar fluxos de trabalho personalizados para pesquisa e publicação","ru":"Разработка команд для Claude Code позволяет создавать пользовательские рабочие процессы для исследований и публикаций","ar":"تطوير الأوامر ل Claude Code يسمح بإنشاء سير عمل مخصصة للبحث والنشر","en":"A comprehensive Claude Code configuration for data science, AI research, and academic writing. Streamline the complete research workflow—from idea to publication."},"seo":{"title":{"zh":"命令开发 - Claude Code 配置指南","ja":"コマンド開発 - Claude Code 構成ガイド","ko":"명령 개발 - Claude Code 구성 가이드","es":"Desarrollo de Comandos para Claude Code","fr":"Développement de Commandes pour Claude Code","de":"Befehlsentwicklung für Claude Code","pt":"Desenvolvimento de Comandos para Claude Code","ru":"Разработка Команд для Claude Code","ar":"تطوير أوامر ل Claude Code","en":"Command Development"},"description":{"zh":"命令开发是 Claude Code 的一个综合配置，用于简化数据科学、AI 研究和学术写作工作流程","ja":"コマンド開発は、データサイエンス、AI 研究、学術論文のワークフローを最適化するための Claude Code 構成です","ko":"명령 개발은 데이터 과학, AI 연구, 학술 저술의 워크플ロー를 간소화하기 위한 Claude Code 구성입니다","es":"El desarrollo de comandos para Claude Code permite crear flujos de trabajo personalizados para la investigación y el desarrollo de IA.","fr":"Le développement de commandes pour Claude Code permet de créer des flux de travail personnalisés pour la recherche et le développement de l''IA.","de":"Die Befehlsentwicklung für Claude Code ermöglicht die Erstellung benutzerdefinierter Workflows für die Forschung und die Entwicklung von KI.","pt":"O desenvolvimento de comandos para Claude Code permite criar fluxos de trabalho personalizados para pesquisa e publicação","ru":"Разработка команд для Claude Code позволяет создавать пользовательские рабочие процессы для исследований и публикаций","ar":"تطوير الأوامر ل Claude Code يسمح بإنشاء سير عمل مخصصة للبحث والنشر","en":"A comprehensive Claude Code configuration for data science, AI research, and academic writing. Streamline the complete research workflow—from idea to publica..."},"definition":{"en":"A comprehensive Claude Code configuration for data science, AI research, and academic writing. Streamline the complete research workflow—from idea to publication."},"features":{"zh":["Markdown 文件格式","YAML 前置内容配置","动态参数和文件引用","Bash 执行上下文","命令组织和命名空间"],"ja":["Markdown ファイル形式","YAML フロントマター構成","動的引数とファイル参照","Bash 実行コンテキスト","コマンド組織とネームスペース"],"ko":["Markdown 파일 형식","YAML 프론트매터 구성","동적 인수 및 파일 참조","Bash 실행 컨텍스트","명령 구성 및 네임스페이스"],"es":["Creación de comandos personalizados","Uso de archivos Markdown para definir comandos","Opciones de configuración con YAML","Argumentos dinámicos y referencias de archivos","Ejecución de Bash para contexto"],"fr":["Création de commandes personnalisées","Utilisation de fichiers Markdown pour définir des commandes","Options de configuration avec YAML","Arguments dynamiques et références de fichiers","Exécution de Bash pour le contexte"],"de":["Erstellung benutzerdefinierter Befehle","Verwendung von Markdown-Dateien zur Definition von Befehlen","KonfigurationsOptionen mit YAML","Dynamische Argumente und Dateireferenzen","Bash-Ausführung für Kontext"],"pt":["Criação de comandos personalizados como arquivos Markdown","Configuração de metadados com YAML frontmatter","Uso de argumentos dinâmicos e referências de arquivos","Execução de comandos Bash para contexto","Organização e namespace de comandos"],"ru":["Создание пользовательских команд как файлов Markdown","Настройка метаданных с помощью YAML frontmatter","Использование динамических аргументов и ссылок на файлы","Выполнение команд Bash для контекста","Организация и пространство имен команд"],"ar":["إنشاء أوامر مخصصة كملفات Markdown","تكوين البيانات الوصفية باستخدام YAML frontmatter","استخدام الحجج الديناميكية ومراجع الملفات","تنفيذ أوامر Bash للسياق","تنظيم الأوامر وتسمية النطاق"]},"keywords":{"zh":["Claude Code","命令开发","数据科学","AI 研究","学术写作","Markdown","YAML","Bash"],"ja":["Claude Code","コマンド開発","データサイエンス","AI 研究","学術論文","Markdown","YAML","Bash"],"ko":["Claude Code","명령 개발","데이터 과학","AI 연구","학술 저술","Markdown","YAML","Bash"],"es":["desarrollo de comandos","Claude Code","investigación de IA","escritura académica","flujos de trabajo personalizados","Markdown","YAML","Bash"],"fr":["développement de commandes","Claude Code","recherche en IA","écriture académique","flux de travail personnalisés","Markdown","YAML","Bash"],"de":["Befehlsentwicklung","Claude Code","KI-Forschung","akademisches Schreiben","benutzerdefinierte Workflows","Markdown","YAML","Bash"],"pt":["desenvolvimento de comandos","Claude Code","fluxo de trabalho personalizado","pesquisa e publicação","comandos personalizados","Markdown","YAML frontmatter","argumentos dinâmicos"],"ru":["разработка команд","Claude Code","пользовательский рабочий процесс","исследования и публикации","пользовательские команды","Markdown","YAML frontmatter","динамические аргументы"],"ar":["تطوير الأوامر","Claude Code","سير عمل مخصص","بحث ونشر","أوامر مخصصة","Markdown","YAML frontmatter","حجج ديناميكية"]}},"owner":"Galaxy-Dawn","repo":"claude-scholar","repoPath":"Galaxy-Dawn/claude-scholar","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"Command Development","description":"This skill should be used when the user asks to create a slash command, add a command, write a custom command, define command arguments, use command frontmatter, organize commands, create command with file references, interactive command, use AskUserQuestion in command, or needs guidance on slash command structure, YAML frontmatter fields, dynamic arguments, bash execution in commands, user interaction patterns, or command development best practices for Claude Code.","version":"0.2.0","bodyPreview":"# Command Development for Claude Code\n\n## Overview\n\nSlash commands are frequently-used prompts defined as Markdown files that Claude executes during interactive sessions. Understanding command structure, frontmatter options, and dynamic features enables creating powerful, reusable workflows.\n\n**Key concepts:**\n- Markdown file format for commands\n- YAML frontmatter for configuration\n- Dynamic arguments and file references\n- Bash execution for context\n- Command organization and namespacing\n\n## Com","body":"# Command Development for Claude Code\n\n## Overview\n\nSlash commands are frequently-used prompts defined as Markdown files that Claude executes during interactive sessions. Understanding command structure, frontmatter options, and dynamic features enables creating powerful, reusable workflows.\n\n**Key concepts:**\n- Markdown file format for commands\n- YAML frontmatter for configuration\n- Dynamic arguments and file references\n- Bash execution for context\n- Command organization and namespacing\n\n## Command Basics\n\n### What is a Slash Command?\n\nA slash command is a Markdown file containing a prompt that Claude executes when invoked. Commands provide:\n- **Reusability**: Define once, use repeatedly\n- **Consistency**: Standardize common workflows\n- **Sharing**: Distribute across team or projects\n- **Efficiency**: Quick access to complex prompts\n\n### Critical: Commands are Instructions FOR Claude\n\n**Commands are written for agent consumption, not human consumption.**\n\nWhen a user invokes `/command-name`, the command content becomes Claude''s instructions. Write commands as directives TO Claude about what to do, not as messages TO the user.\n\n**Correct approach (instructions for Claude):**\n```markdown\nReview this code for security vulnerabilities including:\n- SQL injection\n- XSS attacks\n- Authentication issues\n\nProvide specific line numbers and severity ratings.\n```\n\n**Incorrect approach (messages to user):**\n```markdown\nThis command will review your code for security issues.\nYou''ll receive a report with vulnerability details.\n```\n\nThe first example tells Claude what to do. The second tells the user what will happen but doesn''t instruct Claude. Always use the first approach.\n\n### Command Locations\n\n**Project commands** (shared with team):\n- Location: `.claude/commands/`\n- Scope: Available in specific project\n- Label: Shown as \"(project)\" in `/help`\n- Use for: Team workflows, project-specific tasks\n\n**Personal commands** (available everywhere):\n- Location: `~/.claude/commands/`\n- Scope: Available in all projects\n- Label: Shown as \"(user)\" in `/help`\n- Use for: Personal workflows, cross-project utilities\n\n**Plugin commands** (bundled with plugins):\n- Location: `plugin-name/commands/`\n- Scope: Available when plugin installed\n- Label: Shown as \"(plugin-name)\" in `/help`\n- Use for: Plugin-specific functionality\n\n## File Format\n\n### Basic Structure\n\nCommands are Markdown files with `.md` extension:\n\n```\n.claude/commands/\n├── review.md           # /review command\n├── test.md             # /test command\n└── deploy.md           # /deploy command\n```\n\n**Simple command:**\n```markdown\nReview this code for security vulnerabilities including:\n- SQL injection\n- XSS attacks\n- Authentication bypass\n- Insecure data handling\n```\n\nNo frontmatter needed for basic commands.\n\n### With YAML Frontmatter\n\nAdd configuration using YAML frontmatter:\n\n```markdown\n---\ndescription: Review code for security issues\nallowed-tools: Read, Grep, Bash(git:*)\nmodel: sonnet\n---\n\nReview this code for security vulnerabilities...\n```\n\n## YAML Frontmatter Fields\n\n### description\n\n**Purpose:** Brief description shown in `/help`\n**Type:** String\n**Default:** First line of command prompt\n\n```yaml\n---\ndescription: Review pull request for code quality\n---\n```\n\n**Best practice:** Clear, actionable description (under 60 characters)\n\n### allowed-tools\n\n**Purpose:** Specify which tools command can use\n**Type:** String or Array\n**Default:** Inherits from conversation\n\n```yaml\n---\nallowed-tools: Read, Write, Edit, Bash(git:*)\n---\n```\n\n**Patterns:**\n- `Read, Write, Edit` - Specific tools\n- `Bash(git:*)` - Bash with git commands only\n- `*` - All tools (rarely needed)\n\n**Use when:** Command requires specific tool access\n\n### model\n\n**Purpose:** Specify model for command execution\n**Type:** String (sonnet, opus, haiku)\n**Default:** Inherits from conversation\n\n```yaml\n---\nmodel: haiku\n---\n```\n\n**Use cases:**\n- `haiku` - Fast, simple commands\n- `sonnet` - Standard workflows\n- `opus` - Complex analysis\n\n### argument-hint\n\n**Purpose:** Document expected arguments for autocomplete\n**Type:** String\n**Default:** None\n\n```yaml\n---\nargument-hint: [pr-number] [priority] [assignee]\n---\n```\n\n**Benefits:**\n- Helps users understand command arguments\n- Improves command discovery\n- Documents command interface\n\n### disable-model-invocation\n\n**Purpose:** Prevent SlashCommand tool from programmatically calling command\n**Type:** Boolean\n**Default:** false\n\n```yaml\n---\ndisable-model-invocation: true\n---\n```\n\n**Use when:** Command should only be manually invoked\n\n## Dynamic Arguments\n\n### Using $ARGUMENTS\n\nCapture all arguments as single string:\n\n```markdown\n---\ndescription: Fix issue by number\nargument-hint: [issue-number]\n---\n\nFix issue #$ARGUMENTS following our coding standards and best practices.\n```\n\n**Usage:**\n```\n> /fix-issue 123\n> /fix-issue 456\n```\n\n**Expands to:**\n```\nFix issue #123 following our coding standards...\nFix issue #456 following our coding standards...\n```\n\n### Using Positional Arguments\n\nCapture individual arguments with `$1`, `$2`, `$3`, etc.:\n\n```markdown\n---\ndescription: Review PR with priority and assignee\nargument-hint: [pr-number] [priority] [assignee]\n---\n\nReview pull request #$1 with priority level $2.\nAfter review, assign to $3 for follow-up.\n```\n\n**Usage:**\n```\n> /review-pr 123 high alice\n```\n\n**Expands to:**\n```\nReview pull request #123 with priority level high.\nAfter review, assign to alice for follow-up.\n```\n\n### Combining Arguments\n\nMix positional and remaining arguments:\n\n```markdown\nDeploy $1 to $2 environment with options: $3\n```\n\n**Usage:**\n```\n> /deploy api staging --force --skip-tests\n```\n\n**Expands to:**\n```\nDeploy api to staging environment with options: --force --skip-tests\n```\n\n## File References\n\n### Using @ Syntax\n\nInclude file contents in command:\n\n```markdown\n---\ndescription: Review specific file\nargument-hint: [file-path]\n---\n\nReview @$1 for:\n- Code quality\n- Best practices\n- Potential bugs\n```\n\n**Usage:**\n```\n> /review-file src/api/users.ts\n```\n\n**Effect:** Claude reads `src/api/users.ts` before processing command\n\n### Multiple File References\n\nReference multiple files:\n\n```markdown\nCompare @src/old-version.js with @src/new-version.js\n\nIdentify:\n- Breaking changes\n- New features\n- Bug fixes\n```\n\n### Static File References\n\nReference known files without arguments:\n\n```markdown\nReview @package.json and @tsconfig.json for consistency\n\nEnsure:\n- TypeScript version matches\n- Dependencies are aligned\n- Build configuration is correct\n```\n\n## Bash Execution in Commands\n\nCommands can execute bash commands inline to dynamically gather context before Claude processes the command. This is useful for including repository state, environment information, or project-specific context.\n\n**When to use:**\n- Include dynamic context (git status, environment vars, etc.)\n- Gather project/repository state\n- Build context-aware workflows\n\n**Implementation details:**\nFor complete syntax, examples, and best practices, see `references/plugin-features-reference.md` section on bash execution. The reference includes the exact syntax and multiple working examples to avoid execution issues\n\n## Command Organization\n\n### Flat Structure\n\nSimple organization for small command sets:\n\n```\n.claude/commands/\n├── build.md\n├── test.md\n├── deploy.md\n├── review.md\n└── docs.md\n```\n\n**Use when:** 5-15 commands, no clear categories\n\n### Namespaced Structure\n\nOrganize commands in subdirectories:\n\n```\n.claude/commands/\n├── ci/\n│   ├── build.md        # /build (project:ci)\n│   ├── test.md         # /test (project:ci)\n│   └── lint.md         # /lint (project:ci)\n├── git/\n│   ├── commit.md       # /commit (project:git)\n│   └── pr.md           # /pr (project:git)\n└── docs/\n    ├── generate.md     # /generate (project:docs)\n    └── publish.md      # /publish (project:docs)\n```\n\n**Benefits:**\n- Logical grouping by category\n- Namespace shown in `/help`\n- Easier to find related commands\n\n**Use when:** 15+ commands, clear categories\n\n## Best Practices\n\n### Command Design\n\n1. **Single responsibility:** One command, one task\n2. **Clear descriptions:** Self-explanatory in `/help`\n3. **Explicit dependencies:** Use `allowed-tools` when needed\n4. **Document arguments:** Always provide `argument-hint`\n5. **Consistent naming:** Use verb-noun pattern (review-pr, fix-issue)\n\n### Argument Handling\n\n1. **Validate arguments:** Check for required arguments in prompt\n2. **Provide defaults:** Suggest defaults when arguments missing\n3. **Document format:** Explain expected argument format\n4. **Handle edge cases:** Consider missing or invalid arguments\n\n```markdown\n---\nargument-hint: [pr-number]\n---\n\n$IF($1,\n  Review PR #$1,\n  Please provide a PR number. Usage: /review-pr [number]\n)\n```\n\n### File References\n\n1. **Explicit paths:** Use clear file paths\n2. **Check existence:** Handle missing files gracefully\n3. **Relative paths:** Use project-relative paths\n4. **Glob support:** Consider using Glob tool for patterns\n\n### Bash Commands\n\n1. **Limit scope:** Use `Bash(git:*)` not `Bash(*)`\n2. **Safe commands:** Avoid destructive operations\n3. **Handle errors:** Consider command failures\n4. **Keep fast:** Long-running commands slow invocation\n\n### Documentation\n\n1. **Add comments:** Explain complex logic\n2. **Provide examples:** Show usage in comments\n3. **List requirements:** Document dependencies\n4. **Version commands:** Note breaking changes\n\n```markdown\n---\ndescription: Deploy application to environment\nargument-hint: [environment] [version]\n---\n\n<!--\nUsage: /deploy [staging|production] [version]\nRequires: AWS credentials configured\nExample: /deploy staging v1.2.3\n-->\n\nDeploy application to $1 environment using version $2...\n```\n\n## Common Patterns\n\n### Review Pattern\n\n```markdown\n---\ndescription: Review code changes\nallowed-tools: Read, Bash(git:*)\n---\n\nFiles changed: !`git diff --name-only`\n\nReview each file for:\n1. Code quality and style\n2. Potential bugs or issues\n3. Test coverage\n4. Documentation needs\n\nProvide specific feedback for each file.\n```\n\n### Testing Pattern\n\n```markdown\n---\ndescription: Run tests for specific file\nargument-hint: [test-file]\nallowed-tools: Bash(npm:*)\n---\n\nRun tests: !`npm test $1`\n\nAnalyze results and suggest fixes for failures.\n```\n\n### Documentation Pattern\n\n```markdown\n---\ndescription: Generate documentation for file\nargument-hint: [source-file]\n---\n\nGenerate comprehensive documentation for @$1 including:\n- Function/class descriptions\n- Parameter documentation\n- Return value descriptions\n- Usage examples\n- Edge cases and errors\n```\n\n### Workflow Pattern\n\n```markdown\n---\ndescription: Complete PR workflow\nargument-hint: [pr-number]\nallowed-tools: Bash(gh:*), Read\n---\n\nPR #$1 Workflow:\n\n1. Fetch PR: !`gh pr view $1`\n2. Review changes\n3. Run checks\n4. Approve or request changes\n```\n\n## Troubleshooting\n\n**Command not appearing:**\n- Check file is in correct directory\n- Verify `.md` extension present\n- Ensure valid Markdown format\n- Restart Claude Code\n\n**Arguments not working:**\n- Verify `$1`, `$2` syntax correct\n- Check `argument-hint` matches usage\n- Ensure no extra spaces\n\n**Bash execution failing:**\n- Check `allowed-tools` includes Bash\n- Verify command syntax in backticks\n- Test command in terminal first\n- Check for required permissions\n\n**File references not working:**\n- Verify `@` syntax correct\n- Check file path is valid\n- Ensure Read tool allowed\n- Use absolute or project-relative paths\n\n## Plugin-Specific Features\n\n### CLAUDE_PLUGIN_ROOT Variable\n\nPlugin commands have access to `${CLAUDE_PLUGIN_ROOT}`, an environment variable that resolves to the plugin''s absolute path.\n\n**Purpose:**\n- Reference plugin files portably\n- Execute plugin scripts\n- Load plugin configuration\n- Access plugin templates\n\n**Basic usage:**\n\n```markdown\n---\ndescription: Analyze using plugin script\nallowed-tools: Bash(node:*)\n---\n\nRun analysis: !`node ${CLAUDE_PLUGIN_ROOT}/scripts/analyze.js $1`\n\nReview results and report findings.\n```\n\n**Common patterns:**\n\n```markdown\n# Execute plugin script\n!`bash ${CLAUDE_PLUGIN_ROOT}/scripts/script.sh`\n\n# Load plugin configuration\n@${CLAUDE_PLUGIN_ROOT}/config/settings.json\n\n# Use plugin template\n@${CLAUDE_PLUGIN_ROOT}/templates/report.md\n\n# Access plugin resources\n@${CLAUDE_PLUGIN_ROOT}/docs/reference.md\n```\n\n**Why use it:**\n- Works across all installations\n- Portable between systems\n- No hardcoded paths needed\n- Essential for multi-file plugins\n\n### Plugin Command Organization\n\nPlugin commands discovered automatically from `commands/` directory:\n\n```\nplugin-name/\n├── commands/\n│   ├── foo.md              # /foo (plugin:plugin-name)\n│   ├── bar.md              # /bar (plugin:plugin-name)\n│   └── utils/\n│       └── helper.md       # /helper (plugin:plugin-name:utils)\n└── plugin.json\n```\n\n**Namespace benefits:**\n- Logical command grouping\n- Shown in `/help` output\n- Avoid name conflicts\n- Organize related commands\n\n**Naming conventions:**\n- Use descriptive action names\n- Avoid generic names (test, run)\n- Consider plugin-specific prefix\n- Use hyphens for multi-word names\n\n### Plugin Command Patterns\n\n**Configuration-based pattern:**\n\n```markdown\n---\ndescription: Deploy using plugin configuration\nargument-hint: [environment]\nallowed-tools: Read, Bash(*)\n---\n\nLoad configuration: @${CLAUDE_PLUGIN_ROOT}/config/$1-deploy.json\n\nDeploy to $1 using configuration settings.\nMonitor deployment and report status.\n```\n\n**Template-based pattern:**\n\n```markdown\n---\ndescription: Generate docs from template\nargument-hint: [component]\n---\n\nTemplate: @${CLAUDE_PLUGIN_ROOT}/templates/docs.md\n\nGenerate documentation for $1 following template structure.\n```\n\n**Multi-script pattern:**\n\n```text\n---\ndescription: Complete build workflow\nallowed-tools: Bash(*)\n---\n\n# Example commands (remove # to use):\n# Build: !`bash ${CLAUDE_PLUGIN_ROOT}/scripts/build.sh`\n# Test: !`bash ${CLAUDE_PLUGIN_ROOT}/scripts/test.sh`\n# Package: !`bash ${CLAUDE_PLUGIN_ROOT}/scripts/package.sh`\n\nReview outputs and report workflow status.\n```\n\n**See `references/plugin-features-reference.md` for detailed patterns.**\n\n## Integration with Plugin Components\n\nCommands can integrate with other plugin components for powerful workflows.\n\n### Agent Integration\n\nLaunch plugin agents for complex tasks:\n\n```markdown\n---\ndescription: Deep code review\nargument-hint: [file-path]\n---\n\nInitiate comprehensive review of @$1 using the code-reviewer agent.\n\nThe agent will analyze:\n- Code structure\n- Security issues\n- Performance\n- Best practices\n\nAgent uses plugin resources:\n- ${CLAUDE_PLUGIN_ROOT}/config/rules.json\n- ${CLAUDE_PLUGIN_ROOT}/checklists/review.md\n```\n\n**Key points:**\n- Agent must exist in `plugin/agents/` directory\n- Claude uses Task tool to launch agent\n- Document agent capabilities\n- Reference plugin resources agent uses\n\n### Skill Integration\n\nLeverage plugin skills for specialized knowledge:\n\n```markdown\n---\ndescription: Document API with standards\nargument-hint: [api-file]\n---\n\nDocument API in @$1 following plugin standards.\n\nUse the api-docs-standards skill to ensure:\n- Complete endpoint documentation\n- Consistent formatting\n- Example quality\n- Error documentation\n\nGenerate production-ready API docs.\n```\n\n**Key points:**\n- Skill must exist in `plugin/skills/` directory\n- Mention skill name to trigger invocation\n- Document skill purpose\n- Explain what skill provides\n\n### Hook Coordination\n\nDesign commands that work with plugin hooks:\n- Commands can prepare state for hooks to process\n- Hooks execute automatically on tool events\n- Commands should document expected hook behavior\n- Guide Claude on interpreting hook output\n\nSee `references/plugin-features-reference.md` for examples of commands that coordinate with hooks\n\n### Multi-Component Workflows\n\nCombine agents, skills, and scripts:\n\n```markdown\n---\ndescription: Comprehensive review workflow\nargument-hint: [file]\nallowed-tools: Bash(node:*), Read\n---\n\nTarget: @$1\n\nPhase 1 - Static Analysis:\n!`node ${CLAUDE_PLUGIN_ROOT}/scripts/lint.js $1`\n\nPhase 2 - Deep Review:\nLaunch code-reviewer agent for detailed analysis.\n\nPhase 3 - Standards Check:\nUse coding-standards skill for validation.\n\nPhase 4 - Report:\nTemplate: @${CLAUDE_PLUGIN_ROOT}/templates/review.md\n\nCompile findings into report following template.\n```\n\n**When to use:**\n- Complex multi-step workflows\n- Leverage multiple plugin capabilities\n- Require specialized analysis\n- Need structured outputs\n\n## Validation Patterns\n\nCommands should validate inputs and resources before processing.\n\n### Argument Validation\n\n```markdown\n---\ndescription: Deploy with validation\nargument-hint: [environment]\n---\n\nValidate environment: !`echo \"$1\" | grep -E \"^(dev|staging|prod)$\" || echo \"INVALID\"`\n\nIf $1 is valid environment:\n  Deploy to $1\nOtherwise:\n  Explain valid environments: dev, staging, prod\n  Show usage: /deploy [environment]\n```\n\n### File Existence Checks\n\n```markdown\n---\ndescription: Process configuration\nargument-hint: [config-file]\n---\n\nCheck file exists: !`test -f $1 && echo \"EXISTS\" || echo \"MISSING\"`\n\nIf file exists:\n  Process configuration: @$1\nOtherwise:\n  Explain where to place config file\n  Show expected format\n  Provide example configuration\n```\n\n### Plugin Resource Validation\n\n```markdown\n---\ndescription: Run plugin analyzer\nallowed-tools: Bash(test:*)\n---\n\nValidate plugin setup:\n- Script: !`test -x ${CLAUDE_PLUGIN_ROOT}/bin/analyze && echo \"✓\" || echo \"✗\"`\n- Config: !`test -f ${CLAUDE_PLUGIN_ROOT}/config.json && echo \"✓\" || echo \"✗\"`\n\nIf all checks pass, run analysis.\nOtherwise, report missing components.\n```\n\n### Error Handling\n\n```markdown\n---\ndescription: Build with error handling\nallowed-tools: Bash(*)\n---\n\nExecute build: !`bash ${CLAUDE_PLUGIN_ROOT}/scripts/build.sh 2>&1 || echo \"BUILD_FAILED\"`\n\nIf build succeeded:\n  Report success and output location\nIf build failed:\n  Analyze error output\n  Suggest likely causes\n  Provide troubleshooting steps\n```\n\n**Best practices:**\n- Validate early in command\n- Provide helpful error messages\n- Suggest corrective actions\n- Handle edge cases gracefully\n\n---\n\nFor detailed frontmatter field specifications, see `references/frontmatter-reference.md`.\nFor plugin-specific features and patterns, see `references/plugin-features-reference.md`.\nFor command pattern examples, see `examples/` directory.\n"},"lastSynced":"2026-02-20T04:53:08.032Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Research Agents needing streamlined workflows with Claude Code configuration for data science and academic writing.","zh":"非常适合需要简化工作流程的AI研究代理，具有Claude Code配置，用于数据科学和学术写作。","ja":"Claude Code構成によるデータサイエンスと学術執筆のためのストリームライン化されたワークフローが必要なAIリサーチエージェントに最適です。","ko":"데이터 과학 및 학술 저술을 위한 Claude Code 구성으로 작업 흐름을 간소화해야 하는 AI 연구 에이전트에 적합합니다.","es":"Perfecto para agentes de investigación de IA que necesitan flujos de trabajo optimizados con configuración de Claude Code para ciencia de datos y escritura académica.","fr":"Parfait pour les agents de recherche en IA ayant besoin de flux de travail rationalisés avec une configuration Claude Code pour la science des données et la rédaction académique.","de":"Perfekt für KI-Forschungsagenten, die optimierte Workflows mit Claude-Code-Konfiguration für Data Science und akademisches Schreiben benötigen.","pt":"Perfeito para Agentes de Pesquisa de IA que necessitam de fluxos de trabalho otimizados com configuração de Claude Code para ciência de dados e escrita acadêmica.","ru":"Идеально для агентов-исследователей ИИ, которым требуются оптимизированные рабочие процессы с конфигурацией Claude Code для 데이터 науки и академического письма.","ar":"مثالي للوكلاء البحثيين في مجال الذكاء الاصطناعي الذين يحتاجون إلى تدفقات عمل محسنة مع تكوين Claude Code للعلوم البيانية والكتابة الأكاديمية."},"recommendation":{"en":"Empowers agents to create powerful, reusable workflows using Markdown files, YAML frontmatter, and dynamic features like Bash execution for context, enabling efficient research workflows from idea to publication with Claude Code.","zh":"赋予代理创建强大、可重用的工作流的能力，使用Markdown文件、YAML前置内容和Bash执行等动态功能，使得从想法到出版的研究工作流程高效进行，利用Claude Code。","ja":"マークダウンファイル、YAMLフロントマター、コンテキストのBash実行などのダイナミック機能を使用して、強力で再利用可能なワークフローを作成するエージェントの能力を付与し、Claude Codeを使用して、アイデアから出版までの研究ワークフローを効率的に行うことができます。","ko":"마크다운 파일, YAML 프론트 매터 및 Bash 실행 등의 동적 기능을 사용하여 강력하고 재사용 가능한 워크플로를 생성할 수 있는 에이전트의 능력을 부여하여 Claude Code를 사용하여 아이디어에서 출판까지의 연구 워크플로를 효율적으로 진행할 수 있습니다.","es":"Habilita a los agentes a crear flujos de trabajo potentes y reutilizables utilizando archivos Markdown, frontmatter YAML y características dinámicas como la ejecución de Bash para el contexto, lo que permite flujos de trabajo de investigación eficientes desde la idea hasta la publicación con Claude Code.","fr":"Permet aux agents de créer des flux de travail puissants et réutilisables en utilisant des fichiers Markdown, des métadonnées YAML et des fonctionnalités dynamiques comme l''exécution de Bash pour le contexte, ce qui permet des flux de travail de recherche efficaces de l''idée à la publication avec Claude Code.","de":"Ermöglicht es Agenten, leistungsstarke und wiederverwendbare Workflows mit Markdown-Dateien, YAML-Frontmatter und dynamischen Funktionen wie Bash-Ausführung für den Kontext zu erstellen, was effiziente Forschungsworkflows von der Idee bis zur Veröffentlichung mit Claude Code ermöglicht.","pt":"Habilita os agentes a criar fluxos de trabalho poderosos e reutilizáveis usando arquivos Markdown, frontmatter YAML e recursos dinâmicos como execução Bash para contexto, permitindo fluxos de trabalho de pesquisa eficientes desde a ideia até a publicação com Claude Code.","ru":"Наделяет агентов возможностью создавать мощные и многоразовые рабочие процессы, используя файлы Markdown, YAML-заголовки и динамические функции, такие как выполнение Bash для контекста, что позволяет эффективно проводить исследовательские рабочие процессы от идеи до публикации с Claude Code.","ar":"يمنح الوكلاء القدرة على إنشاء تدفقات عمل قوية ومتكررة باستخدام ملفات Markdown و YAML الأمامي والميزات الديناميكية مثل تنفيذ Bash للسياق، مما يسمح بتدفقات عمل بحثية فعالة من الفكرة إلى النشر مع Claude Code."},"useCases":{"en":["Streamlining research workflows with reusable slash commands","Automating data science tasks using dynamic arguments and file references","Organizing and namespacing commands for efficient interactive sessions with Claude Code"],"zh":["使用可重用的斜杠命令简化研究工作流程","使用动态参数和文件引用自动执行数据科学任务","使用Claude Code组织和命名空间命令以实现高效的交互式会话"],"ja":["再利用可能なスラッシュコマンドを使用して研究ワークフローを簡素化する","ダイナミック引数とファイル参照を使用してデータサイエンスタスクを自動化する","Claude Codeを使用してコマンドを組織および名前空間化して、効率的なインタラクティブセッションを実現する"],"ko":["재사용 가능한 슬래시 명령을 사용하여 연구 워크플로를 간소화하는 것","동적 인수 및 파일 참조를 사용하여 데이터 과학 작업을 자동화하는 것","Claude Code를 사용하여 명령을 구성 및 네임스페이싱하여 효율적인 상호작용 세션을 구현하는 것"],"es":["Optimizar flujos de trabajo de investigación con comandos de barra reutilizables","Automatizar tareas de ciencia de datos utilizando argumentos dinámicos y referencias de archivo","Organizar y espaciar comandos para sesiones interactivas eficientes con Claude Code"],"fr":["Rationaliser les flux de travail de recherche avec des commandes de barre réutilisables","Automatiser les tâches de science des données en utilisant des arguments dynamiques et des références de fichier","Organiser et espacer les commandes pour des sessions interactives efficaces avec Claude Code"],"de":["Forschungsworkflows mit wiederverwendbaren Schrägstrichbefehlen optimieren","Data-Science-Aufgaben mit dynamischen Argumenten und Dateiverweisen automatisieren","Befehle für effiziente Interaktionssitzungen mit Claude Code organisieren und namensspezifisch zuweisen"],"pt":["Otimização de fluxos de trabalho de pesquisa com comandos slash reutilizáveis","Automatização de tarefas de ciência de dados usando argumentos dinâmicos e referências de arquivos","Organização e namespacing de comandos para sessões interativas eficientes com Claude Code"],"ru":["Оптимизация исследовательских рабочих процессов с помощью многоразовых команд slash","Автоматизация задач данных науки с помощью динамических аргументов и ссылок на файлы","Организация и namespacing команд для эффективных интерактивных сессий с Claude Code"],"ar":["تحسين تدفقات العمل البحثية باستخدام أوامر شرطة قابلة لإعادة الاستخدام","توفير مهام علوم البيانات باستخدام حجة ديناميكية ومراجع الملفات","تنظيم وتسمية مساحة الأوامر للجلسات التفاعلية الفعالة مع Claude Code"]},"limitations":{"en":["Requires Claude Code configuration knowledge","Dependent on Markdown file format and YAML frontmatter for command structure","Limited to Claude Code execution environment"],"zh":["需要Claude Code配置知识","依赖于Markdown文件格式和YAML前置内容的命令结构","仅限于Claude Code执行环境"],"ja":["Claude Code構成の知識が必要","マークダウンファイル形式とYAMLフロントマターのコマンド構造に依存","Claude Code実行環境に限定"],"ko":["Claude Code 구성 지식이 필요합니다","마크다운 파일 형식 및 YAML 프론트 매터의 명령 구조에 의존합니다","Claude Code 실행 환경으로 제한됩니다"],"es":["Requiere conocimiento de la configuración de Claude Code","Depende del formato de archivo Markdown y del frontmatter YAML para la estructura de comandos","Limitado al entorno de ejecución de Claude Code"],"fr":["Nécessite des connaissances en configuration Claude Code","Dépend du format de fichier Markdown et des métadonnées YAML pour la structure des commandes","Limité à l''environnement d''exécution de Claude Code"],"de":["Benötigt Kenntnisse in der Konfiguration von Claude Code","Hängt vom Markdown-Dateiformat und YAML-Frontmatter für die Befehlsstruktur ab","Begrenzt auf die Ausführungsumgebung von Claude Code"],"pt":["Exige conhecimento de configuração de Claude Code","Dependente do formato de arquivo Markdown e YAML frontmatter para estrutura de comando","Limitado ao ambiente de execução de Claude Code"],"ru":["Требует знаний конфигурации Claude Code","Зависит от формата файла Markdown и YAML-заголовков для структуры команды","Ограничен средой выполнения Claude Code"],"ar":["يتطلب معرفة تكوين Claude Code","يعتمد على تنسيق ملف Markdown و YAML الأمامي لهيكل الأمر","محدود ببيئة تنفيذ Claude Code"]},"version":3},"contentHash":"76014a8e26c35b0f9396ec4ba7531526259d24f5afff13553365a1c5cb03f447","qualityScore":60}');
