INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Galaxy-Dawn/claude-scholar/Command Development', 'Command Development', 'Galaxy-Dawn', 'claude-scholar', 'community', 'Command Development Galaxy-Dawn claude-scholar community 命令开发是 Claude Code 的一个综合配置，用于简化数据科学、AI 研究和学术写作工作流程 コマンド開発は、データサイエンス、AI 研究、学術論文のワークフローを最適化するための Claude Code 構成です 명령 개발은 데이터 과학, AI 연구, 학술 저술의 워크플ロー를 간소화하기 위한 Claude Code 구성입니다 El desarrollo de comandos para Claude Code permite crear flujos de trabajo personalizados para la investigación y el desarrollo de IA. Le développement de commandes pour Claude Code permet de créer des flux de travail personnalisés pour la recherche et le développement de l''IA. Die Befehlsentwicklung für Claude Code ermöglicht die Erstellung benutzerdefinierter Workflows für die Forschung und die Entwicklung von KI. O desenvolvimento de comandos para Claude Code permite criar fluxos de trabalho personalizados para pesquisa e publicação Разработка команд для Claude Code позволяет создавать пользовательские рабочие процессы для исследований и публикаций تطوير الأوامر ل Claude Code يسمح بإنشاء سير عمل مخصصة للبحث والنشر A comprehensive Claude Code configuration for data science, AI research, and academic writing. Streamline the complete research workflow—from idea to publication. Claude Code 命令开发 数据科学 AI 研究 学术写作 Markdown YAML Bash A comprehensive Claude Code configuration for data science, AI research, and academic writing. Streamline the complete research workflow—from idea to publication.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/wyze', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'wyze', 0, 0, 60, '2026-02-20T04:13:19.579Z', '2026-02-20T04:59:43.874Z', '287c45cf2383474cf872a89a421cba1788537cbe50a3c378b4a1999c7149ba56', '{"id":"majiayu000/claude-skill-registry/wyze","name":"wyze","description":{"zh":"Wyze 技能使 Claude 能够与 Wyze 交互，控制智能家居设备。快速安装和设置指南。","ja":"Wyze スキルにより、Claude が Wyze と連携してスマートホームデバイスを制御できるようになります。クイックインストールとセットアップガイド。","ko":"Wyze 스킬을 통해 Claude가 Wyze와 상호 작용하여 스마트 홈 디바이스를 제어할 수 있습니다. 빠른 설치 및 설정 가이드","es":"Wyze es un skill que permite a Claude controlar dispositivos inteligentes para el hogar, como cámaras y bombillas","fr":"Wyze est un skill qui permet à Claude de contrôler les appareils intelligents pour la maison, tels que les caméras et les ampoules","de":"Wyze ist ein Skill, der es Claude ermöglicht, intelligente Geräte für das Zuhause zu steuern, wie z.B. Kameras und Glühbirnen","pt":"O Wyze é uma habilidade que permite que Claude interaja com dispositivos smart home Wyze, controlando câmeras, lâmpadas, tomadas e mais","ru":"Wyze - это навык, который позволяет Claude взаимодействовать с умными устройствами для дома Wyze, управляя камерами, лампами, розетками и более","ar":"Wyze هو مهارة يسمح ل Claude بالتفاعل مع أجهزة المنزل الذكية Wyze، ويتحكم في الكاميرات واللمبات والمقابس والمزيد","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"Wyze 技能：智能家居设备控制","ja":"Wyze スキル：スマートホームデバイス制御","ko":"Wyze 스킬: 스마트 홈 디바이스 제어","es":"Wyze: Control de dispositivos inteligentes para Claude","fr":"Wyze : Contrôle des appareils intelligents pour Claude","de":"Wyze: Steuerung intelligenter Geräte für Claude","pt":"Wyze: Controle de Dispositivos Smart Home com Claude","ru":"Wyze: Упр