INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/wyze', 'wyze', 'majiayu000', 'claude-skill-registry', 'community', 'wyze majiayu000 claude-skill-registry community Wyze 技能使 Claude 能够与 Wyze 交互，控制智能家居设备。快速安装和设置指南。 Wyze スキルにより、Claude が Wyze と連携してスマートホームデバイスを制御できるようになります。クイックインストールとセットアップガイド。 Wyze 스킬을 통해 Claude가 Wyze와 상호 작용하여 스마트 홈 디바이스를 제어할 수 있습니다. 빠른 설치 및 설정 가이드 Wyze es un skill que permite a Claude controlar dispositivos inteligentes para el hogar, como cámaras y bombillas Wyze est un skill qui permet à Claude de contrôler les appareils intelligents pour la maison, tels que les caméras et les ampoules Wyze ist ein Skill, der es Claude ermöglicht, intelligente Geräte für das Zuhause zu steuern, wie z.B. Kameras und Glühbirnen O Wyze é uma habilidade que permite que Claude interaja com dispositivos smart home Wyze, controlando câmeras, lâmpadas, tomadas e mais Wyze - это навык, который позволяет Claude взаимодействовать с умными устройствами для дома Wyze, управляя камерами, лампами, розетками и более Wyze هو مهارة يسمح ل Claude بالتفاعل مع أجهزة المنزل الذكية Wyze، ويتحكم في الكاميرات واللمبات والمقابس والمزيد The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app Wyze 技能 智能家居设备控制 Claude Wyze 智能家居 设备控制 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
