INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/arlo', 'arlo', 'majiayu000', 'claude-skill-registry', 'community', 'arlo majiayu000 claude-skill-registry community Arlo 技能使 Claude 能够与 Arlo 安防系统交互，支持摄像头直播、录制管理、运动检测配置等功能 Arlo スキルは、Claude が Arlo ホームセキュリティシステムとやり取りできるようにします Arlo 스킬은 Claude가 Arlo 보안 시스템과 상호 작용할 수 있도록 하여 카메라 피드 보기, 녹음 관리, 모션 감지 구성 등을 지원 La habilidad Arlo permite a Claude interactuar con cámaras de seguridad y sistemas de vigilancia para una mayor seguridad La compétence Arlo permet à Claude d''interagir avec les caméras de sécurité et les systèmes de surveillance pour une plus grande sécurité Die Arlo-Fähigkeit ermöglicht es Claude, mit Sicherheitskameras und Überwachungssystemen zu interagieren, um die Sicherheit zu erhöhen O Arlo Skill permite que Claude interaja com a segurança Arlo, oferecendo recursos como visualização de feeds de câmera e configuração de detecção de movimento Навык Arlo позволяет Claude взаимодействовать с системой безопасности Arlo, предоставляя функции, такие как просмотр видеопотока и настройка обнаружения движения تمكين مهارة Arlo من互одействة Claude مع نظام أمان Arlo، وتقديم ميزات مثل عرض تدفقات الكاميرا وتكوين كشف الحركة The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app Arlo 技能 Claude 安防系统 智能家居 摄像头直播 录制管理 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/oss', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'oss', 0, 0, 60, '2026-02-20T04:13:19.579Z', '2026-02-20T05:00:26.532Z', '29e16a852dcbc4445d3d60c4d12908e97c3b2cca1d8810abeb5b6657ba5da671', '{"id":"majiayu000/claude-skill-registry/oss","name":"oss","description":{"zh":"OSS 贡献工作流自动化，实现 GitHub 开源贡献的标准化和效率化","ja":"OSS 貢献ワークフローの自動化により、GitHub のオープンソース貢献を効率化","ko":"OSS 기여 워크플로 자동화로 GitHub 오픈소스 기여를 효율화","es":"Nuestra habilidad OSS facilita flujos de trabajo de contribución de código abierto en GitHub, incluyendo solicitudes de extracción y discusiones.","fr":"Notre compétence OSS facilite les flux de travail de contribution de code source ouvert sur GitHub, y compris les demandes d''extraction et les discussions.","de":"Unsere OSS-Fähigkeit ermöglicht Open-Source-Beitrag-Workflows auf GitHub, einschließlich Pull-Requests und Diskussionen.","pt":"O skill OSS facilita fluxos de trabalho de contribuição para projetos de código aberto no GitHub, incluindo pull requests e issues.","ru":"Умение OSS облегчает потоки вклада в проекты с открытым исходным кодом на GitHub, включая запросы на принятие и проблемы.","ar":"تسهل مهارة OSS تدفقات العمل للمساهمة في مشاريع الكود المفتوح على GitHub، بما في ذلك طلبات السحب والمشكلات.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"OSS 贡献工作流自动化","ja":"OSS 貢献ワークフローの自動化","ko":"OSS 기여 워크플로 자동화","es":"Flujos de contribución de OSS: automatización de tareas","fr":"Workflows de contribution OSS: automatez vos tâches","de":"OSS-Beitrag-Workflows: Automatisierung von Aufgaben","pt":"OSS: Fluxos de Trabalho de Contribuição Aberta","ru":"OSS: Потоки вклада в открытый исходный код","ar":"OSS: تدفقات العمل للمساهمة المفتوحة","en":"oss"},"description":{"zh":"OSS 贡献工作流自动化，实现 GitHub 开源贡献的标准化和效率化","ja":"OSS 貢献ワークフローの自動化により、GitHub のオープンソース貢献を効率化","ko":"OSS 기여 워크플로 자동화로 GitHub 오픈소스 기여를 효율화","es":"Nuestra habilidad OSS facilita flujos de trabajo de contribución de código abierto en GitHub, incluyendo solicitudes de extracción y discusiones.","fr":"Notre compétence OSS facilite les flux de travail de contribution de code source ouvert sur GitHub, y compris les demandes d''extraction et les discussions.","de":"Unsere OSS-Fähigkeit ermöglicht Open-Source-Beitrag-Workflows auf GitHub, einschließlich Pull-Requests und Diskussionen.","pt":"O skill OSS facilita fluxos de trabalho de contribuição para projetos de código aberto no GitHub, incluindo pull requests e issues.","ru":"Умение OSS облегчает потоки вклада в проекты с открытым исходным кодом на GitHub, включая запросы на принятие и проблемы.","ar":"تسهل مهارة OSS تدفقات العمل للمساهمة في مشاريع الكود المفتوح على GitHub، بما في ذلك طلبات السحب والمشكلات.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["GitHub 开源贡献流程自动化","标准化的 pull request 和 issue 处理","元数据应用和仓库约定一致性","命令行界面支持"],"ja":["GitHub のオープンソース貢献プロセスの自動化","標準化された pull request と issue 処理","メタデータの適用とリポジトリ約束の一貫性","コマンドラインインターフェイスのサポート"],"ko":["GitHub 오픈소스 기여 프로세스 자동화","표준화된 pull request 및 issue 처리","메타데이터 적용 및 리포지토리 규약 일관성","명령줄 인터페이스 지원"],"es":["Automatización de solicitudes de extracción","Gestión de problemas y discusiones","Aplicación de metadatos y formato consistente","Adhesión a las convenciones del repositorio","Facilitación de flujos de trabajo de contribución en GitHub","Análisis semántico para tareas de contribución"],"fr":["Automatisation des demandes d''extraction","Gestion des problèmes et des discussions","Application de métadonnées et de formatage cohérent","Adhésion aux conventions du référentiel","Facilitation des flux de travail de contribution sur GitHub","Analyse sémantique pour les tâches de contribution"],"de":["Automatisierung von Pull-Requests","Verwaltung von Problemen und Diskussionen","Anwendung von Metadaten und konsistentem Format","Einhaltung der Repository-Konventionen","Erleichterung von Beitrag-Workflows auf GitHub","Semantische Analyse für Beitrag-Aufgaben"],"pt":["Automatização de tarefas de contribuição","Suporte a pull requests e issues","Formatação consistente e metadados","Adesão às convenções do repositório"],"ru":["Автоматизация задач по внесению вклада","Поддержка запросов на принятие и проблем","Последовательное форматирование и метаданные","Соблюдение конвенций репозитория"],"ar":["أتمتة مهام المساهمة","دعم طلبات السحب والمشكلات","تنسيق متسق والبيانات الوصفية","الامتثال لاتفاقيات المستودع"]},"keywords":{"zh":["OSS 贡献","GitHub 自动化","开源贡献流程","标准化","效率化","命令行界面"],"ja":["OSS 貢献","GitHub 自動化","オープンソース貢献プロセス","標準化","効率化","コマンドラインインターフェイス"],"ko":["OSS 기여","GitHub 자동화","오픈소스 기여 프로세스","표준화","효율화","명령줄 인터페이스"],"es":["contribución de código abierto","flujos de trabajo de OSS","automatización de tareas","GitHub","solicitudes de extracción","problemas y discusiones","metadatos y formato","convenciones del repositorio"],"fr":["contribution de code source ouvert","flux de travail OSS","automatisation de tâches","GitHub","demandes d''extraction","problèmes et discussions","métadonnées et formatage","conventions du référentiel"],"de":["Open-Source-Beiträge","OSS-Workflows","Automatisierung von Aufgaben","GitHub","Pull-Requests","Probleme und Diskussionen","Metadaten und Format","Repository-Konventionen"],"pt":["OSS","código aberto","GitHub","contribuição","pull requests","issues","automatização"],"ru":["OSS","открытый исходный код","GitHub","вклад","запросы на принятие","проблемы","автоматизация"],"ar":["OSS","الكود المفتوح","GitHub","المساهمة","طلبات السحب","المشكلات","أتمتة"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.579Z","topics":[],"category":"community","skillMd":{"name":"oss","description":"This skill should be used when the user asks to create a pull request, create PR, open PR, create an issue, file an issue, create a GitHub issue, create a Claude Code issue, report a bug in Claude Code, create a Codex issue, report a bug in Codex CLI, create a discussion, start a GitHub discussion, or mentions OSS contribution workflows.","version":"0.1.0","bodyPreview":"# OSS Contribution Workflows\n\n## Overview\n\nFacilitate GitHub-based open source contribution workflows including pull requests, issues, and discussions. This skill provides structured automation for common OSS contribution tasks, ensuring consistent formatting, proper metadata application, and adherence to repository conventions. Use this skill when contributing to open source projects or managing GitHub repositories through the command line.\n\nThe skill emphasizes semantic analysis over mechanica","body":"# OSS Contribution Workflows\n\n## Overview\n\nFacilitate GitHub-based open source contribution workflows including pull requests, issues, and discussions. This skill provides structured automation for common OSS contribution tasks, ensuring consistent formatting, proper metadata application, and adherence to repository conventions. Use this skill when contributing to open source projects or managing GitHub repositories through the command line.\n\nThe skill emphasizes semantic analysis over mechanical operations—understand the intent and context of changes before generating titles, descriptions, or selecting templates. All generated content should be conversational and informal rather than robotic or overly formal.\n\n## Prerequisites\n\nBefore using any OSS contribution workflow, verify GitHub CLI authentication status:\n\n```bash\ngh auth status\n```\n\nEnsure the output shows you are logged in to github.com with appropriate scopes (repo, read:org, etc.). If not authenticated, run:\n\n```bash\ngh auth login\n```\n\nFor pull request workflows, also verify:\n\n- Working tree is clean or changes are committed\n- Current branch has commits ahead of the base branch\n- Remote tracking is configured for the current branch\n\n## Related Skills\n\nFor detailed GitHub CLI command syntax, flags, and patterns, activate the `gh-cli` skill. That skill covers the full gh command surface including issue management, PR operations, repository queries, workflow triggers, and API interactions.\n\n## Pull Requests\n\nCreate GitHub pull requests with semantic change analysis and structured formatting. The workflow generates meaningful titles and descriptions by reading actual code changes rather than relying solely on commit messages or filenames.\n\n### Workflow Steps\n\n**Validate Prerequisites**\n\nConfirm git state before proceeding:\n\n- Check `git status` for uncommitted changes\n- Verify branch has commits ahead of base branch via `git log`\n- Confirm remote tracking is configured\n- Ensure gh CLI is authenticated\n\n**Parse Arguments**\n\nSupport the following arguments:\n\n- `base-branch`: Target branch for the PR (default: main/master)\n- `reviewers`: Comma-separated list of GitHub usernames\n- `--draft`: Create as draft PR\n- `--test-plan`: Include test plan section in body\n\n**Semantic Change Analysis**\n\nRead the actual diff to understand what changed:\n\n```bash\ngit diff base-branch...HEAD\n```\n\nAnalyze:\n\n- Nature of changes (feature, fix, refactor, docs, test, chore)\n- Scope of impact (which components/modules affected)\n- Intent and purpose (why the change was made)\n- Dependencies or related changes\n\n**Generate Title and Body**\n\nCraft a concise title summarizing the change. Generate a body with:\n\n- **Summary** section (1-3 bullet points explaining what and why)\n- **Test Plan** section if `--test-plan` flag provided (bulleted checklist)\n- GitHub admonitions (NOTE, TIP, IMPORTANT, WARNING, CAUTION) where appropriate\n\nPass the body using HEREDOC syntax:\n\n```bash\ngh pr create --title \"the pr title\" --body \"$(cat <<''EOF''\n## Summary\n- First bullet point\n- Second bullet point\n\n## Test Plan\n- [ ] Test item one\n- [ ] Test item two\nEOF\n)\"\n```\n\n**Create Pull Request**\n\nExecute the gh command with all parsed flags and generated content. Include:\n\n- `--base` for target branch\n- `--reviewer` for each reviewer\n- `--draft` if draft mode requested\n- Return the PR URL to the user\n\nFor the complete pull request workflow with detailed steps, examples, and edge cases, refer to `./references/pull-requests.md`.\n\n## Issues\n\nCreate GitHub issues with automatic template selection and label application. The workflow intelligently chooses the appropriate issue template based on the description content and applies relevant labels for repositories where you have write access.\n\n### Workflow Steps\n\n**Check for Issue Templates**\n\nSearch the repository for issue templates:\n\n```bash\nls -la .github/ISSUE_TEMPLATE/\n```\n\nTemplates may be in YAML or Markdown format. Parse YAML frontmatter to extract:\n\n- Template name\n- Description\n- Labels to auto-apply\n\n**Auto-Select Template**\n\nAnalyze the issue description to determine the most appropriate template:\n\n- Bug reports: errors, crashes, unexpected behavior\n- Feature requests: enhancements, new functionality\n- Documentation: docs improvements, clarifications\n- Questions: how-to, usage inquiries\n\nIf no template matches or templates don''t exist, proceed without one.\n\n**Apply Labels**\n\nFor repositories where you have write access, apply labels using the `--label` flag:\n\n```bash\ngh issue create --label \"bug\" --label \"needs-triage\"\n```\n\nExtract labels from:\n\n- Selected template metadata\n- Issue description content (infer appropriate labels)\n\n**Support Similar Issue Search**\n\nWhen `--check` flag is provided, search for similar existing issues before creating:\n\n```bash\ngh issue list --search \"search terms\" --state all\n```\n\nDisplay results and ask user if they want to proceed with creation.\n\n**Create Issue**\n\nExecute the gh command with generated title, body, and metadata. Pass multi-line bodies using HEREDOC syntax. Return the issue URL to the user.\n\nFor the complete issue creation workflow with template examples, label strategies, and search patterns, refer to `./references/issues.md`.\n\n## Claude Code Issues\n\nCreate issues specifically in the anthropics/claude-code repository with environment information gathering and specialized templates. This workflow is optimized for reporting bugs, requesting features, or improving documentation for Claude Code itself.\n\n### Workflow Steps\n\n**Identify Issue Type**\n\nDetermine which template to use based on user intent:\n\n- `bug_report`: Errors, crashes, unexpected behavior\n- `feature_request`: New functionality or enhancements\n- `documentation`: Docs improvements or clarifications\n- `model_behavior`: Issues related to Claude''s responses or reasoning\n\n**Gather Environment Information**\n\nCollect relevant environment details:\n\n```bash\n# Claude Code version\nclaude --version\n\n# Operating system\nuname -a\n\n# Terminal emulator (macOS)\necho $TERM_PROGRAM\n\n# Shell\necho $SHELL\n```\n\n**Generate Issue Body**\n\nCreate structured content following the selected template format:\n\n- Clear description of the issue or request\n- Steps to reproduce (for bugs)\n- Expected vs actual behavior (for bugs)\n- Environment information section\n- Additional context or screenshots\n\nUse GitHub admonitions for important callouts:\n\n```markdown\n> [!IMPORTANT]\n> This issue affects all macOS users on Apple Silicon\n```\n\n**Create in anthropics/claude-code**\n\nExecute the gh command targeting the correct repository:\n\n```bash\ngh issue create \\\n  --repo anthropics/claude-code \\\n  --title \"Issue title\" \\\n  --body \"$(cat <<''EOF''\nIssue content here\nEOF\n)\"\n```\n\nReturn the issue URL to the user.\n\nFor the complete Claude Code issue workflow with template examples and environment gathering scripts, refer to `./references/issues-claude-code.md`.\n\n## Codex CLI Issues\n\nCreate issues specifically in the openai/codex repository with environment information gathering and specialized templates. This workflow is optimized for reporting bugs, requesting features, improving documentation, or reporting VS Code extension issues for Codex CLI.\n\n### Workflow Steps\n\n**Identify Issue Type**\n\nDetermine which template to use based on user intent:\n\n- `2-bug-report`: Errors, crashes, unexpected behavior in CLI\n- `4-feature-request`: New functionality or enhancements\n- `3-docs-issue`: Docs improvements or clarifications\n- `5-vs-code-extension`: Issues with the VS Code/Cursor/Windsurf extension\n\n**Gather Environment Information**\n\nCollect relevant environment details:\n\n```bash\n# Codex CLI version\ncodex --version\n\n# Platform (macOS/Linux)\nuname -mprs\n\n# For VS Code extension issues\ncode --version\n```\n\n**Generate Issue Body**\n\nCreate structured content following the selected template format:\n\n- Clear description of the issue or request\n- Steps to reproduce (for bugs)\n- Expected vs actual behavior (for bugs)\n- Environment information section (version, platform, model, subscription)\n- Additional context\n\n**Create in openai/codex**\n\nExecute the gh command targeting the correct repository:\n\n```bash\ngh issue create \\\n  --repo openai/codex \\\n  --title \"Issue title\" \\\n  --body \"$(cat <<''EOF''\nIssue content here\nEOF\n)\"\n```\n\nReturn the issue URL to the user.\n\nFor the complete Codex CLI issue workflow with template examples and environment gathering scripts, refer to `./references/issues-codex-cli.md`.\n\n## Discussions\n\nCreate GitHub discussions using the GraphQL API with automatic category selection. Discussions are ideal for Q&A, ideas, announcements, and general community conversations that don''t fit the issue format.\n\n### Workflow Steps\n\n**Fetch Repository Information**\n\nQuery the repository to get its node ID:\n\n```bash\ngh api graphql -f query=''\n  query($owner: String!, $repo: String!) {\n    repository(owner: $owner, name: $repo) {\n      id\n    }\n  }\n'' -f owner=\"OWNER\" -f repo=\"REPO\"\n```\n\n**Fetch Discussion Categories**\n\nQuery available categories for the repository:\n\n```bash\ngh api graphql -f query=''\n  query($owner: String!, $repo: String!) {\n    repository(owner: $owner, name: $repo) {\n      discussionCategories(first: 10) {\n        nodes {\n          id\n          name\n          description\n        }\n      }\n    }\n  }\n'' -f owner=\"OWNER\" -f repo=\"REPO\"\n```\n\n**Auto-Select Category**\n\nAnalyze the discussion title and body to choose the most appropriate category:\n\n- **Ideas**: Feature suggestions, proposals, brainstorming\n- **Q&A**: Questions seeking answers, how-to inquiries\n- **General**: Broad discussions, community topics\n- **Announcements**: Important updates (if you have permissions)\n- **Show and Tell**: Demos, showcases, sharing work\n\nIf uncertain, default to \"General\" or ask the user to select.\n\n**Support Similar Discussion Search**\n\nWhen `--check` flag is provided, search for similar existing discussions:\n\n```bash\ngh api graphql -f query=''\n  query($owner: String!, $repo: String!, $search: String!) {\n    repository(owner: $owner, name: $repo) {\n      discussions(first: 5, orderBy: {field: CREATED_AT, direction: DESC}, filterBy: {query: $search}) {\n        nodes {\n          title\n          url\n        }\n      }\n    }\n  }\n'' -f owner=\"OWNER\" -f repo=\"REPO\" -f search=\"search terms\"\n```\n\nDisplay results and confirm before proceeding.\n\n**Create Discussion**\n\nExecute the GraphQL mutation to create the discussion:\n\n```bash\ngh api graphql -f query=''\n  mutation($repositoryId: ID!, $categoryId: ID!, $title: String!, $body: String!) {\n    createDiscussion(input: {\n      repositoryId: $repositoryId\n      categoryId: $categoryId\n      title: $title\n      body: $body\n    }) {\n      discussion {\n        url\n      }\n    }\n  }\n'' -f repositoryId=\"REPO_ID\" -f categoryId=\"CATEGORY_ID\" -f title=\"Title\" -f body=\"Body\"\n```\n\nReturn the discussion URL to the user.\n\nFor the complete discussion workflow with GraphQL examples, category selection logic, and search patterns, refer to `./references/discussions.md`.\n\n## Common Patterns\n\nShared conventions and patterns used across all OSS contribution workflows.\n\n### HEREDOC for Multi-line Content\n\nAlways use HEREDOC syntax when passing multi-line bodies to gh commands:\n\n```bash\ngh pr create --title \"Title\" --body \"$(cat <<''EOF''\nFirst paragraph\n\nSecond paragraph\nEOF\n)\"\n```\n\nThe single quotes around `''EOF''` prevent variable expansion, ensuring literal content is passed.\n\n### GitHub Admonitions\n\nUse GitHub-flavored markdown admonitions to highlight important information:\n\n```markdown\n> [!NOTE]\n> Useful information that users should know\n\n> [!TIP]\n> Helpful advice for doing things better\n\n> [!IMPORTANT]\n> Key information users need to know\n\n> [!WARNING]\n> Urgent info that needs immediate attention\n\n> [!CAUTION]\n> Advises about risks or negative outcomes\n```\n\nApply these judiciously—overuse reduces their impact.\n\n### Semantic Analysis Over Mechanical Operations\n\nNever generate content based solely on filenames or commit messages. Always read the actual changes:\n\n```bash\n# Read the diff\ngit diff base-branch...HEAD\n\n# Or for specific files\ngit diff base-branch...HEAD -- path/to/file\n```\n\nUnderstand:\n\n- What changed (the mechanics)\n- Why it changed (the intent)\n- How it fits into the broader system (the context)\n\nUse this understanding to craft meaningful titles and descriptions that communicate value, not just mechanics.\n\n### Informal Tone\n\nGenerated content should be conversational and approachable:\n\n**Good:**\n\n> This PR adds support for parsing YAML frontmatter in issue templates. Previously, we only supported markdown format, which meant users couldn''t take advantage of GitHub''s newer template features.\n\n**Bad:**\n\n> This pull request implements functionality for YAML frontmatter parsing in the issue template processing subsystem. The implementation enhances the system''s capabilities regarding template format support.\n\nWrite like a human talking to another human, not like a technical specification.\n\n### Error Handling\n\nWhen operations fail, provide clear context:\n\n- What was being attempted\n- What went wrong\n- What the user should do to fix it\n\nExample:\n\n```\nFailed to create PR: current branch has no commits ahead of main.\n\nMake sure you''ve committed your changes and that your branch differs from the base branch.\n```\n\n### Confirmation and Feedback\n\nFor destructive or significant operations:\n\n- Show what will happen before executing\n- Ask for confirmation when appropriate\n- Provide clear feedback after completion\n\nFor search operations with `--check`:\n\n- Display found items clearly\n- Let the user decide whether to proceed\n- Don''t automatically skip creation if duplicates exist\n\n## Additional Resources\n\nFor detailed workflows, examples, and edge case handling, refer to these reference documents:\n\n- **`./references/pull-requests.md`** - Complete pull request workflow including git state validation, semantic analysis strategies, template examples, and reviewer management\n- **`./references/issues.md`** - Complete issue creation workflow including template parsing, label application strategies, and duplicate detection\n- **`./references/issues-claude-code.md`** - Claude Code-specific issue creation including all template formats, environment gathering scripts, and submission guidelines\n- **`./references/issues-codex-cli.md`** - Codex CLI-specific issue creation including bug reports, feature requests, docs issues, and VS Code extension templates\n- **`./references/issues-biome.md`** - Biome-specific issue creation including playground reproduction links, formatter/linter bug templates, and environment detection\n- **`./references/discussions.md`** - GitHub discussions workflow including GraphQL queries, category selection logic, and search strategies\n\nThese references provide implementation details, code examples, and troubleshooting guidance for each workflow type.\n"},"lastSynced":"2026-02-20T05:00:26.532Z","agentAnalysis":{"suitability":{"en":"Ideal for GitHub-focused AI Agents needing streamlined open source contribution workflows and automation of pull requests, issues, and discussions.","zh":"适用于专注于 GitHub 的 AI 代理，需要简化开源贡献工作流和自动化拉取请求、问题和讨论。","ja":"GitHub に焦点を当てた AI エージェントに適しており、オープンソースの貢献ワークフローとプルリクエスト、問題、議論の自動化を簡素化する必要があります。","ko":"GitHub에 중점을 둔 AI 에이전트에게 적합하며, 오픈 소스 기여 워크플ロー 및 풀 요청, 문제, 토론의 자동화를 간소화하는 데 필요합니다.","es":"Ideal para agentes de inteligencia artificial centrados en GitHub que necesitan flujos de trabajo de contribución de código abierto simplificados y automatización de solicitudes de extracción, problemas y discusiones.","fr":"Idéal pour les agents d''intelligence artificielle axés sur GitHub nécessitant des flux de travail de contribution de code source ouvert simplifiés et une automatisation des demandes de tirage, des problèmes et des discussions.","de":"Ideal für GitHub-fokussierte KI-Agents, die vereinfachte Open-Source-Beitrag-Workflows und Automatisierung von Pull-Anfragen, Problemen und Diskussionen benötigen.","pt":"Ideal para Agentes de IA focados no GitHub que necessitam de fluxos de trabalho de contribuição de código aberto otimizados e automação de solicitações de pull, problemas e discussões.","ru":"Идеально для агентов ИИ, ориентированных на GitHub, которым необходимы оптимизированные рабочие процессы взноса в открытом исходном коде и автоматизация запросов на вытягивание, проблем и обсуждений.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يركزون على جيت هاب والذين يحتاجون إلى تدفقات عمل للمساهمة في المصدر المفتوح التي تمت.streamlining وآليّة لطلبات السحب والمشاكل والمناقشات."},"recommendation":{"en":"Empowers agents to facilitate semantic analysis over mechanical automation, ensuring consistent formatting and proper metadata application in GitHub repositories, leveraging command line interfaces and repository conventions.","zh":"赋予代理人在 GitHub 存储库中执行语义分析而非机械自动化的能力，确保格式的一致性和元数据的适当应用，利用命令行接口和存储库约定。","ja":"GitHub リポジトリで機械的な自動化よりもセマンティック分析を実行するエージェントを可能にし、コマンドラインインターフェイスとリポジトリの規約を利用して、一貫したフォーマットと適切なメタデータの適用を確保します。","ko":"에이전트가 GitHub 저장소에서 기계적 자동화보다 의미 분석을 수행할 수 있도록 해주어, 명령줄 인터페이스와 저장소 규약을 활용하여 일관된 형식과 적절한 메타데이터 적용을 보장합니다.","es":"Habilita a los agentes a facilitar el análisis semántico sobre la automatización mecánica, garantizando un formato coherente y una aplicación adecuada de metadatos en los repositorios de GitHub, aprovechando las interfaces de línea de comandos y las convenciones de los repositorios.","fr":"Permet aux agents de faciliter l''analyse sémantique sur l''automatisation mécanique, en garantissant un formatage cohérent et une application appropriée des métadonnées dans les référentiels GitHub, en exploitant les interfaces de ligne de commande et les conventions de référentiel.","de":"Ermächtigt Agents, semantische Analyse über mechanische Automatisierung zu ermöglichen, indem sie konsistentes Formatieren und ordnungsgemäße Metadatenanwendung in GitHub-Repositorys gewährleisten, indem sie die Kommandozeilen-Schnittstellen und Repository-Konventionen nutzen.","pt":"Habilita os agentes a facilitar a análise semântica sobre a automação mecânica, garantindo a formatação consistente e a aplicação adequada de metadados nos repositórios do GitHub, utilizando interfaces de linha de comando e convenções de repositório.","ru":"Наделяет агентов возможностью обеспечить семантический анализ над механической автоматизацией, гарантируя последовательное форматирование и правильное применение метаданных в репозиториях GitHub, используя командные интерфейсы и репозиторийные конвенции.","ar":"تمكّن الوكلاء من تسهيل التحليل الدلالي على الاوتوماسيون الميكانيكي، مما يضمن التنسيق المتسق وتطبيق البيانات الوصفية بشكل صحيح في مستودعات جيت هاب، مع استخدام واجهات سطر الأوامر وتقاليد المستودع."},"useCases":{"en":["Automating GitHub-based open source contribution tasks","Managing pull requests, issues, and discussions with structured automation","Ensuring adherence to repository conventions and consistent formatting"],"zh":["自动化基于 GitHub 的开源贡献任务","使用结构化自动化管理拉取请求、问题和讨论","确保遵守存储库约定和一致的格式"],"ja":["GitHub ベースのオープンソースの貢献タスクの自動化","構造化された自動化を使用してプルリクエスト、問題、議論を管理する","リポジトリの規約と一貫したフォーマットの遵守を確保する"],"ko":["GitHub 기반의 오픈 소스 기여 태스크 자동화","구조화된 자동화를 사용하여 풀 요청, 문제, 토론 관리","저장소 규약 및 일관된 형식의 준수를 보장"],"es":["Automatizar tareas de contribución de código abierto basadas en GitHub","Administrar solicitudes de extracción, problemas y discusiones con automatización estructurada","Garantizar el cumplimiento de las convenciones del repositorio y el formato coherente"],"fr":["Automatiser les tâches de contribution de code source ouvert basées sur GitHub","Gérer les demandes de tirage, les problèmes et les discussions avec une automatisation structurée","Assurer le respect des conventions de référentiel et du formatage cohérent"],"de":["Automatisierung von GitHub-basierten Open-Source-Beitrag-Aufgaben","Verwaltung von Pull-Anfragen, Problemen und Diskussionen mit strukturierter Automatisierung","Sicherstellung der Einhaltung von Repository-Konventionen und konsistentem Formatieren"],"pt":["Automatizar tarefas de contribuição de código aberto baseadas no GitHub","Gerenciar solicitações de pull, problemas e discussões com automação estruturada","Garantir a adesão às convenções de repositório e formatação consistente"],"ru":["Автоматизировать задачи взноса в открытом исходном коде на основе GitHub","Управлять запросами на вытягивание, проблемами и обсуждениями с структурированной автоматизацией","Обеспечить соблюдение репозиторийных конвенций и последовательное форматирование"],"ar":["آليّة مهام المساهمة في المصدر المفتوح التي تعتمد على جيت هاب","إدارة طلبات السحب والمشاكل والمناقشات مع آليّة منظمّة","ضمان الالتزام بتقاليد المستودع والتنسيق المتسق"]},"limitations":{"en":["Requires GitHub repository access","Limited to command line interface interactions","Dependent on repository conventions and metadata standards"],"zh":["需要 GitHub 存储库访问权限","仅限命令行接口交互","依赖于存储库约定和元数据标准"],"ja":["GitHub リポジトリへのアクセス権が必要","コマンドラインインターフェイスの相互作用のみ","リポジトリの規約とメタデータの標準に依存"],"ko":["GitHub 저장소 액세스 권한 필요","명령줄 인터페이스 상호작용만","저장소 규약 및 메타데이터 표준에 의존"],"es":["Requiere acceso al repositorio de GitHub","Limitado a interacciones de interfaz de línea de comandos","Dependiente de las convenciones y normas de metadatos del repositorio"],"fr":["Nécessite un accès au référentiel GitHub","Limité aux interactions d''interface de ligne de commande","Dépendant des conventions et des normes de métadonnées du référentiel"],"de":["Benötigt Zugriff auf das GitHub-Repository","Begrenzt auf Kommandozeilen-Schnittstellen-Interaktionen","Abhängig von Repository-Konventionen und Metadaten-Standards"],"pt":["Requer acesso ao repositório do GitHub","Limitado a interações de interface de linha de comando","Dependente de convenções de repositório e padrões de metadados"],"ru":["Требует доступа к репозиторию GitHub","Ограничен взаимодействиями с командной строкой","Зависит от репозиторийных конвенций и стандартов метаданных"],"ar":["يتطلب الوصول إلى مستودع جيت هاب","محدود بالتفاعلات مع واجهة سطر الأوامر","يعتمد على تقاليد المستودع ومعايير البيانات الوصفية"]},"version":3},"contentHash":"29e16a852dcbc4445d3d60c4d12908e97c3b2cca1d8810abeb5b6657ba5da671","qualityScore":60}');
