INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/oss', 'oss', 'majiayu000', 'claude-skill-registry', 'community', 'oss majiayu000 claude-skill-registry community OSS 贡献工作流自动化，实现 GitHub 开源贡献的标准化和效率化 OSS 貢献ワークフローの自動化により、GitHub のオープンソース貢献を効率化 OSS 기여 워크플로 자동화로 GitHub 오픈소스 기여를 효율화 Nuestra habilidad OSS facilita flujos de trabajo de contribución de código abierto en GitHub, incluyendo solicitudes de extracción y discusiones. Notre compétence OSS facilite les flux de travail de contribution de code source ouvert sur GitHub, y compris les demandes d''extraction et les discussions. Unsere OSS-Fähigkeit ermöglicht Open-Source-Beitrag-Workflows auf GitHub, einschließlich Pull-Requests und Diskussionen. O skill OSS facilita fluxos de trabalho de contribuição para projetos de código aberto no GitHub, incluindo pull requests e issues. Умение OSS облегчает потоки вклада в проекты с открытым исходным кодом на GitHub, включая запросы на принятие и проблемы. تسهل مهارة OSS تدفقات العمل للمساهمة في مشاريع الكود المفتوح على GitHub، بما في ذلك طلبات السحب والمشكلات. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app OSS 贡献 GitHub 自动化 开源贡献流程 标准化 效率化 命令行界面 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/core-web-vitals', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'core-web-vitals', 0, 0, 60, '2026-02-20T04:13:19.580Z', '2026-02-20T05:05:40.770Z', 'b03396c9bd7a41950bbaf5964bc8f1cf60a3c81830a6171614d6413c8bff308c', '{"id":"majiayu000/claude-skill-registry/core-web-vitals","name":"core-web-vitals","description":{"zh":"Core Web Vitals LCPINPCLS","ja":"Core Web Vitals LCPINPCLS","ko":"Core Web Vitals LCPINPCLS ","es":"La optimización de Core Web Vitals es crucial para mejorar la experiencia del usuario y el ranking de búsqueda. Aprende a optimizar LCP, INP y CLS.","fr":"L''optimisation des Core Web Vitals est essentielle pour améliorer l''expérience utilisateur et le référencement. Découvrez comment optimiser LCP, INP et CLS.","de":"Die Optimierung der Core Web Vitals ist entscheidend für die Verbesserung der Benutzererfahrung und der Suchmaschinen-Optimierung. Erfahren Sie, wie Sie LCP, INP und CLS optimieren können.","pt":"Otimização de Core Web Vitals para melhorar a experiência do usuário e o ranqueamento no Google. Aprenda sobre os três principais métricos: LCP, INP e CLS.","ru":"Оптимизация Core Web Vitals для улучшения пользовательского опыта и рейтинга в Google. Узнайте о трех основных метриках: LCP, INP и CLS.","ar":"تحسين معايير الويب الأساسية لتحسين تجربة المستخدم وترتيب جوجل. تعرف على المعايير الثلاثة الرئيسية: LCP، INP و CLS.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"Core Web Vitals ","ja":"Core Web Vitals","ko":"Core Web Vitals ","es":"Optimización de Core Web Vitals","fr":"Optimisation des Core Web Vitals","de":"Core Web Vitals Optimierung","pt":"Otimização de Core Web Vitals para Desenvolvedores","ru":"Оптимизация Core Web Vitals для разработчиков","ar":"تحسين معايير الويب الأساسية للأداء","en":"core-web-vitals"},"description":{"zh":"Core Web Vitals LCPINPCLS","ja":"Core Web Vitals LCPINPCLS","ko":"Core Web Vitals LCPINPCLS ","es":"La optimización de Core Web Vitals es crucial para mejorar la experiencia del usuario y el ranking de búsqueda. Aprende a optimizar LCP, INP y CLS.","fr":"L''optimisation des Core Web Vitals est essentielle pour améliorer l''expérience utilisateur et le référencement. Découvrez comment optimiser LCP, INP et CLS.","de":"Die Optimierung der Core Web Vitals ist entscheidend für die Verbesserung der Benutzererfahrung und der Suchmaschinen-Optimierung. Erfahren Sie, wie Sie LCP,...","pt":"Otimização de Core Web Vitals para melhorar a experiência do usuário e o ranqueamento no Google. Aprenda sobre os três principais métricos: LCP, INP e CLS.","ru":"Оптимизация Core Web Vitals для улучшения пользовательского опыта и рейтинга в Google. Узнайте о трех основных метриках: LCP, INP и CLS.","ar":"تحسين معايير الويب الأساسية لتحسين تجربة المستخدم وترتيب جوجل. تعرف على المعايير الثلاثة الرئيسية: LCP، INP و CLS.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["LCP","INP","CLS","SEO","Google","75"],"ja":["LCP","INP","CLS","SEO","Google","75"],"ko":["LCP","INP","CLS","SEO","Google","75"],"es":["Optimización de LCP ( Largest Contentful Paint )","Mejora de la interactividad con INP ( Input Delay )","Optimización de CLS ( Cumulative Layout Shift )","Análisis de la experiencia del usuario","Mejora del ranking de búsqueda en Google","Implementación de mejores prácticas de desarrollo web"],"fr":["Optimisation de LCP ( Largest Contentful Paint )","Amélioration de l''interactivité avec INP ( Input Delay )","Optimisation de CLS ( Cumulative Layout Shift )","Analyse de l''expérience utilisateur","Amélioration du référencement sur Google","Mise en œuvre de meilleures pratiques de développement web"],"de":["Optimierung von LCP ( Largest Contentful Paint )","Verbesserung der Interaktivität mit INP ( Input Delay )","Optimierung von CLS ( Cumulative Layout Shift )","Analyse der Benutzererfahrung","Verbesserung der Suchmaschinen-Optimierung bei Google","Implementierung von Best Practices für die Web-Entwicklung"],"pt":["Otimização de LCP ( Largest Contentful Paint )","Otimização de INP ( Interactivity )","Otimização de CLS ( Cumulative Layout Shift )","Melhoria da experiência do usuário","Aumento do ranqueamento no Google"],"ru":["Оптимизация LCP ( Largest Contentful Paint )","Оптимизация INP ( Interactivity )","Оптимизация CLS ( Cumulative Layout Shift )","Улучшение пользовательского опыта","Повышение рейтинга в Google"],"ar":["تحسين LCP ( Largest Contentful Paint )","تحسين INP ( Interactivity )","تحسين CLS ( Cumulative Layout Shift )","تحسين تجربة المستخدم","تحسين ترتيب جوجل"]},"keywords":{"zh":["Core Web Vitals","LCP","INP","CLS","SEO","Google","Web","Vitals","Optimization"],"ja":["Core Web Vitals","LCP","INP","CLS","SEO","Google","Web","Vitals","Optimization"],"ko":["Core Web Vitals","LCP","INP","CLS","SEO","Google","Web","Vitals","Optimization"],"es":["Core Web Vitals","Optimización de LCP","Mejora de la interactividad","Optimización de CLS","Experiencia del usuario","Ranking de búsqueda","Desarrollo web","SEO"],"fr":["Core Web Vitals","Optimisation de LCP","Amélioration de l''interactivité","Optimisation de CLS","Expérience utilisateur","Référencement","Développement web","SEO"],"de":["Core Web Vitals","Optimierung von LCP","Verbesserung der Interaktivität","Optimierung von CLS","Benutzererfahrung","Suchmaschinen-Optimierung","Web-Entwicklung","SEO"],"pt":["Core Web Vitals","Otimização de site","Experiência do usuário","Ranqueamento no Google","LCP","INP","CLS","Desenvolvimento web"],"ru":["Core Web Vitals","Оптимизация сайта","Пользовательский опыт","Рейтинг в Google","LCP","INP","CLS","Веб-разработка"],"ar":["معايير الويب الأساسية","تحسين موقع ويب","تجربة المستخدم","ترتيب جوجل","LCP","INP","CLS","تطوير الويب"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.580Z","topics":[],"category":"community","skillMd":{"name":"core-web-vitals","description":"Optimize Core Web Vitals (LCP, INP, CLS) for better page experience and search ranking. Use when asked to improve Core Web Vitals, fix LCP, reduce CLS, optimize INP, page experience optimization, or fix layout shifts.","version":"1.0","bodyPreview":"# Core Web Vitals optimization\n\nTargeted optimization for the three Core Web Vitals metrics that affect Google Search ranking and user experience.\n\n## The three metrics\n\n| Metric | Measures | Good | Needs work | Poor |\n|--------|----------|------|------------|------|\n| **LCP** | Loading | ≤ 2.5s | 2.5s – 4s | > 4s |\n| **INP** | Interactivity | ≤ 200ms | 200ms – 500ms | > 500ms |\n| **CLS** | Visual Stability | ≤ 0.1 | 0.1 – 0.25 | > 0.25 |\n\nGoogle measures at the **75th percentile** — 75% of page","body":"# Core Web Vitals optimization\n\nTargeted optimization for the three Core Web Vitals metrics that affect Google Search ranking and user experience.\n\n## The three metrics\n\n| Metric | Measures | Good | Needs work | Poor |\n|--------|----------|------|------------|------|\n| **LCP** | Loading | ≤ 2.5s | 2.5s – 4s | > 4s |\n| **INP** | Interactivity | ≤ 200ms | 200ms – 500ms | > 500ms |\n| **CLS** | Visual Stability | ≤ 0.1 | 0.1 – 0.25 | > 0.25 |\n\nGoogle measures at the **75th percentile** — 75% of page visits must meet \"Good\" thresholds.\n\n---\n\n## LCP: Largest Contentful Paint\n\nLCP measures when the largest visible content element renders. Usually this is:\n- Hero image or video\n- Large text block\n- Background image\n- `<svg>` element\n\n### Common LCP issues\n\n**1. Slow server response (TTFB > 800ms)**\n```\nFix: CDN, caching, optimized backend, edge rendering\n```\n\n**2. Render-blocking resources**\n```html\n<!-- ❌ Blocks rendering -->\n<link rel=\"stylesheet\" href=\"/all-styles.css\">\n\n<!-- ✅ Critical CSS inlined, rest deferred -->\n<style>/* Critical above-fold CSS */</style>\n<link rel=\"preload\" href=\"/styles.css\" as=\"style\" \n      onload=\"this.onload=null;this.rel=''stylesheet''\">\n```\n\n**3. Slow resource load times**\n```html\n<!-- ❌ No hints, discovered late -->\n<img src=\"/hero.jpg\" alt=\"Hero\">\n\n<!-- ✅ Preloaded with high priority -->\n<link rel=\"preload\" href=\"/hero.webp\" as=\"image\" fetchpriority=\"high\">\n<img src=\"/hero.webp\" alt=\"Hero\" fetchpriority=\"high\">\n```\n\n**4. Client-side rendering delays**\n```javascript\n// ❌ Content loads after JavaScript\nuseEffect(() => {\n  fetch(''/api/hero-text'').then(r => r.json()).then(setHeroText);\n}, []);\n\n// ✅ Server-side or static rendering\n// Use SSR, SSG, or streaming to send HTML with content\nexport async function getServerSideProps() {\n  const heroText = await fetchHeroText();\n  return { props: { heroText } };\n}\n```\n\n### LCP optimization checklist\n\n```markdown\n- [ ] TTFB < 800ms (use CDN, edge caching)\n- [ ] LCP image preloaded with fetchpriority=\"high\"\n- [ ] LCP image optimized (WebP/AVIF, correct size)\n- [ ] Critical CSS inlined (< 14KB)\n- [ ] No render-blocking JavaScript in <head>\n- [ ] Fonts don''t block text rendering (font-display: swap)\n- [ ] LCP element in initial HTML (not JS-rendered)\n```\n\n### LCP element identification\n```javascript\n// Find your LCP element\nnew PerformanceObserver((list) => {\n  const entries = list.getEntries();\n  const lastEntry = entries[entries.length - 1];\n  console.log(''LCP element:'', lastEntry.element);\n  console.log(''LCP time:'', lastEntry.startTime);\n}).observe({ type: ''largest-contentful-paint'', buffered: true });\n```\n\n---\n\n## INP: Interaction to Next Paint\n\nINP measures responsiveness across ALL interactions (clicks, taps, key presses) during a page visit. It reports the worst interaction (at 98th percentile for high-traffic pages).\n\n### INP breakdown\n\nTotal INP = **Input Delay** + **Processing Time** + **Presentation Delay**\n\n| Phase | Target | Optimization |\n|-------|--------|--------------|\n| Input Delay | < 50ms | Reduce main thread blocking |\n| Processing | < 100ms | Optimize event handlers |\n| Presentation | < 50ms | Minimize rendering work |\n\n### Common INP issues\n\n**1. Long tasks blocking main thread**\n```javascript\n// ❌ Long synchronous task\nfunction processLargeArray(items) {\n  items.forEach(item => expensiveOperation(item));\n}\n\n// ✅ Break into chunks with yielding\nasync function processLargeArray(items) {\n  const CHUNK_SIZE = 100;\n  for (let i = 0; i < items.length; i += CHUNK_SIZE) {\n    const chunk = items.slice(i, i + CHUNK_SIZE);\n    chunk.forEach(item => expensiveOperation(item));\n    \n    // Yield to main thread\n    await new Promise(r => setTimeout(r, 0));\n    // Or use scheduler.yield() when available\n  }\n}\n```\n\n**2. Heavy event handlers**\n```javascript\n// ❌ All work in handler\nbutton.addEventListener(''click'', () => {\n  // Heavy computation\n  const result = calculateComplexThing();\n  // DOM updates\n  updateUI(result);\n  // Analytics\n  trackEvent(''click'');\n});\n\n// ✅ Prioritize visual feedback\nbutton.addEventListener(''click'', () => {\n  // Immediate visual feedback\n  button.classList.add(''loading'');\n  \n  // Defer non-critical work\n  requestAnimationFrame(() => {\n    const result = calculateComplexThing();\n    updateUI(result);\n  });\n  \n  // Use requestIdleCallback for analytics\n  requestIdleCallback(() => trackEvent(''click''));\n});\n```\n\n**3. Third-party scripts**\n```javascript\n// ❌ Eagerly loaded, blocks interactions\n<script src=\"https://heavy-widget.com/widget.js\"></script>\n\n// ✅ Lazy loaded on interaction or visibility\nconst loadWidget = () => {\n  import(''https://heavy-widget.com/widget.js'')\n    .then(widget => widget.init());\n};\nbutton.addEventListener(''click'', loadWidget, { once: true });\n```\n\n**4. Excessive re-renders (React/Vue)**\n```javascript\n// ❌ Re-renders entire tree\nfunction App() {\n  const [count, setCount] = useState(0);\n  return (\n    <div>\n      <Counter count={count} />\n      <ExpensiveComponent /> {/* Re-renders on every count change */}\n    </div>\n  );\n}\n\n// ✅ Memoized expensive components\nconst MemoizedExpensive = React.memo(ExpensiveComponent);\n\nfunction App() {\n  const [count, setCount] = useState(0);\n  return (\n    <div>\n      <Counter count={count} />\n      <MemoizedExpensive />\n    </div>\n  );\n}\n```\n\n### INP optimization checklist\n\n```markdown\n- [ ] No tasks > 50ms on main thread\n- [ ] Event handlers complete quickly (< 100ms)\n- [ ] Visual feedback provided immediately\n- [ ] Heavy work deferred with requestIdleCallback\n- [ ] Third-party scripts don''t block interactions\n- [ ] Debounced input handlers where appropriate\n- [ ] Web Workers for CPU-intensive operations\n```\n\n### INP debugging\n```javascript\n// Identify slow interactions\nnew PerformanceObserver((list) => {\n  for (const entry of list.getEntries()) {\n    if (entry.duration > 200) {\n      console.warn(''Slow interaction:'', {\n        type: entry.name,\n        duration: entry.duration,\n        processingStart: entry.processingStart,\n        processingEnd: entry.processingEnd,\n        target: entry.target\n      });\n    }\n  }\n}).observe({ type: ''event'', buffered: true, durationThreshold: 16 });\n```\n\n---\n\n## CLS: Cumulative Layout Shift\n\nCLS measures unexpected layout shifts. A shift occurs when a visible element changes position between frames without user interaction.\n\n**CLS Formula:** `impact fraction × distance fraction`\n\n### Common CLS causes\n\n**1. Images without dimensions**\n```html\n<!-- ❌ Causes layout shift when loaded -->\n<img src=\"photo.jpg\" alt=\"Photo\">\n\n<!-- ✅ Space reserved -->\n<img src=\"photo.jpg\" alt=\"Photo\" width=\"800\" height=\"600\">\n\n<!-- ✅ Or use aspect-ratio -->\n<img src=\"photo.jpg\" alt=\"Photo\" style=\"aspect-ratio: 4/3; width: 100%;\">\n```\n\n**2. Ads, embeds, and iframes**\n```html\n<!-- ❌ Unknown size until loaded -->\n<iframe src=\"https://ad-network.com/ad\"></iframe>\n\n<!-- ✅ Reserve space with min-height -->\n<div style=\"min-height: 250px;\">\n  <iframe src=\"https://ad-network.com/ad\" height=\"250\"></iframe>\n</div>\n\n<!-- ✅ Or use aspect-ratio container -->\n<div style=\"aspect-ratio: 16/9;\">\n  <iframe src=\"https://youtube.com/embed/...\" \n          style=\"width: 100%; height: 100%;\"></iframe>\n</div>\n```\n\n**3. Dynamically injected content**\n```javascript\n// ❌ Inserts content above viewport\nnotifications.prepend(newNotification);\n\n// ✅ Insert below viewport or use transform\nconst insertBelow = viewport.bottom < newNotification.top;\nif (insertBelow) {\n  notifications.prepend(newNotification);\n} else {\n  // Animate in without shifting\n  newNotification.style.transform = ''translateY(-100%)'';\n  notifications.prepend(newNotification);\n  requestAnimationFrame(() => {\n    newNotification.style.transform = '''';\n  });\n}\n```\n\n**4. Web fonts causing FOUT**\n```css\n/* ❌ Font swap shifts text */\n@font-face {\n  font-family: ''Custom'';\n  src: url(''custom.woff2'') format(''woff2'');\n}\n\n/* ✅ Optional font (no shift if slow) */\n@font-face {\n  font-family: ''Custom'';\n  src: url(''custom.woff2'') format(''woff2'');\n  font-display: optional;\n}\n\n/* ✅ Or match fallback metrics */\n@font-face {\n  font-family: ''Custom'';\n  src: url(''custom.woff2'') format(''woff2'');\n  font-display: swap;\n  size-adjust: 105%; /* Match fallback size */\n  ascent-override: 95%;\n  descent-override: 20%;\n}\n```\n\n**5. Animations triggering layout**\n```css\n/* ❌ Animates layout properties */\n.animate {\n  transition: height 0.3s, width 0.3s;\n}\n\n/* ✅ Use transform instead */\n.animate {\n  transition: transform 0.3s;\n}\n.animate.expanded {\n  transform: scale(1.2);\n}\n```\n\n### CLS optimization checklist\n\n```markdown\n- [ ] All images have width/height or aspect-ratio\n- [ ] All videos/embeds have reserved space\n- [ ] Ads have min-height containers\n- [ ] Fonts use font-display: optional or matched metrics\n- [ ] Dynamic content inserted below viewport\n- [ ] Animations use transform/opacity only\n- [ ] No content injected above existing content\n```\n\n### CLS debugging\n```javascript\n// Track layout shifts\nnew PerformanceObserver((list) => {\n  for (const entry of list.getEntries()) {\n    if (!entry.hadRecentInput) {\n      console.log(''Layout shift:'', entry.value);\n      entry.sources?.forEach(source => {\n        console.log(''  Shifted element:'', source.node);\n        console.log(''  Previous rect:'', source.previousRect);\n        console.log(''  Current rect:'', source.currentRect);\n      });\n    }\n  }\n}).observe({ type: ''layout-shift'', buffered: true });\n```\n\n---\n\n## Measurement tools\n\n### Lab testing\n- **Chrome DevTools** → Performance panel, Lighthouse\n- **WebPageTest** → Detailed waterfall, filmstrip\n- **Lighthouse CLI** → `npx lighthouse <url>`\n\n### Field data (real users)\n- **Chrome User Experience Report (CrUX)** → BigQuery or API\n- **Search Console** → Core Web Vitals report\n- **web-vitals library** → Send to your analytics\n\n```javascript\nimport {onLCP, onINP, onCLS} from ''web-vitals'';\n\nfunction sendToAnalytics({name, value, rating}) {\n  gtag(''event'', name, {\n    event_category: ''Web Vitals'',\n    value: Math.round(name === ''CLS'' ? value * 1000 : value),\n    event_label: rating\n  });\n}\n\nonLCP(sendToAnalytics);\nonINP(sendToAnalytics);\nonCLS(sendToAnalytics);\n```\n\n---\n\n## Framework quick fixes\n\n### Next.js\n```jsx\n// LCP: Use next/image with priority\nimport Image from ''next/image'';\n<Image src=\"/hero.jpg\" priority fill alt=\"Hero\" />\n\n// INP: Use dynamic imports\nconst HeavyComponent = dynamic(() => import(''./Heavy''), { ssr: false });\n\n// CLS: Image component handles dimensions automatically\n```\n\n### React\n```jsx\n// LCP: Preload in head\n<link rel=\"preload\" href=\"/hero.jpg\" as=\"image\" fetchpriority=\"high\" />\n\n// INP: Memoize and useTransition\nconst [isPending, startTransition] = useTransition();\nstartTransition(() => setExpensiveState(newValue));\n\n// CLS: Always specify dimensions in img tags\n```\n\n### Vue/Nuxt\n```vue\n<!-- LCP: Use nuxt/image with preload -->\n<NuxtImg src=\"/hero.jpg\" preload loading=\"eager\" />\n\n<!-- INP: Use async components -->\n<component :is=\"() => import(''./Heavy.vue'')\" />\n\n<!-- CLS: Use aspect-ratio CSS -->\n<img :style=\"{ aspectRatio: ''16/9'' }\" />\n```\n\n## References\n\n- [web.dev LCP](https://web.dev/articles/lcp)\n- [web.dev INP](https://web.dev/articles/inp)\n- [web.dev CLS](https://web.dev/articles/cls)\n- [Performance skill](../performance/SKILL.md)\n"},"lastSynced":"2026-02-20T05:05:40.770Z","agentAnalysis":{"suitability":{"en":"Perfect for SEO Optimization Agents needing advanced Core Web Vitals metrics analysis for improved Google Search ranking and user experience.","zh":"非常适合需要高级 Core Web Vitals 指标分析以提高 Google 搜索排名和用户体验的 SEO 优化代理。","ja":"SEO 最適化エージェントが Google 検索ランキングとユーザーエクスペリエンスを向上させるために、高度な Core Web Vitals メトリクス分析を必要とする場合に最適です。","ko":"Google 검색 순위와 사용자 경험을 개선하기 위해 고급 Core Web Vitals 메트릭스 분석이 필요한 SEO 최적화 에이전트에게 적합합니다.","es":"Perfecto para agentes de optimización de SEO que necesitan un análisis avanzado de las métricas de Core Web Vitals para mejorar el posicionamiento en la búsqueda de Google y la experiencia del usuario.","fr":"Parfait pour les agents d''optimisation du référencement nécessitant une analyse avancée des métriques de Core Web Vitals pour améliorer le classement de recherche Google et l''expérience utilisateur.","de":"Perfekt für SEO-Optimierungsagenten, die eine erweiterte Analyse von Core Web Vitals-Metriken für eine verbesserte Google-Suchranking und Benutzererfahrung benötigen.","pt":"Perfeito para Agentes de Otimização do SEO que necessitam de análise avançada de métricas de Core Web Vitals para melhorar o ranqueamento no Google Search e a experiência do usuário.","ru":"Идеально для агентов оптимизации SEO, которым необходим продвинутый анализ метрик Core Web Vitals для улучшения рейтинга поиска Google и пользовательского опыта.","ar":"مثالي لعمليات وكيل تحسين محركات البحث التي تحتاج إلى تحليل متقدم لمقاييس Core Web Vitals لتحسين تصنيف البحث في جوجل وتجربة المستخدم."},"recommendation":{"en":"Empowers agents to optimize website performance using LCP, INP, and CLS metrics, leveraging the 75th percentile measurement for accurate assessment, and providing actionable insights to improve loading times, interactivity, and visual stability.","zh":"使代理能够使用 LCP、INP 和 CLS 指标优化网站性能，利用第 75 百分位测量法进行准确评估，并提供可行的见解以改善加载时间、交互性和视觉稳定性。","ja":"エージェントが LCP、INP、CLS メトリクスを使用して Web サイトのパフォーマンスを最適化できるようにし、第 75 パーセントルの測定を使用して正確な評価を行い、ロード時間、インタラクティビティ、視覚的安定性を改善するための実行可能なインサイトを提供します。","ko":"에이전트가 LCP, INP, CLS 메트릭스를 사용하여 웹 사이트 성능을 최적화할 수 있도록 하며, 75 백분위 측정을 사용하여 정확한 평가를 수행하고, 로드 시간, 상호 작용성, 시각적 안정성을 개선하기 위한 실행 가능한 통찰력을 제공합니다.","es":"Habilita a los agentes a optimizar el rendimiento del sitio web utilizando las métricas LCP, INP y CLS, aprovechando la medición del percentil 75 para una evaluación precisa y proporcionando conocimientos prácticos para mejorar los tiempos de carga, la interactividad y la estabilidad visual.","fr":"Permet aux agents d''optimiser les performances du site Web en utilisant les métriques LCP, INP et CLS, en exploitant la mesure du percentile 75 pour une évaluation précise, et en fournissant des connaissances pratiques pour améliorer les temps de chargement, l''interactivité et la stabilité visuelle.","de":"Ermächtigt Agenten, die Website-Leistung mithilfe der LCP-, INP- und CLS-Metriken zu optimieren, die 75. Percentile-Messung für eine genaue Bewertung nutzt und praktische Erkenntnisse zur Verbesserung der Ladezeiten, Interaktivität und visuellen Stabilität bietet.","pt":"Habilita os agentes a otimizar o desempenho do site usando métricas LCP, INP e CLS, aproveitando a medição do percentil 75 para avaliação precisa e fornecendo insights ação para melhorar os tempos de carregamento, interatividade e estabilidade visual.","ru":"Наделяет агентов возможностью оптимизировать производительность сайта с помощью метрик LCP, INP и CLS, используя измерение 75-го процентиля для точной оценки и предоставляя действенные идеи для улучшения времени загрузки, интерактивности и визуальной стабильности.","ar":"تمكّن الوكيل من تحسين أداء الموقع باستخدام مقاييس LCP و INP و CLS، و استخدام قياس Percentil 75 لتقدير دقيق، و 提侤 أفكار ملموسة لتحسين أوقات التحميل والتفاعل والاستقرار البصري."},"useCases":{"en":["Analyzing LCP metrics to reduce loading times below 2.5s","Optimizing INP for improved interactivity with response times under 200ms","Debugging CLS issues to ensure visual stability scores below 0.1"],"zh":["分析 LCP 指标以将加载时间减少到 2.5 秒以下","优化 INP 以提高响应时间在 200ms 以下的交互性","调试 CLS 问题以确保视觉稳定性评分在 0.1 以下"],"ja":["ロード時間を 2.5 秒未満に削減するための LCP メトリクスの分析","200ms 未満のレスポンスタイムでインタラクティビティを向上させるための INP の最適化","視覚的安定性スコアを 0.1 未満に保つための CLS の問題のデバッグ"],"ko":["로딩 시간을 2.5초 이하로 줄이기 위한 LCP 메트릭스 분석","200ms 이하의 응답 시간으로 상호 작용성을 개선하기 위한 INP 최적화","시각적 안정성 점수를 0.1 이하로 유지하기 위한 CLS 문제 디버깅"],"es":["Analizar las métricas LCP para reducir los tiempos de carga por debajo de 2,5 s","Optimizar INP para mejorar la interactividad con tiempos de respuesta inferiores a 200 ms","Depurar problemas de CLS para garantizar puntuaciones de estabilidad visual por debajo de 0,1"],"fr":["Analyser les métriques LCP pour réduire les temps de chargement en dessous de 2,5 s","Optimiser INP pour améliorer l''interactivité avec des temps de réponse inférieurs à 200 ms","Déboguer les problèmes de CLS pour assurer des scores de stabilité visuelle inférieurs à 0,1"],"de":["LCP-Metriken analysieren, um Ladezeiten unter 2,5 s zu reduzieren","INP optimieren, um die Interaktivität mit Response-Zeiten unter 200 ms zu verbessern","CLS-Probleme debuggen, um visuelle Stabilitätsscores unter 0,1 sicherzustellen"],"pt":["Analisar métricas LCP para reduzir tempos de carregamento abaixo de 2,5s","Otimizar INP para melhorar a interatividade com tempos de resposta abaixo de 200ms","Depurar problemas de CLS para garantir pontuações de estabilidade visual abaixo de 0,1"],"ru":["Анализировать метрики LCP для снижения времени загрузки ниже 2,5с","Оптимизировать INP для улучшения интерактивности с временем ответа ниже 200мс","Отладить проблемы CLS для обеспечения показателей визуальной стабильности ниже 0,1"],"ar":["تحليل مقاييس LCP لتقليل أوقات التحميل إلى أقل من 2.5 ثانية","تحسين INP لتحسين التفاعل مع أوقات استجابة أقل من 200 مللي ثانية","تصحيح أخطاء CLS لضمان درجات استقرار مرئي أقل من 0.1"]},"limitations":{"en":["Requires website performance data access","Google Search ranking algorithms subject to change"],"zh":["需要访问网站性能数据","Google 搜索排名算法可能会更改"],"ja":["Web サイトのパフォーマンスデータへのアクセスが必要","Google 検索ランキングアルゴリズムは変更される可能性がある"],"ko":["웹 사이트 성능 데이터에 대한 액세스가 필요합니다.","Google 검색 순위 알고리즘은 변경될 수 있습니다."],"es":["Requiere acceso a datos de rendimiento del sitio web","Los algoritmos de clasificación de búsqueda de Google están sujetos a cambios"],"fr":["Nécessite un accès aux données de performances du site Web","Les algorithmes de classement de recherche Google sont sujets à des changements"],"de":["Benötigt Zugriff auf Website-Performance-Daten","Google-Suchalgorithmus-Regeln unterliegen Änderungen"],"pt":["Requer acesso a dados de desempenho do site","Algoritmos de ranqueamento do Google Search estão sujeitos a mudanças"],"ru":["Требуется доступ к данным производительности сайта","Алгоритмы рейтинга поиска Google могут меняться"],"ar":["يتطلب الوصول إلى بيانات أداء الموقع","خوارزميات تصنيف جوجل سر्च قابلة للتغيير"]},"version":3},"contentHash":"b03396c9bd7a41950bbaf5964bc8f1cf60a3c81830a6171614d6413c8bff308c","qualityScore":60}');
