INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/core-web-vitals', 'core-web-vitals', 'majiayu000', 'claude-skill-registry', 'community', 'core-web-vitals majiayu000 claude-skill-registry community Core Web Vitals LCPINPCLS Core Web Vitals LCPINPCLS Core Web Vitals LCPINPCLS La optimización de Core Web Vitals es crucial para mejorar la experiencia del usuario y el ranking de búsqueda. Aprende a optimizar LCP, INP y CLS. L''optimisation des Core Web Vitals est essentielle pour améliorer l''expérience utilisateur et le référencement. Découvrez comment optimiser LCP, INP et CLS. Die Optimierung der Core Web Vitals ist entscheidend für die Verbesserung der Benutzererfahrung und der Suchmaschinen-Optimierung. Erfahren Sie, wie Sie LCP, INP und CLS optimieren können. Otimização de Core Web Vitals para melhorar a experiência do usuário e o ranqueamento no Google. Aprenda sobre os três principais métricos: LCP, INP e CLS. Оптимизация Core Web Vitals для улучшения пользовательского опыта и рейтинга в Google. Узнайте о трех основных метриках: LCP, INP и CLS. تحسين معايير الويب الأساسية لتحسين تجربة المستخدم وترتيب جوجل. تعرف على المعايير الثلاثة الرئيسية: LCP، INP و CLS. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app Core Web Vitals LCP INP CLS SEO Google Web Vitals Optimization The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OutlineDriven/odin-gemini-cli-extension/agno', 'community', 'OutlineDriven', 'odin-gemini-cli-extension', 'OutlineDriven/odin-gemini-cli-extension', 'agno', 0, 0, 60, '2026-03-07T01:49:01.807Z', '2026-03-07T03:29:39.866Z', '30dffd9b81998d70c9659f772dab968f0fe94e3bd95c44f72a04d60451322fed', '{"id":"OutlineDriven/odin-gemini-cli-extension/agno","name":"agno","description":{"en":"Agno is a modern AI agent framework for building production-ready multi-agent systems. It provides comprehensive assistance with Agno development, including MCP integration, workflow orchestration, and AgentOS runtime.","zh":"Agno Skill提供了现代AI代理框架的开发工具，支持MCP集成、工作流编排和AgentOS运行时","ja":"Agno Skillは、MCP統合、ワークフロー管轄、AgentOSランタイムを備えた現代的なAIエージェントフレームワークの開発を支援","ko":"Agno Skill은 MCP 통합, 워크플로 오케스트레이션, AgentOS 런타임을 지원하는 현대적인 AI 에이전트 프레임워크의 개발을 지원","es":"Agno es un framework de desarrollo de agentes de inteligencia artificial para construir sistemas multi-agente de producción con integración MCP y orquestación de flujos de trabajo","fr":"Agno est un framework de développement d''agents d''intelligence artificielle pour construire des systèmes multi-agents de production avec intégration MCP et orchestration de flux de travail","de":"Agno ist ein Framework für die Entwicklung von KI-Agents, um Produktions-Systeme für Multi-Agenten mit MCP-Integration und Workflow-Orchestrierung zu erstellen","pt":"O Agno é um framework de inteligência artificial para desenvolver sistemas multi-agentes com MCP e orquestração de fluxo de trabalho.","ru":"Agno - это фреймворк искусственного интеллекта для создания многоагентных систем с MCP и оркестровкой рабочих процессов","ar":"Agno هو إطار عمل ذكاء اصطناعي لإنشاء أنظمة متعددة الوكلاء مع MCP وتنسيق سير العمل"},"seo":{"title":{"en":"Agno: Comprehensive AI Agent Development Setup Guide | AI...","zh":"Agno_SETUP GUIDE_AgentOS Runtime","ja":"Agno_BEST PRACTICES_AIエージェント開発","ko":"Agno_SETUP GUIDE_Multi-Agent Systems","es":"Guía de configuración de Agno para agentes de inteligenci...","fr":"Guide de mise en place d''Agno pour les agents d''intellige...","de":"Einrichtungsleitfaden für Agno-KI-Agents","pt":"Guia de Configuração do Agno: Desenvolvimento de Agentes ...","ru":"Настройка Agno: Руководство по созданию ИИ Агентов","ar":"دليل إعداد Agno: إنشاء وكلاء ذكاء اصطناعي"},"description":{"en":"Unlock the full potential of Agno, a modern AI agent framework. Learn how to build production-ready multi-agent systems with MCP integration and workflow orc...","zh":"使用Agno Skill进行现代AI代理框架开发，实现MCP集成、工作流编排和AgentOS运行时","ja":"Agno Skillを使用してAIエージェントの開発を簡素化し、MCP統合、ワークフロー管轄、AgentOSランタイムを実現","ko":"Agno Skill을 사용하여 현대적인 AI 에이전트 프레임워크를 개발하고 MCP 통합, 워크플로 오케스트레이션, AgentOS 런타임을 구현","es":"Aprende a desarrollar agentes de inteligencia artificial con Agno, un framework moderno para sistemas multi-agente con integración MCP y orquestación de fluj...","fr":"Découvrez comment développer des agents d''intelligence artificielle avec Agno, un framework moderne pour les systèmes multi-agents avec intégration MCP et or...","de":"Erfahren Sie, wie Sie KI-Agents mit Agno entwickeln, einem modernen Framework für Multi-Agenten-Systeme mit MCP-Integration und Workflow-Orchestrierung","pt":"Aprenda a configurar o Agno para desenvolver agentes de inteligência artificial com MCP, orquestração de fluxo de trabalho e AgentOS","ru":"Узнайте, как настроить Agno для создания ИИ Агентов с MCP, оркестровкой рабочих процессов и AgentOS","ar":"تعرف على كيفية إعداد Agno لإنشاء وكلاء ذكاء اصطناعي مع MCP وتنسيق سير العمل و AgentOS"},"definition":{"en":"Agno is a cutting-edge AI agent framework that enables developers to build complex multi-agent systems with ease, leveraging tools like Gemini CLI and AgentOS.","zh":"Agno Skill是一种现代AI代理框架，用于构建生产就绪的多代理系统","ja":"Agno Skillは、生産性の高いマルチエージェントシステムを構築するためのモダンなAIエージェントフレームワーク","ko":"Agno Skill은 생산 준비가 된 다중 에이전트 시스템을 구축하기 위한 현대적인 AI 에이전트 프레임워크","es":"Agno es un framework de desarrollo de agentes de inteligencia artificial que permite la creación de sistemas multi-agente de producción","fr":"Agno est un framework de développement d''agents d''intelligence artificielle qui permet la création de systèmes multi-agents de production","de":"Agno ist ein Framework für die Entwicklung von KI-Agents, das die Erstellung von Produktions-Systemen für Multi-Agenten ermöglicht","pt":"O que é Agno? Um framework de desenvolvimento de agentes de inteligência artificial para sistemas multi-agentes","ru":"Что такое Agno? Фреймворк для разработки ИИ Агентов для многоагентных систем","ar":"ما هو Agno؟ إطار عمل لإنشاء وكلاء ذكاء اصطناعي لأنظمة متعددة الوكلاء"},"features":{"en":["Supports building AI agents with tools, memory, and structured outputs","Enables creation of multi-agent teams with role-based delegation and collaboration","Implements workflows with conditional branching, loops, and async execution","Integrates with MCP for seamless communication and data exchange","Utilizes AgentOS runtime for efficient and scalable agent execution","Compatible with Gemini CLI for streamlined development and deployment"],"zh":["支持MCP集成","工作流编排","AgentOS运行时","多代理系统构建","条件分支和循环工作流","异步执行"],"ja":["MCP統合","ワークフロー管轄","AgentOSランタイム","マルチエージェントシステム構築","条件分岐とループワークフロー","非同期実行"],"ko":["MCP 통합","워크플로 오케스트레이션","AgentOS 런타임","다중 에이전트 시스템 구축","조건 분기 및 루프 워크플로","비동기 실행"],"es":["Desarrollo de agentes de inteligencia artificial con herramientas y memoria estructurada","Creación de equipos multi-agente con delegación basada en roles y colaboración","Implementación de flujos de trabajo con ramificación condicional, bucles y ejecución asíncrona","Integración MCP para la orquestación de flujos de trabajo","Soporte para AgentOS runtime para la ejecución de agentes de inteligencia artificial"],"fr":["Développement d''agents d''intelligence artificielle avec des outils et une mémoire structurée","Création d''équipes multi-agents avec délégation basée sur les rôles et collaboration","Mise en œuvre de flux de travail avec branchement conditionnel, boucles et exécution asynchrone","Intégration MCP pour l''orchestration de flux de travail","Prise en charge d''AgentOS runtime pour l''exécution d''agents d''intelligence artificielle"],"de":["Entwicklung von KI-Agents mit Werkzeugen und strukturierter Speicher","Erstellung von Multi-Agenten-Teams mit rollenbasierter Delegation und Zusammenarbeit","Implementierung von Workflows mit bedingter Verzweigung, Schleifen und asynchroner Ausführung","MCP-Integration für die Orchestrierung von Workflows","Unterstützung für AgentOS-Laufzeit für die Ausführung von KI-Agents"],"pt":["Desenvolvimento de agentes de inteligência artificial com MCP","Orquestração de fluxo de trabalho com condições e loops","Integração com AgentOS para execução de agentes","Criação de equipes de agentes com delegação baseada em papéis","Suporte a execução assíncrona de agentes"],"ru":["Разработка ИИ Агентов с MCP","Оркестровка рабочих процессов с условиями и циклами","Интеграция с AgentOS для выполнения агентов","Создание команд агентов с делегированием на основе ролей","Поддержка асинхронного выполнения агентов"],"ar":["إنشاء وكلاء ذكاء اصطناعي مع MCP","تنسيق سير العمل مع الشروط والدوائر","التكامل مع AgentOS لتنفيذ الوكلاء","إنشاء فرق وكلاء مع تفويض temel على الأدوار","دعم التنفيذ غير المتزامن للوكلاء"]},"keywords":{"en":["agno setup guide","agno vs gemini","how to use agno for AI agents","agno install","agno alternative","what is agno","agno documentation","agno tutorial","agno workflow orchestration","agno multi agent systems"],"zh":["Agno Skill","AI代理框架","MCP集成","工作流编排","AgentOS运行时","多代理系统","条件分支","循环工作流","异步执行"],"ja":["Agno Skill","AIエージェントフレームワーク","MCP統合","ワークフロー管轄","AgentOSランタイム","マルチエージェントシステム","条件分岐","ループワークフロー","非同期実行"],"ko":["Agno Skill","AI 에이전트 프레임워크","MCP 통합","워크플로 오케스트레이션","AgentOS 런타임","다중 에이전트 시스템","조건 분기","루프 워크플로","비동기 실행"],"es":["agentes de inteligencia artificial","desarrollo de agentes de IA","sistemas multi-agente","integración MCP","orquestación de flujos de trabajo","Agno framework","AgentOS runtime","desarrollo de software de IA"],"fr":["agents d''intelligence artificielle","développement d''agents d''IA","systèmes multi-agents","intégration MCP","orchestration de flux de travail","framework Agno","runtime AgentOS","développement de logiciels d''IA"],"de":["KI-Agents","Entwicklung von KI-Agents","Multi-Agenten-Systeme","MCP-Integration","Workflow-Orchestrierung","Agno-Framework","AgentOS-Laufzeit","Entwicklung von KI-Software"],"pt":["Agno","Desenvolvimento de agentes de inteligência artificial","MCP","Orquestração de fluxo de trabalho","AgentOS","Sistemas multi-agentes","ИИ Агенты"],"ru":["Agno","Разработка ИИ Агентов","MCP","Оркестровка рабочих процессов","AgentOS","Многоагентные системы","ИИ Агенты"],"ar":["Agno","إنشاء وكلاء ذكاء اصطناعي","MCP","تنسيق سير العمل","AgentOS","أنظمة متعددة الوكلاء","وكلاء ذكاء اصطناعي"]}},"owner":"OutlineDriven","repo":"odin-gemini-cli-extension","repoPath":"OutlineDriven/odin-gemini-cli-extension","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.807Z","topics":[],"category":"community","skillMd":{"name":"agno","description":"Agno AI agent framework. Use for building multi-agent systems, AgentOS runtime, MCP server integration, and agentic AI development.","bodyPreview":"# Agno Skill\n\nComprehensive assistance with Agno development - a modern AI agent framework for building production-ready multi-agent systems with MCP integration, workflow orchestration, and AgentOS runtime.\n\n## When to Use This Skill\n\nThis skill should be triggered when:\n\n- **Building AI agents** with tools, memory, and structured outputs\n- **Creating multi-agent teams** with role-based delegation and collaboration\n- **Implementing workflows** with conditional branching, loops, and async execut","body":"# Agno Skill\n\nComprehensive assistance with Agno development - a modern AI agent framework for building production-ready multi-agent systems with MCP integration, workflow orchestration, and AgentOS runtime.\n\n## When to Use This Skill\n\nThis skill should be triggered when:\n\n- **Building AI agents** with tools, memory, and structured outputs\n- **Creating multi-agent teams** with role-based delegation and collaboration\n- **Implementing workflows** with conditional branching, loops, and async execution\n- **Integrating MCP servers** (stdio, SSE, or Streamable HTTP transports)\n- **Deploying AgentOS** with custom FastAPI apps, JWT middleware, or database backends\n- **Working with knowledge bases** for RAG and document processing\n- **Debugging agent behavior** with debug mode and telemetry\n- **Optimizing agent performance** with exponential backoff, retries, and rate limiting\n\n## Key Concepts\n\n### Core Architecture\n\n- **Agent**: Single autonomous AI unit with model, tools, instructions, and optional memory/knowledge\n- **Team**: Collection of agents that collaborate on tasks with role-based delegation\n- **Workflow**: Multi-step orchestration with conditional branching, loops, and parallel execution\n- **AgentOS**: FastAPI-based runtime for deploying agents as production APIs\n\n### MCP Integration\n\n- **MCPTools**: Connect to single MCP server via stdio, SSE, or Streamable HTTP\n- **MultiMCPTools**: Connect to multiple MCP servers simultaneously\n- **Transport Types**: stdio (local processes), SSE (server-sent events), Streamable HTTP (production)\n\n### Memory & Knowledge\n\n- **Session Memory**: Conversation state stored in PostgreSQL, SQLite, or cloud storage (GCS)\n- **Knowledge Base**: RAG-powered document retrieval with vector embeddings\n- **User Memory**: Persistent user-specific memories across sessions\n\n## Quick Reference\n\n### 1. Basic Agent with Tools\n\n```python\nfrom agno.agent import Agent\nfrom agno.tools.duckduckgo import DuckDuckGoTools\n\nagent = Agent(\n    tools=[DuckDuckGoTools()],\n    markdown=True,\n)\n\nagent.print_response(\"Search for the latest AI news\", stream=True)\n```\n\n### 2. Agent with Structured Output\n\n```python\nfrom agno.agent import Agent\nfrom pydantic import BaseModel, Field\n\n\nclass MovieScript(BaseModel):\n    name: str = Field(..., description=\"Movie title\")\n    genre: str = Field(..., description=\"Movie genre\")\n    storyline: str = Field(..., description=\"3 sentence storyline\")\n\n\nagent = Agent(\n    description=\"You help people write movie scripts.\",\n    output_schema=MovieScript,\n)\n\nresult = agent.run(\"Write a sci-fi thriller\")\nprint(result.content.name)  # Access structured output\n```\n\n### 3. MCP Server Integration (stdio)\n\n```python\nimport asyncio\nfrom agno.agent import Agent\nfrom agno.tools.mcp import MCPTools\n\n\nasync def run_agent(message: str) -> None:\n    mcp_tools = MCPTools(command=\"uvx mcp-server-git\")\n    await mcp_tools.connect()\n\n    try:\n        agent = Agent(tools=[mcp_tools])\n        await agent.aprint_response(message, stream=True)\n    finally:\n        await mcp_tools.close()\n\n\nasyncio.run(run_agent(\"What is the license for this project?\"))\n```\n\n### 4. Multiple MCP Servers\n\n```python\nimport asyncio\nimport os\nfrom agno.agent import Agent\nfrom agno.tools.mcp import MultiMCPTools\n\n\nasync def run_agent(message: str) -> None:\n    env = {\n        **os.environ,\n        \"GOOGLE_MAPS_API_KEY\": os.getenv(\"GOOGLE_MAPS_API_KEY\"),\n    }\n\n    mcp_tools = MultiMCPTools(\n        commands=[\n            \"npx -y @openbnb/mcp-server-airbnb --ignore-robots-txt\",\n            \"npx -y @modelcontextprotocol/server-google-maps\",\n        ],\n        env=env,\n    )\n    await mcp_tools.connect()\n\n    try:\n        agent = Agent(tools=[mcp_tools], markdown=True)\n        await agent.aprint_response(message, stream=True)\n    finally:\n        await mcp_tools.close()\n```\n\n### 5. Multi-Agent Team with Role Delegation\n\n```python\nfrom agno.agent import Agent\nfrom agno.team import Team\nfrom agno.tools.duckduckgo import DuckDuckGoTools\nfrom agno.tools.hackernews import HackerNewsTools\n\nresearch_agent = Agent(\n    name=\"Research Specialist\",\n    role=\"Gather information on topics\",\n    tools=[DuckDuckGoTools()],\n    instructions=[\"Find comprehensive information\", \"Cite sources\"],\n)\n\nnews_agent = Agent(\n    name=\"News Analyst\",\n    role=\"Analyze tech news\",\n    tools=[HackerNewsTools()],\n    instructions=[\"Focus on trending topics\", \"Summarize key points\"],\n)\n\nteam = Team(\n    members=[research_agent, news_agent],\n    instructions=[\"Delegate research tasks to appropriate agents\"],\n)\n\nteam.print_response(\"Research AI trends and latest HN discussions\", stream=True)\n```\n\n### 6. Workflow with Conditional Branching\n\n```python\nfrom agno.agent import Agent\nfrom agno.workflow.workflow import Workflow\nfrom agno.workflow.router import Router\nfrom agno.workflow.step import Step\nfrom agno.tools.duckduckgo import DuckDuckGoTools\nfrom agno.tools.hackernews import HackerNewsTools\n\nsimple_researcher = Agent(\n    name=\"Simple Researcher\",\n    tools=[DuckDuckGoTools()],\n)\n\ndeep_researcher = Agent(\n    name=\"Deep Researcher\",\n    tools=[HackerNewsTools()],\n)\n\nworkflow = Workflow(\n    steps=[\n        Router(\n            routes={\n                \"simple_topics\": Step(agent=simple_researcher),\n                \"complex_topics\": Step(agent=deep_researcher),\n            }\n        )\n    ]\n)\n\nworkflow.run(\"Research quantum computing\")\n```\n\n### 7. Agent with Database Session Storage\n\n```python\nfrom agno.agent import Agent\nfrom agno.db.postgres import PostgresDb\n\ndb = PostgresDb(\n    db_url=\"postgresql://user:pass@localhost:5432/agno\", schema=\"agno_sessions\"\n)\n\nagent = Agent(\n    db=db,\n    session_id=\"user-123\",  # Persistent session\n    add_history_to_messages=True,\n)\n\n# Conversations are automatically saved and restored\nagent.print_response(\"Remember my favorite color is blue\")\nagent.print_response(\"What''s my favorite color?\")  # Will remember\n```\n\n### 8. AgentOS with Custom FastAPI App\n\n```python\nfrom fastapi import FastAPI\nfrom agno.agent import Agent\nfrom agno.models.openai import OpenAIChat\nfrom agno.os import AgentOS\n\n# Custom FastAPI app\napp = FastAPI(title=\"Custom App\")\n\n\n@app.get(\"/health\")\ndef health_check():\n    return {\"status\": \"healthy\"}\n\n\n# Add AgentOS routes\nagent_os = AgentOS(\n    agents=[Agent(id=\"assistant\", model=OpenAIChat(id=\"gpt-5-mini\"))],\n    base_app=app,  # Merge with custom app\n)\n\nif __name__ == \"__main__\":\n    agent_os.serve(app=\"custom_app:app\", reload=True)\n```\n\n### 9. Agent with Debug Mode\n\n```python\nfrom agno.agent import Agent\nfrom agno.tools.hackernews import HackerNewsTools\n\nagent = Agent(\n    tools=[HackerNewsTools()],\n    debug_mode=True,  # Enable detailed logging\n    # debug_level=2,  # More verbose output\n)\n\n# See detailed logs of:\n# - Messages sent to model\n# - Tool calls and results\n# - Token usage and timing\nagent.print_response(\"Get top HN stories\")\n```\n\n### 10. Workflow with Input Schema Validation\n\n```python\nfrom typing import List\nfrom agno.agent import Agent\nfrom agno.workflow.workflow import Workflow\nfrom agno.workflow.step import Step\nfrom pydantic import BaseModel, Field\n\n\nclass ResearchTopic(BaseModel):\n    \"\"\"Structured research topic with specific requirements\"\"\"\n\n    topic: str\n    focus_areas: List[str] = Field(description=\"Specific areas to focus on\")\n    target_audience: str = Field(description=\"Who this research is for\")\n    sources_required: int = Field(description=\"Number of sources needed\", default=5)\n\n\nworkflow = Workflow(\n    input_schema=ResearchTopic,  # Validate inputs\n    steps=[Step(agent=Agent(instructions=[\"Research based on focus areas\"]))],\n)\n\n# This will validate the input structure\nworkflow.run(\n    {\n        \"topic\": \"AI Safety\",\n        \"focus_areas\": [\"alignment\", \"interpretability\"],\n        \"target_audience\": \"researchers\",\n        \"sources_required\": 10,\n    }\n)\n```\n\n## Reference Files\n\nThis skill includes comprehensive documentation in `references/`:\n\n### **agentos.md** (22 pages)\n\n- MCP server integration (stdio, SSE, Streamable HTTP)\n- Multiple MCP server connections\n- Custom FastAPI app integration\n- JWT middleware and authentication\n- AgentOS lifespan management\n- Telemetry and monitoring\n\n### **agents.md** (834 pages)\n\n- Agent creation and configuration\n- Tools integration (DuckDuckGo, HackerNews, Pandas, PostgreSQL, Wikipedia)\n- Structured outputs with Pydantic\n- Memory management (session, user, knowledge)\n- Debugging with debug mode\n- Human-in-the-loop patterns\n- Multimodal agents (audio, video, images)\n- Database backends (PostgreSQL, SQLite, GCS)\n- State management and session persistence\n\n### **examples.md** (188 pages)\n\n- Workflow patterns (conditional branching, loops, routers)\n- Team collaboration examples\n- Async streaming workflows\n- Audio/video processing teams\n- Image generation pipelines\n- Multi-step orchestration\n- Input schema validation\n\n### **getting_started.md**\n\n- Installation and setup\n- First agent examples\n- MCP server quickstarts\n- Common patterns and best practices\n\n### **integration.md**\n\n- Third-party integrations\n- API connections\n- Custom tool creation\n- Database setup\n\n### **migration.md**\n\n- Upgrading between versions\n- Breaking changes and migration guides\n- Deprecated features\n\n### **other.md**\n\n- Advanced topics\n- Performance optimization\n- Production deployment\n\n## Working with This Skill\n\n### For Beginners\n\nStart with **getting_started.md** to understand:\n\n- Basic agent creation with `Agent()`\n- Adding tools for web search, databases, etc.\n- Running agents with `.print_response()` or `.run()`\n- Understanding the difference between Agent, Team, and Workflow\n\n**Quick Start Pattern:**\n\n```python\nfrom agno.agent import Agent\nfrom agno.tools.duckduckgo import DuckDuckGoTools\n\nagent = Agent(tools=[DuckDuckGoTools()])\nagent.print_response(\"Your question here\")\n```\n\n### For Intermediate Users\n\nExplore **agents.md** and **examples.md** for:\n\n- Multi-agent teams with role delegation\n- MCP server integration (local tools via stdio)\n- Workflow orchestration with conditional logic\n- Session persistence with databases\n- Structured outputs with Pydantic models\n\n**Team Pattern:**\n\n```python\nfrom agno.team import Team\n\nteam = Team(\n    members=[researcher, analyst, writer],\n    instructions=[\"Delegate tasks based on agent roles\"],\n)\n```\n\n### For Advanced Users\n\nDeep dive into **agentos.md** for:\n\n- AgentOS deployment with custom FastAPI apps\n- Multiple MCP server orchestration\n- Production authentication with JWT middleware\n- Custom lifespan management\n- Performance tuning with exponential backoff\n- Telemetry and monitoring integration\n\n**AgentOS Pattern:**\n\n```python\nfrom agno.os import AgentOS\n\nagent_os = AgentOS(\n    agents=[agent1, agent2], db=PostgresDb(...), base_app=custom_fastapi_app\n)\nagent_os.serve()\n```\n\n### Navigation Tips\n\n1. **Looking for examples?** → Check `examples.md` first for real-world patterns\n2. **Need API details?** → Search `agents.md` for class references and parameters\n3. **Deploying to production?** → Read `agentos.md` for AgentOS setup\n4. **Integrating external tools?** → See `integration.md` for MCP and custom tools\n5. **Debugging issues?** → Enable `debug_mode=True` and check logs\n\n## Common Patterns\n\n### Pattern: MCP Server Connection Lifecycle\n\n```python\nasync def run_with_mcp():\n    mcp_tools = MCPTools(command=\"uvx mcp-server-git\")\n    await mcp_tools.connect()  # Always connect before use\n\n    try:\n        agent = Agent(tools=[mcp_tools])\n        await agent.aprint_response(\"Your query\")\n    finally:\n        await mcp_tools.close()  # Always close when done\n```\n\n### Pattern: Persistent Sessions with Database\n\n```python\nfrom agno.agent import Agent\nfrom agno.db.postgres import PostgresDb\n\ndb = PostgresDb(db_url=\"postgresql://...\")\n\nagent = Agent(\n    db=db,\n    session_id=\"unique-user-id\",\n    add_history_to_messages=True,  # Include conversation history\n)\n```\n\n### Pattern: Conditional Workflow Routing\n\n```python\nfrom agno.workflow.router import Router\n\nworkflow = Workflow(\n    steps=[\n        Router(\n            routes={\n                \"route_a\": Step(agent=agent_a),\n                \"route_b\": Step(agent=b),\n            }\n        )\n    ]\n)\n```\n\n## Resources\n\n### Official Links\n\n- **Documentation**: https://docs.agno.com\n- **GitHub**: https://github.com/agno-agi/agno\n- **Examples**: https://github.com/agno-agi/agno/tree/main/cookbook\n\n### Key Concepts to Remember\n\n- **Always close MCP connections**: Use try/finally blocks or async context managers\n- **Enable debug mode for troubleshooting**: `debug_mode=True` shows detailed execution logs\n- **Use structured outputs for reliability**: Define Pydantic schemas with `output_schema=`\n- **Persist sessions with databases**: PostgreSQL or SQLite for production agents\n- **Disable telemetry if needed**: Set `AGNO_TELEMETRY=false` or `telemetry=False`\n\n## scripts/\n\nAdd helper scripts here for common automation tasks.\n\n## assets/\n\nAdd templates, boilerplate, or example projects here.\n\n## Notes\n\n- This skill was automatically generated from official Agno documentation\n- Reference files preserve structure and examples from source docs\n- Code examples include language detection for better syntax highlighting\n- Quick reference patterns are extracted from real-world usage in the docs\n- All examples are tested and production-ready\n\n## Updating\n\nTo refresh this skill with updated documentation:\n\n1. Re-run the scraper with the same configuration\n2. The skill will be rebuilt with the latest information from docs.agno.com\n"},"lastSynced":"2026-03-07T03:29:39.866Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Developers needing comprehensive assistance with multi-agent system development using Agno framework","zh":"非常适合需要使用Agno框架进行多智能体系统开发的全面辅助的AI智能体开发人员","ja":"Agnoフレームワークを使用したマルチエージェントシステム開発で包括的な支援が必要なAIエージェント開発者に最適","ko":"Agno 프레임워크를 사용하여 다중 에이전트 시스템 개발에 대한 포괄적인 지원이 필요한 AI 에이전트 개발자를 위한 최적의 선택","es":"Perfecto para desarrolladores de Agentes de IA que necesitan asistencia integral para el desarrollo de sistemas de multiagentes utilizando el framework Agno","fr":"Parfait pour les développeurs d''agents IA ayant besoin d''une assistance complète pour le développement de systèmes multi-agents en utilisant le framework Agno","de":"Perfekt für Entwickler von KI-Agents, die umfassende Unterstützung bei der Entwicklung von Multiagentensystemen mit dem Agno-Framework benötigen","pt":"Perfeito para desenvolvedores de Agentes de IA que necessitam de assistência abrangente para o desenvolvimento de sistemas de multiagentes usando o framework Agno","ru":"Идеально для разработчиков агентов ИИ, которым требуется всесторонняя помощь в разработке систем многоагентных систем с использованием фреймворка Agno","ar":"مثالي لمنطقي توسعه الوكلاء الذين يحتاجون إلى مساعدة شاملة لتطوير نظام متعدد الوكلاء باستخدام إطار العمل Agno"},"recommendation":{"en":"Empowers agents to build production-ready multi-agent systems with MCP integration, workflow orchestration, and AgentOS runtime, enabling efficient collaboration and role-based delegation","zh":"赋予智能体建立生产就绪的多智能体系统的能力，具有MCP集成、工作流程编排和AgentOS运行时，实现高效的协作和基于角色的委派","ja":"MCP統合、ワークフローオーケストレーション、AgentOSランタイムを備えた、生成可能なマルチエージェントシステムをエージェントが構築できるようにし、効率的なコラボレーションとロールベースの委任を可能にします","ko":"MCP 통합, 워크플로 오케스트레이션 및 AgentOS 런타임을 갖춘 생성 가능한 다중 에이전트 시스템을 에이전트가 구축할 수 있도록 하여 효율적인 협업 및 역할 기반 위임을 가능하게 함","es":"Habilita a los agentes a construir sistemas multiagentes de producción con integración