INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('OutlineDriven/odin-gemini-cli-extension/agno', 'agno', 'OutlineDriven', 'odin-gemini-cli-extension', 'community', 'agno OutlineDriven odin-gemini-cli-extension community Agno is a modern AI agent framework for building production-ready multi-agent systems. It provides comprehensive assistance with Agno development, including MCP integration, workflow orchestration, and AgentOS runtime. Agno Skill提供了现代AI代理框架的开发工具，支持MCP集成、工作流编排和AgentOS运行时 Agno Skillは、MCP統合、ワークフロー管轄、AgentOSランタイムを備えた現代的なAIエージェントフレームワークの開発を支援 Agno Skill은 MCP 통합, 워크플로 오케스트레이션, AgentOS 런타임을 지원하는 현대적인 AI 에이전트 프레임워크의 개발을 지원 Agno es un framework de desarrollo de agentes de inteligencia artificial para construir sistemas multi-agente de producción con integración MCP y orquestación de flujos de trabajo Agno est un framework de développement d''agents d''intelligence artificielle pour construire des systèmes multi-agents de production avec intégration MCP et orchestration de flux de travail Agno ist ein Framework für die Entwicklung von KI-Agents, um Produktions-Systeme für Multi-Agenten mit MCP-Integration und Workflow-Orchestrierung zu erstellen O Agno é um framework de inteligência artificial para desenvolver sistemas multi-agentes com MCP e orquestração de fluxo de trabalho. Agno - это фреймворк искусственного интеллекта для создания многоагентных систем с MCP и оркестровкой рабочих процессов Agno هو إطار عمل ذكاء اصطناعي لإنشاء أنظمة متعددة الوكلاء مع MCP وتنسيق سير العمل agno setup guide agno vs gemini how to use agno for AI agents agno install agno alternative what is agno agno documentation agno tutorial agno workflow orchestration agno multi agent systems Agno Skill AI代理框架 MCP集成 工作流编排 AgentOS运行时 多代理系统 条件分支 循环工作流 异步执行 Supports building AI agents with tools, memory, and structured outputs Enables creation of multi-agent teams with role-based delegation and collaboration Implements workflows with conditional branching, loops, and async execution Integrates with MCP for seamless communication and data exchange Utilizes AgentOS runtime for efficient and scalable agent execution Compatible with Gemini CLI for streamlined development and deployment Agno is a cutting-edge AI agent framework that enables developers to build complex multi-agent systems with ease, leveraging tools like Gemini CLI and AgentOS.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HoangNguyen0403/agent-skills-standard/Flutter Notifications', 'community', 'HoangNguyen0403', 'agent-skills-standard', 'HoangNguyen0403/agent-skills-standard', 'Flutter Notifications', 0, 0, 60, '2026-02-20T04:13:19.578Z', '2026-03-01T07:21:17.105Z', 'bf266e59d83bf6ca47a130267af6f3d753230869653f0568164264b21806c1ae', '{"id":"HoangNguyen0403/agent-skills-standard/Flutter Notifications","name":"Flutter Notifications","description":{"zh":"Flutter通知是使用Firebase Cloud Messaging和flutter_local_notifications实现的推送通知和本地通知","ja":"Flutter通知はFirebase Cloud Messagingとflutter_local_notificationsを使用したプッシュ通知とローカル通知です","ko":"Flutter 알림은 Firebase Cloud Messaging과 flutter_local_notifications를 사용하여 푸시 알림 및 로컬 알림을 구현합니다","es":"Notificaciones push y locales para Flutter utilizando Firebase Cloud Messaging y flutter_local_notifications","fr":"Notifications push et locales pour Flutter utilisant Firebase Cloud Messaging et flutter_local_notifications","de":"Push- und Lokalbenachrichtigungen für Flutter mit Firebase Cloud Messaging und flutter_local_notifications","pt":"Notificações push e locais para Flutter usando Firebase Cloud Messaging e flutter_local_notifications","ru":"Уведомления Flutter: push-уведомления и локальные уведомления с помощью Firebase Cloud Messaging и flutter_local_notifications","ar":"إشعارات Flutter: إشعارات الضغط والمحلية باستخدام Firebase Cloud Messaging و flutter_local_notifications","en":"Push notifications and local notifications for Flutter using Firebase Cloud Messaging and flutter_local_notifications."},"seo":{"title":{"zh":"Flutter AIエージェント通知","ja":"Flutter AIエージェント通知","ko":"Flutter AI 에이전트 알림","es":"Notificaciones Flutter con Firebase y herramientas de AI","fr":"Notifications Flutter avec Firebase et outils d''IA","de":"Flutter-Benachrichtigungen mit Firebase und KI-Tools","pt":"Notificações Flutter com Ferramentas de IA","ru":"ИИ Агенты: Уведомления Flutter","ar":"العملاء الذكية: إشعارات Flutter","en":"Flutter Notifications"},"description":{"zh":"Flutter通知是使用Firebase Cloud Messaging和flutter_local_notifications实现的推送通知和本地通知","ja":"Flutter通知はFirebase Cloud Messagingとflutter_local_notificationsを使用したプッシュ通知とローカル通知です","ko":"Flutter 알림은 Firebase Cloud Messaging과 flutter_local_notifications를 사용하여 푸시 알림 및 로컬 알림을 구현합니다","es":"Notificaciones push y locales para Flutter utilizando Firebase Cloud Messaging y flutter_local_notifications","fr":"Notifications push et locales pour Flutter utilisant Firebase Cloud Messaging et flutter_local_notifications","de":"Push- und Lokalbenachrichtigungen für Flutter mit Firebase Cloud Messaging und flutter_local_notifications","pt":"Notificações push e locais para Flutter usando Firebase Cloud Messaging e flutter_local_notifications","ru":"Уведомления Flutter: push-уведомления и локальные уведомления с помощью Firebase Cloud Messaging и flutter_local_notifications","ar":"إشعارات Flutter: إشعارات الضغط والمحلية باستخدام Firebase Cloud Messaging و flutter_local_notifications","en":"Push notifications and local notifications for Flutter using Firebase Cloud Messaging and flutter_local_notifications."},"definition":{"en":"Push notifications and local notifications for Flutter using Firebase Cloud Messaging and flutter_local_notifications."},"features":{"zh":["使用Firebase Cloud Messaging实现推送通知","使用flutter_local_notifications实现本地通知","支持自定义通知内容","支持多种通知触发方式","兼容多种移动设备"],"ja":["Firebase Cloud Messagingを使用したプッシュ通知","flutter_local_notificationsを使用したローカル通知","カスタム通知コンテンツのサポート","複数の通知トリガー方式のサポート","複数のモバイルデバイスの互換性"],"ko":["Firebase Cloud Messaging을 사용한 푸시 알림","flutter_local_notifications을 사용한 로컬 알림","사용자 정의 알림 내용 지원","다중 알림 트리거 방법 지원","다중 모바일 기기의 호환성"],"es":["Notificaciones push con Firebase Cloud Messaging","Notificaciones locales con flutter_local_notifications","Personalización de notificaciones","Compatibilidad con múltiples plataformas","Integración con herramientas de AI"],"fr":["Notifications push avec Firebase Cloud Messaging","Notifications locales avec flutter_local_notifications","Personnalisation des notifications","Compatibilité avec plusieurs plateformes","Intégration avec des outils d''IA"],"de":["Push-Benachrichtigungen mit Firebase Cloud Messaging","Lokalbenachrichtigungen mit flutter_local_notifications","Anpassung der Benachrichtigungen","Kompatibilität mit mehreren Plattformen","Integration mit KI-Tools"],"pt":["Notificações push com Firebase Cloud Messaging","Notificações locais com flutter_local_notifications","Personalização de notificações","Suporte a múltiplos canais de notificação","Integração com aplicativos Flutter"],"ru":["Push-уведомления с Firebase Cloud Messaging","Локальные уведомления с flutter_local_notifications","Настройка уведомлений","Поддержка нескольких каналов уведомлений","Интеграция с приложениями Flutter"],"ar":["إشعارات الضغط مع Firebase Cloud Messaging","إشعارات المحلية مع flutter_local_notifications","تخصيص الإشعارات","دعم قنوات الإشعار المتعددة","التكامل مع تطبيقات Flutter"]},"keywords":{"zh":["Flutter通知实现","Firebase Cloud Messaging教程","flutter_local_notifications使用","Flutter推送通知","Flutter本地通知","AIエージェント技术","移动应用程序通知"],"ja":["Flutter通知の実装","Firebase Cloud Messagingチュートリアル","flutter_local_notificationsの使用","Flutterプッシュ通知","Flutterローカル通知","AIエージェント技術","モバイルアプリケーションの通知"],"ko":["Flutter 알림 구현","Firebase Cloud Messaging 튜토리얼","flutter_local_notifications 사용","Flutter 푸시 알림","Flutter 로컬 알림","AI 에이전트 기술","모바일 애플리케이션의 알림"],"es":["notificaciones flutter","herramientas de ai para notificaciones","firebase cloud messaging","flutter_local_notifications","cómo usar notificaciones en flutter","guía de instalación de notificaciones en flutter","alternativas a notificaciones en flutter"],"fr":["notifications flutter","outils d''ia pour les notifications","firebase cloud messaging","flutter_local_notifications","comment utiliser les notifications dans flutter","guide d''installation des notifications dans flutter","alternatives aux notifications dans flutter"],"de":["flutter-benachrichtigungen","ki-tools für benachrichtigungen","firebase cloud messaging","flutter_local_notifications","wie man benachrichtigungen in flutter verwendet","anleitung zur installation von benachrichtigungen in flutter","alternativen zu benachrichtigungen in flutter"],"pt":["notificações flutter","como usar notificações flutter","notificações push flutter","notificações locais flutter","flutter local notifications","firebase cloud messaging flutter","guia de instalação notificações flutter","configuração notificações flutter"],"ru":["уведомления flutter","как использовать уведомления flutter","push-уведомления flutter","локальные уведомления flutter","flutter локальные уведомления","firebase cloud messaging flutter","руководство по установке уведомлений flutter","настройка уведомлений flutter"],"ar":["إشعارات flutter","كيفية استخدام إشعارات flutter","إشعارات الضغط flutter","إشعارات المحلية flutter","flutter إشعارات المحلية","firebase cloud messaging flutter","دليل تثبيت إشعارات flutter","إعداد إشعارات flutter"]}},"owner":"HoangNguyen0403","repo":"agent-skills-standard","repoPath":"HoangNguyen0403/agent-skills-standard","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"Flutter Notifications","description":"Push notifications and local notifications for Flutter using Firebase Cloud Messaging and flutter_local_notifications.","bodyPreview":"# Flutter Notifications\n\n## **Priority: P1 (OPERATIONAL)**\n\nPush and local notifications interactions.\n\n## Guidelines\n\n- **Stack**: Use `firebase_messaging` (Push) + `flutter_local_notifications` (Local/Foreground).\n- **Lifecycle**: Handle all 3 states explicitly: Foreground, Background, Terminated.\n- **Permissions**: Prime users with a custom dialog explaining benefits _before_ system request.\n- **Navigation**: Validate notification payload data strictly before navigating.\n- **Badges**: Manuall","body":"# Flutter Notifications\n\n## **Priority: P1 (OPERATIONAL)**\n\nPush and local notifications interactions.\n\n## Guidelines\n\n- **Stack**: Use `firebase_messaging` (Push) + `flutter_local_notifications` (Local/Foreground).\n- **Lifecycle**: Handle all 3 states explicitly: Foreground, Background, Terminated.\n- **Permissions**: Prime users with a custom dialog explaining benefits _before_ system request.\n- **Navigation**: Validate notification payload data strictly before navigating.\n- **Badges**: Manually clear iOS app badges when visiting relevant screens.\n\n[Implementation Details](references/implementation.md)\n\n## Anti-Patterns\n\n- **No Unconditional Permission**: Don''t ask on startup without context.\n- **No Missing State Handlers**: Forgetting `getInitialMessage()` breaks \"open from terminated\".\n- **No Forgotten Badge Clear**: Leaving notifications un-cleared frustrates users.\n- **No Direct Navigation**: Parsing JSON payloads without validation leads to crashes.\n\n## Related Topics\n\nflutter-navigation | mobile-ux-core | firebase/fcm\n"},"lastSynced":"2026-03-01T07:21:17.105Z","agentAnalysis":{"suitability":{"en":"Ideal for Mobile Agents requiring seamless push and local notification integration in Flutter applications.","zh":"适用于需要在 Flutter 应用程序中实现无缝推送和本地通知集成的移动代理。","ja":"Flutter アプリケーションでシームレスなプッシュとローカル通知の統合を必要とするモバイル エージェントに適しています。","ko":"플러터 애플리케이션에서 무결점 푸시 및 로컬 알림 통합이 필요한 모바일 에이전트에 적합합니다.","es":"Ideal para agentes móviles que requieren una integración perfecta de notificaciones push y locales en aplicaciones Flutter.","fr":"Idéal pour les agents mobiles nécessitant une intégration transparente des notifications push et locales dans les applications Flutter.","de":"Ideal für Mobile Agents, die eine nahtlose Integration von Push- und Lokalbenachrichtigungen in Flutter-Anwendungen erfordern.","pt":"Ideal para Agentes Móveis que exigem integração de push e notificação local sem interrupções em aplicações Flutter.","ru":"Идеально для Мобильных Агентов, требующих бесшовной интеграции push-уведомлений и локальных уведомлений в приложениях Flutter.","ar":"مثالي للوكلاء المحمولين الذين يتطلبون تكامل الإشعارات الدفعية والإشعارات المحلية دون انقطاع في تطبيقات Flutter."},"recommendation":{"en":"Empowers agents to handle push notifications via firebase_messaging and local notifications using flutter_local_notifications, ensuring robust lifecycle management across foreground, background, and terminated states, while also facilitating custom permission dialogs and strict navigation validation.","zh":"赋予代理处理通过 firebase_messaging 进行的推送通知和使用 flutter_local_notifications 进行的本地通知的能力，确保在前台、后台和终止状态之间实现强大的生命周期管理，同时也方便自定义权限对话框和严格的导航验证。","ja":"firebase_messaging を介したプッシュ通知と flutter_local_notifications を介したローカル通知の処理をエージェントに可能にし、前景、背景、終了状態間のロバストなライフサイクル管理を保証しながら、カスタムのパーミッション ダイアログと厳格なナビゲーションの検証も容易にします。","ko":"에이전트가 firebase_messaging을 통해 푸시 알림과 flutter_local_notifications을 통해 로컬 알림을 처리할 수 있도록 하여, 전경, 배경, 종료 상태 간의 강력한 수명 주기 관리를 보장同时에도 사용자 지정 권한 대화 상자 및 엄격한 탐색 검증을 용이하게 합니다.","es":"Habilita a los agentes a manejar notificaciones push a través de firebase_messaging y notificaciones locales utilizando flutter_local_notifications, garantizando una gestión robusta del ciclo de vida en los estados de primer plano, segundo plano y terminado, y también facilitando diálogos de permisos personalizados y una validación estricta de la navegación.","fr":"Permet aux agents de gérer les notifications push via firebase_messaging et les notifications locales en utilisant flutter_local_notifications, assurant une gestion robuste du cycle de vie à travers les états avant-plan, arrière-plan et terminé, tout en facilitant les boîtes de dialogue de permission personnalisées et une validation stricte de la navigation.","de":"Ermächtigt Agenten, Push-Benachrichtigungen über firebase_messaging und lokale Benachrichtigungen unter Verwendung von flutter_local_notifications zu verwalten, wodurch eine robuste Lebenszyklusverwaltung über die Zustände im Vordergrund, Hintergrund und beendet sichergestellt wird, während auch benutzerdefinierte Berechtigungsdialoge und eine strenge Navigationsvalidierung erleichtert werden.","pt":"Habilita os agentes a lidarem com notificações push via firebase_messaging e notificações locais usando flutter_local_notifications, garantindo um gerenciamento de ciclo de vida robusto em estados de primeiro plano, segundo plano e terminados, além de facilitar diálogos de permissão personalizados e validação de navegação estrita.","ru":"Наделяет агентов возможностью обрабатывать push-уведомления через firebase_messaging и локальные уведомления с помощью flutter_local_notifications, обеспечивая прочное управление жизненным циклом на протяжении всех состояний: foreground, background и завершенных, а также облегчая создание диалогов запроса разрешений по собственному дизайну и строгую проверку навигации.","ar":"تمكين الوكلاء من التعامل مع الإشعارات الدفعية عبر firebase_messaging والإشعارات المحلية باستخدام flutter_local_notifications، مما يضمن إدارة دورة حياة قوية عبر الحالات الثلاث: الأمامية والخلفية والإنهائية، بالإضافة إلى تسهيل حوارات التصريح المخصصة وعمليات التحقق الصارمة للتنقل."},"useCases":{"en":["Implementing custom notification permission dialogs to enhance user experience","Handling lifecycle states for notifications in Flutter applications","Validating notification payload data for secure navigation"],"zh":["实现自定义通知权限对话框以增强用户体验","处理 Flutter 应用程序中的通知生命周期状态","验证通知有效载荷数据以进行安全导航"],"ja":["ユーザーエクスペリエンスを向上させるためのカスタム通知パーミッション ダイアログの実装","Flutter アプリケーションでの通知ライフサイクル状態の処理","セキュアなナビゲーションのための通知ペイロード データの検証"],"ko":["사용자 경험을 향상시키기 위한 사용자 지정 알림 권한 대화 상자의 구현","플러터 애플리케이션의 알림 수명 주기 상태 처리","보안 탐색을 위한 알림有效载荷 데이터의 검증"],"es":["Implementar diálogos de permisos de notificación personalizados para mejorar la experiencia del usuario","Gestionar estados del ciclo de vida para notificaciones en aplicaciones Flutter","Validar datos de carga útil de notificación para una navegación segura"],"fr":["Mettre en œuvre des boîtes de dialogue de permission de notification personnalisées pour améliorer l''expérience utilisateur","Gérer les états du cycle de vie pour les notifications dans les applications Flutter","Valider les données de charge utile de notification pour une navigation sécurisée"],"de":["Implementieren von benutzerdefinierten Berechtigungsdialogen für Benachrichtigungen, um die Benutzererfahrung zu verbessern","Verwalten von Lebenszykluszuständen für Benachrichtigungen in Flutter-Anwendungen","Validieren von Nutzlastdaten für Benachrichtigungen für eine sichere Navigation"],"pt":["Implementar diálogos de permissão de notificação personalizados para melhorar a experiência do usuário","Lidar com estados de ciclo de vida para notificações em aplicações Flutter","Validar dados de carga de notificação para navegação segura"],"ru":["Реализация настраиваемых диалогов разрешения уведомлений для улучшения пользовательского опыта","Обработка состояний жизненного цикла для уведомлений в приложениях Flutter","Проверка данных полезной нагрузки уведомлений для безопасной навигации"],"ar":["تنفيذ حوارات تصريح إشعار مخصصة لتحسين تجربة المستخدم","التعامل مع حالات دورة حياة للإشعارات في تطبيقات Flutter"," التحقق من بيانات حمولة الإشعار للتنقل الآمن"]},"limitations":{"en":["Requires integration with firebase_messaging for push notifications","Needs flutter_local_notifications for local and foreground notifications","Manual badge management required"],"zh":["需要与 firebase_messaging 集成以进行推送通知","需要 flutter_local_notifications 以进行本地和前台通知","需要手动管理徽章"],"ja":["プッシュ通知のために firebase_messaging と統合する必要がある","ローカルおよび前景通知のために flutter_local_notifications が必要","マニュアルでバッジを管理する必要がある"],"ko":["푸시 알림을 위해 firebase_messaging과 통합해야 함","로컬 및 전경 알림을 위해 flutter_local_notifications이 필요","수동으로 배지를 관리해야 함"],"es":["Requiere integración con firebase_messaging para notificaciones push","Necesita flutter_local_notifications para notificaciones locales y de primer plano","Se requiere una gestión manual de insignias"],"fr":["Nécessite une intégration avec firebase_messaging pour les notifications push","A besoin de flutter_local_notifications pour les notifications locales et de premier plan","Une gestion manuelle des badges est requise"],"de":["Benötigt eine Integration mit firebase_messaging für Push-Benachrichtigungen","Benötigt flutter_local_notifications für lokale und Vordergrundbenachrichtigungen","Eine manuelle Badge-Verwaltung ist erforderlich"],"pt":["Exige integração com firebase_messaging para notificações push","Necessita de flutter_local_notifications para notificações locais e em primeiro plano","Requer gerenciamento manual de insignias"],"ru":["Требует интеграции с firebase_messaging для push-уведомлений","Требует flutter_local_notifications для локальных и foreground уведомлений","Требует ручного управления значками"],"ar":["يتطلب تكاملًا مع firebase_messaging للإشعارات الدفعية","يحتاج إلى flutter_local_notifications للإشعارات المحلية وأمامية","يتطلب إدارة يدوية للشعارات"]},"version":3},"contentHash":"bf266e59d83bf6ca47a130267af6f3d753230869653f0568164264b21806c1ae","qualityScore":60}');
