INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HoangNguyen0403/agent-skills-standard/Flutter Notifications', 'Flutter Notifications', 'HoangNguyen0403', 'agent-skills-standard', 'community', 'Flutter Notifications HoangNguyen0403 agent-skills-standard community Flutter通知是使用Firebase Cloud Messaging和flutter_local_notifications实现的推送通知和本地通知 Flutter通知はFirebase Cloud Messagingとflutter_local_notificationsを使用したプッシュ通知とローカル通知です Flutter 알림은 Firebase Cloud Messaging과 flutter_local_notifications를 사용하여 푸시 알림 및 로컬 알림을 구현합니다 Notificaciones push y locales para Flutter utilizando Firebase Cloud Messaging y flutter_local_notifications Notifications push et locales pour Flutter utilisant Firebase Cloud Messaging et flutter_local_notifications Push- und Lokalbenachrichtigungen für Flutter mit Firebase Cloud Messaging und flutter_local_notifications Notificações push e locais para Flutter usando Firebase Cloud Messaging e flutter_local_notifications Уведомления Flutter: push-уведомления и локальные уведомления с помощью Firebase Cloud Messaging и flutter_local_notifications إشعارات Flutter: إشعارات الضغط والمحلية باستخدام Firebase Cloud Messaging و flutter_local_notifications Push notifications and local notifications for Flutter using Firebase Cloud Messaging and flutter_local_notifications. Flutter通知实现 Firebase Cloud Messaging教程 flutter_local_notifications使用 Flutter推送通知 Flutter本地通知 AIエージェント技术 移动应用程序通知 Push notifications and local notifications for Flutter using Firebase Cloud Messaging and flutter_local_notifications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dojoengine/daimyo/create-a-plan', 'community', 'dojoengine', 'daimyo', 'dojoengine/daimyo', 'create-a-plan', 0, 0, 60, '2026-03-06T12:59:22.218Z', '2026-03-06T14:01:29.377Z', '76755dca1a8ade8c8e895de1efdf62f805b008bf3c8a9c427ad3a6c8bb1c1ddd', '{"id":"dojoengine/daimyo/create-a-plan","name":"create-a-plan","description":{"en":"The create-a-plan skill runs a structured technical interview to turn ideas into implementable plans, outputting organized foundations, workstreams, and integration plans for parallel execution.","zh":"Create-a-Plan 技术面试技能通过对粗略的想法或现有规格进行结构化的技术面试，生成详细的可执行计划","ja":"Create-a-Plan スキルは、粗略なアイデアや既存の仕様を詳細な実行可能な計画に変換するために構造化された技術面接を実行します","ko":"Create-a-Plan 개발 스킬은 아이디어나 기존 사양을 구체적인 실행 가능한 계획으로 전환하기 위해 구조화된 기술 면접을 수행합니다","es":"La habilidad ''create-a-plan'' ejecuta una entrevista técnica estructurada para convertir una idea o especificación en un plan implementable","fr":"La compétence ''create-a-plan'' exécute un entretien technique structuré pour convertir une idée ou une spécification en un plan réalisable","de":"Die Fähigkeit ''create-a-plan'' führt ein strukturiertes technisches Interview durch, um eine Idee oder Spezifikation in einen umsetzbaren Plan umzuwandeln","pt":"O Create-a-Plan é uma ferramenta de planejamento de projetos que cria planos detalhados e implementáveis a partir de ideias ou especificações existentes","ru":"Create-a-Plan - это инструмент для создания детальных планов проектов, который преобразует грубые идеи или существующие спецификации в реализуемые планы","ar":"Create-a-Plan هو أداة لتخطيط المشاريع التي تحول الأفكار أو المواصفات الحالية إلى مخططات تفصيلية وقابلة للتنفيذ"},"seo":{"title":{"en":"create-a-plan: Structured Technical Interview Setup Guide...","zh":"Create-a-Plan 技术面试指南：从想法到详细计划","ja":"Create-a-Plan スキル：AIエージェントを使用した詳細計画の作成","ko":"Create-a-Plan 개발 가이드: 아이디어를 구체적인 계획으로","es":"Crear un Plan con Herramientas de AI: Guía de Configuración","fr":"Créer un Plan avec des Outils d''IA: Guide de Mise en Place","de":"Erstellen Sie einen Plan mit KI-Tools: Einrichtungsleitfaden","pt":"Guia de Configuração do Create-a-Plan: Ferramenta de Plan...","ru":"Настройка Create-a-Plan: Инструмент для Создания Детально...","ar":"دليل إعداد خطة Create-a-Plan: أداة إنشاء مخطط تفصيلي للمش..."},"description":{"en":"Transform rough ideas into detailed plans with create-a-plan. Get started now and streamline your development workflow!","zh":"使用 Create-a-Plan 技术面试技能，将粗略的想法或现有规格转化为详细的可执行计划","ja":"AIエージェントを使用して、詳細な実行可能な計画を作成します。Create-a-Plan スキルの詳細はこちら","ko":"Create-a-Plan 개발 스킬을 사용하여 아이디어를 구체적인 계획으로 전환하고 병렬 실행을 위한 구조화된 출력을 생성합니다","es":"Aprende a crear un plan detallado con la habilidad ''create-a-plan'' y herramientas de AI para desarrolladores","fr":"Découvrez comment créer un plan détaillé avec la compétence ''create-a-plan'' et des outils d''IA pour les développeurs","de":"Erfahren Sie, wie Sie mit der Fähigkeit ''create-a-plan'' und KI-Tools einen detaillierten Plan für Entwickler erstellen","pt":"Aprenda a configurar o Create-a-Plan, uma ferramenta de planejamento de projetos que usa inteligência artificial para criar planos detalhados e implementáveis","ru":"Узнайте, как настроить Create-a-Plan, инструмент для создания детальных планов проектов с помощью ИИ Агентов и параллельного выполнения","ar":"تعرف على كيفية إعداد خطة Create-a-Plan، أداة لتخطيط المشاريع التي تستخدم الذكاء الاصطناعي لإنشاء مخططات تفصيلية وقابلة للتنفيذ"},"definition":{"en":"create-a-plan is a skill that facilitates the creation of detailed, implementable plans from rough ideas or existing specs through a structured technical interview process.","zh":"Create-a-Plan 是一种技术面试技能，用于将粗略的想法或现有规格转化为详细的可执行计划","ja":"Create-a-Plan は、AIエージェントを使用して、粗略なアイデアや既存の仕様を詳細な実行可能な計画に変換する技術面接スキルです","ko":"Create-a-Plan은 아이디어나 기존 사양을 구체적인 실행 가능한 계획으로 전환하는 기술 면접 스킬입니다","es":"La habilidad ''create-a-plan'' es una herramienta de AI que ayuda a los desarrolladores a crear planes detallados a partir de ideas o especificaciones","fr":"La compétence ''create-a-plan'' est un outil d''IA qui aide les développeurs à créer des plans détaillés à partir d''idées ou de spécifications","de":"Die Fähigkeit ''create-a-plan'' ist ein KI-Tool, das Entwicklern hilft, detaillierte Pläne aus Ideen oder Spezifikationen zu erstellen","pt":"O Create-a-Plan é uma ferramenta de inteligência artificial que cria planos de projeto detalhados e implementáveis","ru":"Create-a-Plan - это инструмент ИИ Агентов, который создает детальные и реализуемые планы проектов","ar":"Create-a-Plan هو أداة ذكاء اصطناعي لإنشاء مخططات تفصيلية وقابلة للتنفيذ للمشاريع"},"features":{"en":["Runs a structured technical interview to turn rough ideas into detailed plans","Accepts input from spec or plan files (e.g., SPEC.md, PLAN.md, RFC.md)","Processes rough descriptions of desired builds or feature requests","Outputs organized plans for parallel execution, including foundations, independent workstreams, and merge/integration plans"],"zh":["结构化的技术面试流程","支持从 SPEC.md、PLAN.md、RFC.md 文件中读取输入","生成详细的可执行计划","输出组织为并行执行","支持多种输入格式"],"ja":["構造化された技術面接プロセス","SPEC.md、PLAN.md、RFC.md ファイルからの入力読み込みをサポート","詳細な実行可能な計画を生成","出力は並列実行用に組織化","複数の入力形式をサポート"],"ko":["구조화된 기술 면접 프로세스","SPEC.md, PLAN.md, RFC.md 파일로부터 입력을 읽는 것을 지원","세부적인 실행 가능한 계획을 생성","출력은 병렬 실행을 위한 구조화","다중 입력 형식을 지원"],"es":["Ejecuta entrevistas técnicas estructuradas","Convierte ideas o especificaciones en planes implementables","Organiza la salida para la ejecución paralela","Soporta la entrada de archivos de especificación o planes existentes","Permite la descripción de características o problemas","Genera un plan detallado con fundamentos, flujos de trabajo independientes y merge"],"fr":["Exécute des entretiens techniques structurés","Convertissez des idées ou des spécifications en plans réalisables","Organise la sortie pour l''exécution parallèle","Prend en charge l''entrée de fichiers de spécification ou de plans existants","Permet la description de fonctionnalités ou de problèmes","Génère un plan détaillé avec des fondements, des flux de travail indépendants et un merge"],"de":["Führt strukturierte technische Interviews durch","Wandelt Ideen oder Spezifikationen in umsetzbare Pläne um","Organisiert die Ausgabe für die parallele Ausführung","Unterstützt die Eingabe von Spezifikations- oder Plan-Dateien","Ermöglicht die Beschreibung von Funktionen oder Problemen","Erstellt einen detaillierten Plan mit Grundlagen, unabhängigen Arbeitsabläufen und Merge"],"pt":["Criação de planos de projeto detalhados a partir de ideias ou especificações existentes","Execução paralela de tarefas independentes","Integração de trabalhos e fusão de resultados","Suporte a arquivos de especificação e plano (por exemplo, SPEC.md, PLAN.md, RFC.md)","Interface de usuário intuitiva para fornecer descrições de recursos ou problemas"],"ru":["Создание детальных планов проектов из грубых идей или существующих спецификаций","Параллельное выполнение независимых задач","Интеграция работ и слияние результатов","Поддержка файлов спецификации и плана (например, SPEC.md, PLAN.md, RFC.md)","Интуитивно понятный интерфейс пользователя для предоставления описаний функций или проблем"],"ar":["إنشاء مخططات تفصيلية للمشاريع من الأفكار أو المواصفات الحالية","تنفيذ متوازي للعمليات المستقلة","دمج الأعمال ودمج النتائج","دعم ملفات المواصفات والمخطط (على سبيل المثال، SPEC.md، PLAN.md، RFC.md)","واجهة مستخدم直观ية لتقديم وصفات الميزات أو المشاكل"]},"keywords":{"en":["how to use create-a-plan","create-a-plan setup guide","create-a-plan alternative","create-a-plan vs project management tools","what is create-a-plan","create-a-plan install","create-a-plan for AI agents","structured technical interview","parallel execution planning"],"zh":["Create-a-Plan 技术面试","AI 技术面试工具","详细计划生成","并行执行计划","技术面试流程","SPEC.md 文件读取","PLAN.md 文件读取","RFC.md 文件读取"],"ja":["Create-a-Plan 技術面接","AIエージェント技術面接","詳細計画生成","並列実行計画","技術面接プロセス","SPEC.md ファイル読み込み","PLAN.md ファイル読み込み","RFC.md ファイル読み込み"],"ko":["Create-a-Plan 기술 면접","AI 에이전트 기술 면접","세부적인 계획 생성","병렬 실행 계획","기술 면접 프로세스","SPEC.md 파일 읽기","PLAN.md 파일 읽기","RFC.md 파일 읽기"],"es":["herramientas de AI para desarrolladores","crear un plan de proyecto","entrevista técnica estructurada","planes implementables","ejecución paralela","desarrollo de software","gestión de proyectos","planificación de proyectos","herramientas de productividad para desarrolladores"],"fr":["outils d''IA pour les développeurs","créer un plan de projet","entretien technique structuré","plans réalisables","exécution parallèle","développement de logiciels","gestion de projets","planification de projets","outils de productivité pour les développeurs"],"de":["KI-Tools für Entwickler","Erstellen eines Projektplans","strukturiertes technisches Interview","umsetzbare Pläne","parallele Ausführung","Software-Entwicklung","Projektmanagement","Projektplanung","Produktivitäts-Tools für Entwickler"],"pt":["ferramenta de planejamento de projetos","inteligência artificial","criação de planos","execução paralela","integração de trabalhos","arquivos de especificação","desenvolvimento de software","gerenciamento de projetos"],"ru":["инструмент планирования проектов","ИИ Агенты","создание планов","параллельное выполнение","интеграция работ","файлы спецификации","разработка программного обеспечения","управление проектами"],"ar":["أداة تخطيط المشاريع","وكلاء الذكاء الاصطناعي","إنشاء مخططات","تنفيذ متوازي","دمج الأعمال","ملفات المواصفات","تطوير البرمجيات","إدارة المشاريع"]}},"owner":"dojoengine","repo":"daimyo","repoPath":"dojoengine/daimyo","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.218Z","topics":[],"category":"community","skillMd":{"name":"create-a-plan","description":"Conduct a focused technical planning interview to produce an implementable, parallelizable plan or spec with clear dependencies, risks, and open questions.","bodyPreview":"# Create a Plan Skill\n\nThis skill runs a structured technical interview to turn a rough idea or an existing spec into a detailed, implementable plan. The output is organized for parallel execution: foundations first, then independent workstreams, then merge and integration.\n\n## Invocation\n\nThe user will provide one of:\n- A path to a spec or plan file (for example: `SPEC.md`, `PLAN.md`, `RFC.md`)\n- A rough description of what they want to build\n- A feature request or problem statement\n\nOutput is","body":"# Create a Plan Skill\n\nThis skill runs a structured technical interview to turn a rough idea or an existing spec into a detailed, implementable plan. The output is organized for parallel execution: foundations first, then independent workstreams, then merge and integration.\n\n## Invocation\n\nThe user will provide one of:\n- A path to a spec or plan file (for example: `SPEC.md`, `PLAN.md`, `RFC.md`)\n- A rough description of what they want to build\n- A feature request or problem statement\n\nOutput is always written to `PLAN.md` in the repo root.\n\n## Process\n\n### Phase 0: Preflight\n\n1. If a file path is provided, read it first and note goals, non-goals, constraints, and gaps.\n2. Confirm you will produce `PLAN.md` as the output in the repo root. If `PLAN.md` already exists, update it rather than creating a new file.\n\n### Phase 1: Discovery\n\nSummarize what is known, then identify missing details. Focus on:\n- Goals and non-goals\n- Constraints (time, budget, platform, dependencies)\n- Success metrics and acceptance criteria\n\n### Phase 2: Deep Interview\n\nUse the `AskUserQuestion` (Claude) and/or `request_user_input` (Codex) tools in rounds. Ask 1-3 questions per round. Each round should go deeper and avoid repeating what is already known.\n\nCRITICAL RULES:\n1. Never ask obvious questions. If the codebase or spec already answers it, do not ask it again.\n2. Ask about edge cases and failure modes.\n3. Probe for hidden complexity (state transitions, migrations, concurrency).\n4. Challenge assumptions when they create risk or ambiguity.\n5. Identify parallelization boundaries and serial dependencies.\n6. If the user is unsure, propose a default and ask for confirmation.\n\nQuestion categories to cover as relevant:\n- Technical architecture and data flow\n- Data model and state management\n- API contracts and versioning\n- Caching and invalidation\n- Background jobs, retries, and idempotency\n- Error handling and recovery\n- Observability and debugging\n- Performance, scale, and SLAs\n- Security, privacy, and compliance\n- Integrations and external dependencies\n- UX flows, accessibility, and responsiveness\n- Rollout, migration, and rollback\n- Testing strategy and validation\n\n### Phase 3: Dependency Analysis\n\nIdentify:\n1. Serial dependencies that must complete first\n2. Parallel workstreams that can run independently\n3. Merge points where work reconvenes\n\n### Phase 4: Plan Generation\n\nWrite the final plan to `PLAN.md`. Ensure the plan includes concrete verification steps the agent can run end to end. If the user only wants a plan in chat, provide it inline and mention that it would be written to `PLAN.md`.\n\n## Output Format\n\nThe generated plan MUST follow this structure:\n\n```markdown\n# [Feature Name] Implementation Plan\n\n## Overview\n[2-3 sentence summary of what this implements and why]\n\n## Goals\n- [Explicit goal 1]\n- [Explicit goal 2]\n\n## Non-Goals\n- [What this explicitly does NOT do]\n\n## Assumptions and Constraints\n- [Known constraints or assumptions]\n\n## Requirements\n\n### Functional\n- [Requirement]\n\n### Non-Functional\n- [Performance, reliability, security, compliance]\n\n## Technical Design\n\n### Data Model\n[Schema changes, new entities, relationships]\n\n### API Design\n[New endpoints, request/response shapes, versioning]\n\n### Architecture\n[System diagram in text or mermaid, component interactions]\n\n### UX Flow (if applicable)\n[Key screens, loading states, error recovery]\n\n---\n\n## Implementation Plan\n\n### Serial Dependencies (Must Complete First)\n\nThese tasks create foundations that other work depends on. Complete in order.\n\n#### Phase 0: [Foundation Name]\n**Prerequisite for:** All subsequent phases\n\n| Task | Description | Output |\n|------|-------------|--------|\n| 0.1 | [Task description] | [Concrete deliverable] |\n| 0.2 | [Task description] | [Concrete deliverable] |\n\n---\n\n### Parallel Workstreams\n\nThese workstreams can be executed independently after Phase 0.\n\n#### Workstream A: [Name]\n**Dependencies:** Phase 0\n**Can parallelize with:** Workstreams B, C\n\n| Task | Description | Output |\n|------|-------------|--------|\n| A.1 | [Task description] | [Concrete deliverable] |\n| A.2 | [Task description] | [Concrete deliverable] |\n\n#### Workstream B: [Name]\n**Dependencies:** Phase 0\n**Can parallelize with:** Workstreams A, C\n\n| Task | Description | Output |\n|------|-------------|--------|\n| B.1 | [Task description] | [Concrete deliverable] |\n\n---\n\n### Merge Phase\n\nAfter parallel workstreams complete, these tasks integrate the work.\n\n#### Phase N: Integration\n**Dependencies:** Workstreams A, B, C\n\n| Task | Description | Output |\n|------|-------------|--------|\n| N.1 | [Integration task] | [Concrete deliverable] |\n\n---\n\n## Testing and Validation\n\n- [Unit, integration, end-to-end coverage]\n- [Manual test plan if needed]\n\n## Rollout and Migration\n\n- [Feature flags, staged rollout, migration steps]\n- [Rollback plan]\n\n## Verification Checklist\n\n- [Exact commands or manual steps the agent can run to verify correctness]\n- [Expected outputs or success criteria]\n\n## Risk Assessment\n\n| Risk | Likelihood | Impact | Mitigation |\n|------|------------|--------|------------|\n| [Risk description] | Low/Med/High | Low/Med/High | [Strategy] |\n\n## Open Questions\n\n- [ ] [Question that still needs resolution]\n\n## Decision Log\n\n| Decision | Rationale | Alternatives Considered |\n|----------|-----------|------------------------|\n| [Decision made] | [Why] | [What else was considered] |\n```\n\n## Interview Flow Example\n\nRound 1: High-Level Architecture\n- \"The spec mentions a sync engine. Is this push-based (webhooks), pull-based (polling), or event-driven (queue)?\"\n- \"What is the expected data volume and throughput?\"\n\nRound 2: Edge Cases\n- \"If a batch fails mid-run, do we retry the whole batch or resume from a checkpoint?\"\n- \"What happens when source data is deleted but still referenced downstream?\"\n\nRound 3: Parallelization\n- \"Can we process different categories independently, or are there cross-category dependencies?\"\n- \"Is there a natural partition key that allows sharding?\"\n\nRound 4: Operational\n- \"What is the acceptable latency for sync or processing?\"\n- \"How will operators debug failures and what visibility do they need?\"\n\n## Key Behaviors\n\n1. Persist until the plan is implementable and verifiable by the agent, but avoid user fatigue by batching questions.\n2. Challenge vague answers when they affect design decisions.\n3. Identify hidden work and operational overhead.\n4. Think about the merge and integration steps early.\n5. Summarize understanding and confirm before writing the final plan.\n\n## Completing the Interview\n\nAfter sufficient rounds of questions:\n1. Summarize your understanding back to the user\n2. Confirm the parallelization strategy\n3. Write the complete plan to the target file\n4. Ask if any sections need refinement\n"},"lastSynced":"2026-03-06T14:01:29.377Z","agentAnalysis":{"suitability":{"en":"Ideal for Technical Agents needing to turn ideas into structured, implementable plans with organized foundations and workstreams","zh":"适合于需要将想法转化为结构化、可实施计划的技术代理，具有组织良好的基础和工作流","ja":"技術エージェントがアイデアを構造化された実行可能な計画に変換する必要がある場合に最適です。計画には整理された基礎とワークフローが含まれます","ko":"기술 에이전트가 아이디어를 구조화된 실행 가능한 계획으로 변환해야 하는 경우에 적합합니다. 계획에는 조직화된 기반과 워크플ロー가 포함됩니다","es":"Ideal para Agentes Técnicos que necesitan convertir ideas en planes estructurados e implementables con fundamentos y flujos de trabajo organizados","fr":"Idéal pour les agents techniques ayant besoin de transformer des idées en plans structurés et réalisables avec des fondements et des flux de travail organisés","de":"Ideal für technische Agenten, die Ideen in strukturierte und umsetzbare Pläne mit organisierten Grundlagen und Arbeitsabläufen umwandeln müssen","pt":"Ideal para Agentes Técnicos que precisam transformar ideias em planos estruturados e implementáveis com fundamentos organizados e fluxos de trabalho","ru":"Идеально для Технических Агентов, которым необходимо преобразовать идеи в структурированные и реализуемые планы с организованными основами и потоками работы","ar":"مثالي لوكلاء الفنيين الذين يحتاجون إلى تحويل الأفكار إلى خطط منظمّة ويمكن تنفيذها مع أسس وعمليات عمل منسقة"},"recommendation":{"en":"Empowers agents to transform rough ideas or specs into detailed plans with parallel execution capabilities, utilizing technical interviews and outputting organized foundations, workstreams, and integration plans in formats like SPEC.md or PLAN.md","zh":"赋予代理能力，将粗略的想法或规格转化为详细的计划，具有并行执行能力，利用技术面试，输出组织化的基础、工作流和集成计划，格式如 SPEC.md 或 PLAN.md","ja":"エージェントに、粗いアイデアや仕様を詳細な計画に変換する能力を付与します。並列実行機能を使用し、技術面接を利用して、整理された基礎、ワークフロー、統合計画を出力します。フォーマットは SPEC.md または PLAN.md のような形式です","ko":"에이전트에게 粗略한 아이디어나 사양을詳細한 계획으로 변환할 수 있는 능력을 부여합니다. 병렬 실행 기능을 사용하고 기술 면접을 활용하여 조직화된 基礎, 워크플ロー, 통합 계획을 출력합니다. 형식은 SPEC.md 또는 PLAN.md와 같은 형식입니다","es":"Habilita a los agentes a transformar ideas o especificaciones rudimentarias en planes detallados con capacidades de ejecución paralela, utilizando entrevistas técnicas y generando fundamentos, flujos de trabajo y planes de integración organizados en formatos como SPEC.md o PLAN.md","fr":"Permet aux agents de transformer des idées ou des spécifications sommaires en plans détaillés avec des capacités d''exécution parallèle, en utilisant des entretiens techniques et en produisant des fondements, des flux de travail et des plans d''intégration organisés dans des formats comme SPEC.md ou PLAN.md","de":"Ermöglicht es Agenten, grobe Ideen oder Spezifikationen in detaillierte Pläne mit paralleler Ausführungsfähigkeit umzuwandeln, indem technische Interviews verwendet und organisierte Grundlagen, Arbeitsabläufe und Integrationspläne in Formaten wie SPEC.md oder PLAN.md ausgegeben werden","pt":"Permite que os agentes transformem ideias ou especificações grosseiras em planos detalhados com capacidades de execução paralela, utilizando entrevistas técnicas e produzindo fundamentos organizados, fluxos de trabalho e planos de integração em formatos como SPEC.md ou PLAN.md","ru":"Позволяет агентам преобразовать грубые идеи или спецификации в подробные планы с возможностями параллельного выполнения, используя технические интервью и выдавая организованные основы, потоки работы и планы интеграции в форматах như SPEC.md или PLAN.md","ar":"تمكن الوكلاء من تحويل الأفكار أو المواصفات الخشنة إلى خطط مفصلة مع قدرات تنفيذ متوازي، باستخدام المقابلات الفنية وانتاج أسس منسقة وعمليات عمل وخطط دمج بالتنسيقات مثل SPEC.md أو PLAN.md"},"useCases":{"en":["Automating the planning process for new projects","Generating detailed workstreams from rough feature requests","Creating integration plans for parallel execution"],"zh":["为新项目自动化规划流程","从粗略的功能请求生成详细的工作流","为并行执行创建集成计划"],"ja":["新しいプロジェクトの計画プロセスを自動化する","粗い機能リクエストから詳細なワークフローを生成する","並列実行のための統合計画を作成する"],"ko":["새로운 프로젝트의 계획 프로세스를 자동화하는 것"," 粗略한 기능 요청에서 자세한 워크플로우를 생성하는 것","병렬 실행을 위한 통합 계획을 생성하는 것"],"es":["Automatizar el proceso de planificación para nuevos proyectos","Generar flujos de trabajo detallados a partir de solicitudes de características rudimentarias","Crear planes de integración para la ejecución paralela"],"fr":["Automatiser le processus de planification pour les nouveaux projets","Générer des flux de travail détaillés à partir de demandes de fonctionnalités sommaires","Créer des plans d''intégration pour l''exécution parallèle"],"de":["Automatisieren des Planungsprozesses für neue Projekte","Erstellen detaillierter Arbeitsabläufe aus groben Funktionsanforderungen","Erstellen von Integrationsplänen für die parallele Ausführung"],"pt":["Automatizar o processo de planejamento para novos projetos","Gerar fluxos de trabalho detalhados a partir de solicitações de recursos grosseiras","Criar planos de integração para execução paralela"],"ru":["Автоматизировать процесс планирования для новых проектов","Генерировать подробные потоки работы из грубых запросов на функции","Создавать планы интеграции для параллельного выполнения"],"ar":["أتمتة عملية التخطيط لمشاريع جديدة","إنتاج عمليات عمل مفصلة من طلبات الميزات الخشنة","إنشاء خطط دمج للتنفيذ المتوازي"]},"limitations":{"en":["Requires user input in the form of a spec or plan file, or a rough description of the idea","Output is structured for parallel execution, which may require additional coordination"],"zh":["需要用户以规格或计划文件的形式输入，或者粗略地描述该想法","输出是为并行执行而结构化的，这可能需要额外的协调"],"ja":["仕様または計画ファイルの形式でのユーザー入力、またはアイデアの粗い説明が必要","出力は並列実行のために構造化されており、追加の調整が必要になる場合がある"],"ko":["사양 또는 계획 파일 형식의 사용자 입력이 필요하거나 아이디어에 대한 粗略한 설명이 필요합니다","출력은 병렬 실행을 위해 구조화되어 있으므로 추가적인 조정이 필요할 수 있습니다"],"es":["Requiere la entrada del usuario en forma de archivo de especificación o plan, o una descripción rudimentaria de la idea","La salida está estructurada para la ejecución paralela, lo que puede requerir una coordinación adicional"],"fr":["Nécessite une entrée utilisateur sous la forme d''un fichier de spécification ou de plan, ou d''une description sommaire de l''idée","La sortie est structurée pour l''exécution parallèle, ce qui peut nécessiter une coordination supplémentaire"],"de":["Benötigt die Eingabe des Benutzers in Form einer Spezifikations- oder Plan-Datei oder einer groben Beschreibung der Idee","Die Ausgabe ist für die parallele Ausführung strukturiert, was eine zusätzliche Koordination erfordern kann"],"pt":["Exige entrada do usuário na forma de um arquivo de especificação ou plano, ou uma descrição grosseira da ideia","A saída é estruturada para execução paralela, o que pode exigir coordenação adicional"],"ru":["Требует ввода пользователя в виде файла спецификации или плана, или грубого описания идеи","Выходные данные структурированы для параллельного выполнения, что может потребовать дополнительной координации"],"ar":["يتطلب إدخال المستخدم في شكل ملف مواصفات أو خطة، أو وصف خشن للفكرة","الخرج منظم للتنفيذ المتوازي، مما قد يتطلب تنسيقًا إضافيًا"]},"version":4},"contentHash":"76755dca1a8ade8c8e895de1efdf62f805b008bf3c8a9c427ad3a6c8bb1c1ddd","qualityScore":60}');
