INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dojoengine/daimyo/create-a-plan', 'create-a-plan', 'dojoengine', 'daimyo', 'community', 'create-a-plan dojoengine daimyo community The create-a-plan skill runs a structured technical interview to turn ideas into implementable plans, outputting organized foundations, workstreams, and integration plans for parallel execution. Create-a-Plan 技术面试技能通过对粗略的想法或现有规格进行结构化的技术面试，生成详细的可执行计划 Create-a-Plan スキルは、粗略なアイデアや既存の仕様を詳細な実行可能な計画に変換するために構造化された技術面接を実行します Create-a-Plan 개발 스킬은 아이디어나 기존 사양을 구체적인 실행 가능한 계획으로 전환하기 위해 구조화된 기술 면접을 수행합니다 La habilidad ''create-a-plan'' ejecuta una entrevista técnica estructurada para convertir una idea o especificación en un plan implementable La compétence ''create-a-plan'' exécute un entretien technique structuré pour convertir une idée ou une spécification en un plan réalisable Die Fähigkeit ''create-a-plan'' führt ein strukturiertes technisches Interview durch, um eine Idee oder Spezifikation in einen umsetzbaren Plan umzuwandeln O Create-a-Plan é uma ferramenta de planejamento de projetos que cria planos detalhados e implementáveis a partir de ideias ou especificações existentes Create-a-Plan - это инструмент для создания детальных планов проектов, который преобразует грубые идеи или существующие спецификации в реализуемые планы Create-a-Plan هو أداة لتخطيط المشاريع التي تحول الأفكار أو المواصفات الحالية إلى مخططات تفصيلية وقابلة للتنفيذ how to use create-a-plan create-a-plan setup guide create-a-plan alternative create-a-plan vs project management tools what is create-a-plan create-a-plan install create-a-plan for AI agents structured technical interview parallel execution planning Create-a-Plan 技术面试 AI 技术面试工具 详细计划生成 并行执行计划 技术面试流程 SPEC.md 文件读取 PLAN.md 文件读取 RFC.md 文件读取 Runs a structured technical interview to turn rough ideas into detailed plans Accepts input from spec or plan files (e.g., SPEC.md, PLAN.md, RFC.md) Processes rough descriptions of desired builds or feature requests Outputs organized plans for parallel execution, including foundations, independent workstreams, and merge/integration plans create-a-plan is a skill that facilitates the creation of detailed, implementable plans from rough ideas or existing specs through a structured technical interview process.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pradeepmouli/lspeasy/changelog-automation', 'community', 'pradeepmouli', 'lspeasy', 'pradeepmouli/lspeasy', 'changelog-automation', 0, 0, 60, '2026-03-07T01:49:01.624Z', '2026-03-07T02:13:07.637Z', '3b5fc90d13fa54918da996f84920eeb233efdb597decd77728f4c2d1d84049e6', '{"id":"pradeepmouli/lspeasy/changelog-automation","name":"changelog-automation","description":{"en":"The changelog-automation skill provides an ergonomic and accessible TypeScript SDK for LSP clients/servers, automating changelog generation and release notes. It benefits developers and teams managing version control and release workflows.","zh":"changelog-automation 提供了自动化生成变更日志、发布说明和版本管理的工具与模式。它遵循行业标准，支持 Conventional Commits 和语义化版本控制，可集成到 GitHub/GitLab 工作流中。","ja":"changelog-automation は、変更履歴の自動生成、リリースノート、バージョン管理のためのパターンとツールを提供します。業界標準に準拠し、Conventional Commits とセマンティックバージョニングをサポートし、GitHub/GitLab ワークフローに統合できます。","ko":"changelog-automation은 자동 변경 로그 생성, 릴리스 노트, 버전 관리를 위한 패턴과 도구를 제공합니다. 업계 표준을 따르며 Conventional Commits와 Semantic Versioning을 지원하고 GitHub/GitLab 워크플로우에 통합할 수 있습니다.","es":"changelog-automation es un conjunto de patrones y herramientas para automatizar la generación de changelogs, notas de lanzamiento y gestión de versiones. Sigue estándares de la industria como Conventional Commits y el formato Keep a Changelog para flujos de trabajo en GitHub y GitLab.","fr":"changelog-automation est un ensemble de modèles et d''outils pour automatiser la génération de changelogs, de notes de version et la gestion des versions. Il suit les standards industriels comme les Conventional Commits et le format Keep a Changelog pour les workflows GitHub et GitLab.","de":"changelog-automation ist ein Set von Patterns und Tools zur Automatisierung der Changelog-Generierung, von Release Notes und Versionsverwaltung. Es folgt Industriestandards wie Conventional Commits und dem Keep a Changelog-Format für GitHub- und GitLab-Workflows.","pt":"O SDK de TypeScript para clientes e servidores LSP permite a automação de changelog, seguindo padrões da indústria","ru":"SDK TypeScript для клиентов и серверов LSP позволяет автоматизировать changelog, следуя отраслевым стандартам","ar":"SDK TypeScript لعميل و خادم LSP يسمح بالتطبيق الآلي لسجل التغيير، متبعة معايير الصناعة"},"seo":{"title":{"en":"changelog-automation: Automated Release Note Generation |...","zh":"changelog-automation 设置指南：自动化变更日志生成","ja":"changelog-automation ベストプラクティス：AIエージェントによる変更履歴自動化","ko":"changelog-automation 설정 가이드: 자동 변경 로그 생성","es":"changelog-automation: Setup Guide para Generación Automát...","fr":"changelog-automation : Guide de Configuration pour l''Auto...","de":"changelog-automation: Setup-Anleitung für automatische Ch...","pt":"Guia de Configuração de Automação de Changelog com TypeSc...","ru":"Настройка автоматизации changelog с помощью ИИ Агентов и ...","ar":"دليل إعداد آلي لسجل التغيير باستخدام TypeScript"},"description":{"en":"Streamline your development workflow with changelog-automation, learn how to automate changelog generation and release notes with industry-standard tools","zh":"使用 changelog-automation AI 工具自动化生成变更日志和发布说明。支持 Conventional Commits 标准和语义化版本管理，集成 GitHub/GitLab 工作流。","ja":"changelog-automation AIエージェントで変更履歴とリリースノートを自動生成。Conventional Commits とセマンティックバージョニングに対応し、GitHub/GitLab と連携。","ko":"changelog-automation AI 도구로 자동 변경 로그 및 릴리스 노트 생성. Conventional Commits 표준과 Semantic Versioning 지원, GitHub/GitLab 통합.","es":"Automatiza la generación de changelogs y release notes con changelog-automation. Implementa Conventional Commits, gestiona versiones semánticas y genera nota...","fr":"Automatisez la génération de changelogs et de notes de version avec l''outil IA changelog-automation. Implémentez les Conventional Commits, gérez le versionin...","de":"Automatisieren Sie die Generierung von Changelogs und Release Notes mit der KI-Agentur changelog-automation. Implementieren Sie Conventional Commits, verwalt...","pt":"Aprenda a automatizar a geração de changelog com o SDK de TypeScript para clientes e servidores LSP, seguindo padrões da indústria","ru":"Узнайте, как автоматизировать генерацию changelog с помощью SDK TypeScript для клиентов и серверов LSP, следуя отраслевым стандартам","ar":"تعلم كيفية تطبيق آلي لإنتاج سجل التغيير باستخدام SDK TypeScript لعميل و خادم LSP، متبعة معايير الصناعة"},"definition":{"en":"changelog-automation is a set of patterns and tools for automating changelog generation, release notes, and version management following industry standards","zh":"changelog-automation 是一个用于自动化生成变更日志、发布说明和版本管理的开发工具集。它基于 Keep a Changelog 格式，支持 Conventional Commits 规范，旨在标准化提交消息格式并实现语义化版本控制。","ja":"changelog-automation は、変更履歴の自動生成、リリースノート、バージョン管理のための開発ツールキットです。Keep a Changelog 形式に基づき、Conventional Commits 仕様をサポートし、コミットメッセージのフォーマットを標準化しセマンティックバージョニングを実現します。","ko":"changelog-automation은 자동 변경 로그 생성, 릴리스 노트, 버전 관리를 위한 개발 도구 세트입니다. Keep a Changelog 형식을 기반으로 Conventional Commits 사양을 지원하며 커밋 메시지 형식을 표준화하고 Semantic Versioning을 구현합니다.","es":"changelog-automation es una skill de IA que proporciona herramientas para automatizar la creación de changelogs y notas de lanzamiento. Utiliza Conventional Commits y el formato Keep a Changelog para gestionar versiones semánticas y generar documentación de cambios para plataformas como GitHub y GitLab.","fr":"changelog-automation est un outil IA qui fournit des modèles pour automatiser la création de changelogs et de notes de version. Il utilise les Conventional Commits et le format Keep a Changelog pour gérer le versioning sémantique et générer une documentation des changements pour GitHub et GitLab.","de":"changelog-automation ist ein KI-Tool, das Werkzeuge zur Automatisierung der Erstellung von Changelogs und Release Notes bereitstellt. Es nutzt Conventional Commits und das Keep a Changelog-Format, um semantische Versionierung zu verwalten und Änderungsdokumentation für GitHub und GitLab zu generieren.","pt":"Automação de changelog é um processo que utiliza padrões da indústria para gerar registros de alterações","ru":"Автоматизация changelog - это процесс, использующий отраслевые стандарты для генерации записей изменений","ar":"آلية سجل التغيير هو عملية تستخدم معايير الصناعة لإنتاج سجلات التغييرات"},"features":{"en":["Generates GitHub/GitLab release notes","Implements Conventional Commits for standardized commit message formats","Manages semantic versioning for accurate version control","Creates release note workflows for streamlined development","Supports Keep a Changelog format for organized change tracking","Automates changelog generation for reduced manual effort"],"zh":["基于 Keep a Changelog 格式的自动化变更日志生成","支持 Conventional Commits 规范标准化提交消息","自动化语义化版本管理（Semantic Versioning）","GitHub 发布说明自动生成工作流","GitLab 发布说明自动生成集成","标准化提交消息格式的工具和模式"],"ja":["Keep a Changelog 形式に基づく自動変更履歴生成","Conventional Commits 仕様によるコミットメッセージ標準化","自動セマンティックバージョニング管理","GitHub リリースノート自動生成ワークフロー","GitLab リリースノート自動生成連携","コミットメッセージフォーマット標準化のツールとパターン"],"ko":["Keep a Changelog 형식 기반 자동 변경 로그 생성","Conventional Commits 사양을 통한 커밋 메시지 표준화","자동 Semantic Versioning 관리","GitHub 릴리스 노트 자동 생성 워크플로우","GitLab 릴리스 노트 자동 생성 통합","커밋 메시지 형식 표준화를 위한 도구 및 패턴"],"es":["Generación automática de changelogs siguiendo el formato Keep a Changelog","Implementación de Conventional Commits para estandarizar mensajes de commit","Workflows automatizados para crear release notes en GitHub y GitLab","Gestión de semantic versioning (versionado semántico)","Automatización de la documentación de cambios para proyectos de software","Configuración de estándares para formatos de mensajes de commit"],"fr":["Génération automatique de changelogs suivant le format Keep a Changelog","Implémentation des Conventional Commits pour standardiser les messages de commit","Workflows automatisés pour créer des notes de version sur GitHub et GitLab","Gestion du versioning sémantique (semantic versioning)","Automatisation de la documentation des changements pour les projets logiciels","Configuration de standards pour les formats de messages de commit"],"de":["Automatische Generierung von Changelogs nach dem Keep a Changelog-Format","Implementierung von Conventional Commits zur Standardisierung von Commit-Messages","Automatisierte Workflows für die Erstellung von Release Notes auf GitHub und GitLab","Verwaltung von semantischer Versionierung (semantic versioning)","Automatisierung der Änderungsdokumentation für Softwareprojekte","Konfiguration von Standards für Commit-Message-Formate"],"pt":["Geração automática de changelog","Implementação de Commits Convencionais","Criação de fluxos de trabalho de notas de lançamento","Padronização de formatos de mensagem de commit","Geração de notas de lançamento do GitHub/GitLab","Gerenciamento de versionamento semântico"],"ru":["Автоматическая генерация changelog","Реализация Конвенциональных Коммитов","Создание рабочих процессов заметок о выпуске","Стандартизация форматов сообщений о коммитах","Генерация заметок о выпуске GitHub/GitLab","Управление семантическим версионированием"],"ar":["التطبيق الآلي لإنتاج سجل التغيير","تنفيذ الإلتزامات التقليدية","إنشاء سير عمل لملاحظات الإصدار","مواصفة تنسيقات رسائل الإلتزام","إنتاج ملاحظات الإصدار من GitHub/GitLab","إدارة إصدار_VERSION السेमنتيك"]},"keywords":{"en":["how to use changelog-automation","changelog-automation setup guide","changelog-automation alternative","automated release note generation","Conventional Commits tutorial","semantic versioning best practices","changelog-automation install","GitHub release notes automation","changelog-automation vs manual changelog"],"zh":["changelog-automation","自动化变更日志生成","Conventional Commits 规范","语义化版本管理","GitHub 发布说明自动化","GitLab 发布说明生成","Keep a Changelog 格式","提交消息标准化","AI 工具自动化"],"ja":["changelog-automation","変更履歴自動生成","Conventional Commits 仕様","セマンティックバージョニング","GitHub リリースノート自動化","GitLab リリースノート生成","Keep a Changelog 形式","コミットメッセージ標準化","AIエージェント 自動化"],"ko":["changelog-automation","자동 변경 로그 생성","Conventional Commits 사양","Semantic Versioning","GitHub 릴리스 노트 자동화","GitLab 릴리스 노트 생성","Keep a Changelog 형식","커밋 메시지 표준화","AI 도구 자동화"],"es":["automatización changelog conventional commits","generar changelog automático github","herramienta ia para release notes","keep a changelog formato español","semantic versioning automation","gitlab release notes automático","standard commit messages","changelog-automation setup guide"],"fr":["automatisation changelog conventional commits","générer changelog automatique github","outil ia pour notes de version","keep a changelog format français","automatisation versioning sémantique","gitlab notes de version automatique","messages de commit standardisés","changelog-automation guide configuration"],"de":["automatisierung changelog conventional commits","automatische changelog generierung github","ki tool für release notes","keep a changelog format deutsch","semantic versioning automatisierung","gitlab release notes automatisch","standardisierte commit messages","changelog-automation einrichtungsanleitung"],"pt":["automação de changelog","typescript","LSP","clientes LSP","servidores LSP","padrões da indústria","geração automática de changelog","commits convencionais"],"ru":["автоматизация changelog","typescript","LSP","клиенты LSP","серверы LSP","отраслевые стандарты","автоматическая генерация changelog","Конвенциональные Коммиты"],"ar":["آلية سجل التغيير","typescript","LSP","عملاء LSP","خادم LSP","معايير الصناعة","التطبيق الآلي لإنتاج سجل التغيير","الإلتزامات التقليدية"]}},"owner":"pradeepmouli","repo":"lspeasy","repoPath":"pradeepmouli/lspeasy","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.624Z","topics":[],"category":"community","skillMd":{"name":"changelog-automation","description":"Automate changelog generation from commits, PRs, and releases following Keep a Changelog format. Use when setting up release workflows, generating release notes, or standardizing commit conventions.","bodyPreview":"# Changelog Automation\n\nPatterns and tools for automating changelog generation, release notes, and version management following industry standards.\n\n## When to Use This Skill\n\n- Setting up automated changelog generation\n- Implementing Conventional Commits\n- Creating release note workflows\n- Standardizing commit message formats\n- Generating GitHub/GitLab release notes\n- Managing semantic versioning\n\n## Core Concepts\n\n### 1. Keep a Changelog Format\n\n```markdown\n# Changelog\n\nAll notable changes to","body":"# Changelog Automation\n\nPatterns and tools for automating changelog generation, release notes, and version management following industry standards.\n\n## When to Use This Skill\n\n- Setting up automated changelog generation\n- Implementing Conventional Commits\n- Creating release note workflows\n- Standardizing commit message formats\n- Generating GitHub/GitLab release notes\n- Managing semantic versioning\n\n## Core Concepts\n\n### 1. Keep a Changelog Format\n\n```markdown\n# Changelog\n\nAll notable changes to this project will be documented in this file.\n\nThe format is based on [Keep a Changelog](https://keepachangelog.com/en/1.1.0/),\nand this project adheres to [Semantic Versioning](https://semver.org/spec/v2.0.0.html).\n\n## [Unreleased]\n\n### Added\n\n- New feature X\n\n## [1.2.0] - 2024-01-15\n\n### Added\n\n- User profile avatars\n- Dark mode support\n\n### Changed\n\n- Improved loading performance by 40%\n\n### Deprecated\n\n- Old authentication API (use v2)\n\n### Removed\n\n- Legacy payment gateway\n\n### Fixed\n\n- Login timeout issue (#123)\n\n### Security\n\n- Updated dependencies for CVE-2024-1234\n\n[Unreleased]: https://github.com/user/repo/compare/v1.2.0...HEAD\n[1.2.0]: https://github.com/user/repo/compare/v1.1.0...v1.2.0\n```\n\n### 2. Conventional Commits\n\n```\n<type>[optional scope]: <description>\n\n[optional body]\n\n[optional footer(s)]\n```\n\n| Type       | Description      | Changelog Section  |\n| ---------- | ---------------- | ------------------ |\n| `feat`     | New feature      | Added              |\n| `fix`      | Bug fix          | Fixed              |\n| `docs`     | Documentation    | (usually excluded) |\n| `style`    | Formatting       | (usually excluded) |\n| `refactor` | Code restructure | Changed            |\n| `perf`     | Performance      | Changed            |\n| `test`     | Tests            | (usually excluded) |\n| `chore`    | Maintenance      | (usually excluded) |\n| `ci`       | CI changes       | (usually excluded) |\n| `build`    | Build system     | (usually excluded) |\n| `revert`   | Revert commit    | Removed            |\n\n### 3. Semantic Versioning\n\n```\nMAJOR.MINOR.PATCH\n\nMAJOR: Breaking changes (feat! or BREAKING CHANGE)\nMINOR: New features (feat)\nPATCH: Bug fixes (fix)\n```\n\n## Implementation\n\n### Method 1: Conventional Changelog (Node.js)\n\n```bash\n# Install tools\nnpm install -D @commitlint/cli @commitlint/config-conventional\nnpm install -D husky\nnpm install -D standard-version\n# or\nnpm install -D semantic-release\n\n# Setup commitlint\ncat > commitlint.config.js << ''EOF''\nmodule.exports = {\n  extends: [''@commitlint/config-conventional''],\n  rules: {\n    ''type-enum'': [\n      2,\n      ''always'',\n      [\n        ''feat'',\n        ''fix'',\n        ''docs'',\n        ''style'',\n        ''refactor'',\n        ''perf'',\n        ''test'',\n        ''chore'',\n        ''ci'',\n        ''build'',\n        ''revert'',\n      ],\n    ],\n    ''subject-case'': [2, ''never'', [''start-case'', ''pascal-case'', ''upper-case'']],\n    ''subject-max-length'': [2, ''always'', 72],\n  },\n};\nEOF\n\n# Setup husky\nnpx husky init\necho \"npx --no -- commitlint --edit \\$1\" > .husky/commit-msg\n```\n\n### Method 2: standard-version Configuration\n\n```javascript\n// .versionrc.js\nmodule.exports = {\n  types: [\n    { type: \"feat\", section: \"Features\" },\n    { type: \"fix\", section: \"Bug Fixes\" },\n    { type: \"perf\", section: \"Performance Improvements\" },\n    { type: \"revert\", section: \"Reverts\" },\n    { type: \"docs\", section: \"Documentation\", hidden: true },\n    { type: \"style\", section: \"Styles\", hidden: true },\n    { type: \"chore\", section: \"Miscellaneous\", hidden: true },\n    { type: \"refactor\", section: \"Code Refactoring\", hidden: true },\n    { type: \"test\", section: \"Tests\", hidden: true },\n    { type: \"build\", section: \"Build System\", hidden: true },\n    { type: \"ci\", section: \"CI/CD\", hidden: true },\n  ],\n  commitUrlFormat: \"{{host}}/{{owner}}/{{repository}}/commit/{{hash}}\",\n  compareUrlFormat:\n    \"{{host}}/{{owner}}/{{repository}}/compare/{{previousTag}}...{{currentTag}}\",\n  issueUrlFormat: \"{{host}}/{{owner}}/{{repository}}/issues/{{id}}\",\n  userUrlFormat: \"{{host}}/{{user}}\",\n  releaseCommitMessageFormat: \"chore(release): {{currentTag}}\",\n  scripts: {\n    prebump: ''echo \"Running prebump\"'',\n    postbump: ''echo \"Running postbump\"'',\n    prechangelog: ''echo \"Running prechangelog\"'',\n    postchangelog: ''echo \"Running postchangelog\"'',\n  },\n};\n```\n\n```json\n// package.json scripts\n{\n  \"scripts\": {\n    \"release\": \"standard-version\",\n    \"release:minor\": \"standard-version --release-as minor\",\n    \"release:major\": \"standard-version --release-as major\",\n    \"release:patch\": \"standard-version --release-as patch\",\n    \"release:dry\": \"standard-version --dry-run\"\n  }\n}\n```\n\n### Method 3: semantic-release (Full Automation)\n\n```javascript\n// release.config.js\nmodule.exports = {\n  branches: [\n    \"main\",\n    { name: \"beta\", prerelease: true },\n    { name: \"alpha\", prerelease: true },\n  ],\n  plugins: [\n    \"@semantic-release/commit-analyzer\",\n    \"@semantic-release/release-notes-generator\",\n    [\n      \"@semantic-release/changelog\",\n      {\n        changelogFile: \"CHANGELOG.md\",\n      },\n    ],\n    [\n      \"@semantic-release/npm\",\n      {\n        npmPublish: true,\n      },\n    ],\n    [\n      \"@semantic-release/github\",\n      {\n        assets: [\"dist/**/*.js\", \"dist/**/*.css\"],\n      },\n    ],\n    [\n      \"@semantic-release/git\",\n      {\n        assets: [\"CHANGELOG.md\", \"package.json\"],\n        message:\n          \"chore(release): ${nextRelease.version} [skip ci]\\n\\n${nextRelease.notes}\",\n      },\n    ],\n  ],\n};\n```\n\n### Method 4: GitHub Actions Workflow\n\n```yaml\n# .github/workflows/release.yml\nname: Release\n\non:\n  push:\n    branches: [main]\n  workflow_dispatch:\n    inputs:\n      release_type:\n        description: \"Release type\"\n        required: true\n        default: \"patch\"\n        type: choice\n        options:\n          - patch\n          - minor\n          - major\n\npermissions:\n  contents: write\n  pull-requests: write\n\njobs:\n  release:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n          token: ${{ secrets.GITHUB_TOKEN }}\n\n      - uses: actions/setup-node@v4\n        with:\n          node-version: \"20\"\n          cache: \"npm\"\n\n      - run: npm ci\n\n      - name: Configure Git\n        run: |\n          git config user.name \"github-actions[bot]\"\n          git config user.email \"github-actions[bot]@users.noreply.github.com\"\n\n      - name: Run semantic-release\n        env:\n          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n          NPM_TOKEN: ${{ secrets.NPM_TOKEN }}\n        run: npx semantic-release\n\n  # Alternative: manual release with standard-version\n  manual-release:\n    if: github.event_name == ''workflow_dispatch''\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n\n      - uses: actions/setup-node@v4\n        with:\n          node-version: \"20\"\n\n      - run: npm ci\n\n      - name: Configure Git\n        run: |\n          git config user.name \"github-actions[bot]\"\n          git config user.email \"github-actions[bot]@users.noreply.github.com\"\n\n      - name: Bump version and generate changelog\n        run: npx standard-version --release-as ${{ inputs.release_type }}\n\n      - name: Push changes\n        run: git push --follow-tags origin main\n\n      - name: Create GitHub Release\n        uses: softprops/action-gh-release@v1\n        with:\n          tag_name: ${{ steps.version.outputs.tag }}\n          body_path: RELEASE_NOTES.md\n          generate_release_notes: true\n```\n\n### Method 5: git-cliff (Rust-based, Fast)\n\n```toml\n# cliff.toml\n[changelog]\nheader = \"\"\"\n# Changelog\n\nAll notable changes to this project will be documented in this file.\n\n\"\"\"\nbody = \"\"\"\n{% if version %}\\\n    ## [{{ version | trim_start_matches(pat=\"v\") }}] - {{ timestamp | date(format=\"%Y-%m-%d\") }}\n{% else %}\\\n    ## [Unreleased]\n{% endif %}\\\n{% for group, commits in commits | group_by(attribute=\"group\") %}\n    ### {{ group | upper_first }}\n    {% for commit in commits %}\n        - {% if commit.scope %}**{{ commit.scope }}:** {% endif %}\\\n            {{ commit.message | upper_first }}\\\n            {% if commit.github.pr_number %} ([#{{ commit.github.pr_number }}](https://github.com/owner/repo/pull/{{ commit.github.pr_number }})){% endif %}\\\n    {% endfor %}\n{% endfor %}\n\"\"\"\nfooter = \"\"\"\n{% for release in releases -%}\n    {% if release.version -%}\n        {% if release.previous.version -%}\n            [{{ release.version | trim_start_matches(pat=\"v\") }}]: \\\n                https://github.com/owner/repo/compare/{{ release.previous.version }}...{{ release.version }}\n        {% endif -%}\n    {% else -%}\n        [unreleased]: https://github.com/owner/repo/compare/{{ release.previous.version }}...HEAD\n    {% endif -%}\n{% endfor %}\n\"\"\"\ntrim = true\n\n[git]\nconventional_commits = true\nfilter_unconventional = true\nsplit_commits = false\ncommit_parsers = [\n    { message = \"^feat\", group = \"Features\" },\n    { message = \"^fix\", group = \"Bug Fixes\" },\n    { message = \"^doc\", group = \"Documentation\" },\n    { message = \"^perf\", group = \"Performance\" },\n    { message = \"^refactor\", group = \"Refactoring\" },\n    { message = \"^style\", group = \"Styling\" },\n    { message = \"^test\", group = \"Testing\" },\n    { message = \"^chore\\\\(release\\\\)\", skip = true },\n    { message = \"^chore\", group = \"Miscellaneous\" },\n]\nfilter_commits = false\ntag_pattern = \"v[0-9]*\"\nskip_tags = \"\"\nignore_tags = \"\"\ntopo_order = false\nsort_commits = \"oldest\"\n\n[github]\nowner = \"owner\"\nrepo = \"repo\"\n```\n\n```bash\n# Generate changelog\ngit cliff -o CHANGELOG.md\n\n# Generate for specific range\ngit cliff v1.0.0..v2.0.0 -o RELEASE_NOTES.md\n\n# Preview without writing\ngit cliff --unreleased --dry-run\n```\n\n### Method 6: Python (commitizen)\n\n```toml\n# pyproject.toml\n[tool.commitizen]\nname = \"cz_conventional_commits\"\nversion = \"1.0.0\"\nversion_files = [\n    \"pyproject.toml:version\",\n    \"src/__init__.py:__version__\",\n]\ntag_format = \"v$version\"\nupdate_changelog_on_bump = true\nchangelog_incremental = true\nchangelog_start_rev = \"v0.1.0\"\n\n[tool.commitizen.customize]\nmessage_template = \"{{change_type}}{% if scope %}({{scope}}){% endif %}: {{message}}\"\nschema = \"<type>(<scope>): <subject>\"\nschema_pattern = \"^(feat|fix|docs|style|refactor|perf|test|chore)(\\\\(\\\\w+\\\\))?:\\\\s.*\"\nbump_pattern = \"^(feat|fix|perf|refactor)\"\nbump_map = {\"feat\" = \"MINOR\", \"fix\" = \"PATCH\", \"perf\" = \"PATCH\", \"refactor\" = \"PATCH\"}\n```\n\n```bash\n# Install\npip install commitizen\n\n# Create commit interactively\ncz commit\n\n# Bump version and update changelog\ncz bump --changelog\n\n# Check commits\ncz check --rev-range HEAD~5..HEAD\n```\n\n## Release Notes Templates\n\n### GitHub Release Template\n\n```markdown\n## What''s Changed\n\n### 🚀 Features\n\n{{ range .Features }}\n\n- {{ .Title }} by @{{ .Author }} in #{{ .PR }}\n  {{ end }}\n\n### 🐛 Bug Fixes\n\n{{ range .Fixes }}\n\n- {{ .Title }} by @{{ .Author }} in #{{ .PR }}\n  {{ end }}\n\n### 📚 Documentation\n\n{{ range .Docs }}\n\n- {{ .Title }} by @{{ .Author }} in #{{ .PR }}\n  {{ end }}\n\n### 🔧 Maintenance\n\n{{ range .Chores }}\n\n- {{ .Title }} by @{{ .Author }} in #{{ .PR }}\n  {{ end }}\n\n## New Contributors\n\n{{ range .NewContributors }}\n\n- @{{ .Username }} made their first contribution in #{{ .PR }}\n  {{ end }}\n\n**Full Changelog**: https://github.com/owner/repo/compare/v{{ .Previous }}...v{{ .Current }}\n```\n\n### Internal Release Notes\n\n```markdown\n# Release v2.1.0 - January 15, 2024\n\n## Summary\n\nThis release introduces dark mode support and improves checkout performance\nby 40%. It also includes important security updates.\n\n## Highlights\n\n### 🌙 Dark Mode\n\nUsers can now switch to dark mode from settings. The preference is\nautomatically saved and synced across devices.\n\n### ⚡ Performance\n\n- Checkout flow is 40% faster\n- Reduced bundle size by 15%\n\n## Breaking Changes\n\nNone in this release.\n\n## Upgrade Guide\n\nNo special steps required. Standard deployment process applies.\n\n## Known Issues\n\n- Dark mode may flicker on initial load (fix scheduled for v2.1.1)\n\n## Dependencies Updated\n\n| Package | From    | To      | Reason                   |\n| ------- | ------- | ------- | ------------------------ |\n| react   | 18.2.0  | 18.3.0  | Performance improvements |\n| lodash  | 4.17.20 | 4.17.21 | Security patch           |\n```\n\n## Commit Message Examples\n\n```bash\n# Feature with scope\nfeat(auth): add OAuth2 support for Google login\n\n# Bug fix with issue reference\nfix(checkout): resolve race condition in payment processing\n\nCloses #123\n\n# Breaking change\nfeat(api)!: change user endpoint response format\n\nBREAKING CHANGE: The user endpoint now returns `userId` instead of `id`.\nMigration guide: Update all API consumers to use the new field name.\n\n# Multiple paragraphs\nfix(database): handle connection timeouts gracefully\n\nPreviously, connection timeouts would cause the entire request to fail\nwithout retry. This change implements exponential backoff with up to\n3 retries before failing.\n\nThe timeout threshold has been increased from 5s to 10s based on p99\nlatency analysis.\n\nFixes #456\nReviewed-by: @alice\n```\n\n## Best Practices\n\n### Do''s\n\n- **Follow Conventional Commits** - Enables automation\n- **Write clear messages** - Future you will thank you\n- **Reference issues** - Link commits to tickets\n- **Use scopes consistently** - Define team conventions\n- **Automate releases** - Reduce manual errors\n\n### Don''ts\n\n- **Don''t mix changes** - One logical change per commit\n- **Don''t skip validation** - Use commitlint\n- **Don''t manual edit** - Generated changelogs only\n- **Don''t forget breaking changes** - Mark with `!` or footer\n- **Don''t ignore CI** - Validate commits in pipeline\n\n## Resources\n\n- [Keep a Changelog](https://keepachangelog.com/)\n- [Conventional Commits](https://www.conventionalcommits.org/)\n- [Semantic Versioning](https://semver.org/)\n- [semantic-release](https://semantic-release.gitbook.io/)\n- [git-cliff](https://git-cliff.org/)\n"},"lastSynced":"2026-03-07T02:13:07.637Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated changelog generation and release note management.","zh":"非常适合需要自动化变更日志生成和发布说明管理的开发Agent。","ja":"変更ログの自動生成とリリースノート管理を必要とする開発エージェントに最適です。","ko":"변경 로그 자동 생성 및 릴리스 노트 관리가 필요한 개발 에이전트에 완벽합니다.","es":"Perfecto para Development Agents que necesitan generación automatizada de changelogs y gestión de notas de la versión.","fr":"Parfait pour les Development Agents nécessitant une génération automatisée de changelogs et une gestion des notes de version.","de":"Perfekt für Development Agents, die automatisierte Changelog-Generierung und Verwaltung von Release Notes benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de geração automática de changelog e gerenciamento de notas de lançamento.","ru":"Идеально для агентов разработки, которым требуется автоматизированная генерация журнала изменений и управление заметками о выпуске.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى توليد سجل التغييرات وتحكم إدارة ملاحظات الإصدار."},"recommendation":{"en":"Empowers agents to automate changelog generation, implement Conventional Commits, and manage semantic versioning using industry-standard tools and formats like GitHub/GitLab release notes and Markdown.","zh":"赋能Agent自动化变更日志生成，实施Conventional Commits，并使用行业标准工具和格式（如GitHub/GitLab发布说明和Markdown）来管理语义化版本控制。","ja":"エージェントが変更ログ生成の自動化、Conventional Commitsの実装、およびGitHub/GitLabリリースノートやMarkdownなどの業界標準ツールとフォーマットを使用したセマンティックバージョニングの管理を可能にします。","ko":"에이전트가 변경 로그 생성 자동화, Conventional Commits 구현, 그리고 GitHub/GitLab 릴리스 노트 및 Markdown과 같은 업계 표준 도구 및 형식을 사용한 시맨틱 버전 관리를 수행할 수 있도록 합니다.","es":"Permite a los agents automatizar la generación de changelogs, implementar Conventional Commits y gestionar el versionado semántico utilizando herramientas y formatos estándar de la industria como las GitHub/GitLab release notes y Markdown.","fr":"Permet aux agents d''automatiser la génération de changelogs, de mettre en œuvre Conventional Commits et de gérer le versioning sémantique en utilisant des outils et formats standard de l''industrie comme les GitHub/GitLab release notes et Markdown.","de":"Ermöglicht Agents, die Changelog-Generierung zu automatisieren, Conventional Commits zu implementieren und semantische Versionierung mit branchenüblichen Tools und Formaten wie GitHub/GitLab Release Notes und Markdown zu verwalten.","pt":"Habilita os agentes a automatizar a geração de changelog, implementar Commits Convencionais e gerenciar a versão semântica usando ferramentas e formatos padrão da indústria, como notas de lançamento do GitHub/GitLab e Markdown.","ru":"Наделяет агентов возможностью автоматизировать генерацию журнала изменений, реализовать Конвенциональные Коммиты и управлять семантическим версионированием с использованием отраслевых стандартных инструментов и форматов, таких как заметки о выпуске GitHub/GitLab и Markdown.","ar":"يمنح الوكلاء القدرة على توفير سجل التغييرات، وتنفيذ الالتزامات التقليدية، وإدارة الإصدارات الدلالية باستخدام أدوات ومواصفات الصناعة، مثل ملاحظات الإصدار GitHub/GitLab و Markdown."},"useCases":{"en":["Automating changelog generation","Implementing Conventional Commits for standardized commit messages","Generating GitHub/GitLab release notes"],"zh":["自动化变更日志生成","实施Conventional Commits以实现标准化的提交信息","生成GitHub/GitLab发布说明"],"ja":["変更ログ生成の自動化","標準化されたコミットメッセージのためのConventional Commitsの実装","GitHub/GitLabリリースノートの生成"],"ko":["변경 로그 생성 자동화","표준화된 커밋 메시지를 위한 Conventional Commits 구현","GitHub/GitLab 릴리스 노트 생성"],"es":["Automatización de la generación de changelogs","Implementación de Conventional Commits para mensajes de commit estandarizados","Generación de GitHub/GitLab release notes"],"fr":["Automatisation de la génération de changelogs","Mise en œuvre de Conventional Commits pour des messages de commit standardisés","Génération de GitHub/GitLab release notes"],"de":["Automatisierung der Changelog-Generierung","Implementierung von Conventional Commits für standardisierte Commit-Messages","Generierung von GitHub/GitLab Release Notes"],"pt":["Automatizar a geração de changelog","Implementar Commits Convencionais para mensagens de commit padronizadas","Gerar notas de lançamento do GitHub/GitLab"],"ru":["Автоматизировать генерацию журнала изменений","Реализовать Конвенциональные Коммиты для стандартизированных сообщений о коммите","Генерировать заметки о выпуске GitHub/GitLab"],"ar":["توليد سجل التغييرات تلقائيًا","تنفيذ الالتزامات التقليدية للرسائل التزامية المعيارية","توليد ملاحظات الإصدار GitHub/GitLab"]},"limitations":{"en":["Requires TypeScript SDK compatibility","Limited to LSP clients/servers"],"zh":["需要TypeScript SDK兼容性","仅限于LSP客户端/服务器"],"ja":["TypeScript SDKとの互換性が必要","LSPクライアント/サーバーに限定される"],"ko":["TypeScript SDK 호환성 필요","LSP 클라이언트/서버로 제한됨"],"es":["Requiere compatibilidad con el SDK de TypeScript","Limitado a clientes/servidores LSP"],"fr":["Nécessite une compatibilité avec le SDK TypeScript","Limité aux clients/serveurs LSP"],"de":["Erfordert TypeScript SDK-Kompatibilität","Beschränkt auf LSP-Clients/Server"],"pt":["Requer compatibilidade com SDK do TypeScript","Limitado a clientes/servidores LSP"],"ru":["Требует совместимости с SDK TypeScript","Ограничен для клиентов/серверов LSP"],"ar":["يتطلب توافقًا مع SDK TypeScript","محدود لعملاء/خادمات LSP"]},"version":4},"contentHash":"3b5fc90d13fa54918da996f84920eeb233efdb597decd77728f4c2d1d84049e6","qualityScore":60}');
