INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pradeepmouli/lsproxy/changelog-automation', 'changelog-automation', 'pradeepmouli', 'lsproxy', 'community', 'changelog-automation pradeepmouli lsproxy community This AI Agent skill automates changelog generation and release note workflows by enforcing the ''Keep a Changelog'' format and Conventional Commits standard. It is designed for developers and engineering teams managing semantic versioning. Changelog Automation是一个代理LSP服务器/客户端，具有插件/扩展支持，用于自动化变更日志生成和版本管理 Changelog Automationは、プラグイン/拡張機能をサポートするプロキシLSPサーバー/クライアントで、変更ログの自動化とバージョン管理を行います Changelog Automation은 플러그인/확장 기능을 지원하는 프록시 LSP 서버/클라이언트로, 변경 로그 자동화 및 버전 관리를 수행합니다 Automatice la generación de registros de cambios y notas de lanzamiento con patrones y herramientas de industria Automatisez la génération des journaux des modifications et des notes de publication avec des modèles et des outils de l''industrie Automatisieren Sie die Erstellung von Changelogs und Release-Notes mit Branchen-Mustern und -Tools A automação de changelog é um padrão de desenvolvimento que utiliza ferramentas de gerenciamento de versão para automatizar a geração de registros de alterações Автоматизация изменений - это padrão разработки, который использует инструменты управления версиями для автоматизации генерации журналов изменений آلة تشغيل سجل التغييرات هو نمط تطوير يستخدم أدوات إدارة الإصدارات لآلية تشغيل سجلات التغييرات how to use changelog-automation what is changelog-automation changelog-automation alternative changelog-automation vs standard-version changelog-automation install changelog-automation setup guide automate conventional commits github release notes automation semantic versioning automation 自动变更日志 Changelog Automation 变更日志生成 发布说明 版本管理 Conventional Commits 语义版本 AI工具 AIエージェント Automates changelog generation following the ''Keep a Changelog'' format Implements Conventional Commits for standardized commit messages Generates release notes for GitHub and GitLab platforms Manages semantic versioning (semver) for projects Provides extensibility through plugin and LSP server/client support changelog-automation is an AI Agent skill that acts as a proxy LSP server/client with plugin support. It provides patterns and tools for automating the generation of changelogs, release notes, and version management following industry standards like Conventional Commits.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AmitabhainArunachala/clawd/github-action-gen', 'community', 'AmitabhainArunachala', 'clawd', 'AmitabhainArunachala/clawd', 'github-action-gen', 0, 0, 60, '2026-03-07T01:49:01.811Z', '2026-03-07T03:31:54.336Z', '702367d412e26389bc4d35ec43bdecb6f104066af8929564c14b51cae4c4fde5', '{"id":"AmitabhainArunachala/clawd/github-action-gen","name":"github-action-gen","description":{"en":"github-action-gen generates complete GitHub Actions workflow files, handling common patterns like test, build, and deploy. It benefits developers by providing a quick and efficient way to automate workflows.","zh":"github-action-gen是一种AI工具，能够自动化生成GitHub Actions工作流，支持测试、构建和部署","ja":"github-action-genは、GitHub Actionsワークフローを自動生成するAIエージェントであり、テスト、ビルド、デプロイをサポートする","ko":"github-action-gen은 GitHub Actions 워크플ロー 자동 생성을 위한 AI 에이전트로, 테스트, 빌드 및 배포를 지원한다","es":"github-action-gen es una herramienta que genera flujos de trabajo de GitHub completos con un solo comando, incluyendo caché y despliegues múltiples.","fr":"github-action-gen est un outil qui génère des flux de travail GitHub complets avec une seule commande, y compris du cache et des déploiements multiples.","de":"github-action-gen ist ein Tool, das vollständige GitHub-Workflows mit einem einzigen Befehl generiert, einschließlich Cache und mehrfacher Bereitstellung.","pt":"O github-action-gen é uma ferramenta que gera workflows de GitHub Actions completos com apenas um comando","ru":"github-action-gen - это инструмент, который генерирует полные рабочие процессы GitHub Actions всего лишь одной командой","ar":"github-action-gen هو أداة تنتج سير عمل GitHub Actions كاملة باستخدام أمر واحد فقط"},"seo":{"title":{"en":"github-action-gen: Automated Workflow Generation for AI A...","zh":"github-action-gen Setup Guide - AI工具自动化工作流","ja":"github-action-gen セットアップガイド - AIエージェントによる自動化ワークフロー","ko":"github-action-gen 설정 가이드 - AI 에이전트를 활용한 자동화 워크플ロー","es":"Guía de configuración de github-action-gen: Generador de ...","fr":"Guide de mise en route de github-action-gen: Générateur d...","de":"Einrichtungsleitfaden für github-action-gen: GitHub-Actio...","pt":"Guia de Configuração do github-action-gen: Crie Workflows...","ru":"Настройка github-action-gen: Генератор рабочих процессов ...","ar":"دليل إعداد github-action-gen: إنشاء سير عمل GitHub Action..."},"description":{"en":"Streamline your GitHub workflow with github-action-gen. Learn how to generate complete workflow files with one command and zero config. Get started now!","zh":"使用github-action-gen自动化GitHub Actions工作流，简化测试、构建和部署过程","ja":"github-action-genを使用してGitHub Actionsワークフローを自動化し、テスト、ビルド、デプロイのプロセスを簡素化する","ko":"github-action-gen을 사용하여 GitHub Actions 워크플ロー 자동화, 테스트, 빌드 및 배포 단순화","es":"Descubre cómo github-action-gen genera flujos de trabajo de GitHub completos con un solo comando. Aprende a optimizar tus flujos de trabajo con caché y despl...","fr":"Découvrez comment github-action-gen génère des flux de travail GitHub complets avec une seule commande. Apprenez à optimiser vos flux de travail avec du cach...","de":"Erfahren Sie, wie github-action-gen vollständige GitHub-Workflows mit einem einzigen Befehl generiert. Lernen Sie, Ihre Workflows mit Cache und mehrfachen Be...","pt":"Aprenda a usar o github-action-gen para criar workflows de GitHub Actions personalizados sem precisar copiar e colar YAML","ru":"Узнайте, как использовать github-action-gen для создания индивидуальных рабочих процессов GitHub Actions без копирования YAML","ar":"تعرف على كيفية استخدام github-action-gen لإنشاء سير عمل GitHub Actions مخصصة بدون نسخ ولصق YAML"},"definition":{"en":"github-action-gen is a multi-agent content factory and coordination protocol that generates GitHub Actions workflows with features like caching and multiple deploy targets.","zh":"github-action-gen是一种AI工具，用于自动化生成GitHub Actions工作流","ja":"github-action-genはGitHub Actionsワークフローを自動生成するAIエージェント","ko":"github-action-gen은 GitHub Actions 워크플ロー 자동 생성을 위한 AI 에이전트","es":"github-action-gen es un generador de flujos de trabajo de GitHub que utiliza AI para crear flujos de trabajo personalizados con un solo comando.","fr":"github-action-gen est un générateur d''actions GitHub qui utilise l''IA pour créer des flux de travail personnalisés avec une seule commande.","de":"github-action-gen ist ein GitHub-Actions-Generator, der KI verwendet, um benutzerdefinierte Workflows mit einem einzigen Befehl zu erstellen.","pt":"O github-action-gen é um agente de IA que gera arquivos de workflow de GitHub Actions","ru":"github-action-gen - это ИИ Агент, генерирующий файлы рабочих процессов GitHub Actions","ar":"github-action-gen هو أداة إلكترونية تعتمد على الذكاء الاصطناعي لإنشاء ملفات سير عمل GitHub Actions"},"features":{"en":["Generates complete GitHub Actions workflow files","Handles common patterns like test, build, and deploy","Includes caching for faster runs","Supports multiple deploy targets","Can be used with a single command: npx ai-github-action","Zero configuration required"],"zh":["自动化生成GitHub Actions工作流","支持测试、构建和部署","包含缓存以加快运行速度","支持多个部署目标"],"ja":["GitHub Actionsワークフローを自動生成","テスト、ビルド、デプロイのサポート","キャッシュを含む高速化","複数のデプロイ先のサポート"],"ko":["GitHub Actions 워크플ロー 자동 생성","테스트, 빌드 및 배포 지원","캐시 포함으로 실행 속도 향상","다중 배포 대상 지원"],"es":["Genera flujos de trabajo de GitHub completos con un solo comando","Incluye caché para ejecuciones más rápidas","Soporta despliegues múltiples","Maneja patrones comunes como prueba, compilación y despliegue","Compatible con la línea de comandos (CLI)"],"fr":["Génère des flux de travail GitHub complets avec une seule commande","Inclut du cache pour des exécutions plus rapides","Prend en charge les déploiements multiples","Gère les modèles courants tels que test, build et déploiement","Compatible avec la ligne de commande (CLI)"],"de":["Erstellt vollständige GitHub-Workflows mit einem einzigen Befehl","Enthält Cache für schnellere Ausführungen","Unterstützt mehrfache Bereitstellungen","Verarbeitet gängige Muster wie Test, Build und Bereitstellung","Kompatibel mit der Kommandozeile (CLI)"],"pt":["Gera arquivos de workflow de GitHub Actions completos","Suporta padrões comuns como teste, build e deploy","Inclui cache para execuções mais rápidas","Suporta múltiplos alvos de deploy"],"ru":["Генерирует полные файлы рабочих процессов GitHub Actions","Поддерживает общие шаблоны, такие как тестирование, сборка и развертывание","Включает кэш для более быстрых запусков","Поддерживает несколько целей развертывания"],"ar":["ينتج ملفات سير عمل GitHub Actions كاملة","يدعم الأنماط الشائعة مثل الاختبار والبناء والتوزيع","يضم ذاكرة مؤقتة لتشغيل أسرع","يدعم أهداف توزيع متعددة"]},"keywords":{"en":["how to use github-action-gen","github-action-gen setup guide","github-action-gen alternative","github-action-gen vs github actions","github-action-gen install","automated workflow generation","github actions workflow files","multi-agent content factory"],"zh":["github-action-gen","AI工具","自动化工作流","GitHub Actions","测试自动化","构建自动化","部署自动化"],"ja":["github-action-gen","AIエージェント","自動化ワークフロー","GitHub Actions","テスト自動化","ビルド自動化","デプロイ自動化"],"ko":["github-action-gen","AI 에이전트","자동화 워크플ロー","GitHub Actions","테스트 자동화","빌드 자동화","배포 자동화"],"es":["github-action-gen","generador de flujos de trabajo de GitHub","herramientas de automatización de GitHub","despliegue continuo","pruebas automatizadas","integración continua","github actions","ai para desarrolladores","herramientas de desarrollo de software"],"fr":["github-action-gen","générateur d''actions GitHub","outils d''automatisation GitHub","déploiement continu","tests automatisés","intégration continue","github actions","ia pour les développeurs","outils de développement de logiciels"],"de":["github-action-gen","github-actions-generator","github-automatisierungstools","kontinuierliche bereitstellung","automatisierte tests","kontinuierliche integration","github actions","ki für entwickler","software-entwicklungstools"],"pt":["github-action-gen","agente de IA para GitHub Actions","criar workflows de GitHub Actions","ferramenta de automação de workflow","otimização de workflow de GitHub Actions","github actions cli","npx ai-github-action"],"ru":["github-action-gen","ИИ Агент для GitHub Actions","создание рабочих процессов GitHub Actions","инструмент автоматизации рабочих процессов","оптимизация рабочих процессов GitHub Actions","github actions cli","npx ai-github-action"],"ar":["github-action-gen","أداة ذكاء اصطناعي لإنشاء سير عمل GitHub Actions","إنشاء سير عمل GitHub Actions","أداة ت自动 سير العمل","تحسين سير عمل GitHub Actions","github actions cli","npx ai-github-action"]}},"owner":"AmitabhainArunachala","repo":"clawd","repoPath":"AmitabhainArunachala/clawd","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.811Z","topics":[],"category":"community","skillMd":{"name":"github-action-gen","description":"Generate GitHub Actions workflows from plain English. Use when setting up CI.","bodyPreview":"# GitHub Action Generator\n\nStop copy-pasting workflow YAML from StackOverflow. Describe what you want and get a working GitHub Actions workflow.\n\n**One command. Zero config. Just works.**\n\n## Quick Start\n\n```bash\nnpx ai-github-action \"test and deploy on push to main\"\n```\n\n## What It Does\n\n- Generates complete GitHub Actions workflow files\n- Handles common patterns like test, build, deploy\n- Includes caching for faster runs\n- Supports multiple deploy targets\n\n## Usage Examples\n\n```bash\n# Test and","body":"# GitHub Action Generator\n\nStop copy-pasting workflow YAML from StackOverflow. Describe what you want and get a working GitHub Actions workflow.\n\n**One command. Zero config. Just works.**\n\n## Quick Start\n\n```bash\nnpx ai-github-action \"test and deploy on push to main\"\n```\n\n## What It Does\n\n- Generates complete GitHub Actions workflow files\n- Handles common patterns like test, build, deploy\n- Includes caching for faster runs\n- Supports multiple deploy targets\n\n## Usage Examples\n\n```bash\n# Test and deploy\nnpx ai-github-action \"test and deploy on push to main\"\n\n# PR checks\nnpx ai-github-action \"run eslint and prettier on PRs\" --install\n\n# Docker workflow\nnpx ai-github-action \"build docker image and push to ECR\" -o deploy.yml\n\n# Scheduled job\nnpx ai-github-action \"run database backup every night at 2am\"\n```\n\n## Best Practices\n\n- **Use secrets** - never hardcode credentials\n- **Cache dependencies** - saves minutes per run\n- **Fail fast** - run quick checks first\n- **Use matrix builds** - test multiple node versions\n\n## When to Use This\n\n- Setting up CI for a new repo\n- Adding deployment automation\n- Creating custom workflows\n- Learning GitHub Actions syntax\n\n## Part of the LXGIC Dev Toolkit\n\nThis is one of 110+ free developer tools built by LXGIC Studios. No paywalls, no sign-ups, no API keys on free tiers. Just tools that work.\n\n**Find more:**\n- GitHub: https://github.com/LXGIC-Studios\n- Twitter: https://x.com/lxgicstudios\n- Substack: https://lxgicstudios.substack.com\n- Website: https://lxgicstudios.com\n\n## Requirements\n\nNo install needed. Just run with npx. Node.js 18+ recommended. Needs OPENAI_API_KEY environment variable.\n\n```bash\nnpx ai-github-action --help\n```\n\n## How It Works\n\nTakes your plain English description and generates GitHub Actions YAML with the right triggers, jobs, and steps. The AI knows common patterns and best practices for different workflows.\n\n## License\n\nMIT. Free forever. Use it however you want.\n"},"lastSynced":"2026-03-07T03:31:54.336Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing automated GitHub Actions workflow generation.","zh":"非常适合需要自动化 GitHub Actions 工作流生成的 DevOps 代理。","ja":"GitHub Actions ワークフローの自動生成を必要とする DevOps エージェントに最適です。","ko":"GitHub Actions 워크플로 자동 생성이 필요한 DevOps 에이전트에게 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan generación automática de flujos de trabajo de GitHub Actions.","fr":"Parfait pour les agents DevOps ayant besoin de génération automatique de flux de travail GitHub Actions.","de":"Perfekt für DevOps-Agents, die eine automatisierte Erstellung von GitHub Actions-Workflows benötigen.","pt":"Perfeito para Agents DevOps que necessitam de geração automática de fluxos de trabalho do GitHub Actions.","ru":"Идеально подходит для агентов DevOps, которым необходима автоматическая генерация рабочих процессов GitHub Actions.","ar":"مثالي للوكلاء DevOps الذين يحتاجون إلى توليد تلقائي لتدفقات العمل GitHub Actions."},"recommendation":{"en":"Empowers agents to generate complete GitHub Actions workflow files, handling common patterns like test, build, and deploy, with features including caching for faster runs and support for multiple deploy targets using YAML.","zh":"赋予代理生成完整的 GitHub Actions 工作流文件的能力，处理诸如测试、构建和部署等常见模式，功能包括缓存以实现更快的运行和使用 YAML 支持多个部署目标。","ja":"エージェントに、テスト、ビルド、デプロイなどの一般的なパターンを処理し、キャッシングによる高速実行や YAML を使用した複数のデプロイ先のサポートなどの機能を備えた、完全な GitHub Actions ワークフロー ファイルを生成する能力を提供します。","ko":"에이전트가 테스트, 빌드, 배포 등의 일반적인 패턴을 처리하고, 캐싱을 통한 빠른 실행 및 YAML을 사용한 여러 배포 대상 지원等의 기능을 갖춘 완전한 GitHub Actions 워크플로 파일을 생성할 수 있는 능력을 제공합니다.","es":"Habilita a los agentes a generar archivos de flujo de trabajo de GitHub Actions completos, manejando patrones comunes como pruebas, compilación y implementación, con características que incluyen caché para ejecuciones más rápidas y soporte para múltiples objetivos de implementación usando YAML.","fr":"Permet aux agents de générer des fichiers de flux de travail GitHub Actions complets, en gérant des modèles courants tels que les tests, la build et le déploiement, avec des fonctionnalités incluant la mise en cache pour des exécutions plus rapides et la prise en charge de plusieurs cibles de déploiement à l''aide de YAML.","de":"Ermöglicht es Agenten, vollständige GitHub Actions-Workflow-Dateien zu generieren, die gängige Muster wie Testen, Erstellen und Bereitstellen verarbeiten, mit Funktionen wie Caching für schnellere Ausführungen und Unterstützung für mehrere Bereitstellungsziele unter Verwendung von YAML.","pt":"Habilita os agentes a gerar arquivos de fluxo de trabalho do GitHub Actions completos, lidando com padrões comuns como teste, compilação e implantação, com recursos incluindo cache para execuções mais rápidas e suporte a vários alvos de implantação usando YAML.","ru":"Наделяет агентов возможностью генерировать полные файлы рабочих процессов GitHub Actions, обрабатывая общие шаблоны, такие как тест, сборка и развертывание, с функциями, включая кэширование для более быстрого выполнения и поддержку нескольких целевых объектов развертывания с использованием YAML.","ar":"يعزز الوكلاء لإنشاء ملفات تدفق عمل GitHub Actions كاملة، وتحديد أنماط شائعة مثل الاختبار والبناء والنشر، مع ميزات تشمل ذاكرة التخزين المؤقت لأوقات تشغيل أسرع ودعم أهداف النشر المتعددة باستخدام YAML."},"useCases":{"en":["Automating workflow generation for test and deploy pipelines","Generating workflows with caching for faster execution","Creating deploy workflows for multiple targets"],"zh":["自动化测试和部署管道的工作流生成","使用缓存以实现更快执行的工作流生成","为多个目标创建部署工作流"],"ja":["テストとデプロイ パイプラインのワークフロー自動生成","キャッシングによる高速実行のワークフロー生成","複数のターゲットのデプロイ ワークフロー作成"],"ko":["테스트 및 배포 파이프라인의 워크플로 자동 생성","캐싱을 통한 빠른 실행의 워크플로 생성","여러 대상의 배포 워크플로 생성"],"es":["Automatización de la generación de flujos de trabajo para pipelines de prueba y despliegue","Generación de flujos de trabajo con caché para ejecución más rápida","Creación de flujos de trabajo de despliegue para múltiples objetivos"],"fr":["Automatisation de la génération de flux de travail pour les pipelines de test et de déploiement","Génération de flux de travail avec mise en cache pour exécution plus rapide","Création de flux de travail de déploiement pour plusieurs cibles"],"de":["Automatisierung der Workflow-Erstellung für Test- und Bereitstellungspipelines","Erstellung von Workflows mit Caching für schnellere Ausführung","Erstellung von Bereitstellungsworkflows für mehrere Ziele"],"pt":["Automatizar a geração de fluxos de trabalho para pipelines de teste e implantação","Gerar fluxos de trabalho com cache para execução mais rápida","Criar fluxos de trabalho de implantação para vários alvos"],"ru":["Автоматизация генерации рабочих процессов для конвейеров тестирования и развертывания","Генерация рабочих процессов с кэшированием для более быстрого выполнения","Создание рабочих процессов развертывания для нескольких целей"],"ar":["توليد تلقائي لتدفقات العمل لخطوط أنابيب الاختبار والنشر","إنشاء تدفقات العمل مع ذاكرة التخزين المؤقت للتشغيل الأسرع","إنشاء تدفقات العمل لنشر العدة أهداف"]},"limitations":{"en":["Requires npm or npx for execution","Limited to GitHub Actions workflow generation"],"zh":["需要 npm 或 npx 才能执行","仅限 GitHub Actions 工作流生成"],"ja":["実行には npm または npx が必要","GitHub Actions ワークフロー生成のみ"],"ko":["실행에는 npm 또는 npx가 필요","GitHub Actions 워크플로 생성만"],"es":["Requiere npm o npx para la ejecución","Limitado a la generación de flujos de trabajo de GitHub Actions"],"fr":["Nécessite npm ou npx pour l''exécution","Limité à la génération de flux de travail GitHub Actions"],"de":["Benötigt npm oder npx für die Ausführung","Begrenzt auf die Erstellung von GitHub Actions-Workflows"],"pt":["Exige npm ou npx para execução","Limitado à geração de fluxos de trabalho do GitHub Actions"],"ru":["Требует npm или npx для выполнения","Ограничен генерацией рабочих процессов GitHub Actions"],"ar":["يتطلب npm أو npx للتنفيذ","محدود بتوليد تدفقات العمل GitHub Actions"]},"version":4},"contentHash":"702367d412e26389bc4d35ec43bdecb6f104066af8929564c14b51cae4c4fde5","qualityScore":60}');
