INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AmitabhainArunachala/clawd/github-action-gen', 'github-action-gen', 'AmitabhainArunachala', 'clawd', 'community', 'github-action-gen AmitabhainArunachala clawd community github-action-gen generates complete GitHub Actions workflow files, handling common patterns like test, build, and deploy. It benefits developers by providing a quick and efficient way to automate workflows. github-action-gen是一种AI工具，能够自动化生成GitHub Actions工作流，支持测试、构建和部署 github-action-genは、GitHub Actionsワークフローを自動生成するAIエージェントであり、テスト、ビルド、デプロイをサポートする github-action-gen은 GitHub Actions 워크플ロー 자동 생성을 위한 AI 에이전트로, 테스트, 빌드 및 배포를 지원한다 github-action-gen es una herramienta que genera flujos de trabajo de GitHub completos con un solo comando, incluyendo caché y despliegues múltiples. github-action-gen est un outil qui génère des flux de travail GitHub complets avec une seule commande, y compris du cache et des déploiements multiples. github-action-gen ist ein Tool, das vollständige GitHub-Workflows mit einem einzigen Befehl generiert, einschließlich Cache und mehrfacher Bereitstellung. O github-action-gen é uma ferramenta que gera workflows de GitHub Actions completos com apenas um comando github-action-gen - это инструмент, который генерирует полные рабочие процессы GitHub Actions всего лишь одной командой github-action-gen هو أداة تنتج سير عمل GitHub Actions كاملة باستخدام أمر واحد فقط how to use github-action-gen github-action-gen setup guide github-action-gen alternative github-action-gen vs github actions github-action-gen install automated workflow generation github actions workflow files multi-agent content factory github-action-gen AI工具 自动化工作流 GitHub Actions 测试自动化 构建自动化 部署自动化 Generates complete GitHub Actions workflow files Handles common patterns like test, build, and deploy Includes caching for faster runs Supports multiple deploy targets Can be used with a single command: npx ai-github-action Zero configuration required github-action-gen is a multi-agent content factory and coordination protocol that generates GitHub Actions workflows with features like caching and multiple deploy targets.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rysweet/amplihack/github', 'community', 'rysweet', 'amplihack', 'rysweet/amplihack', 'github', 0, 0, 60, '2026-03-06T12:59:22.125Z', '2026-03-06T13:13:22.951Z', '2d7fc654fdf190cce87c47f9760ee0961c7ff92590cb21bd1b196e5f1998a0d4', '{"id":"rysweet/amplihack/github","name":"github","description":{"en":"The GitHub skill provides a framework for agentic coding, supporting popular tools. It benefits developers by streamlining their workflow with features like authentication and configuration.","zh":"GitHub CLI 是一个支持多种流行的代码工具的框架，提供交互式认证、配置默认编辑器和浏览器等功能","ja":"GitHub CLI は、インタラクティブ認証、デフォルトエディターとブラウザーの設定など、複数のコードツールをサポートするフレームワークです","ko":"GitHub CLI는 상호작용 인증, 기본 편집기 및 브라우저 설정 등을 제공하는 다중 코드 도구를 지원하는 프레임워크입니다","es":"El framework de GitHub CLI permite a los desarrolladores interactuar con GitHub de manera efectiva. Configure y autentice su instancia con facilidad","fr":"Le framework GitHub CLI permet aux développeurs d''interagir avec GitHub de manière efficace. Configurez et authentifiez votre instance avec facilité","de":"Das GitHub CLI-Framework ermöglicht es Entwicklern, mit GitHub effektiv zu interagieren. Konfigurieren und authentifizieren Sie Ihre Instanz problemlos","pt":"O GitHub CLI é uma ferramenta de linha de comando para interagir com o GitHub. Ele suporta autenticação interativa e configuração de editor e navegador padrão","ru":"GitHub CLI — это командная строка для взаимодействия с GitHub. Он поддерживает интерактивную аутентификацию и конфигурацию редактора и браузера по умолчанию","ar":"GitHub CLI هو أداة سطر الأوامر للتفاعل مع GitHub. يدعم المصادقة التفاعلية وتكوين محرر ومتصفح افتراضي"},"seo":{"title":{"en":"GitHub: Setup Guide for AI Agents | AI Agent Skill","zh":"GitHub CLI Setup Guide","ja":"GitHub CLI のベストプラクティス","ko":"GitHub CLI 설정 가이드","es":"Guía de configuración de GitHub CLI","fr":"Guide de configuration de GitHub CLI","de":"GitHub CLI-Konfigurationsleitfaden","pt":"Guia de Configuração GitHub CLI para Desenvolvedores","ru":"Настройка GitHub CLI: Руководство для разработчиков ИИ Аг...","ar":"دليل إعداد GitHub CLI للبرمجة الوكيلية"},"description":{"en":"Unlock the full potential of GitHub with our expert guide. Learn how to authenticate, configure, and optimize your workflow with GitHub CLI.","zh":"学习如何使用 GitHub CLI 实现交互式认证、配置默认编辑器和浏览器等功能","ja":"GitHub CLI を使用してインタラクティブ認証、デフォルトエディターとブラウザーの設定などを行う方法を学びます","ko":"GitHub CLI를 사용하여 상호작용 인증, 기본 편집기 및 브라우저 설정 등을 수행하는 방법을 배우세요","es":"Aprende a configurar y autenticar GitHub CLI con nuestros ejemplos de código y consejos prácticos para desarrolladores","fr":"Découvrez comment configurer et authentifier GitHub CLI avec nos exemples de code et conseils pratiques pour les développeurs","de":"Erfahren Sie, wie Sie GitHub CLI konfigurieren und authentifizieren können, mit unseren Codebeispielen und praktischen Tipps für Entwickler","pt":"Aprenda a configurar o GitHub CLI com autenticação interativa e configuração de editor e navegador padrão para melhorar a produtividade dos desenvolvedores","ru":"Узнайте, как настроить GitHub CLI с помощью интерактивной аутентификации и конфигурации редактора и браузера по умолчанию для повышения производительности ра...","ar":"تعلم كيفية cấu hình GitHub CLI باستخدام مصادقة تفاعلية وتكوين محرر ومتصفح افتراضي لتحسين إنتاجية المطورين"},"definition":{"en":"GitHub is a framework for agentic coding that supports many popular agent coding tools, providing features like interactive authentication and configuration.","zh":"GitHub CLI 是一个命令行接口，用于与 GitHub 进行交互","ja":"GitHub CLI は、GitHub と対話するためのコマンドラインインターフェイスです","ko":"GitHub CLI는 GitHub와 상호작용하는 명령줄 인터페이스입니다","es":"GitHub CLI es un framework para la codificación de agentes que admite varias herramientas de codificación de agentes populares","fr":"GitHub CLI est un framework pour la codification d''agents qui prend en charge plusieurs outils de codification d''agents populaires","de":"GitHub CLI ist ein Framework für die Kodierung von Agenten, das mehrere beliebte Agentenkodierungstools unterstützt","pt":"O que é GitHub CLI? É uma ferramenta de linha de comando para interagir com o GitHub","ru":"Что такое GitHub CLI? Это командная строка для взаимодействия с GitHub","ar":"ما هو GitHub CLI؟ هو أداة سطر الأوامر للتفاعل مع GitHub"},"features":{"en":["Interactive authentication using gh auth login","Configuration of default editor with gh config set editor","Setting default browser with gh config set browser","Support for SSH git protocol with gh config set git_protocol","Login to enterprise with gh auth login --hostname"],"zh":["交互式认证","配置默认编辑器","配置默认浏览器","支持 SSH Git 协议","设置默认 Git 协议"],"ja":["インタラクティブ認証","デフォルトエディターの設定","デフォルトブラウザーの設定","SSH Git プロトコルのサポート","デフォルト Git プロトコルの設定"],"ko":["상호작용 인증","기본 편집기 설정","기본 브라우저 설정","SSH Git 프로토콜 지원","기본 Git 프로토콜 설정"],"es":["Autenticación interactiva con gh auth login","Configuración del editor predeterminado con gh config set editor","Configuración del protocolo Git predeterminado con gh config set git_protocol","Compatibilidad con tokens de autenticación","Soporte para empresas con gh auth login --hostname"],"fr":["Authentification interactive avec gh auth login","Configuration de l''éditeur par défaut avec gh config set editor","Configuration du protocole Git par défaut avec gh config set git_protocol","Compatibilité avec les jetons d''authentification","Prise en charge des entreprises avec gh auth login --hostname"],"de":["Interaktive Authentifizierung mit gh auth login","Konfiguration des Standardeditors mit gh config set editor","Konfiguration des Standard-Git-Protokolls mit gh config set git_protocol","Unterstützung für Authentifizierungstoken","Unterstützung für Unternehmen mit gh auth login --hostname"],"pt":["Autenticação interativa com gh auth login","Configuração de editor padrão com gh config set editor","Configuração de navegador padrão com gh config set browser","Suporte a protocolo git ssh com gh config set git_protocol","Login com token com gh auth login --with-token"],"ru":["Интерактивная аутентификация с gh auth login","Конфигурация редактора по умолчанию с gh config set editor","Конфигурация браузера по умолчанию с gh config set browser","Поддержка протокола git ssh с gh config set git_protocol","Вход с токеном с gh auth login --with-token"],"ar":["المصادقة التفاعلية مع gh auth login","تكوين محرر افتراضي مع gh config set editor","تكوين متصفح افتراضي مع gh config set browser","دعم بروتوكول git ssh مع gh config set git_protocol","دخول بالرمز مع gh auth login --with-token"]},"keywords":{"en":["how to use github cli","github setup guide","github vs gitlab","github install","what is github cli","github authentication tutorial","github configuration best practices"],"zh":["GitHub CLI","交互式认证","代码工具","命令行接口","Git 协议","SSH Git","AIエージェント","代码管理"],"ja":["GitHub CLI","インタラクティブ認証","コードツール","コマンドラインインターフェイス","Git プロトコル","SSH Git","AIエージェント","コード管理"],"ko":["GitHub CLI","상호작용 인증","코드 도구","명령줄 인터페이스","Git 프로토콜","SSH Git","AI 에이전트","코드 관리"],"es":["GitHub CLI","autenticación de GitHub","configuración de GitHub","herramientas de codificación de agentes","framework de agentes","desarrollo de software","Herramientas de desarrollo","Integración con GitHub","Autenticación de tokens"],"fr":["GitHub CLI","authentification GitHub","configuration GitHub","outils de codification d''agents","framework d''agents","développement de logiciels","Outils de développement","Intégration avec GitHub","Authentification de jetons"],"de":["GitHub CLI","GitHub-Authentifizierung","GitHub-Konfiguration","Agentenkodierungstools","Agentenframework","Softwareentwicklung","Entwicklungstools","Integration mit GitHub","Authentifizierungstoken"],"pt":["github cli","autenticação interativa","configuração de editor","configuração de navegador","protocolo git ssh","login com token","desenvolvedores","programação","ferramentas de desenvolvimento"],"ru":["github cli","интерактивная аутентификация","конфигурация редактора","конфигурация браузера","протокол git ssh","вход с токеном","разработчики","программирование","инструменты разработки","ИИ Агенты"],"ar":["github cli","المصادقة التفاعلية","تكوين محرر","تكوين متصفح","بروتوكول git ssh","دخول بالرمز","مطورين","برمجة","أدوات التطوير","البرمجة الوكيلية"]}},"owner":"rysweet","repo":"amplihack","repoPath":"rysweet/amplihack","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.125Z","topics":[],"category":"community","skillMd":{"name":"github","description":"Expert guidance for GitHub CLI (gh) - issues, PRs, repos, releases, and GitHub API. Use when working with GitHub, managing issues/PRs, or when user mentions GitHub, PRs, issues, or repos. Preferred over GitHub MCP server for context efficiency.","bodyPreview":"# GitHub CLI Skill\n\n## Quick Start\n\n### Authentication\n\n```bash\n# Interactive authentication (recommended)\ngh auth login\n\n# Check authentication status\ngh auth status\n\n# Login with token\ngh auth login --with-token < token.txt\n\n# Login to enterprise\ngh auth login --hostname github.example.com\n```\n\n### Configuration\n\n```bash\n# Set default editor\ngh config set editor \"code --wait\"\n\n# Set default browser\ngh config set browser \"firefox\"\n\n# Set default git protocol\ngh config set git_protocol ssh\n\n# Vi","body":"# GitHub CLI Skill\n\n## Quick Start\n\n### Authentication\n\n```bash\n# Interactive authentication (recommended)\ngh auth login\n\n# Check authentication status\ngh auth status\n\n# Login with token\ngh auth login --with-token < token.txt\n\n# Login to enterprise\ngh auth login --hostname github.example.com\n```\n\n### Configuration\n\n```bash\n# Set default editor\ngh config set editor \"code --wait\"\n\n# Set default browser\ngh config set browser \"firefox\"\n\n# Set default git protocol\ngh config set git_protocol ssh\n\n# View all settings\ngh config list\n```\n\n## Essential Commands (Most Common First)\n\n### 1. Issues\n\n```bash\n# Create issue\ngh issue create --title \"Bug: something broken\" --body \"Description here\"\n\n# Create with labels\ngh issue create --title \"Feature request\" --label \"enhancement,priority:high\"\n\n# List issues\ngh issue list                    # Open issues\ngh issue list --state all        # All issues\ngh issue list --assignee @me     # Assigned to me\ngh issue list --label \"bug\"      # By label\n\n# View issue\ngh issue view 123                # By number\ngh issue view 123 --comments     # With comments\n\n# Edit issue\ngh issue edit 123 --title \"New title\"\ngh issue edit 123 --add-label \"in-progress\"\ngh issue edit 123 --assignee username\n\n# Close/reopen\ngh issue close 123\ngh issue close 123 --comment \"Fixed in PR #456\"\ngh issue reopen 123\n\n# Comment\ngh issue comment 123 --body \"This is a comment\"\n```\n\n### 2. Pull Requests\n\n```bash\n# Create PR\ngh pr create --title \"Feature: new thing\" --body \"Description\"\ngh pr create --draft                       # Create as draft\ngh pr create --fill                        # Auto-fill from commits\n\n# List PRs\ngh pr list                        # Open PRs\ngh pr list --state merged         # Merged PRs\ngh pr list --author @me           # My PRs\ngh pr list --search \"review:required\"\n\n# View PR\ngh pr view 123                    # By number\ngh pr view                        # Current branch PR\ngh pr diff 123                    # View diff\ngh pr checks 123                  # View CI status\n\n# Review PRs\ngh pr review 123 --approve\ngh pr review 123 --request-changes --body \"Please fix X\"\ngh pr review 123 --comment --body \"Looks good overall\"\n\n# Merge\ngh pr merge 123                   # Interactive\ngh pr merge 123 --squash          # Squash merge\ngh pr merge 123 --rebase          # Rebase merge\ngh pr merge 123 --auto            # Auto-merge when checks pass\n\n# Mark ready\ngh pr ready 123                   # Convert draft to ready\n\n# Comment\ngh pr comment 123 --body \"Comment text\"\n\n# Close\ngh pr close 123\n```\n\n### 3. Repository\n\n```bash\n# Clone\ngh repo clone owner/repo\ngh repo clone owner/repo -- --depth 1   # Shallow clone\n\n# Create\ngh repo create my-repo --public\ngh repo create my-repo --private --clone\n\n# View\ngh repo view                      # Current repo\ngh repo view owner/repo           # Specific repo\ngh repo view --web                # Open in browser\n\n# Fork\ngh repo fork owner/repo\ngh repo fork owner/repo --clone   # Fork and clone\n\n# Sync fork\ngh repo sync                      # Sync fork with upstream\n\n# List repos\ngh repo list                      # Your repos\ngh repo list owner                # Organization repos\n```\n\n### 4. Workflow (GitHub Actions)\n\n```bash\n# List workflows\ngh workflow list\n\n# View workflow runs\ngh run list                       # Recent runs\ngh run list --workflow ci.yml     # By workflow\ngh run list --status failure      # Failed runs\n\n# View run details\ngh run view 123456                # By run ID\ngh run view 123456 --log          # With logs\ngh run view 123456 --log-failed   # Only failed logs\n\n# Trigger workflow\ngh workflow run ci.yml\ngh workflow run ci.yml -f param=value\n\n# Watch run\ngh run watch                      # Watch current branch run\ngh run watch 123456               # Watch specific run\n\n# Cancel/rerun\ngh run cancel 123456\ngh run rerun 123456\ngh run rerun 123456 --failed      # Rerun only failed jobs\n```\n\n### 5. Search\n\n```bash\n# Search issues/PRs\ngh search issues \"bug in:title\"\ngh search issues \"label:bug state:open\"\ngh search prs \"author:username is:merged\"\n\n# Search repos\ngh search repos \"language:python stars:>1000\"\n\n# Search code\ngh search code \"function handleError\"\ngh search code \"filename:config.json org:myorg\"\n```\n\n## Advanced Commands\n\n### Releases\n\n```bash\n# Create release\ngh release create v1.0.0 --title \"Version 1.0\" --notes \"Release notes\"\ngh release create v1.0.0 --generate-notes   # Auto-generate notes\ngh release create v1.0.0 ./dist/*           # Upload assets\n\n# List/view\ngh release list\ngh release view v1.0.0\n\n# Download assets\ngh release download v1.0.0\ngh release download v1.0.0 --pattern \"*.zip\"\n```\n\n### Gists\n\n```bash\n# Create gist\ngh gist create file.txt\ngh gist create --public file.txt\ngh gist create -d \"Description\" file1.txt file2.txt\n\n# List/view\ngh gist list\ngh gist view gist_id\n\n# Edit\ngh gist edit gist_id\n```\n\n### API Access\n\n```bash\n# GraphQL query\ngh api graphql -f query=''{ viewer { login } }''\n\n# REST API\ngh api repos/owner/repo/issues\ngh api repos/owner/repo/issues --method POST -f title=\"Issue title\"\n\n# Paginate\ngh api repos/owner/repo/issues --paginate\n```\n\n### SSH Keys & GPG\n\n```bash\n# SSH keys\ngh ssh-key add ~/.ssh/id_ed25519.pub --title \"My laptop\"\ngh ssh-key list\n\n# GPG keys\ngh gpg-key add key.asc\ngh gpg-key list\n```\n\n## Common Patterns\n\n### Issue-to-PR Workflow\n\n```bash\n# 1. Create issue\ngh issue create --title \"Feature: X\" --label \"enhancement\"\n# Returns issue #123\n\n# 2. Create branch and work\ngit checkout -b feat/issue-123-x\n\n# 3. Create PR linking to issue\ngh pr create --title \"Feature: X\" --body \"Closes #123\"\n```\n\n### Code Review Flow\n\n```bash\n# Check out PR locally\ngh pr checkout 456\n\n# Run tests, review code...\n\n# Approve or request changes\ngh pr review 456 --approve --body \"LGTM!\"\n```\n\n### CI Failure Investigation\n\n```bash\n# List failed runs\ngh run list --status failure\n\n# Get logs\ngh run view RUN_ID --log-failed\n\n# Rerun after fix\ngh run rerun RUN_ID\n```\n\n## Re-enabling GitHub MCP Server\n\nIf you need the full GitHub MCP server for advanced operations (e.g., complex GraphQL queries, bulk operations), you can ask:\n\n> \"Please use the GitHub MCP server\" or \"Re-enable GitHub MCP\"\n\nTo re-enable manually:\n\n1. Edit `~/.copilot/github-copilot/mcp.json`\n2. Remove or set `\"disabled\": false` for github-mcp-server:\n\n```json\n{\n  \"mcpServers\": {\n    \"github-mcp-server\": {\n      \"disabled\": false\n    }\n  }\n}\n```\n\n3. Restart the Copilot CLI session\n\n**When to use MCP vs gh CLI:**\n\n| Use gh CLI                         | Use GitHub MCP                            |\n| ---------------------------------- | ----------------------------------------- |\n| Standard issue/PR operations       | Complex multi-step GitHub operations      |\n| CI/CD workflow management          | Bulk operations across many repos         |\n| Quick lookups and status checks    | Advanced GraphQL queries                  |\n| Script automation                  | Operations requiring persistent state     |\n| **Most daily GitHub interactions** | **Rare, specialized GitHub integrations** |\n\n## Troubleshooting\n\n```bash\n# Check auth\ngh auth status\n\n# Refresh token\ngh auth refresh\n\n# Clear cache\ngh cache delete --all\n\n# Debug mode\nGH_DEBUG=api gh issue list\n```\n\n## Environment Variables\n\n```bash\nGH_TOKEN           # Auth token (alternative to gh auth)\nGH_HOST            # Default host (for enterprise)\nGH_REPO            # Default repo (owner/repo format)\nGH_EDITOR          # Editor for interactive commands\nGH_BROWSER         # Browser for --web commands\nGH_DEBUG           # Enable debug output (api, oauth)\nNO_COLOR           # Disable colored output\n```\n"},"lastSynced":"2026-03-06T13:13:22.951Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents requiring streamlined GitHub workflow integration and authentication capabilities.","zh":"适合需要简化GitHub工作流集成和身份验证功能的开发者代理。","ja":"GitHubワークフロー統合と認証機能をストリームライン化する必要がある開発者エージェントに最適。","ko":"GitHub 워크플로 통합 및 인증 기능을 간소화해야 하는 개발자 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollador que requieren una integración y capacidades de autenticación de flujo de trabajo de GitHub optimizadas.","fr":"Idéal pour les agents de développement nécessitant une intégration et des capacités d''authentification de workflow GitHub optimisées.","de":"Ideal für Entwickleragenten, die eine optimierte GitHub-Workflow-Integration und Authentifizierungsfunktionen benötigen.","pt":"Ideal para Agentes de Desenvolvedor que requerem integração e capacidades de autenticação de fluxo de trabalho do GitHub otimizados.","ru":"Идеально для агентов разработчиков, требующих оптимизированной интеграции и аутентификации рабочего процесса GitHub.","ar":"مثالي لوكلاء المطورين الذين يحتاجون إلى تكامل وتأهيل عملية العمل على GitHub المُيسَر"},"recommendation":{"en":"Empowers agents to automate GitHub interactions using the GitHub CLI, supporting features like authentication with tokens, configuration of default editors and browsers, and setting git protocols such as SSH, enhancing their workflow efficiency and security.","zh":"赋予代理自动化GitHub交互的能力，使用GitHub CLI，支持令牌身份验证、默认编辑器和浏览器配置以及设置Git协议（如SSH），从而提高工作效率和安全性。","ja":"GitHub CLIを使用して、エージェントがGitHubの相互作用を自動化できるようにし、トークンによる認証、デフォルトエディターとブラウザーの構成、Gitプロトコル（SSHなど）の設定などをサポートし、ワークフローの効率とセキュリティを向上させます。","ko":"GitHub CLI를 사용하여 에이전트가 GitHub 상호 작용을 자동화 할 수 있도록 하며 토큰 인증, 기본 편집기 및 브라우저 구성, Git 프로토콜 (SSH 등) 설정 등을 지원하여 워크플로 효율성과 보안을 향상합니다.","es":"Habilita a los agentes a automatizar las interacciones de GitHub utilizando la CLI de GitHub, que admite características como la autenticación con tokens, la configuración de editores y navegadores predeterminados y la configuración de protocolos git como SSH, mejorando así su eficiencia y seguridad del flujo de trabajo.","fr":"Permet aux agents d''automatiser les interactions GitHub en utilisant la CLI GitHub, prenant en charge des fonctionnalités comme l''authentification avec des jetons, la configuration des éditeurs et navigateurs par défaut et la configuration des protocoles git tels que SSH, améliorant ainsi leur efficacité et sécurité du flux de travail.","de":"Ermächtigt die Agenten, die GitHub-Interaktionen mithilfe der GitHub-CLI zu automatisieren, die Funktionen wie Authentifizierung mit Token, Konfiguration von Standardeditoren und -browsern und Festlegung von Git-Protokollen wie SSH unterstützt, wodurch die Effizienz und Sicherheit des Arbeitsablaufs verbessert werden.","pt":"Habilita os agentes a automatizar interações do GitHub usando o GitHub CLI, com recursos como autenticação com tokens, configuração de editores e navegadores padrão e definição de protocolos git como SSH, melhorando a eficiência e segurança do fluxo de trabalho.","ru":"Предоставляет агентам возможность автоматизировать взаимодействия с GitHub с помощью GitHub CLI, поддерживая функции, такие как аутентификация с помощью токенов, настройка редакторов и браузеров по умолчанию, а также установка протоколов git, таких как SSH, повышая эффективность и безопасность рабочего процесса.","ar":"يمنح الوكلاء القدرة على توفير آلي للتفاعلات مع GitHub باستخدام واجهة سطر الأوامر GitHub، مع دعم لميزات مثل التأهيل باستخدام الرموز، وتكوين محررات وبرمجيات العرض الافتراضية، وضبط بروتوكولات جيت مثل SSH، مما يعزز كفاءة وأمان عملية العمل"},"useCases":{"en":["Automating repository management","Configuring default development tools","Debugging authentication issues with gh auth status"],"zh":["自动化仓库管理","配置默认开发工具","使用gh auth status调试身份验证问题"],"ja":["リポジトリ管理の自動化","デフォルト開発ツールの構成","gh auth statusで認証問題をデバッグ"],"ko":["仓庫 관리 자동화","기본 개발 도구 구성","gh auth status로 인증 문제 디버깅"],"es":["Automatización de la gestión de repositorios","Configuración de herramientas de desarrollo predeterminadas","Depuración de problemas de autenticación con gh auth status"],"fr":["Automatisation de la gestion des référentiels","Configuration des outils de développement par défaut","Débogage des problèmes d''authentification avec gh auth status"],"de":["Automatisierung der Repository-Verwaltung","Konfiguration von Standard-Entwicklungstools","Fehlerbehebung bei Authentifizierungsproblemen mit gh auth status"],"pt":["Automatizar gerenciamento de repositórios","Configurar ferramentas de desenvolvimento padrão","Depurar problemas de autenticação com gh auth status"],"ru":["Автоматизировать управление репозиториями","Настроить инструменты разработки по умолчанию","Отладить проблемы аутентификации с помощью gh auth status"],"ar":["توفير آلي لإدارة المستودعات","تكوين أدوات التطوير الافتراضية","تصحيح مشاكل التأهيل باستخدام حالة تأهيل جيه"]},"limitations":{"en":["Requires GitHub CLI installation","Needs authentication token or interactive login","Limited to GitHub platforms"],"zh":["需要GitHub CLI安装","需要身份验证令牌或交互式登录","仅限GitHub平台"],"ja":["GitHub CLIのインストールが必要","認証トークンまたは対話式ログインが必要","GitHubプラットフォームのみ"],"ko":["GitHub CLI 설치 필요","인증 토큰 또는 상호 작용 로그인 필요","GitHub 플랫폼만 해당"],"es":["Requiere la instalación de la CLI de GitHub","Necesita un token de autenticación o inicio de sesión interactivo","Limitado a plataformas de GitHub"],"fr":["Nécessite l''installation de la CLI GitHub","Nécessite un jeton d''authentification ou une connexion interactive","Limité aux plateformes GitHub"],"de":["Benötigt die Installation der GitHub-CLI","Benötigt ein Authentifizierungstoken oder interaktiven Login","Begrenzt auf GitHub-Plattformen"],"pt":["Requer instalação do GitHub CLI","Necessita de token de autenticação ou login interativo","Limitado às plataformas do GitHub"],"ru":["Требует установки GitHub CLI","Требует токена аутентификации или интерактивного входа","Ограничен платформами GitHub"],"ar":["يتطلب تثبيت واجهة سطر الأوامر GitHub","يحتاج إلى رمز تأهيل أو تسجيل الدخول التفاعلي","محدود منصات GitHub"]},"version":4},"contentHash":"2d7fc654fdf190cce87c47f9760ee0961c7ff92590cb21bd1b196e5f1998a0d4","qualityScore":60}');
