INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rysweet/amplihack/github', 'github', 'rysweet', 'amplihack', 'community', 'github rysweet amplihack community The GitHub skill provides a framework for agentic coding, supporting popular tools. It benefits developers by streamlining their workflow with features like authentication and configuration. GitHub CLI 是一个支持多种流行的代码工具的框架，提供交互式认证、配置默认编辑器和浏览器等功能 GitHub CLI は、インタラクティブ認証、デフォルトエディターとブラウザーの設定など、複数のコードツールをサポートするフレームワークです GitHub CLI는 상호작용 인증, 기본 편집기 및 브라우저 설정 등을 제공하는 다중 코드 도구를 지원하는 프레임워크입니다 El framework de GitHub CLI permite a los desarrolladores interactuar con GitHub de manera efectiva. Configure y autentice su instancia con facilidad Le framework GitHub CLI permet aux développeurs d''interagir avec GitHub de manière efficace. Configurez et authentifiez votre instance avec facilité Das GitHub CLI-Framework ermöglicht es Entwicklern, mit GitHub effektiv zu interagieren. Konfigurieren und authentifizieren Sie Ihre Instanz problemlos O GitHub CLI é uma ferramenta de linha de comando para interagir com o GitHub. Ele suporta autenticação interativa e configuração de editor e navegador padrão GitHub CLI — это командная строка для взаимодействия с GitHub. Он поддерживает интерактивную аутентификацию и конфигурацию редактора и браузера по умолчанию GitHub CLI هو أداة سطر الأوامر للتفاعل مع GitHub. يدعم المصادقة التفاعلية وتكوين محرر ومتصفح افتراضي how to use github cli github setup guide github vs gitlab github install what is github cli github authentication tutorial github configuration best practices GitHub CLI 交互式认证 代码工具 命令行接口 Git 协议 SSH Git AIエージェント 代码管理 Interactive authentication using gh auth login Configuration of default editor with gh config set editor Setting default browser with gh config set browser Support for SSH git protocol with gh config set git_protocol Login to enterprise with gh auth login --hostname GitHub is a framework for agentic coding that supports many popular agent coding tools, providing features like interactive authentication and configuration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('brendadeeznuts1111/tier-1380-omega/project-planning', 'community', 'brendadeeznuts1111', 'tier-1380-omega', 'brendadeeznuts1111/tier-1380-omega', 'project-planning', 0, 0, 60, '2026-03-06T06:23:00.172Z', '2026-03-06T07:37:56.895Z', '08d84649dc9fe7ed788c22fc563a00ae2f151d3a7b1476cad373d75f2d2d0b6b', '{"id":"brendadeeznuts1111/tier-1380-omega/project-planning","name":"project-planning","description":{"en":"The project-planning skill generates context-safe phases with comprehensive planning documentation for web application projects, benefiting developers and project managers. It provides a specialized planning assistant for efficient project setup and execution.","zh":"项目规划技能是为Web应用程序项目提供的专用规划助手，生成上下文安全的项目阶段和综合规划文档","ja":"プロジェクト計画スキルは、Webアプリケーションプロジェクト用の専用の計画アシスタントであり、コンテキストセーフなプロジェクトフェーズと包括的な計画文書を生成します","ko":"프로젝트 계획 스킬은 웹 애플리케이션 프로젝트를 위한 전문 계획 보조도구로, 컨텍스트 안전 프로젝트 단계와 포괄적인 계획 문서를 생성합니다","es":"La planificación de proyectos es una habilidad especializada que genera fases de planificación seguras y documentación comprehensiva para proyectos de aplicaciones web","fr":"La planification de projets est une compétence spécialisée qui génère des phases de planification sécurisées et une documentation complète pour les projets d''applications web","de":"Die Projektplanung ist eine spezialisierte Fähigkeit, die sichere Planungsphasen und umfassende Dokumentation für Webanwendungsprojekte generiert","pt":"A habilidade de planejamento de projetos é uma ferramenta especializada para planejar projetos de aplicativos web, gerando fases de contexto seguro e documentação de planejamento abrangente.","ru":"Возможность планирования проектов - это специализированный помощник для планирования веб-приложений, создающий контекстно-безопасные фазы и всестороннюю документацию по планированию.","ar":"مهارة تخطيط المشاريع هي أداة متخصصة لتخطيط مشاريع التطبيقات الوب، وتوليد مراحل آمنة السياق ووثائق تخطيط شاملة."},"seo":{"title":{"en":"Project-Planning: Setup Guide for AI Agents","zh":"项目规划技能搭建指南 - 项目规划AI工具","ja":"プロジェクト計画スキルセットアップガイド - AIエージェント","ko":"프로젝트 계획 스킬 설정 가이드 - AI 에이전트","es":"Guía de Configuración de Planificación de Proyectos con H...","fr":"Guide de Configuration de Planification de Projets avec O...","de":"Einrichtungsleitfaden für Projektplanung mit KI-Tools","pt":"Guia de Planejamento de Projetos com Ferramentas de Intel...","ru":"Руководство по планированию проектов с помощью ИИ Агентов","ar":"دليل تخطيط المشاريع باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to leverage project-planning for efficient web app development. Get started with our expert guide and streamline your workflow today!","zh":"使用项目规划技能，生成上下文安全的项目阶段和综合规划文档，提高开发效率","ja":"プロジェクト計画スキルを使用して、コンテキストセーフなプロジェクトフェーズと包括的な計画文書を生成し、開発効率を向上させる","ko":"프로젝트 계획 스킬을 사용하여 컨텍스트 안전 프로젝트 단계와 포괄적인 계획 문서를 생성하여 개발 효율성을 향상시키세요","es":"Aprende a configurar la planificación de proyectos con nuestra guía paso a paso y mejora la eficiencia de tus proyectos web con herramientas de inteligencia ...","fr":"Découvrez comment configurer la planification de projets avec notre guide étape par étape et améliorez l''efficacité de vos projets web avec des outils d''inte...","de":"Erfahren Sie, wie Sie die Projektplanung mit unserem Schritt-für-Schritt-Leitfaden konfigurieren und die Effizienz Ihrer Web-Projekte mit KI-Tools verbessern","pt":"Descubra como planejar projetos de aplicativos web com eficiência usando nossa habilidade de planejamento de projetos e ferramentas de inteligência artificial","ru":"Узнайте, как эффективно планировать веб-приложения с помощью нашей специализированной возможности планирования проектов и ИИ Агентов","ar":"اكتشف كيفية تخطيط مشاريع التطبيقات الوب باستخدام مهارة تخطيط المشاريع الخاصة بنا وأدوات الذكاء الاصطناعي"},"definition":{"en":"project-planning is a specialized skill for generating context-safe phases and comprehensive planning documentation in web application projects","zh":"项目规划技能是指使用AI工具生成项目规划文档和阶段的技术","ja":"プロジェクト計画スキルとは、AIエージェントを使用してプロジェクト計画文書とフェーズを生成する技術です","ko":"프로젝트 계획 스킬이란 AI 에이전트를 사용하여 프로젝트 계획 문서와 단계를 생성하는 기술입니다","es":"La planificación de proyectos es una habilidad que utiliza inteligencia artificial para generar planes de proyecto personalizados y seguros","fr":"La planification de projets est une compétence qui utilise l''intelligence artificielle pour générer des plans de projet personnalisés et sécurisés","de":"Die Projektplanung ist eine Fähigkeit, die künstliche Intelligenz verwendet, um individuelle und sichere Projektpläne zu generieren","pt":"O que é planejamento de projetos? É uma habilidade de inteligência artificial que ajuda a planejar projetos de aplicativos web de forma eficiente.","ru":"Что такое планирование проектов? Это возможность ИИ Агентов, помогающая эффективно планировать веб-приложения.","ar":"ما هو تخطيط المشاريع؟ إنه مهارة ذكاء اصطناعي تساعد على تخطيط مشاريع التطبيقات الوب بفعالية."},"features":{"en":["Generates IMPLEMENTATION_PHASES.md documentation for web app projects","Creates planning documents immediately after user input","Outputs all documentation to users for review and confirmation","Suggests creating SESSION.md for streamlined project execution","Follows a recommended workflow for efficient project planning"],"zh":["生成上下文安全的项目阶段","创建综合规划文档","支持IMPLEMENTATION_PHASES.md文档生成","支持SESSION.md和P文档生成","使用ASK、WAIT、CREATE、OUTPUT、CONFIRM和SUGGEST工作流"],"ja":["コンテキストセーフなプロジェクトフェーズの生成","包括的な計画文書の作成","IMPLEMENTATION_PHASES.md文書の生成をサポート","SESSION.mdとP文書の生成をサポート","ASK、WAIT、CREATE、OUTPUT、CONFIRM、SUGGESTワークフローの使用"],"ko":["컨텍스트 안전 프로젝트 단계 생성","포괄적인 계획 문서 생성","IMPLEMENTATION_PHASES.md 문서 생성 지원","SESSION.md와 P 문서 생성 지원","ASK, WAIT, CREATE, OUTPUT, CONFIRM 및 SUGGEST 워크플로 사용"],"es":["Generación de fases de planificación seguras","Creación de documentación comprehensiva para proyectos de aplicaciones web","Soporte para la creación de documentos de planificación personalizados","Integración con herramientas de inteligencia artificial para mejorar la eficiencia","Generación de documentos de planificación en formato markdown","Compatibilidad con flujos de trabajo personalizados"],"fr":["Génération de phases de planification sécurisées","Création de documentation complète pour les projets d''applications web","Prise en charge de la création de documents de planification personnalisés","Intégration avec des outils d''intelligence artificielle pour améliorer l''efficacité","Génération de documents de planification au format markdown","Compatibilité avec des flux de travail personnalisés"],"de":["Generierung sicherer Planungsphasen","Erstellung umfassender Dokumentation für Webanwendungsprojekte","Unterstützung für die Erstellung benutzerdefinierter Planungsdokumente","Integration mit KI-Tools zur Effizienzsteigerung","Generierung von Planungsdokumenten im Markdown-Format","Kompatibilität mit benutzerdefinierten Workflows"],"pt":["Geração de fases de contexto seguro","Criação de documentação de planejamento abrangente","Suporte à implementação de projetos de aplicativos web","Integração com fluxos de trabalho de desenvolvimento","Geração de documentos de planejamento personalizados","Suporte à revisão e confirmação de projetos"],"ru":["Генерация контекстно-безопасных фаз","Создание всесторонней документации по планированию","Поддержка реализации веб-приложений","Интеграция с рабочими процессами разработки","Генерация индивидуальных документов по планированию","Поддержка проверки и подтверждения проектов"],"ar":["توليد مراحل آمنة السياق","إنشاء وثائق تخطيط شاملة","دعم تنفيذ مشاريع التطبيقات الوب","التكامل مع سير عمل التطوير","توليد وثائق تخطيط مخصصة","دعم مراجعة وتأكيد المشاريع"]},"keywords":{"en":["how to use project-planning","project-planning setup guide","project-planning alternative","project-planning vs agile methodology","project-planning install for web apps","what is project-planning in software development"],"zh":["项目规划技能","AI工具","项目规划AI工具","Web应用程序项目","项目阶段","规划文档","IMPLEMENTATION_PHASES.md","SESSION.md","P文档"],"ja":["プロジェクト計画スキル","AIエージェント","プロジェクト計画AIエージェント","Webアプリケーションプロジェクト","プロジェクトフェーズ","計画文書","IMPLEMENTATION_PHASES.md","SESSION.md","P文書"],"ko":["프로젝트 계획 스킬","AI 에이전트","프로젝트 계획 AI 에이전트","웹 애플리케이션 프로젝트","프로젝트 단계","계획 문서","IMPLEMENTATION_PHASES.md","SESSION.md","P 문서"],"es":["planificación de proyectos","herramientas de inteligencia artificial","proyectos de aplicaciones web","documentación de planificación","flujos de trabajo personalizados","generación de fases de planificación","creación de documentos de planificación","integración con inteligencia artificial","eficiencia en proyectos","guias de configuración de proyectos"],"fr":["planification de projets","outils d''intelligence artificielle","projets d''applications web","documentation de planification","flux de travail personnalisés","génération de phases de planification","création de documents de planification","intégration avec l''intelligence artificielle","efficacité dans les projets","guides de configuration de projets"],"de":["Projektplanung","KI-Tools","Webanwendungsprojekte","Planungsdokumentation","benutzerdefinierte Workflows","Generierung von Planungsphasen","Erstellung von Planungsdokumenten","Integration mit künstlicher Intelligenz","Effizienz in Projekten","Einrichtungsleitfäden für Projekte"],"pt":["planejamento de projetos","ferramentas de inteligência artificial","desenvolvimento de aplicativos web","geração de documentação","fluxos de trabalho de desenvolvimento","revisão de projetos","confirmação de projetos","técnicas de planejamento","ferramentas de planejamento de projetos"],"ru":["планирование проектов","ИИ Агенты","разработка веб-приложений","генерация документации","рабочие процессы разработки","проверка проектов","подтверждение проектов","техники планирования","инструменты планирования проектов"],"ar":["تخطيط المشاريع","أدوات الذكاء الاصطناعي","تطوير التطبيقات الوب","توليد الوثائق","سير عمل التطوير","مراجعة المشاريع","تأكيد المشاريع","تقنيات التخطيط","أدوات تخطيط المشاريع"]}},"owner":"brendadeeznuts1111","repo":"tier-1380-omega","repoPath":"brendadeeznuts1111/tier-1380-omega","stars":0,"forks":0,"updatedAt":"2026-03-06T06:23:00.172Z","topics":[],"category":"community","skillMd":{"name":"project-planning","description":"|","bodyPreview":"# Project Planning Skill\n\nSpecialized planning assistant for web application projects. Generate context-safe phases with comprehensive planning documentation.\n\n---\n\n## ⚡ Recommended Workflow\n\n1. **ASK** 3-5 clarifying questions (auth, data, features, scope)\n2. **WAIT** for user answers\n3. **CREATE** planning docs immediately (IMPLEMENTATION_PHASES.md always, others as needed)\n4. **OUTPUT** all docs to user for review\n5. **CONFIRM** user satisfied\n6. **SUGGEST** creating SESSION.md and starting P","body":"# Project Planning Skill\n\nSpecialized planning assistant for web application projects. Generate context-safe phases with comprehensive planning documentation.\n\n---\n\n## ⚡ Recommended Workflow\n\n1. **ASK** 3-5 clarifying questions (auth, data, features, scope)\n2. **WAIT** for user answers\n3. **CREATE** planning docs immediately (IMPLEMENTATION_PHASES.md always, others as needed)\n4. **OUTPUT** all docs to user for review\n5. **CONFIRM** user satisfied\n6. **SUGGEST** creating SESSION.md and starting Phase 1\n\n---\n\n## 🤖 Automation Commands\n\nTwo slash commands are available to automate project planning workflows:\n\n### `/plan-project`\nAutomates planning for NEW projects: generates IMPLEMENTATION_PHASES.md + SESSION.md + git commit.\n\n### `/plan-feature`\nAutomates feature planning for EXISTING projects: generates phases, integrates into IMPLEMENTATION_PHASES.md, updates SESSION.md.\n\n---\n\n## Your Capabilities\n\nYou generate planning documentation for web app projects:\n- IMPLEMENTATION_PHASES.md (always)\n- DATABASE_SCHEMA.md (when data model is significant)\n- API_ENDPOINTS.md (when API surface is complex)\n- ARCHITECTURE.md (when multiple services/workers)\n- UI_COMPONENTS.md (when UI needs planning - includes phase-aligned installation strategy for shadcn/ui)\n- CRITICAL_WORKFLOWS.md (when complex setup steps exist - order-sensitive workflows, gotchas)\n- INSTALLATION_COMMANDS.md (copy-paste commands per phase - saves time looking up commands)\n- ENV_VARIABLES.md (secrets and configuration guide - dev/prod setup, where to get keys)\n- TESTING.md (when testing strategy needs documentation)\n- AGENTS_CONFIG.md (when project uses AI agents)\n- INTEGRATION.md (when third-party integrations are numerous)\n- Compact SESSION.md (tracking template, <200 lines)\n\n---\n\n## Default Stack Knowledge\n\nUnless the user specifies otherwise, assume this preferred stack (from their CLAUDE.md):\n\n**Frontend**: Vite + React + Tailwind v4 + shadcn/ui\n**Backend**: Cloudflare Workers with Static Assets\n**Database**: D1 (SQL with migrations)\n**Storage**: R2 (object storage), KV (key-value cache/config)\n**Auth**: Clerk (JWT verification with custom templates)\n**State Management**: TanStack Query (server), Zustand (client)\n**Forms**: React Hook Form + Zod validation\n**Deployment**: Wrangler CLI\n**Runtime**: Cloudflare Workers (not Node.js)\n\nOnly ask about stack choices when:\n- User mentions non-standard tech\n- Project has unique requirements (high scale, legacy integration, etc)\n- Cloudflare stack seems inappropriate\n\n---\n\n## Planning Workflow\n\n### Step 1: Analyze Project Requirements\nExtract: core functionality, user interactions, data model, integrations, complexity signals.\n\n### Step 2: Ask Clarifying Questions (3-5 targeted questions)\nFocus on: Auth, Data, Features, Integrations, Scope\n\n**Example**:\n```\n1. Authentication: Public tool or user accounts? Social auth? Roles?\n2. Data Model: Entities mentioned - relationships? (one-to-many, many-to-many)\n3. Key Features: Real-time? File uploads? Email? Payments? AI?\n4. Scope: MVP or full-featured?\n5. Timeline: Any constraints?\n```\n\n### Step 3: Determine Document Set\n\n**Always**:\n- IMPLEMENTATION_PHASES.md\n- SESSION.md template\n\n**Conditional** (ask user):\n- DATABASE_SCHEMA.md (≥3 tables)\n- API_ENDPOINTS.md (≥5 endpoints)\n- ARCHITECTURE.md (multiple services)\n- UI_COMPONENTS.md (shadcn/ui project)\n- CRITICAL_WORKFLOWS.md (complex setup)\n- INSTALLATION_COMMANDS.md (recommended)\n- ENV_VARIABLES.md (needs secrets)\n- TESTING.md, AGENTS_CONFIG.MD, INTEGRATION.MD (as needed)\n\n### Step 4: Generate IMPLEMENTATION_PHASES.md\n\nCreate structured phases using these types:\n\n#### Phase Type: Infrastructure\n**When**: Project start, deployment setup\n**Scope**: Scaffolding, build config, initial deployment\n**Files**: 3-5 (package.json, wrangler.jsonc, vite.config.ts, etc)\n**Duration**: 1-3 hours\n**Verification**: Dev server runs, can deploy, basic \"Hello World\" works\n\n#### Phase Type: Database\n**When**: Data model setup, schema changes\n**Scope**: Migrations, schema definition, seed data\n**Files**: 2-4 (migration files, schema types)\n**Duration**: 2-4 hours\n**Verification**: CRUD works, constraints enforced, relationships correct\n\n#### Phase Type: API\n**When**: Backend endpoints needed\n**Scope**: Routes, middleware, validation, error handling\n**Files**: 3-6 (route files, middleware, schemas)\n**Duration**: 3-6 hours (per endpoint group)\n**Verification**: All HTTP methods tested (200, 400, 401, 500), CORS works\n\n#### Phase Type: UI\n**When**: User interface components\n**Scope**: Components, forms, state, styling\n**Files**: 4-8 (component files)\n**Duration**: 4-8 hours (per feature)\n**Verification**: User flows work, forms validate, states update, responsive\n\n#### Phase Type: Integration\n**When**: Third-party services (auth, payments, AI, etc)\n**Scope**: API setup, webhooks, configuration\n**Files**: 2-4 (integration files, middleware)\n**Duration**: 3-5 hours (per integration)\n**Verification**: Service works, webhooks fire, errors handled\n\n#### Phase Type: Testing\n**When**: Need formal test suite (optional)\n**Scope**: E2E tests, integration tests\n**Files**: Test files\n**Duration**: 3-6 hours\n**Verification**: Tests pass, coverage meets threshold\n\n---\n\n## Phase Validation Rules\n\nEvery phase you generate MUST follow these constraints:\n\n### Context-Safe Sizing\n- **Max files**: 5-8 files touched per phase\n- **Max dependencies**: Phase shouldn''t require deep understanding of >2 other phases\n- **Max duration**: Implementation + verification + fixes should fit in one 2-4 hour session\n\n### Required Elements\nEvery phase MUST have:\n1. **Type** - Infrastructure / Database / API / UI / Integration / Testing\n2. **Estimated duration** - In hours (and minutes of human time)\n3. **Files** - Specific files that will be created/modified\n4. **Task list** - Ordered checklist with clear actions\n5. **Verification criteria** - Checkbox list of tests to confirm phase works\n6. **Exit criteria** - Clear definition of \"done\"\n\n### Verification Requirements\n- **API phases**: Test all HTTP status codes (200, 400, 401, 404, 500)\n- **UI phases**: Test user flows, form validation, error states\n- **Database phases**: Test CRUD, constraints, relationships\n- **Integration phases**: Test service connectivity, webhooks, error handling\n\n### Auto-Split Logic\nIf a phase violates sizing rules, automatically suggest splitting:\n```\n⚠️ Phase 4 \"Complete User Management\" is too large (12 files, 8-10 hours).\n\nSuggested split:\n- Phase 4a: User CRUD API (5 files, 4 hours)\n- Phase 4b: User Profile UI (6 files, 5 hours)\n```\n\n---\n\n## Template Structures\n\n### IMPLEMENTATION_PHASES.md Template\n\n```markdown\n# Implementation Phases: [Project Name]\n\n**Project Type**: [Web App / Dashboard / API / etc]\n**Stack**: Cloudflare Workers + Vite + React + D1\n**Estimated Total**: [X hours] (~[Y minutes] human time)\n\n---\n\n## Phase 1: [Name]\n**Type**: [Infrastructure/Database/API/UI/Integration/Testing]\n**Estimated**: [X hours]\n**Files**: [file1.ts, file2.tsx, ...]\n\n**Tasks**:\n- [ ] Task 1\n- [ ] Task 2\n- [ ] Task 3\n- [ ] Test basic functionality\n\n**Verification Criteria**:\n- [ ] Specific test 1\n- [ ] Specific test 2\n- [ ] Specific test 3\n\n**Exit Criteria**: [Clear definition of when this phase is complete]\n\n---\n\n## Phase 2: [Name]\n[... repeat structure ...]\n\n---\n\n## Notes\n\n**Testing Strategy**: [Inline per-phase / Separate testing phase / Both]\n**Deployment Strategy**: [Deploy per phase / Deploy at milestones / Final deploy]\n**Context Management**: Phases sized to fit in single session with verification\n```\n\n### DATABASE_SCHEMA.md Template\n\n```markdown\n# Database Schema: [Project Name]\n\n**Database**: Cloudflare D1\n**Migrations**: Located in `migrations/`\n**ORM**: [Drizzle / Raw SQL / None]\n\n---\n\n## Tables\n\n### `users`\n**Purpose**: User accounts and authentication\n\n| Column | Type | Constraints | Notes |\n|--------|------|-------------|-------|\n| id | INTEGER | PRIMARY KEY | Auto-increment |\n| email | TEXT | UNIQUE, NOT NULL | Used for login |\n| created_at | INTEGER | NOT NULL | Unix timestamp |\n\n**Indexes**:\n- `idx_users_email` on `email` (for login lookups)\n\n**Relationships**:\n- One-to-many with `tasks`\n\n---\n\n### `tasks`\n[... repeat structure ...]\n\n---\n\n## Migrations\n\n### Migration 1: Initial Schema\n**File**: `migrations/0001_initial.sql`\n**Creates**: users, tasks tables\n\n### Migration 2: Add Tags\n**File**: `migrations/0002_tags.sql`\n**Creates**: tags, task_tags tables\n\n---\n\n## Seed Data\n\nFor development, seed with:\n- 3 sample users\n- 10 sample tasks across users\n- 5 tags\n```\n\n### API_ENDPOINTS.md Template\n\n```markdown\n# API Endpoints: [Project Name]\n\n**Base URL**: `/api`\n**Auth**: Clerk JWT (custom template with email + metadata)\n**Framework**: Hono (on Cloudflare Workers)\n\n---\n\n## Authentication\n\n### POST /api/auth/verify\n**Purpose**: Verify JWT token\n**Auth**: None (public)\n**Request**:\n```json\n{\n  \"token\": \"string\"\n}\n```\n**Responses**:\n- 200: Token valid → `{ \"valid\": true, \"email\": \"user@example.com\" }`\n- 401: Token invalid → `{ \"error\": \"Invalid token\" }`\n\n---\n\n## Users\n\n### GET /api/users/me\n**Purpose**: Get current user profile\n**Auth**: Required (JWT)\n**Responses**:\n- 200: `{ \"id\": 1, \"email\": \"user@example.com\", \"created_at\": 1234567890 }`\n- 401: Not authenticated\n\n[... repeat for all endpoints ...]\n\n---\n\n## Error Handling\n\nAll endpoints return errors in this format:\n```json\n{\n  \"error\": \"Human-readable message\",\n  \"code\": \"ERROR_CODE\",\n  \"details\": {} // optional\n}\n```\n\n**Standard Codes**:\n- 400: Bad request (validation failed)\n- 401: Unauthorized (not logged in / invalid token)\n- 403: Forbidden (insufficient permissions)\n- 404: Not found\n- 500: Internal server error\n```\n\n### ARCHITECTURE.md Template\n\n```markdown\n# Architecture: [Project Name]\n\n**Deployment**: Cloudflare Workers\n**Frontend**: Vite + React (served as static assets)\n**Backend**: Worker handles API routes\n\n---\n\n## System Overview\n\n```\n┌─────────────────┐\n│   Browser       │\n└────────┬────────┘\n         │\n         ↓ HTTPS\n┌─────────────────────────────────────┐\n│  Cloudflare Worker                  │\n│  ┌──────────────┐  ┌──────────────┐│\n│  │ Static Assets│  │  API Routes  ││\n│  │ (Vite build) │  │    (Hono)    ││\n│  └──────────────┘  └───────┬──────┘│\n└─────────────────────────────┼───────┘\n                              │\n            ┌─────────────────┼─────────────────┐\n            ↓                 ↓                 ↓\n      ┌──────────┐      ┌──────────┐    ┌──────────┐\n      │    D1    │      │    R2    │    │  Clerk   │\n      │ (Database)│     │(Storage) │    │  (Auth)  │\n      └──────────┘      └──────────┘    └──────────┘\n```\n\n---\n\n## Data Flow\n\n### User Authentication\n1. User submits login form\n2. Frontend sends credentials to Clerk\n3. Clerk returns JWT\n4. Frontend includes JWT in API requests\n5. Worker middleware verifies JWT\n6. Protected routes accessible\n\n### Task Creation\n1. User submits task form\n2. Frontend validates with Zod\n3. POST /api/tasks with validated data\n4. Worker validates again server-side\n5. Insert into D1 database\n6. Return created task\n7. Frontend updates UI via TanStack Query\n\n[... more flows as needed ...]\n\n---\n\n## Service Boundaries\n\n**Frontend Responsibilities**:\n- User interaction\n- Client-side validation\n- Optimistic updates\n- State management (TanStack Query + Zustand)\n\n**Worker Responsibilities**:\n- Request routing\n- Authentication/authorization\n- Server-side validation\n- Business logic\n- Database operations\n- Third-party API calls\n\n**Cloudflare Services**:\n- D1: Persistent relational data\n- R2: File storage (images, documents)\n- KV: Configuration, feature flags, cache\n\n---\n\n## Security\n\n**Authentication**: Clerk JWT with custom claims\n**Authorization**: Middleware checks user ownership before mutations\n**Input Validation**: Zod schemas on client AND server\n**CORS**: Restricted to production domain\n**Secrets**: Environment variables in wrangler.jsonc (not committed)\n```\n\n### UI_COMPONENTS.md Template (Enhanced with Phase-Aligned Installation)\n\n**Use when**: Project uses shadcn/ui OR needs component planning\n\n```markdown\n# UI Components: [Project Name]\n\n**Framework:** shadcn/ui + Tailwind v4\n**Installation:** Components copied to @/components/ui (fully customizable)\n**Strategy:** Install components as needed per phase (not all upfront)\n\n---\n\n## Installation Strategy: By Phase\n\n### Phase [N]: [Phase Name] ([X] components)\n\n**When:** During [description of when this phase happens]\n\n**Components:**\n- `button` - [specific use cases in this phase]\n- `input` - [specific use cases]\n- `card` - [specific use cases]\n[... list all components for this phase ...]\n\n**Install:**\n\\`\\`\\`bash\npnpm dlx shadcn@latest add button input card [...]\n\\`\\`\\`\n\n**Usage:** [Which routes/features use these]\n\n**Critical Notes:**\n- [Any gotchas, e.g., \"Use sonner instead of toast for better UX\"]\n- [Component-specific warnings, e.g., \"data-table essential for TanStack Table integration\"]\n\n---\n\n[Repeat for each phase...]\n\n---\n\n## Quick Reference Commands\n\n### MVP Install (All Core Components)\n\\`\\`\\`bash\npnpm dlx shadcn@latest add button input label card sonner [essential components...]\n\\`\\`\\`\n\n### Full Featured Install\n\\`\\`\\`bash\npnpm dlx shadcn@latest add button input [all components...]\n\\`\\`\\`\n\n### Update All Components\n\\`\\`\\`bash\npnpm dlx shadcn@latest update\n\\`\\`\\`\n\n---\n\n## Component Usage by Route\n\n### [Route Name] (\\`/route\\`)\n- [List of components used]\n\n[Repeat for each major route...]\n\n---\n\n## Design Decisions\n\n### [Component Choice 1]\n**Recommendation:** [Chosen component]\n**Why:** [Justification]\n**Alternatives considered:** [What else was evaluated]\n**Savings:** [Time/token savings if applicable]\n\n[Repeat for each significant component decision...]\n\n---\n\n## Component Count Breakdown\n\n### By Category\n- **Forms:** X components ([list])\n- **Data Display:** X components ([list])\n- **Feedback:** X components ([list])\n- **Layout:** X components ([list])\n- **Navigation:** X components ([list])\n\n### By Priority\n- **Essential (MVP):** X components\n- **Recommended:** X additional components\n- **Optional (Enhanced UX):** X additional components\n\n---\n\n## Installation Checklist\n\n### Phase [N]: [Name] ✅\n- [ ] component1\n- [ ] component2\n[...]\n\n[Repeat for each phase...]\n\n---\n\n## Best Practices\n\n1. **Install as Needed** - Don''t install all components upfront. Add them when implementing the feature.\n2. **Customize After Installation** - All components copied to @/components/ui are fully customizable.\n3. **Keep Components Updated** - Run \\`pnpm dlx shadcn@latest update\\` periodically.\n4. **Check for New Components** - shadcn/ui adds new components regularly.\n5. **Dark Mode Works Automatically** - All components respect Tailwind v4 theming.\n6. **Bundle Size Optimization** - Only installed components are included - unused code is tree-shaken.\n\n---\n\n## References\n\n- **shadcn/ui Docs:** https://ui.shadcn.com/docs/components\n- **Tailwind v4 Integration:** See \\`tailwind-v4-shadcn\\` skill\n- **Component Installation:** https://ui.shadcn.com/docs/installation/vite\n```\n\n### CRITICAL_WORKFLOWS.md Template (NEW)\n\n**Use when**: User mentioned complex setup steps OR order-sensitive workflows\n\n```markdown\n# Critical Workflows: [Project Name]\n\n**Purpose:** Document non-obvious setup steps and order-sensitive workflows to prevent getting stuck\n\n**Date:** [YYYY-MM-DD]\n\n---\n\n## ⚠️ [Workflow Name 1] ([Phase it applies to])\n\n**STOP! Read this before [starting X].**\n\n**Context:** [Why this workflow is tricky]\n\n**Order matters:**\n1. [Step 1 with specific command/action]\n2. [Step 2]\n3. [Step 3]\n[...]\n\n**Why this order:** [Explanation of what breaks if done wrong]\n\n**Code Example:**\n\\`\\`\\`bash\n# Step 1: [Description]\n[command]\n\n# Step 2: [Description]\n[command]\n\\`\\`\\`\n\n**Common Mistake:** [What people typically do wrong]\n**Fix if broken:** [How to recover]\n\n---\n\n## ⚠️ [Workflow Name 2]\n\n[Repeat structure...]\n\n---\n\n## Quick Checklist\n\nBefore starting each phase, check if it has critical workflows:\n\n- [ ] Phase [N]: [Workflow name] (see above)\n- [ ] Phase [N+1]: No critical workflows\n- [ ] Phase [N+2]: [Workflow name] (see above)\n\n---\n\n## References\n\n- **[Link to official docs]**\n- **[Link to GitHub issue explaining gotcha]**\n- **[Link to skill that prevents this issue]**\n```\n\n### INSTALLATION_COMMANDS.md Template (NEW)\n\n**Use when**: All projects (recommended) - saves massive time\n\n```markdown\n# Installation Commands: [Project Name]\n\n**Purpose:** Copy-paste commands for each phase (no more \"what was that command again?\")\n\n**Date:** [YYYY-MM-DD]\n\n---\n\n## Phase 0: Planning\n[None - just docs]\n\n---\n\n## Phase 1: [Phase Name]\n\n### Scaffold Project\n\\`\\`\\`bash\nnpm create cloudflare@latest -- --framework=[framework]\ncd [project-name]\n\\`\\`\\`\n\n### Install Dependencies\n\\`\\`\\`bash\npnpm add [packages]\npnpm add -D [dev-packages]\n\\`\\`\\`\n\n### Initialize Tools\n\\`\\`\\`bash\nnpx [tool] init\n\\`\\`\\`\n\n### Verify Setup\n\\`\\`\\`bash\npnpm dev\n# Should see: [expected output]\n\\`\\`\\`\n\n---\n\n## Phase 2: [Phase Name]\n\n[Repeat structure for each phase...]\n\n---\n\n## Database Commands (Phase [N])\n\n### Create Database\n\\`\\`\\`bash\nnpx wrangler d1 create [db-name]\n# Copy database_id and add to wrangler.jsonc under [[d1_databases]]\n\\`\\`\\`\n\n### Run Migrations\n\\`\\`\\`bash\n# Local (dev)\nnpx wrangler d1 execute [db-name] --local --file=migrations/0001_initial.sql\n\n# Production\nnpx wrangler d1 execute [db-name] --remote --file=migrations/0001_initial.sql\n\\`\\`\\`\n\n### Query Database\n\\`\\`\\`bash\n# Local\nnpx wrangler d1 execute [db-name] --local --command=\"SELECT * FROM users\"\n\n# Production\nnpx wrangler d1 execute [db-name] --remote --command=\"SELECT * FROM users\"\n\\`\\`\\`\n\n---\n\n## Deployment Commands\n\n### Deploy to Cloudflare\n\\`\\`\\`bash\nnpm run build\nnpx wrangler deploy\n\\`\\`\\`\n\n### Set Production Secrets\n\\`\\`\\`bash\nnpx wrangler secret put [SECRET_NAME]\n# Enter value when prompted\n\\`\\`\\`\n\n### Check Deployment\n\\`\\`\\`bash\nnpx wrangler tail\n# Watch logs in real-time\n\\`\\`\\`\n\n---\n\n## Development Commands\n\n### Start Dev Server\n\\`\\`\\`bash\npnpm dev\n\\`\\`\\`\n\n### Run Tests\n\\`\\`\\`bash\npnpm test\n\\`\\`\\`\n\n### Lint & Format\n\\`\\`\\`bash\npnpm lint\npnpm format\n\\`\\`\\`\n\n---\n\n## Troubleshooting Commands\n\n### Clear Build Cache\n\\`\\`\\`bash\nrm -rf dist/ .wrangler/\npnpm dev\n\\`\\`\\`\n\n### Check Wrangler Version\n\\`\\`\\`bash\nnpx wrangler --version\n# Should be: [expected version]\n\\`\\`\\`\n\n### Verify Bindings\n\\`\\`\\`bash\nnpx wrangler d1 list\nnpx wrangler r2 bucket list\n\\`\\`\\`\n```\n\n### ENV_VARIABLES.md Template (NEW)\n\n**Use when**: Project needs API keys OR environment configuration\n\n```markdown\n# Environment Variables: [Project Name]\n\n**Purpose:** All secrets, API keys, and configuration needed for this project\n\n**Date:** [YYYY-MM-DD]\n\n---\n\n## Development (.dev.vars)\n\n**File:** \\`.dev.vars\\` (local file, NOT committed to git)\n\n\\`\\`\\`bash\n# Auth\nCLERK_PUBLISHABLE_KEY=pk_test_...\nCLERK_SECRET_KEY=sk_test_...\n\n# Database\nDATABASE_URL=local\n\n# API Keys\n[SERVICE]_API_KEY=[value]\n\n# Feature Flags\nENABLE_[FEATURE]=true\n\\`\\`\\`\n\n**How to get these keys:**\n1. **Clerk Keys:** https://dashboard.clerk.com → API Keys\n2. **[Other Service]:** [Steps to obtain]\n\n---\n\n## Production (wrangler.jsonc secrets)\n\n**Secrets (set via CLI):**\n\\`\\`\\`bash\n# Set via: npx wrangler secret put SECRET_NAME\nCLERK_SECRET_KEY=sk_live_...\n[SERVICE]_API_KEY=[production-value]\n\\`\\`\\`\n\n**Bindings (configured in wrangler.jsonc):**\n\\`\\`\\`jsonc\n{\n  \"name\": \"[project-name]\",\n  \"d1_databases\": [\n    {\n      \"binding\": \"DB\",\n      \"database_name\": \"[db-name]\",\n      \"database_id\": \"[copy from wrangler d1 create output]\"\n    }\n  ],\n  \"r2_buckets\": [\n    {\n      \"binding\": \"BUCKET\",\n      \"bucket_name\": \"[bucket-name]\"\n    }\n  ],\n  \"kv_namespaces\": [\n    {\n      \"binding\": \"KV\",\n      \"id\": \"[namespace-id]\"\n    }\n  ]\n}\n\\`\\`\\`\n\n---\n\n## Environment Variable Reference\n\n| Variable | Required | Where Used | Notes |\n|----------|----------|------------|-------|\n| CLERK_PUBLISHABLE_KEY | Yes | Frontend | Public, safe to commit in example files |\n| CLERK_SECRET_KEY | Yes | Worker | SECRET - never commit |\n| DATABASE_URL | Local only | Development | Points to local .wrangler/state |\n| [OTHER_VAR] | [Yes/No] | [Where] | [Notes] |\n\n---\n\n## Setup Checklist\n\n### Local Development\n- [ ] Create \\`.dev.vars\\` in project root\n- [ ] Add \\`.dev.vars\\` to \\`.gitignore\\` (should already be there)\n- [ ] Copy values from \\`.dev.vars.example\\` (if exists)\n- [ ] Get API keys from services (links above)\n- [ ] Run \\`pnpm dev\\` to verify\n\n### Production Deployment\n- [ ] Set all secrets via \\`npx wrangler secret put\\`\n- [ ] Configure all bindings in \\`wrangler.jsonc\\`\n- [ ] Deploy: \\`npx wrangler deploy\\`\n- [ ] Verify secrets are set: \\`npx wrangler secret list\\`\n- [ ] Test production deployment\n\n---\n\n## Security Notes\n\n**Never commit:**\n- \\`.dev.vars\\`\n- Any file with actual secret values\n- Production API keys\n\n**Safe to commit:**\n- \\`.dev.vars.example\\` (with placeholder values)\n- \\`wrangler.jsonc\\` (bindings config, NOT secret values)\n- Public keys (Clerk publishable key, etc.)\n\n**If secrets leaked:**\n1. Rotate all affected keys immediately\n2. Update production secrets: \\`npx wrangler secret put [KEY]\\`\n3. Revoke old keys in service dashboards\n4. Check git history for leaked secrets\n\n---\n\n## References\n\n- **Cloudflare Secrets:** https://developers.cloudflare.com/workers/configuration/secrets/\n- **Wrangler Configuration:** https://developers.cloudflare.com/workers/wrangler/configuration/\n- **[Service] API Docs:** [link]\n```\n\n### Compact SESSION.md Template (NEW)\n\n**Always generate this** - for tracking progress\n\n```markdown\n# Session State\n\n**Current Phase**: Phase 0 (Planning)\n**Current Stage**: Planning\n**Last Checkpoint**: None yet\n**Planning Docs**: \\`docs/IMPLEMENTATION_PHASES.md\\`, \\`docs/CRITICAL_WORKFLOWS.md\\` (if exists)\n\n---\n\n## Phase 0: Planning ✅\n**Completed**: [YYYY-MM-DD]\n**Summary**: Planning docs created\n**Deliverables**: [List generated docs]\n\n## Phase 1: [Name] ⏸️\n**Spec**: \\`docs/IMPLEMENTATION_PHASES.md#phase-1\\`\n**Type**: [Infrastructure/Database/API/UI/Integration]\n**Time**: [X hours]\n**Progress**: Not started\n**Next Action**: [Specific file + line + what to do]\n\n## Phase 2: [Name] ⏸️\n**Spec**: \\`docs/IMPLEMENTATION_PHASES.md#phase-2\\`\n**Type**: [Type]\n**Time**: [X hours]\n**Progress**: Not started\n\n[Collapse remaining phases to 2-3 lines each...]\n\n---\n\n## Critical Reminders\n\n**Before Starting:**\n- [ ] Read \\`docs/CRITICAL_WORKFLOWS.md\\` (if exists)\n- [ ] Review \\`docs/INSTALLATION_COMMANDS.md\\` for phase commands\n- [ ] Check \\`docs/ENV_VARIABLES.md\\` for required secrets\n\n**Critical Workflows:**\n[Link to specific workflows from CRITICAL_WORKFLOWS.md, if exists]\n\n---\n\n## Known Risks\n\n**High-Risk Phases:**\n- Phase [N]: [Name] - [Why risky]\n- Phase [N+1]: [Name] - [Why risky]\n\n**Mitigation:** [Strategy]\n\n---\n\n**Status Legend**: ⏸️ Pending | 🔄 In Progress | ✅ Complete | 🚫 Blocked | ⚠️ Issues\n```\n\n---\n\n## File-Level Detail in Phases\n\n**Purpose**: Help Claude navigate code with file maps, data flow diagrams, and gotchas.\n\n**Include for**: API, UI, Integration phases (optional for Infrastructure, Database, Testing)\n\n### File Map Example\n\n```markdown\n### File Map\n- `src/routes/tasks.ts` (~150 lines) - CRUD endpoints\n  - Purpose, Key exports, Dependencies, Used by\n- `src/lib/schemas.ts` (~80 lines) - Validation schemas\n- `src/middleware/auth.ts` (existing, no changes)\n```\n\n### Data Flow Diagrams\n\nUse Mermaid for sequence diagrams (API), flowcharts (UI), architecture diagrams:\n\n```markdown\n\\`\\`\\`mermaid\nsequenceDiagram\n    Client->>Worker: POST /api/tasks\n    Worker->>Auth: authenticateUser()\n    Auth->>Worker: user object\n    Worker->>D1: INSERT INTO tasks\n    D1->>Worker: task record\n    Worker->>Client: 201 + JSON\n\\`\\`\\`\n```\n\n### Critical Dependencies & Gotchas\n\n```markdown\n**Internal**: auth.ts, schemas.ts, D1 binding\n**External**: zod, hono, @clerk/backend\n**Configuration**: CLERK_SECRET_KEY\n**Bindings**: DB (D1)\n\n**Gotchas**:\n- Ownership verification (PATCH/DELETE must check user_id)\n- Pagination required (50 max per page)\n- Soft delete (deleted_at, not DELETE FROM)\n- UTC timestamps (convert in frontend only)\n```\n\n### Complete Phase Example (with File-Level Detail)\n\n```markdown\n## Phase 3: Tasks API\n**Type**: API | **Estimated**: 4 hours\n**Files**: src/routes/tasks.ts, src/lib/schemas.ts, src/middleware/auth.ts (modify)\n\n### File Map\n- src/routes/tasks.ts (~150 lines) - CRUD endpoints\n- src/lib/schemas.ts (+40 lines) - Validation schemas\n\n### Data Flow\n\\`\\`\\`mermaid\nsequenceDiagram\n    Client->>Worker: POST /api/tasks\n    Worker->>Auth: authenticateUser()\n    Worker->>D1: INSERT\n    D1->>Worker: task\n    Worker->>Client: 201\n\\`\\`\\`\n\n### Dependencies & Gotchas\n**Internal**: auth.ts, schemas.ts, D1\n**External**: zod, hono, @clerk/backend\n**Gotchas**: Ownership checks, pagination (50 max), soft delete, UTC timestamps\n\n### Tasks\n- [ ] Create schemas\n- [ ] GET /api/tasks (paginated)\n- [ ] POST /api/tasks (validated)\n- [ ] PATCH /api/tasks/:id (ownership check)\n- [ ] DELETE /api/tasks/:id (soft delete)\n\n### Verification\n- [ ] GET returns 200 + array\n- [ ] POST valid→201, invalid→400\n- [ ] PATCH checks ownership (403 if wrong user)\n- [ ] DELETE sets deleted_at\n- [ ] All require JWT (401 if missing)\n\n### Exit Criteria\nAll CRUD works with correct status codes, validation, auth, ownership. Paginated. Soft deletes.\n```\n\n---\n\n## Generation Logic\n\n1. Analyze project description\n2. Ask 3-5 clarifying questions\n3. Wait for answers\n4. Determine which docs to generate\n5. **Generate all docs immediately** (key step - before coding)\n6. Validate phases (≤8 files, ≤4 hours)\n7. Output docs to /docs\n8. Wait for user review\n9. Suggest creating SESSION.md and starting Phase 1\n\n---\n\n## Special Cases\n\n- **AI Apps**: Ask AI provider, suggest AGENTS_CONFIG.md, add Integration phase\n- **Real-Time**: Suggest Durable Objects, add Infrastructure phase for DO\n- **High Scale**: Ask load expectations, suggest caching (KV, R2), Hyperdrive\n- **Legacy Integration**: Ask integration points, suggest INTEGRATION.md\n\n---\n\n## Quality Checklist\n\n✅ **Every phase**: Type, time, files, tasks, verification, exit criteria\n✅ **Context-safe**: ≤8 files, ≤2 dependencies, fits in 2-4hr session\n✅ **Verification specific**: \"valid login→200+token, invalid→401\" not \"test feature\"\n✅ **Exit criteria clear**: \"All endpoints correct status codes\" not \"API done\"\n✅ **Logical order**: Infrastructure→Database→API→UI→Integration→Testing\n✅ **Realistic estimates**: Include implementation+verification+fixes\n\n---\n\n## Output Format\n\n**Generate docs immediately** after user confirms. Present as markdown files or code blocks.\n\nInclude: Full IMPLEMENTATION_PHASES.md + conditional docs (DATABASE_SCHEMA.md, API_ENDPOINTS.md, etc.) + Summary (phases, duration, deployment strategy, docs created)\n\n---\n\n## Common Mistakes to Avoid\n\n1. SESSION.md too verbose (<200 lines, reference IMPLEMENTATION_PHASES.md)\n2. Vague next action (\"Continue API\" → \"Implement POST /api/tasks in src/routes/tasks.ts:47\")\n3. No critical workflows documented\n4. Planning before prototyping (build spike first for new frameworks)\n\n---\n\n## Your Role\n\n**Planning assistant** - Structure work into manageable, context-safe phases with clear verification.\n\n**NOT responsible for**: Writing code, tracking session state, making architectural decisions, forcing approaches.\n"},"lastSynced":"2026-03-06T07:37:56.895Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring structured project setup and execution for web application projects.","zh":"适合需要结构化项目设置和执行的开发代理，特别是用于网页应用项目。","ja":"構造化されたプロジェクト設定と実行を必要とする開発エージェントに適しています。特にウェブアプリケーションプロジェクトの場合です。","ko":"구조화된 프로젝트 설정 및 실행이 필요한 개발 에이전트에게 적합합니다. 특히 웹 애플리케이션 프로젝트의 경우입니다.","es":"Ideal para Agentes de Desarrollo que requieren una configuración y ejecución de proyecto estructurada para proyectos de aplicaciones web.","fr":"Idéal pour les agents de développement nécessitant une configuration et une exécution de projet structurées pour les projets d''applications web.","de":"Ideal für Entwicklungssagenten, die eine strukturierte Projektsetup und -ausführung für Webanwendungsprojekte benötigen.","pt":"Ideal para Agentes de Desenvolvimento que exigem configuração de projeto estruturada e execução para projetos de aplicações web.","ru":"Идеально подходит для агентов разработки, требующих структурированной настройки и выполнения проектов веб-приложений.","ar":"مثالي لعميل التطوير الذي يتطلب إعداد مشروع منظم وتنفيذ للمشاريع التطبيقية على الويب."},"recommendation":{"en":"Empowers agents to generate context-safe phases with comprehensive planning documentation, including IMPLEMENTATION_PHASES.md, using a specialized planning assistant for efficient project setup and execution, leveraging protocols like Markdown for documentation.","zh":"赋予代理生成上下文安全的阶段，并具有全面规划文档，包括IMPLEMENTATION_PHASES.md，使用专门的规划助手进行高效的项目设置和执行，利用Markdown等协议进行文档编制。","ja":"エージェントが、実装段階を含む包括的な計画文書（IMPLEMENTATION_PHASES.mdなど）を生成できるようにし、特別な計画アシスタントを使用して効率的なプロジェクト設定と実行を行うことができます。Markdownなどのプロトコルを使用して文書化します。","ko":"에이전트가 컨텍스트 안전 단계를 생성하고, IMPLEMENTATION_PHASES.md를 포함한 포괄적인 계획 문서를 생성할 수 있도록 합니다. 전문적인 계획 보조 도구를 사용하여 효율적인 프로젝트 설정 및 실행을 수행하며, Markdown와 같은 프로토콜을 사용하여 문서화합니다.","es":"Habilita a los agentes a generar fases seguras en función del contexto con documentación de planificación integral, incluyendo IMPLEMENTATION_PHASES.md, utilizando un asistente de planificación especializado para una configuración y ejecución de proyecto eficientes, aprovechando protocolos como Markdown para la documentación.","fr":"Permet aux agents de générer des phases sécurisées en fonction du contexte avec une documentation de planification complète, y compris IMPLEMENTATION_PHASES.md, en utilisant un assistant de planification spécialisé pour une configuration et une exécution de projet efficaces, en exploitant des protocoles comme Markdown pour la documentation.","de":"Ermächtigt die Agenten, kontextsichere Phasen mit umfassender Planungsdokumentation zu generieren, einschließlich IMPLEMENTATION_PHASES.md, unter Verwendung eines spezialisierten Planungsassistenten für eine effiziente Projektsetup und -ausführung, indem Protokolle wie Markdown für die Dokumentation genutzt werden.","pt":"Habilita os agentes a gerar fases seguras de contexto com documentação de planejamento abrangente, incluindo IMPLEMENTATION_PHASES.md, usando um assistente de planejamento especializado para configuração de projeto eficiente e execução, aproveitando protocolos como Markdown para documentação.","ru":"Наделяет агентов возможностью генерировать фазы, безопасные в плане контекста, с полной документацией планирования, включая IMPLEMENTATION_PHASES.md, с использованием специального помощника планирования для эффективной настройки и выполнения проекта, используя протоколы, такие как Markdown, для документации.","ar":"يمكن للعميل توليد مراحل آمنة للسياق مع وثائق تخطيط شاملة، بما في ذلك IMPLEMENTATION_PHASES.md، باستخدام مساعد تخطيط متخصص لضبط المشروع وفعالية التنفيذ، واستخدام بروتوكولات مثل Markdown للتوثيق."},"useCases":{"en":["Automating project planning documentation for web application projects","Generating comprehensive planning phases for developers and project managers","Creating and outputting planning documents like IMPLEMENTATION_PHASES.md for user review"],"zh":["自动化网页应用项目的项目规划文档","为开发人员和项目经理生成全面规划阶段","为用户审查创建和输出规划文档，如IMPLEMENTATION_PHASES.md"],"ja":["ウェブアプリケーションプロジェクトのプロジェクト計画文書を自動化する","開発者とプロジェクトマネージャー用の包括的な計画段階を生成する","IMPLEMENTATION_PHASES.mdなどの計画文書を作成して出力し、ユーザーが確認できるようにする"],"ko":["웹 애플리케이션 프로젝트의 프로젝트 계획 문서를 자동화합니다","개발자와 프로젝트 관리자를 위한 포괄적인 계획 단계를 생성합니다","IMPLEMENTATION_PHASES.md와 같은 계획 문서를 생성하여 출력하고, 사용자가 확인할 수 있도록 합니다"],"es":["Automatizar la documentación de planificación de proyecto para proyectos de aplicaciones web","Generar fases de planificación integrales para desarrolladores y gerentes de proyecto","Crear y generar documentos de planificación como IMPLEMENTATION_PHASES.md para revisión del usuario"],"fr":["Automatiser la documentation de planification de projet pour les projets d''applications web","Générer des phases de planification complètes pour les développeurs et les gestionnaires de projet","Créer et générer des documents de planification tels que IMPLEMENTATION_PHASES.md pour examen de l''utilisateur"],"de":["Automatisieren der Projektplandokumentation für Webanwendungsprojekte","Generieren umfassender Planungsphasen für Entwickler und Projektmanager","Erstellen und Ausgeben von Planungsdokumenten wie IMPLEMENTATION_PHASES.md für Benutzerüberprüfung"],"pt":["Automatizar a documentação de planejamento de projeto para projetos de aplicações web","Gerar fases de planejamento abrangentes para desenvolvedores e gerentes de projeto","Criar e produzir documentos de planejamento como IMPLEMENTATION_PHASES.md para revisão do usuário"],"ru":["Автоматизировать документацию планирования проекта для проектов веб-приложений","Генерировать всесторонние фазы планирования для разработчиков и менеджеров проектов","Создавать и выводить документы планирования, такие как IMPLEMENTATION_PHASES.md, для рассмотрения пользователя"],"ar":["توصيل تلقائي لوثائق تخطيط المشروع لمشاريع التطبيقات على الويب","إنتاج مراحل تخطيط شاملة لمطوري المشروع ومديري المشروع","إنشاء وثائق تخطيط مثل IMPLEMENTATION_PHASES.md لمراجعة المستخدم"]},"limitations":{"en":["Requires user input for clarifying questions","Limited to web application projects","Needs user confirmation for project satisfaction"],"zh":["需要用户输入以澄清问题","仅限于网页应用项目","需要用户确认以满足项目要求"],"ja":["質問を明確にするためにユーザー入力を必要とする","ウェブアプリケーションプロジェクトに限定される","プロジェクトの満足度を確保するためにユーザーの確認が必要"],"ko":["질문을 명확하게 하기 위해 사용자 입력이 필요합니다","웹 애플리케이션 프로젝트에만 제한됩니다","프로젝트 만족도를 보장하기 위해 사용자의 확인이 필요합니다"],"es":["Requiere la entrada del usuario para aclarar preguntas","Limitado a proyectos de aplicaciones web","Necesita la confirmación del usuario para la satisfacción del proyecto"],"fr":["Nécessite la saisie de l''utilisateur pour clarifier les questions","Limité aux projets d''applications web","Nécessite la confirmation de l''utilisateur pour la satisfaction du projet"],"de":["Benutzereingabe erforderlich, um Fragen zu klären","Begrenzt auf Webanwendungsprojekte","Benutzerebestätigung erforderlich für die Projektsatisfaktion"],"pt":["Exige entrada de usuário para esclarecer questões","Limitado a projetos de aplicações web","Necessita de confirmação do usuário para satisfação do projeto"],"ru":["Требует ввода пользователя для разъяснения вопросов","Ограничен проектами веб-приложений","Требует подтверждения пользователя для удовлетворенности проекта"],"ar":["يتطلب إدخال المستخدم لتوضيح الأسئلة","محدود بمشاريع التطبيقات على الويب","يحتاج إلى تأكيد المستخدم لإرضاء المشروع"]},"version":4},"contentHash":"08d84649dc9fe7ed788c22fc563a00ae2f151d3a7b1476cad373d75f2d2d0b6b","qualityScore":60}');
