INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('QuyDatSadBoy/Agent-skill/tailored-resume-generator', 'tailored-resume-generator', 'QuyDatSadBoy', 'Agent-skill', 'community', 'tailored-resume-generator QuyDatSadBoy Agent-skill community The tailored-resume-generator skill analyzes job descriptions to extract key requirements and creates customized resumes for specific job positions, highlighting relevant experience and skills. 个性化简历生成器根据工作描述分析和提取关键要求，生成定制简历以提高申请成功率 カスタムResume生成ツールは求人情報を分析して重要な要件を抽出し、カスタマイズされた簡历を生成して応募成功率を高めます 맞춤형 이력서 생성기는 일자리 설명을 분석하여 핵심 요구사항을 추출하고 맞춤형 이력서를 생성하여 지원 성공률을 높입니다 El generador de resumen personalizado analiza descripciones de trabajo y extrae requisitos clave para crear CVs personalizados Le générateur de CV sur mesure analyse les descriptions de travail et extrait les exigences clés pour créer des CV personnalisés Der individuelle Lebenslauf-Generator analysiert Stellenbeschreibungen und extrahiert wichtige Anforderungen, um individuelle Lebensläufe zu erstellen O gerador de currículos personalizados analisa descrições de vagas e extrai requisitos-chave para criar currículos personalizados Генератор резюме ИИ Агенты анализирует описания вакансий и извлекает ключевые требования для создания индивидуальных резюме جهاز توليد السيرة الذاتية المخصص ي分析 وصفات الوظائف ويستخرج المتطلبات الرئيسية لإنشاء سير ذاتية مخصصة how to use tailored-resume-generator what is tailored-resume-generator tailored-resume-generator alternative tailored-resume-generator vs resume builder tailored-resume-generator install tailored-resume-generator setup guide customized resume creation ATS optimized resumes job description analysis 个性化简历生成器 AIエージェント 简历定制 工作描述分析 申请者追踪系统 相关经验 简历版本 特定技能 Analyzes Job Descriptions to extract key requirements and skills Customizes resumes for different industries or roles Highlights relevant experience for career transitions Optimizes resumes for ATS (Applicant Tracking Systems) Creates multiple resume versions for different job applications Emphasizes specific skills mentioned in job postings tailored-resume-generator is a skill that generates customized resumes by analyzing job descriptions and extracting key requirements, skills, and qualifications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('clearclown/claude-code-aida-red/aida:fix', 'community', 'clearclown', 'claude-code-aida-red', 'clearclown/claude-code-aida-red', 'aida:fix', 0, 0, 60, '2026-03-07T01:49:01.807Z', '2026-03-07T03:29:53.000Z', '73d95a4c8157e14a1afecbd1b6e87d7ebd921e66b9fe8ceab2dcdbb36c7cae20', '{"id":"clearclown/claude-code-aida-red/aida:fix","name":"aida:fix","description":{"en":"aida:fix is a skill that fixes existing projects to meet all 19 quality gates, benefiting developers who need to validate and repair their projects. It takes an existing project and fixes it to pass all quality gates.","zh":"AIDA Fix是一种自动化工具，帮助开发者修复项目以满足19个质量门槛。它可以检查项目目录、后端和前端代码","ja":"AIDA Fixは、開発者がプロジェクトを19の品質ゲートに適合させるために修復することを支援する自動化ツールです。プロジェクトディレクトリ、バックエンド、フロントエンドコードをチェックします","ko":"AIDA Fix는 개발자가 프로젝트를 19개의 품질 게이트에 맞춰 수정하도록 도와주는 자동화 도구입니다. 프로젝트 디렉토리, 백엔드, 프론트엔드 코드를 확인합니다","es":"Aida:fix es una herramienta que soluciona proyectos existentes para cumplir con las 19 puertas de calidad","fr":"Aida:fix est un outil qui résout les projets existants pour atteindre les 19 portes de qualité","de":"Aida:fix ist ein Tool, das bestehende Projekte löst, um die 19 Qualitätsprüfungen zu bestehen","pt":"O aida:fix é uma ferramenta de IA que corrige projetos para atender aos 19 portais de qualidade. Use a linha de comando para validar e corrigir projetos","ru":"aida:fix - это инструмент ИИ, который исправляет проекты, чтобы удовлетворить 19 качественным воротам. Используйте командную строку для проверки и исправления проектов","ar":"aida:fix هو أداة ذكاء اصطناعي تصحيح المشاريع لتلبية 19 بوابة جودة. استخدم سطر الأوامر للتحقق من صحة المشاريع وتصحيحها"},"seo":{"title":{"en":"aida:fix: Project Quality Gate Setup Guide | AI Agent Skill","zh":"AIDA Fix_SETUP GUIDE：自动化项目质量检查","ja":"AIDA Fix セットアップガイド：AIエージェントによるプロジェクト品質改善","ko":"AIDA Fix 설정 가이드: 프로젝트 품질 개선 도구","es":"Configuración de aida:fix: Guía de solución de proyectos","fr":"aida:fix: Guide de configuration pour les développeurs","de":"aida:fix-Setup: Leitfaden für Entwickler","pt":"Guia de Configuração do aida:fix - Ferramentas de IA para...","ru":"Настройка aida:fix - ИИ Агенты для Разработчиков","ar":"دليل إعداد aida:fix - أدوات الذكاء الاصطناعي للمطورين"},"description":{"en":"Fix your project with aida:fix. Learn how to validate and repair your project to meet all 19 quality gates. Get started now!","zh":"AIDA Fix是一种自动化工具，帮助开发者修复项目以满足19个质量门槛。了解如何使用AIDA Fix提高项目质量","ja":"AIDA Fixは、開発者がプロジェクトを19の品質ゲートに適合させるために修復することを支援する自動化ツールです。AIDA Fixの使い方を学ぶ","ko":"AIDA Fix는 개발자가 프로젝트를 19개의 품질 게이트에 맞춰 수정하도록 도와주는 자동화 도구입니다. AIDA Fix 사용 방법을 알아보세요","es":"Aprende a configurar aida:fix para solucionar proyectos y cumplir con las 19 puertas de calidad","fr":"Découvrez comment configurer aida:fix pour résoudre les projets et atteindre les 19 portes de qualité","de":"Erfahren Sie, wie Sie aida:fix konfigurieren, um Projekte zu beheben und die 19 Qualitätsprüfungen zu bestehen","pt":"Aprenda a usar o aida:fix para corrigir projetos e atender aos 19 portais de qualidade. Descubra como usar a linha de comando para validar e corrigir projetos","ru":"Узнайте, как использовать aida:fix для исправления проектов и удовлетворения 19 качественным воротам. Ознакомьтесь с использованием командной строки для пров...","ar":"تعرف على كيفية استخدام aida:fix لتصحيح المشاريع وتلبية 19 بوابة جودة. اكتشف كيفية استخدام سطر الأوامر للتحقق من صحة المشاريع وتصحيحها"},"definition":{"en":"aida:fix is a technical skill that validates and repairs existing projects to ensure they meet all 19 quality gates, using commands like /aida:fix <project-name>.","zh":"AIDA Fix是一种自动化工具，用于修复项目以满足质量门槛","ja":"AIDA Fixは、プロジェクトを品質ゲートに適合させるために修復する自動化ツールです","ko":"AIDA Fix는 프로젝트를 품질 게이트에 맞춰 수정하는 자동화 도구입니다","es":"Aida:fix es una herramienta de desarrollo que soluciona proyectos para cumplir con estándares de calidad","fr":"Aida:fix est un outil de développement qui résout les projets pour atteindre les normes de qualité","de":"Aida:fix ist ein Entwicklungstool, das Projekte löst, um Qualitätsstandards zu erfüllen","pt":"O aida:fix é uma ferramenta de IA que corrige projetos para atender aos padrões de qualidade","ru":"aida:fix - это инструмент ИИ, который исправляет проекты, чтобы удовлетворить качественным стандартам","ar":"aida:fix هو أداة ذكاء اصطناعي تصحيح المشاريع لتلبية معايير الجودة"},"features":{"en":["Validates project existence using bash commands like ls -la ./","Repairs projects to pass all 19 quality gates","Uses the /aida:fix <project-name> command for execution","Supports project directory checking for backend and frontend","Follows a mandatory execution protocol for quality gate validation"],"zh":["自动化项目质量检查","支持19个质量门槛","检查项目目录、后端和前端代码","使用CLI命令行工具","支持多种项目类型"],"ja":["自動化されたプロジェクト品質チェック","19の品質ゲートをサポート","プロジェクトディレクトリ、バックエンド、フロントエンドコードをチェック","CLIコマンドラインツールを使用","複数のプロジェクトタイプをサポート"],"ko":["자동화된 프로젝트 품질 체크","19개의 품질 게이트를 지원","프로젝트 디렉토리, 백엔드, 프론트엔드 코드를 확인","CLI 명령줄 도구를 사용","다수의 프로젝트 유형을 지원"],"es":["Validación de proyectos existentes","Reparación de proyectos para cumplir con las 19 puertas de calidad","Uso de comandos CLI para la configuración","Compatibilidad con proyectos frontend y backend","Cumplimiento de protocolos de ejecución obligatorios","Soporte para la creación de proyectos completos"],"fr":["Validation de projets existants","Résolution de projets pour atteindre les 19 portes de qualité","Utilisation de commandes CLI pour la configuration","Compatibilité avec les projets frontend et backend","Respect des protocoles d''exécution obligatoires","Prise en charge de la création de projets complets"],"de":["Validierung von bestehenden Projekten","Behebung von Projekten, um die 19 Qualitätsprüfungen zu bestehen","Verwendung von CLI-Befehlen für die Konfiguration","Kompatibilität mit Frontend- und Backend-Projekten","Einhaltung von obligatorischen Ausführungsprotokollen","Unterstützung für die Erstellung von vollständigen Projekten"],"pt":["Validação de projetos usando a linha de comando","Correção de projetos para atender aos 19 portais de qualidade","Uso de tecnologias de ponta para garantir a qualidade dos projetos","Integração com ferramentas de desenvolvimento para simplificar o processo de correção","Suporte a projetos em React e outras tecnologias de front-end","Compatibilidade com sistemas operacionais Linux e macOS"],"ru":["Проверка проектов с помощью командной строки","Исправление проектов, чтобы удовлетворить 19 качественным воротам","Использование передовых технологий для обеспечения качества проектов","Интеграция с инструментами разработки для упрощения процесса исправления","Поддержка проектов на React и других технологиях front-end","Совместимость с операционными системами Linux и macOS"],"ar":["التحقق من مشاريع باستخدام سطر الأوامر","تصحيح المشاريع لتلبية 19 بوابة جودة","استخدام أحدث التكنولوجيا لضمان جودة المشاريع","التكامل مع أدوات التطوير لتسهيل عملية التصحيح","دعم مشاريع React و تكنولوجيا الواجهة الأمامية الأخرى","التوافق مع أنظمة التشغيل Linux و macOS"]},"keywords":{"en":["how to use aida:fix","aida:fix setup guide","what is aida:fix","aida:fix alternative","aida:fix vs project validation tools","aida:fix install","aida:fix project repair","quality gate validation","project validation tools"],"zh":["AIDA Fix","自动化项目质量检查","质量门槛","CLI命令行工具","项目质量改善","AI工具","开发者工具"],"ja":["AIDA Fix","自動化されたプロジェクト品質チェック","品質ゲート","CLIコマンドラインツール","プロジェクト品質改善","AIエージェント","開発者ツール"],"ko":["AIDA Fix","자동화된 프로젝트 품질 체크","품질 게이트","CLI 명령줄 도구","프로젝트 품질 개선","AI 도구","개발자 도구"],"es":["herramientas de desarrollo","solución de proyectos","cumplimiento de calidad","configuración de aida:fix","desarrollo de software","proyectos de código abierto","herramientas de línea de comandos","desarrollo frontend","desarrollo backend"],"fr":["outils de développement","résolution de projets","respect de la qualité","configuration d''aida:fix","développement de logiciels","projets de code source ouvert","outils de ligne de commande","développement frontend","développement backend"],"de":["Entwicklungstools","Projektbehebung","Qualitätskonformität","Konfiguration von aida:fix","Softwareentwicklung","Open-Source-Projekte","Kommandozeilentools","Frontend-Entwicklung","Backend-Entwicklung"],"pt":["aida:fix","ferramentas de IA","desenvolvimento de software","qualidade de código","React","linha de comando","validação de projetos","correção de projetos","tecnologias de ponta"],"ru":["aida:fix","ИИ Агенты","разработка программного обеспечения","качество кода","React","командная строка","проверка проектов","исправление проектов","передовые технологии"],"ar":["aida:fix","أدوات الذكاء الاصطناعي","تطوير البرمجيات","جودة الكود","React","سطر الأوامر","التحقق من مشاريع","تصحيح مشاريع","أحدث التكنولوجيا"]}},"owner":"clearclown","repo":"claude-code-aida-red","repoPath":"clearclown/claude-code-aida-red","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.807Z","topics":[],"category":"community","skillMd":{"name":"aida:fix","description":"|","bodyPreview":"# AIDA Fix\n\nFix an existing project to meet all 19 quality gates.\n\n## Usage\n\n```\n/aida:fix <project-name>\n```\n\nExample:\n```\n/aida:fix twitter-clone\n```\n\n---\n\n## MANDATORY EXECUTION PROTOCOL\n\n**You MUST follow this protocol exactly. Do NOT deviate.**\n\nThis command takes an existing (possibly incomplete) project and fixes it to pass all quality gates.\n\n---\n\n## Step 1: Validate Project Exists\n\nCheck project directory:\n\n```bash\nls -la ./\nls -la ./backend/\nls -la ./frontend/\n```\n\n**If project doesn''t","body":"# AIDA Fix\n\nFix an existing project to meet all 19 quality gates.\n\n## Usage\n\n```\n/aida:fix <project-name>\n```\n\nExample:\n```\n/aida:fix twitter-clone\n```\n\n---\n\n## MANDATORY EXECUTION PROTOCOL\n\n**You MUST follow this protocol exactly. Do NOT deviate.**\n\nThis command takes an existing (possibly incomplete) project and fixes it to pass all quality gates.\n\n---\n\n## Step 1: Validate Project Exists\n\nCheck project directory:\n\n```bash\nls -la ./\nls -la ./backend/\nls -la ./frontend/\n```\n\n**If project doesn''t exist:**\n```\nProject {{PROJECT}} not found.\n\nAvailable projects:\n$(ls ./)\n\nTo create a new project:\n  /aida \"Your project description\"\n```\n\n---\n\n## Step 2: Run Quality Gates (Diagnostic)\n\nRun quality gates to identify failures:\n\n```bash\n./scripts/quality-gates.sh {{PROJECT}} 2>&1 | tee /tmp/gate-diagnostic.log\n```\n\nParse the output to identify:\n- Which gates PASSED\n- Which gates FAILED\n- Specific error messages\n\n---\n\n## Step 3: Create Fix Plan\n\nBased on gate failures, create a prioritized fix plan:\n\n### Gate 1-2 (Backend Build/Tests) Failures:\n- Syntax errors in Go code\n- Missing dependencies\n- Failing tests\n\n### Gate 3-4 (Frontend Build/Tests) Failures:\n- TypeScript errors\n- Missing packages\n- Failing component tests\n\n### Gate 5-7 (Docker) Failures:\n- Dockerfile issues\n- docker-compose.yml problems\n- Health check failures\n\n### Gate 8 (API Coverage) Failures:\n- Need more handler functions\n- Missing endpoints\n\n### Gate 9 (Frontend Features) Failures:\n- Need more pages\n- Missing routing\n- No API client\n\n### Gate 10 (Integration) Failures:\n- Frontend/Backend not connected\n- Missing CORS\n- No Docker links\n\n### Gate 11 (Backend Test Count < 80) Failures:\n- Add more unit tests\n- Add integration tests\n- Add edge case tests\n\n### Gate 12 (Frontend Test Count < 100) Failures:\n- Add component tests\n- Add context tests\n- Add API client tests\n\n### Gate 13 (Empty Array Pattern) Failures:\n- Replace `var slice []T` with `make([]T, 0)`\n- Ensure JSON returns `[]` not `null`\n\n### Gate 14 (Backend Coverage < 75%) Failures:\n- Add tests for uncovered code\n- Focus on handlers and services\n\n### Gate 15-18 (E2E/Design) Failures:\n- Add Playwright tests\n- Improve UI components\n- Add more E2E scenarios\n\n### Gate 19 (E2E Execution) Failures:\n- Fix Playwright configuration\n- Update selectors\n- Fix timing issues\n\n---\n\n## Step 4: Execute Fixes\n\nFor each failure category, either:\n\n### A. Fix Directly (Minor Issues)\n- Syntax errors\n- Missing imports\n- Configuration issues\n- Small code changes (<20 lines)\n\n### B. Spawn Player (Major Issues)\n\n**Backend Player for test additions:**\n```\nTask tool:\n  description: \"Backend Player: Add Tests for Coverage\"\n  subagent_type: \"general-purpose\"\n  model: \"sonnet\"\n  prompt: |\n    You are AIDA Backend Player in FIX mode.\n\n    ## Current State\n    Project: {{PROJECT}}\n    Location: ./backend/\n\n    ## Problem\n    {{SPECIFIC_GATE_FAILURE}}\n\n    ## Your Task\n    {{SPECIFIC_FIX_INSTRUCTIONS}}\n\n    ## Requirements\n    - Follow TDD (write test first, then implementation)\n    - Run `go test ./...` after each change\n    - Achieve minimum 80 tests, 75% coverage\n\n    ## Completion\n    Write results to .aida/results/fix-backend-{{PROJECT}}.json\n```\n\n**Frontend Player for test additions:**\n```\nTask tool:\n  description: \"Frontend Player: Add Tests for Coverage\"\n  subagent_type: \"general-purpose\"\n  model: \"sonnet\"\n  prompt: |\n    You are AIDA Frontend Player in FIX mode.\n\n    ## Current State\n    Project: {{PROJECT}}\n    Location: ./frontend/\n\n    ## Problem\n    {{SPECIFIC_GATE_FAILURE}}\n\n    ## Your Task\n    {{SPECIFIC_FIX_INSTRUCTIONS}}\n\n    ## Requirements\n    - Follow TDD\n    - Run `pnpm test -- --run` after each change\n    - Achieve minimum 100 tests, 70% coverage\n    - Ensure E2E tests pass\n\n    ## Completion\n    Write results to .aida/results/fix-frontend-{{PROJECT}}.json\n```\n\n---\n\n## Step 5: Iterate Until All Gates Pass\n\n```\n┌─────────────────────────────────────────────────────────────────┐\n│  FIX LOOP (ralph-loop style)                                     │\n│                                                                  │\n│  1. RUN GATES → ./scripts/quality-gates.sh {{PROJECT}}          │\n│                                                                  │\n│  2. PARSE OUTPUT → Which gates failed?                          │\n│                                                                  │\n│  3. FOR EACH FAILURE:                                            │\n│     → Determine fix strategy                                     │\n│     → Apply fix (direct or via Player)                          │\n│     → Verify fix worked                                          │\n│                                                                  │\n│  4. RE-RUN GATES                                                 │\n│                                                                  │\n│  5. IF ALL 19 PASS → DONE                                        │\n│     ELSE → GOTO step 3                                           │\n└─────────────────────────────────────────────────────────────────┘\n```\n\n---\n\n## Step 6: Run Docker + E2E Verification\n\nAfter basic gates pass, verify Docker and E2E:\n\n```bash\n# Start Docker environment\npodman-compose up -d --build  # or docker compose\n\n# Wait for services\nsleep 30\n\n# Health checks\ncurl -sf http://localhost:8080/health\ncurl -sf http://localhost:5173/\n\n# Run E2E tests\ncd frontend\nE2E_BASE_URL=http://localhost:5173 pnpm test:e2e\n\n# Cleanup\ncd ..\npodman-compose down\n```\n\n---\n\n## Step 7: Update Session and Kanban\n\nAfter all gates pass:\n\n**Update session.json:**\n```json\n{\n  \"current_phase\": \"COMPLETED\",\n  \"quality_gates_passed\": true,\n  \"fixed_at\": \"<ISO8601>\",\n  \"fix_summary\": {\n    \"gates_fixed\": [\"Gate 11\", \"Gate 12\", \"Gate 19\"],\n    \"tests_added\": 45,\n    \"coverage_improvement\": \"68% → 83%\"\n  }\n}\n```\n\n**Update kanban.md:**\n```markdown\n## Status: COMPLETED ✅ (Fixed)\n\n## Quality Gates - ALL 19 PASSED ✅\n- [x] Gate 1-18: (existing gates)\n- [x] Gate 19: E2E Test Execution (Playwright)\n\n## Fix Summary\n- Fixed at: {{TIMESTAMP}}\n- Gates fixed: {{LIST}}\n- Tests added: {{COUNT}}\n```\n\n---\n\n## Step 8: Report Completion\n\n```\nAIDA Fix Complete\n\nProject: {{PROJECT}}\nDuration: {{DURATION}}\n\nGates Fixed:\n- Gate 11: Backend Test Count (50 → 85)\n- Gate 12: Frontend Test Count (80 → 110)\n- Gate 14: Backend Coverage (65% → 78%)\n- Gate 19: E2E Test Execution (PASS)\n\nQuality Gates: 19/19 PASSED\n\nTo run the project:\n  docker compose up -d\n  open http://localhost:5173\n```\n\n---\n\n## Common Fix Patterns\n\n### Adding Backend Tests Quickly\n\nFocus on table-driven tests for high coverage:\n\n```go\nfunc TestHandler_AllCases(t *testing.T) {\n    tests := []struct {\n        name           string\n        input          string\n        expectedStatus int\n    }{\n        {\"valid\", `{\"field\":\"value\"}`, 200},\n        {\"empty\", ``, 400},\n        {\"invalid json\", `{bad}`, 400},\n        // Add 10+ cases for quick coverage boost\n    }\n\n    for _, tt := range tests {\n        t.Run(tt.name, func(t *testing.T) {\n            // test implementation\n        })\n    }\n}\n```\n\n### Adding Frontend Tests Quickly\n\nFocus on render and interaction tests:\n\n```tsx\ndescribe(''Component'', () => {\n  it(''renders correctly'', () => { ... });\n  it(''handles click'', () => { ... });\n  it(''shows loading state'', () => { ... });\n  it(''shows error state'', () => { ... });\n  it(''handles empty data'', () => { ... });\n  // 5 tests per component = quick coverage\n});\n```\n\n### Fixing E2E Test Failures\n\nCommon issues:\n1. **Selector not found** → Update to use `getByRole` or `getByText`\n2. **Timeout** → Add explicit waits\n3. **Network error** → Ensure backend is running\n4. **State pollution** → Add proper test isolation\n\n---\n\n## Related Commands\n\n| Command | Description |\n|---------|-------------|\n| `/aida` | Start new project from scratch |\n| `/aida:resume` | Continue from last session state |\n| `/aida:status` | Check current state |\n"},"lastSynced":"2026-03-07T03:29:53.000Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing automated project validation and repair capabilities.","zh":"适用于需要自动化项目验证和修复功能的代码审查代理。","ja":"コードレビューエージェントが自動化されたプロジェクトの検証と修復機能を必要とする場合に最適です。","ko":"자동화된 프로젝트 검증 및 수리 기능이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan capacidades de validación y reparación de proyectos automatizados.","fr":"Parfait pour les Agents de Révision de Code ayant besoin de capacités de validation et de réparation de projets automatisées.","de":"Perfekt für Code-Review-Agenten, die automatisierte Projektvalidierungs- und Reparaturfunktionen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que precisam de validação e reparo de projetos automatizados.","ru":"Идеально для агентов проверки кода, которым необходимы автоматизированные возможности проверки и исправления проектов.","ar":"مثالي لعميل مراجعة الكود الذي يحتاج إلى إمكانيات التحقق والتصحيح الآلي للمشاريع."},"recommendation":{"en":"Empowers agents to fix existing projects and pass all 19 quality gates, leveraging command-line interfaces and directory validation protocols like `ls -la`.","zh":"赋予代理修复现有项目并通过所有 19 个质量门的能力，利用命令行接口和目录验证协议，如 `ls -la`。","ja":"エージェントに既存のプロジェクトを修復し、すべての 19 個の品質ゲートを通過する能力を付与します。コマンドラインインターフェースとディレクトリの検証プロトコル (`ls -la` など) を利用します。","ko":"에이전트가 기존 프로젝트를 수정하고 모든 19개의 품질 게이트를 통과할 수 있는 능력을 부여합니다. 명령줄 인터페이스와 디렉토리 검증 프로토콜(예: `ls -la`)을 활용합니다.","es":"Habilita a los agentes a arreglar proyectos existentes y pasar las 19 puertas de calidad, aprovechando interfaces de línea de comandos y protocolos de validación de directorios como `ls -la`.","fr":"Permet aux agents de réparer les projets existants et de passer les 19 portes de qualité, en exploitant les interfaces de ligne de commande et les protocoles de validation de répertoires comme `ls -la`.","de":"Ermächtigt Agenten, bestehende Projekte zu beheben und alle 19 Qualitätsprüfungen zu bestehen, indem sie Kommandozeilen-Schnittstellen und Verzeichnisv