INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jiahao-jayden/vibe-any-tanstack/ai-elements', 'ai-elements', 'jiahao-jayden', 'vibe-any-tanstack', 'community', 'ai-elements jiahao-jayden vibe-any-tanstack community ai-elements is a full-stack starter for building AI-powered web apps with TanStack, including authentication and database. It benefits developers looking to build AI-native applications faster. ai-elements是一款基于shadcn/ui的组件库和自定义注册表，帮助您快速构建AI原生应用 ai-elementsはshadcn/uiをベースにしたコンポーネントライブラリとカスタムレジストリで、AIネイティブアプリケーションの構築を迅速化します ai-elements는 shadcn/ui를 기반으로 하는 컴포넌트 라이브러리와 커스텀 레지스트리로 AI 네이티브 애플리케이션을 빠르게 구축하는 데 도움을 줍니다 ai-elements es una biblioteca de componentes y registro personalizado para desarrollar aplicaciones web de IA de forma rápida ai-elements est une bibliothèque de composants et un registre personnalisé pour développer rapidement des applications web IA ai-elements ist eine Komponentenbibliothek und ein benutzerdefinierter Registry, um AI-Webanwendungen schnell zu entwickeln ai-elements é uma biblioteca de componentes e registro personalizado para construir aplicativos web inteligentes com TanStack ai-elements - это библиотека компонентов и пользовательский реестр для создания веб-приложений с функциями ИИ на основе TanStack ai-elements هو مكتبة مكونات وسجل مخصص لإنشاء تطبيقات ويب ذكية مع TanStack how to use ai-elements ai-elements setup guide ai-elements alternative ai-elements vs shadcn/ui ai-elements install what is ai-elements ai-elements documentation ai-elements tutorial ai-elements full-stack development ai-elements AI元素 TanStack Start.Ships shadcn/ui AI原生应用 组件库 自定义注册表 快速部署 CLI命令行工具 Pre-built components like conversations and messages Custom registry built on top of shadcn/ui Supports integration via standard shadcn/ui CLI Dedicated CLI command for fastest setup Includes authentication, database, landing page, blog, docs, i18n, and admin panel ai-elements is a component library and custom registry built on top of shadcn/ui for building AI-native applications');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mj-meyer/choo-choo-ralph/release-skills', 'community', 'mj-meyer', 'choo-choo-ralph', 'mj-meyer/choo-choo-ralph', 'release-skills', 27, 2, 59, '2026-02-23T14:29:56Z', '2026-03-06T06:39:32.094Z', '220b163cfe79562e417d5fe8a2586d254aabac186a86bb667a087743196d94be', '{"id":"mj-meyer/choo-choo-ralph/release-skills","name":"release-skills","description":{"en":"The release-skills plugin adds structured workflow formulas to the Ralph loop, supporting various project types. It benefits developers by automating release workflows with multi-language changelog generation.","zh":"Release Skills 是一个 Claude Code 插件，提供结构化的可自定义的工作流公式，支持多语言的变更日志","ja":"Release Skills は Claude Code プラグインであり、構造化されたカスタマイズ可能なワークフローフォーミュラを提供し、多言語の変更ログをサポートします","ko":"Release Skills는 Claude Code 플러그인으로 구조화된 워크플로 수식을 제공하며 다중 언어의 변경 로그를 지원합니다","es":"Release-skills es un plugin de Claude Code que agrega fórmulas de flujo de trabajo estructuradas y personalizables al bucle de Ralph. Soporta proyectos Node.js, Python, Rust y más","fr":"Release-skills est un plugin Claude Code qui ajoute des formules de workflow structurées et personnalisables à la boucle Ralph. Il prend en charge les projets Node.js, Python, Rust et plus","de":"Release-skills ist ein Claude-Code-Plugin, das strukturierte und anpassbare Workflow-Formeln zum Ralph-Loop hinzufügt. Es unterstützt Node.js-, Python-, Rust- und weitere Projekte","pt":"O release-skills é um plugin Claude Code que adiciona fluxos de trabalho personalizáveis ao Ralph loop, suportando projetos em Node.js, Python, Rust e mais","ru":"Release-skills - это плагин Claude Code, который добавляет настраиваемые рабочие процессы в цикл Ralph, поддерживая проекты на Node.js, Python, Rust и других","ar":"release-skills هو ملحق Claude Code يضيف سير عمل مخصصة إلى حلقة Ralph، يدعم مشاريع Node.js و Python و Rust وغيرها"},"seo":