INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mattgierhart/PRD-driven-context-engineering/prd-v03-moat-definition', 'prd-v03-moat-definition', 'mattgierhart', 'PRD-driven-context-engineering', 'community', 'prd-v03-moat-definition mattgierhart PRD-driven-context-engineering community ai-assisted claude developer-tools nextjs product-development productivity rapid-development supabase templates workflow prd-v03-moat-definition enables developers to build AI-powered products using progressive documentation and context-aware development workflows. It benefits developers working with Next.js, Supabase, and Claude. prd-v03-moat-definition是一种系统化的方法，使用进阶文档和上下文感知开发工作流构建AI驱动产品 prd-v03-moat-definitionは、進歩的なドキュメントとコンテキスト認識開発ワークフローを使用してAI駆動製品を構築する体系的なアプローチです prd-v03-moat-definition은 진보된 문서와 컨텍스트 인식 개발 워크플로우를 사용하여 AI 구동 제품을 구축하는 체계적인 접근 방식입니다 prd-v03-moat-definition es una aproximación sistemática para desarrollar productos con AI, utilizando documentación progresiva y flujos de trabajo de desarrollo de contexto prd-v03-moat-definition est une approche systématique pour développer des produits avec l''IA, en utilisant une documentation progressive et des flux de travail de développement de contexte prd-v03-moat-definition ist ein systematischer Ansatz zur Entwicklung von Produkten mit KI, unter Verwendung von fortschreitender Dokumentation und Kontext-Entwicklungs-Workflows O PRD-v03-Moat Definition é uma abordagem sistemática para desenvolver produtos AI-powered com documentação progressiva e fluxos de trabalho de engenharia de contexto PRD-v03-Moat Definition - это системный подход к разработке продуктов с поддержкой ИИ с помощью прогрессивной документации и контекстно-зависимых рабочих процессов PRD-v03-Moat Definition هو نهج منهجي لتعزيز منتجاتك بالذكاء الاصطناعي باستخدام توثيق تقدمي وfluxos de trabalho de engenharia de contexto how to use prd-v03-moat-definition what is prd-v03-moat-definition prd-v03-moat-definition alternative prd-v03-moat-definition vs competitive landscape mapping prd-v03-moat-definition install prd-v03-moat-definition setup guide for Next.js prd-v03-moat-definition and Supabase integration context engineering with prd-v03-moat-definition AI-powered product development with prd-v03-moat-definition AI驱动产品开发 进阶文档 上下文感知开发工作流 竞争地图制图 竞争情报收集 Next.js Supabase AIエージェント开发 Consumes landscape map artifacts from Competitive Landscape Mapping Utilizes CFD-* entries for competitive intelligence and documented competitors Integrates with BR-* product type entries for informed product development Supports workflow positioning between v0.2 Competitive Landscape and v0.3 Pricing Model Selection Leverages progressive documentation for efficient product development Enables context-aware development workflows for AI-powered products prd-v03-moat-definition is a systematic approach to building AI-powered products using progressive documentation and context-aware development workflows, positioned in the HORIZON workflow between Competitive Landscape and Pricing Model Selection.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vladm3105/aidoc-flow-framework/doc-sys-validator', 'community', 'vladm3105', 'aidoc-flow-framework', 'vladm3105/aidoc-flow-framework', 'doc-sys-validator', 9, 2, 59, '2026-03-01T01:56:07Z', '2026-03-06T06:48:02.410Z', 'db05a184d918a34a1c28239dd7c118b75bf35f53de565d881d3d6a4e8456e5fe', '{"id":"vladm3105/aidoc-flow-framework/doc-sys-validator","name":"doc-sys-validator","description":{"en":"The doc-sys-validator skill automatically validates SYS documents against the defined Layer 6 schema standards. It is invoked for validating or after modifying SYS artifacts, ensuring they meet the required structural and schema criteria for developers and technical writers.","zh":"doc-sys-validator 是一个AI驱动的技能，用于在创建或修改后自动验证SYS文档。它严格检查文件夹嵌套规则，并依据`SYS_MVP_SCHEMA.yaml` schema确保Layer 6工件符合标准。","ja":"doc-sys-validator は、SYS文書の作成や変更後に自動検証を行うAIエージェントスキルです。ネストされたフォルダ構造を厳密にチェックし、`SYS_MVP_SCHEMA.yaml`スキーマに基づいてLayer 6アーティファクトの標準準拠を保証します。","ko":"doc-sys-validator는 SYS 문서 생성 또는 수정 후 자동 검증을 수행하는 AI 에이전트 스킬입니다. 중첩 폴더 구조를 엄격히 확인하고 `SYS_MVP_SCHEMA.yaml` 스키마를 기준으로 Layer 6 아티팩트의 표준 준수를 보장합니다.","es":"El doc-sys-validator es una herramienta que valida documentos SYS contra el estándar de esquema de Layer 6. Permite la validación de estructuras de carpetas y artefactos SYS","fr":"Le doc-sys-validator est un outil qui valide les documents SYS contre la norme de schéma de la couche 6. Il permet la validation des structures de dossiers et des artefacts SYS","de":"Der doc-sys-validator ist ein Tool, das SYS-Dokumente gegen den Schmastaandard von Layer 6 überprüft. Es ermöglicht die Überprüfung von Ordnerstrukturen und SYS-Artefakten","pt":"O doc-sys-validator é uma ferramenta que valida documentos SYS contra o padrão de esquema da Camada 6","ru":"doc-sys-validator - это инструмент, который проверяет SYS-документы против стандартов схемы слоя 6","ar":"doc-sys-validator هو أداة لتحقق وثائق SYS ضد معايير مخطط الطبقة 6"},"seo":{"title":{"en":"doc-sys-validator: SYS Document Schema Validation | AI Ag...","zh":"doc-sys-validator 设置指南：验证 SYS 文档","ja":"doc-sys-validator セットアップガイド：SYS文書検証AIエージェント","ko":"doc-sys-validator 설정 가이드: SYS 문서 검증","es":"Guía de configuración de doc-sys-validator para la valida...","fr":"Configurer le doc-sys-validator pour la validation de doc...","de":"Einrichtungsanleitung für doc-sys-validator zur Überprüfu...","pt":"Guia de Configuração do doc-sys-validator para Validação ...","ru":"ИИ Агенты: Настройка doc-sys-validator для валидации SYS","ar":"دليل إعداد doc-sys-validator لتحقق SYS"},"description":{"en":"Validate Layer 6 SYS documents against the SYS_MVP_SCHEMA.yaml standard. This AI Agent skill enforces nested folder structure rules and provides a blocking c...","zh":"专为开发者设计的AI工具，用于根据Layer 6的YAML schema自动验证系统需求(SYS)文档的结构与文件夹层级，确保符合MVP标准。","ja":"開発者向けAIエージェント。Layer 6のYAMLスキーマに基づきシステム要件(SYS)文書の構造とフォルダ階層を自動検証し、MVP標準への準拠を保証します。","ko":"개발자를 위한 AI 에이전트 도구입니다. Layer 6의 YAML 스키마를 기준으로 시스템 요구사항(SYS) 문서의 구조와 폴더 계층을 자동 검증하여 MVP 표준 준수를 보장합니다.","es":"Aprende a configurar y utilizar el doc-sys-validator para validar documentos SYS contra el estándar de esquema de Layer 6","fr":"Découvrez comment configurer et utiliser le doc-sys-validator pour valider les documents SYS contre la norme de schéma de la couche 6","de":"Erfahren Sie, wie Sie den doc-sys-validator konfigurieren und verwenden, um SYS-Dokumente gegen den Schmastaandard von Layer 6 zu überprüfen","pt":"Aprenda a configurar o doc-sys-validator para validar documentos SYS contra o padrão de esquema da Camada 6","ru":"Узнайте, как настроить doc-sys-validator для проверки SYS-документов против стандартов схемы слоя 6","ar":"تعرف على كيفية إعداد doc-sys-validator لتحقق وثائق SYS ضد معايير مخطط الطبقة 6"},"definition":{"en":"doc-sys-validator is an AI Agent skill that validates System Requirements (SYS) documents against the Layer 6 schema standard defined in SYS_MVP_SCHEMA.yaml. It performs blocking folder structure checks and ensures artifact compliance.","zh":"doc-sys-validator 是一款AI工具技能，专门用于根据`ai_dev_ssd_flow/06_SYS/SYS_MVP_SCHEMA.yaml` schema标准验证系统需求(SYS)文档。它强制执行嵌套文件夹规则，并对Layer 6工件类型进行阻塞性验证。","ja":"doc-sys-validator は、`ai_dev_ssd_flow/06_SYS/SYS_MVP_SCHEMA.yaml`スキーマ標準に基づきシステム要件(SYS)文書を検証するAIエージェントスキルです。ネストされたフォルダ規則を強制し、Layer 6アーティファクトタイプのブロッキング検証を行います。","ko":"doc-sys-validator는 `ai_dev_ssd_flow/06_SYS/SYS_MVP_SCHEMA.yaml` 스키마 표준에 따라 시스템 요구사항(SYS) 문서를 검증하는 AI 에이전트 스킬입니다. 중첩 폴더 규칙을 강제하고 Layer 6 아티팩트 유형에 대한 블로킹 검증을 수행합니다.","es":"El doc-sys-validator es una herramienta de validación de SYS que verifica la conformidad con el estándar de esquema de Layer 6","fr":"Le doc-sys-validator est un outil de validation de SYS qui vérifie la conformité à la norme de schéma de la couche 6","de":"Der doc-sys-validator ist ein Überprüfungstool für SYS, das die Konformität mit dem Schmastaandard von Layer 6 überprüft","pt":"O que é doc-sys-validator? Uma ferramenta de validação de SYS contra o padrão de esquema da Camada 6","ru":"Что такое doc-sys-validator? Инструмент для проверки SYS-документов против стандартов схемы слоя 6","ar":"ما هو doc-sys-validator؟ أداة لتحقق وثائق SYS ضد معايير مخطط الطبقة 6"},"features":{"en":["Validates SYS documents against the SYS_MVP_SCHEMA.yaml schema standard","Enforces the blocking nested folder rule for all SYS documents","Activates upon user request for SYS validation","Triggers automatically after creating or modifying SYS artifacts","Operates at Layer 6 for System Requirements artifacts"],"zh":["根据Layer 6的SYS_MVP_SCHEMA.yaml schema进行验证","强制执行阻塞性的嵌套文件夹规则验证","在文档创建或修改后自动调用","专为系统需求(SYS)文档工件设计","确保MVP标准合规性"],"ja":["Layer 6のSYS_MVP_SCHEMA.yamlスキーマに基づく検証","ブロッキングなネストされたフォルダ規則の強制検証","文書作成・変更後の自動呼び出し","システム要件(SYS)文書アーティファクト専用設計","MVP標準へのコンプライアンス確保"],"ko":["Layer 6 SYS_MVP_SCHEMA.yaml 스키마 기반 검증","블로킹 중첩 폴더 규칙 강제 검증","문서 생성 또는 수정 후 자동 호출","시스템 요구사항(SYS) 문서 아티팩트 전용 설계","MVP 표준 준수성 보장"],"es":["Validación de estructuras de carpetas anidadas","Comprobación de la conformidad con el estándar de esquema de Layer 6","Soporte para la validación de artefactos SYS","Utiliza el esquema de validación SYS_MVP_SCHEMA.yaml","Permite la validación después de crear o modificar artefactos SYS"],"fr":["Validation des structures de dossiers imbriqués","Vérification de la conformité à la norme de schéma de la couche 6","Prise en charge de la validation des artefacts SYS","Utilise le schéma de validation SYS_MVP_SCHEMA.yaml","Permet la validation après création ou modification d''artefacts SYS"],"de":["Überprüfung von Ordnerstrukturen mit verschachtelten Ordnern","Überprüfung der Konformität mit dem Schmastaandard von Layer 6","Unterstützung für die Überprüfung von SYS-Artefakten","Verwendung des Überprüfungsschemas SYS_MVP_SCHEMA.yaml","Ermöglicht die Überprüfung nach Erstellung oder Änderung von SYS-Artefakten"],"pt":["Validação de estrutura de pastas aninhadas","Verificação contra o padrão de esquema da Camada 6","Suporte à criação e modificação de artefatos SYS","Integração com o esquema SYS_MVP_SCHEMA.yaml","Validação de documentos SYS em pastas aninhadas"],"ru":["Валидация вложенной структуры папок","Проверка против стандартов схемы слоя 6","Поддержка создания и модификации SYS-артефактов","Интеграция с схемой SYS_MVP_SCHEMA.yaml","Проверка SYS-документов во вложенных папках"],"ar":["تحقق هيكل المجلدات المترابطة","التحقق ضد معايير مخطط الطبقة 6","دعم إنشاء وتعديل مكونات SYS","التكامل مع مخطط SYS_MVP_SCHEMA.yaml","التحقق من وثائق SYS في المجلدات المترابطة"]},"keywords":{"en":["doc-sys-validator setup guide","how to validate SYS documents","SYS_MVP_SCHEMA.yaml validation","Layer 6 schema standards","doc-sys-validator vs sys-doc-checker","ai agent SYS validation skill","nested folder rule for SYS documents","install doc-sys-validator","what is doc-sys-validator"],"zh":["doc-sys-validator","SYS文档验证","Layer 6 schema","YAML验证工具","AI代理开发","系统需求验证","文件夹结构验证","SYS_MVP_SCHEMA"],"ja":["doc-sys-validator","SYS文書検証","Layer 6スキーマ","YAML検証ツール","AIエージェント開発","システム要件検証","フォルダ構造検証","SYS_MVP_SCHEMA"],"ko":["doc-sys-validator","SYS 문서 검증","Layer 6 스키마","YAML 검증 도구","AI 에이전트 개발","시스템 요구사항 검증","폴더 구조 검증","SYS_MVP_SCHEMA"],"es":["herramientas de validación de SYS","validación de documentos SYS","estándar de esquema de Layer 6","validación de estructuras de carpetas","SYS_MVP_SCHEMA.yaml","configuración de doc-sys-validator","validación de artefactos SYS"],"fr":["outils de validation de SYS","validation de documents SYS","norme de schéma de la couche 6","validation des structures de dossiers","SYS_MVP_SCHEMA.yaml","configuration de doc-sys-validator","validation des artefacts SYS"],"de":["Überprüfungstools für SYS","Überprüfung von SYS-Dokumenten","Schmastaandard von Layer 6","Überprüfung von Ordnerstrukturen","SYS_MVP_SCHEMA.yaml","Konfiguration von doc-sys-validator","Überprüfung von SYS-Artefakten"],"pt":["validação de SYS","doc-sys-validator","Camada 6","esquema de validação","arteefatos SYS","criação de SYS","modificação de SYS","validação de documentos SYS"],"ru":["валидация SYS","doc-sys-validator","слой 6","стандарты схемы","SYS-артефакты","создание SYS","модификация SYS","проверка SYS-документов"],"ar":["تحقق SYS","doc-sys-validator","الطبقة 6","معايير مخطط","مكونات SYS","إنشاء SYS","تعديل SYS","التحقق من وثائق SYS"]}},"owner":"vladm3105","repo":"aidoc-flow-framework","repoPath":"vladm3105/aidoc-flow-framework","stars":9,"forks":2,"updatedAt":"2026-03-01T01:56:07Z","topics":[],"category":"community","skillMd":{"name":"doc-sys-validator","description":"Validate System Requirements (SYS) documents against Layer 6 schema standards","version":"1.2","tags":"","bodyPreview":"# doc-sys-validator\n\nValidate System Requirements (SYS) documents against Layer 6 schema standards.\n\n## Activation\n\nInvoke when user requests validation of SYS documents or after creating/modifying SYS artifacts.\n\n## Validation Schema Reference\n\nSchema: `ai_dev_ssd_flow/06_SYS/SYS_MVP_SCHEMA.yaml`\nLayer: 6\nArtifact Type: SYS\n\n## Validation Checklist\n\n### 0. Folder Structure Validation (BLOCKING)\n\n**Nested Folder Rule**: ALL SYS documents MUST be in nested folders regardless of size.\n\n**Required","body":"# doc-sys-validator\n\nValidate System Requirements (SYS) documents against Layer 6 schema standards.\n\n## Activation\n\nInvoke when user requests validation of SYS documents or after creating/modifying SYS artifacts.\n\n## Validation Schema Reference\n\nSchema: `ai_dev_ssd_flow/06_SYS/SYS_MVP_SCHEMA.yaml`\nLayer: 6\nArtifact Type: SYS\n\n## Validation Checklist\n\n### 0. Folder Structure Validation (BLOCKING)\n\n**Nested Folder Rule**: ALL SYS documents MUST be in nested folders regardless of size.\n\n**Required Structure**:\n\n| SYS Type | Required Location |\n|----------|-------------------|\n| Monolithic | `docs/06_SYS/SYS-NN_{slug}/SYS-NN_{slug}.md` |\n\n**Validation**:\n\n```\n1. Check document is inside a nested folder: docs/06_SYS/SYS-NN_{slug}/\n2. Verify folder name matches SYS ID pattern: SYS-NN_{slug}\n3. Verify file name matches folder: SYS-NN_{slug}.md\n4. Parent path must be: docs/06_SYS/\n```\n\n**Example Valid Structure**:\n\n```\ndocs/06_SYS/\n├── SYS-01_f1_iam/\n│   ├── SYS-01_f1_iam.md           ✓ Valid\n│   ├── SYS-01.R_review_report_v001.md\n│   └── .drift_cache.json\n├── SYS-02_f2_session/\n│   └── SYS-02_f2_session.md       ✓ Valid\n```\n\n**Invalid Structure**:\n\n```\ndocs/06_SYS/\n├── SYS-01_f1_iam.md               ✗ NOT in nested folder\n```\n\n**Error Codes**:\n\n| Code | Severity | Description |\n|------|----------|-------------|\n| SYS-E020 | ERROR | SYS not in nested folder (BLOCKING) |\n| SYS-E021 | ERROR | Folder name doesn''t match SYS ID |\n| SYS-E022 | ERROR | File name doesn''t match folder name |\n| VAL-H001 | ERROR | Drift cache missing hash for upstream document |\n| VAL-H002 | ERROR | Invalid hash format (must be sha256:<64 hex chars>) |\n\n**This check is BLOCKING** - SYS must pass folder structure validation before other checks proceed.\n\n---\n\n### 1. Metadata Validation\n\n```yaml\nRequired custom_fields:\n  - document_type: [\"sys\", \"template\"]\n  - artifact_type: \"SYS\"\n  - layer: 6\n  - architecture_approaches: [array format]\n  - priority: [\"primary\", \"shared\", \"fallback\"]\n  - development_status: [\"active\", \"draft\", \"deprecated\", \"reference\"]\n\nRequired tags:\n  - sys (or sys-template)\n  - layer-6-artifact\n\nForbidden tag patterns:\n  - \"^system-requirements$\"\n  - \"^sys-doc$\"\n  - \"^sys-\\\\d{3}$\"\n```\n\n### 2. Structure Validation\n\n**Required Sections (15 sections):**\n- Title (H1): `# SYS-NNN: Title`\n- Section 1: Document Control\n- Section 2: Executive Summary\n- Section 3: Scope (Boundaries, Inclusions, Exclusions)\n- Section 4: Functional Requirements (SYS.NN.01.SS format)\n- Section 5: Quality Attributes (Performance, Reliability, Security)\n- Section 6: Interface Specifications\n- Section 7: Data Management\n- Section 8: Testing Requirements\n- Section 9: Deployment Requirements\n- Section 10: Compliance Requirements\n- Section 11: Acceptance Criteria\n- Section 12: Risk Assessment\n- Section 13: Traceability\n- Section 14: Implementation Notes\n- Section 15: Change History\n\n**Document Control Required Fields:**\n- SYS ID\n- Document Name\n- Version\n- Date Created\n- Last Updated\n- Author\n- Reviewer\n- Status\n\n**File Naming:**\nPattern: `SYS-NNN_descriptive_name.md`\n\n### 3. Content Validation\n\n**Functional Requirement Format:**\n- Pattern: `SYS.NN.01.SS` (unified 4-segment format)\n- Table columns: SYS ID, Requirement, Priority, Source, Verification Method\n- Element type code: 01 = Functional Requirement\n- Priority values: Must Have, Should Have, Could Have, Won''t Have\n\n**Quality Attribute Format (4-segment):**\n- Pattern: `SYS.NN.02.SS` (02 = Quality Attribute type)\n- Example: `SYS.08.02.15`\n- Categories: Performance, Reliability, Scalability, Security, Observability, Maintainability\n\n**Quality Attribute Metrics:**\n\n| Category | Keywords | Metrics |\n|----------|----------|---------|\n| Performance | latency, response time, throughput, p50/p95/p99 | Response Time, Throughput, Latency |\n| Reliability | uptime, availability, MTBF, MTTR | Availability, Error Rate |\n| Scalability | concurrent, horizontal, vertical | Concurrent Users, Data Volume |\n| Security | auth, encrypt, RBAC, compliance | Authentication, Authorization |\n| Observability | log, monitor, alert, trace | Logging, Monitoring, Alerting |\n| Maintainability | coverage, deploy, CI/CD | Code Coverage, Deploy Frequency |\n\n**REQ-Ready Score:**\n- Minimum threshold: 90%\n- Components: Functional completeness, quality attributes, interfaces, data management, testing, acceptance criteria, traceability\n\n### 4. Traceability Validation\n\n**Layer 6 Cumulative Tags:**\n- @brd: BRD.NN.01.SS (required)\n- @prd: PRD.NN.07.SS (required)\n- @ears: EARS.NN.24.SS (required)\n- @bdd: BDD.NN.13.SS (required)\n- @adr: ADR-NN (required)\n\n**Downstream Expected:**\n- REQ documents\n- SPEC documents\n- TASKS documents\n\n**Same-Type References:**\n- @related-sys: SYS-NN\n- @depends-sys: SYS-NN\n\n## Error Codes\n\n| Code | Severity | Description |\n|------|----------|-------------|\n| SYS-E001 | error | Missing required tag ''sys'' |\n| SYS-E002 | error | Missing required tag ''layer-6-artifact'' |\n| SYS-E003 | error | Invalid document_type |\n| SYS-E004 | error | Invalid architecture_approaches format |\n| SYS-E005 | error | Forbidden tag pattern detected |\n| SYS-E006 | error | Missing required section |\n| SYS-E007 | error | Multiple H1 headings detected |\n| SYS-E008 | error | Section numbering not sequential (1-15) |\n| SYS-E009 | error | Document Control missing required fields |\n| SYS-E010 | error | Missing Functional Requirements (Section 4) |\n| SYS-E011 | error | Missing Quality Attributes (Section 5) |\n| SYS-E012 | error | Missing Traceability (Section 13) |\n| SYS-E013 | warning | File name does not match format |\n| SYS-W001 | warning | Functional requirements not using SYS.NN.01.SS |\n| SYS-W002 | warning | Quality attributes not using 4-segment format |\n| SYS-W003 | warning | Missing Performance category |\n| SYS-W004 | warning | Missing Security category |\n| SYS-W005 | warning | Missing upstream tags (require 5) |\n| SYS-W006 | warning | REQ-Ready Score below 90% |\n| SYS-W007 | warning | Testing Requirements missing coverage |\n| SYS-I001 | info | Consider adding p50/p95/p99 latency |\n| SYS-I002 | info | Consider adding MTBF/MTTR metrics |\n\n## Validation Commands\n\n```bash\n# Validate single SYS document\npython ai_dev_ssd_flow/06_SYS/scripts/validate_sys.py docs/06_SYS/SYS-01_example/SYS-01_example.md\n\n# Validate all SYS documents\npython ai_dev_ssd_flow/06_SYS/scripts/validate_sys.py docs/06_SYS/\n\n# Check with verbose output\npython ai_dev_ssd_flow/06_SYS/scripts/validate_sys.py docs/06_SYS/ --verbose\n```\n\n## Validation Workflow\n\n1. Parse YAML frontmatter\n2. Check required metadata fields\n3. Validate tag taxonomy\n4. Verify section structure (1-15)\n5. Validate Document Control table\n6. Check functional requirement format\n7. Check quality attribute format\n8. Verify quality categories coverage\n9. Validate upstream references (5 required)\n10. Calculate REQ-Ready Score\n11. Verify file naming convention\n12. Generate validation report\n\n## Integration\n\n- Invoked by: doc-flow, doc-sys (post-creation)\n- Feeds into: trace-check (cross-document validation)\n- Reports to: quality-advisor\n\n## Output Format\n\n```\nSYS Validation Report\n=====================\nDocument: SYS-001_example.md\nStatus: PASS/FAIL\n\nQuality Attribute Coverage:\n- Performance: Present/Missing\n- Reliability: Present/Missing\n- Security: Present/Missing\n- Scalability: Present/Missing\n- Observability: Present/Missing\n\nErrors: N\nWarnings: N\nInfo: N\n\n[Details listed by severity]\n```\n\n---\n\n## Version History\n\n| Version | Date | Changes | Author |\n|---------|------|---------|--------|\n| 1.2 | 2026-02-27 | Migrated frontmatter to `metadata`; aligned schema to `SYS_MVP_SCHEMA.yaml`; normalized validation commands to `ai_dev_ssd_flow/06_SYS/scripts/validate_sys.py` | System |\n| 1.1 | 2026-02-11 | **Nested Folder Rule**: Added Section 0 Folder Structure Validation (BLOCKING); SYS must be in `docs/06_SYS/SYS-NN_{slug}/` folders; Added error codes SYS-E020, SYS-E021, SYS-E022 |\n| 1.0 | 2026-02-08 | Initial validator skill definition with YAML frontmatter | System |\n\n## Implementation Plan Consistency (IPLAN-004)\n\n- Treat plan-derived outputs as valid source mode and verify intent preservation from implementation plan scope/objectives.\n- Validate upstream autopilot precedence assumption: `--iplan > --ref > --prompt`.\n- Flag objective/scope conflicts between plan context and artifact output as blocking issues requiring clarification.\n- Do not introduce legacy fallback paths such as `docs-v2.0/00_REF`.\n\n"},"lastSynced":"2026-03-06T06:48:02.410Z","agentAnalysis":{"suitability":{"en":"Ideal for Technical Writing Agents requiring strict SYS document validation against Layer 6 schema standards.","zh":"适用于需要严格SYS文档验证的技术写作代理，验证标准基于Layer 6模式标准。","ja":"Layer 6 スキーマ標準に対する厳格なSYSドキュメントの検証を必要とするテクニカルライティングエージェントに適しています。","ko":"Layer 6 스키마 표준에 대한 엄격한 SYS 문서 검증이 필요한 기술 작성 에이전트에 적합합니다.","es":"Ideal para agentes de escritura técnica que requieren una validación estricta de documentos SYS contra los estándares de esquema de Layer 6.","fr":"Idéal pour les agents de rédaction technique nécessitant une validation stricte des documents SYS contre les normes de schéma Layer 6.","de":"Ideal für technische Schreibagenten, die eine strenge Validierung von SYS-Dokumenten gegen die Layer-6-Schema-Standards erfordern.","pt":"Ideal para Agentes de Escrita Técnica que requerem validação estrita de documentos SYS contra os padrões de esquema da Camada 6.","ru":"Идеально подходит для агентов технической документации, требующих строгой валидации документов SYS против стандартов схемы слоя 6.","ar":"مثالي لعمليات كتابة تقنية تتطلب التحقق الصارم لوثائق SYS ضد معايير مخطط طبقة 6."},"recommendation":{"en":"Empowers agents to validate SYS documents against the defined Layer 6 schema standards, ensuring compliance with structural and schema criteria through the `ai_dev_ssd_flow/06_SYS/SYS_MVP_SCHEMA.yaml` schema reference, facilitating accurate validation of SYS artifacts.","zh":"赋予代理验证SYS文档与定义的Layer 6模式标准一致性，确保结构和模式标准的符合通过`ai_dev_ssd_flow/06_SYS/SYS_MVP_SCHEMA.yaml`模式参考，实现SYS文档的准确验证。","ja":"エージェントに、SYSドキュメントを定義されたLayer 6 スキーマ標準と照合して検証する能力を与え、`ai_dev_ssd_flow/06_SYS/SYS_MVP_SCHEMA.yaml` スキーマ参照を通じて構造とスキーマ基準の準拠を確保し、SYSアーティファクトの正確な検証を促進します。","ko":"에이전트가 정의된 Layer 6 스키마 표준과 SYS 문서를 비교하여 검증할 수 있는 능력을 부여하여, `ai_dev_ssd_flow/06_SYS/SYS_MVP_SCHEMA.yaml` 스키마 참조를 통해 구조 및 스키마 기준의 준수를 보장하고 SYS 아티팩트의 정확한 검증을 촉진합니다.","es":"Habilita a los agentes a validar documentos SYS contra los estándares de esquema de Layer 6 definidos, garantizando el cumplimiento de los criterios estructurales y de esquema a través de la referencia de esquema `ai_dev_ssd_flow/06_SYS/SYS_MVP_SCHEMA.yaml`, facilitando la validación precisa de artefactos SYS.","fr":"Permet aux agents de valider des documents SYS contre les normes de schéma Layer 6 définies, garantissant la conformité aux critères structurels et de schéma via la référence de schéma `ai_dev_ssd_flow/06_SYS/SYS_MVP_SCHEMA.yaml`, facilitant la validation précise des artefacts SYS.","de":"Ermächtigt Agenten, SYS-Dokumente gegen die definierten Layer-6-Schema-Standards zu validieren, sicherstellend, dass die structuralen und Schema-Kriterien durch die Schema-Referenz `ai_dev_ssd_flow/06_SYS/SYS_MVP_SCHEMA.yaml` eingehalten werden, wodurch eine genaue Validierung von SYS-Artefakten erleichtert wird.","pt":"Habilita os agentes a validar documentos SYS contra os padrões de esquema da Camada 6 definidos, garantindo a conformidade com os critérios estruturais e de esquema por meio da referência de esquema `ai_dev_ssd_flow/06_SYS/SYS_MVP_SCHEMA.yaml`, facilitando a validação precisa de artefatos SYS.","ru":"Наделяет агентов возможностью проверять документы SYS против определенных стандартов схемы слоя 6, обеспечивая соответствие структурным и схемным критериям посредством ссылки на схему `ai_dev_ssd_flow/06_SYS/SYS_MVP_SCHEMA.yaml`, облегчая точную проверку артефактов SYS.","ar":"يتمكن العميل من التحقق من وثائق SYS ضد معايير مخطط طبقة 6 المحددة، مما يضمن المطابقة مع معايير الهيكل والمخطط من خلال مرجع المخطط `ai_dev_ssd_flow/06_SYS/SYS_MVP_SCHEMA.yaml`، ويتيسر التحقق الدقيق لمكونات SYS."},"useCases":{"en":["Validating SYS documents against Layer 6 schema standards","Automating SYS artifact validation after creation or modification","Ensuring nested folder structure for SYS documents"],"zh":["验证SYS文档与Layer 6模式标准一致性","自动化SYS文档创建或修改后的验证","确保SYS文档的嵌套文件夹结构"],"ja":["SYSドキュメントをLayer 6 スキーマ標準と照合して検証する","SYSアーティファクトの作成または変更後の検証を自動化する","SYSドキュメントのネストされたフォルダ構造を確保する"],"ko":["SYS 문서를 Layer 6 스키마 표준과 비교하여 검증한다","SYS 아티팩트의 생성 또는 수정 후 검증을 자동화한다","SYS 문서의 중첩 폴더 구조를 보장한다"],"es":["Validar documentos SYS contra los estándares de esquema de Layer 6","Automatizar la validación de artefactos SYS después de la creación o modificación","Garantizar la estructura de carpetas anidadas para documentos SYS"],"fr":["Valider des documents SYS contre les normes de schéma Layer 6","Automatiser la validation des artefacts SYS après création ou modification","Assurer la structure de dossiers imbriqués pour les documents SYS"],"de":["SYS-Dokumente gegen die Layer-6-Schema-Standards validieren","Die Validierung von SYS-Artefakten nach Erstellung oder Änderung automatisieren","Eine verschachtelte Ordnerstruktur für SYS-Dokumente gewährleisten"],"pt":["Validar documentos SYS contra os padrões de esquema da Camada 6","Automatizar a validação de artefatos SYS após criação ou modificação","Garantir estrutura de pasta aninhada para documentos SYS"],"ru":["Проверка документов SYS против стандартов схемы слоя 6","Автоматизация проверки артефактов SYS после создания или изменения","Обеспечение вложенной структуры папок для документов SYS"],"ar":["التحقق من وثائق SYS ضد معايير مخطط طبقة 6","التنفيذ التلقائي للتحقق من مكونات SYS بعد الإنشاء أو التعديل","ضمان هيكل مجلدات متداخلة لوثائق SYS"]},"limitations":{"en":["Requires access to SYS documents and artifacts","Limited to validation against Layer 6 schema standards","Dependent on the accuracy of the `SYS_MVP_SCHEMA.yaml` schema reference"],"zh":["需要访问SYS文档和文档","仅限于Layer 6模式标准的验证","依赖于`SYS_MVP_SCHEMA.yaml`模式引用的准确性"],"ja":["SYSドキュメントとアーティファクトへのアクセスが必要","Layer 6 スキーマ標準への検証に限定される","`SYS_MVP_SCHEMA.yaml` スキーマ参照の正確性に依存する"],"ko":["SYS 문서 및 아티팩트에 대한 액세스가 필요하다","Layer 6 스키마 표준에 대한 검증으로 제한된다","`SYS_MVP_SCHEMA.yaml` 스키마 참조의 정확성에 의존한다"],"es":["Requiere acceso a documentos y artefactos SYS","Limitado a la validación contra los estándares de esquema de Layer 6","Dependiente de la precisión de la referencia de esquema `SYS_MVP_SCHEMA.yaml`"],"fr":["Nécessite un accès aux documents et artefacts SYS","Limité à la validation contre les normes de schéma Layer 6","Dépend de la précision de la référence de schéma `SYS_MVP_SCHEMA.yaml`"],"de":["Benötigt Zugriff auf SYS-Dokumente und -Artefakte","Begrenzt auf die Validierung gegen die Layer-6-Schema-Standards","Abhängig von der Genauigkeit der Schema-Referenz `SYS_MVP_SCHEMA.yaml`"],"pt":["Requer acesso a documentos e artefatos SYS","Limitado à validação contra os padrões de esquema da Camada 6","Dependente da precisão da referência de esquema `SYS_MVP_SCHEMA.yaml`"],"ru":["Требует доступа к документам и артефактам SYS","Ограничен проверкой против стандартов схемы слоя 6","Зависит от точности ссылки на схему `SYS_MVP_SCHEMA.yaml`"],"ar":["يتطلب الوصول إلى وثائق ومكونات SYS","محدود بالتحقق ضد معايير مخطط طبقة 6","يعتمد على دقة مرجع المخطط `SYS_MVP_SCHEMA.yaml`"]},"version":4},"contentHash":"db05a184d918a34a1c28239dd7c118b75bf35f53de565d881d3d6a4e8456e5fe","qualityScore":59}');
