INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vladm3105/aidoc-flow-framework/doc-sys-validator', 'doc-sys-validator', 'vladm3105', 'aidoc-flow-framework', 'community', 'doc-sys-validator vladm3105 aidoc-flow-framework community The doc-sys-validator skill automatically validates SYS documents against the defined Layer 6 schema standards. It is invoked for validating or after modifying SYS artifacts, ensuring they meet the required structural and schema criteria for developers and technical writers. doc-sys-validator 是一个AI驱动的技能，用于在创建或修改后自动验证SYS文档。它严格检查文件夹嵌套规则，并依据`SYS_MVP_SCHEMA.yaml` schema确保Layer 6工件符合标准。 doc-sys-validator は、SYS文書の作成や変更後に自動検証を行うAIエージェントスキルです。ネストされたフォルダ構造を厳密にチェックし、`SYS_MVP_SCHEMA.yaml`スキーマに基づいてLayer 6アーティファクトの標準準拠を保証します。 doc-sys-validator는 SYS 문서 생성 또는 수정 후 자동 검증을 수행하는 AI 에이전트 스킬입니다. 중첩 폴더 구조를 엄격히 확인하고 `SYS_MVP_SCHEMA.yaml` 스키마를 기준으로 Layer 6 아티팩트의 표준 준수를 보장합니다. El doc-sys-validator es una herramienta que valida documentos SYS contra el estándar de esquema de Layer 6. Permite la validación de estructuras de carpetas y artefactos SYS Le doc-sys-validator est un outil qui valide les documents SYS contre la norme de schéma de la couche 6. Il permet la validation des structures de dossiers et des artefacts SYS Der doc-sys-validator ist ein Tool, das SYS-Dokumente gegen den Schmastaandard von Layer 6 überprüft. Es ermöglicht die Überprüfung von Ordnerstrukturen und SYS-Artefakten O doc-sys-validator é uma ferramenta que valida documentos SYS contra o padrão de esquema da Camada 6 doc-sys-validator - это инструмент, который проверяет SYS-документы против стандартов схемы слоя 6 doc-sys-validator هو أداة لتحقق وثائق SYS ضد معايير مخطط الطبقة 6 doc-sys-validator setup guide how to validate SYS documents SYS_MVP_SCHEMA.yaml validation Layer 6 schema standards doc-sys-validator vs sys-doc-checker ai agent SYS validation skill nested folder rule for SYS documents install doc-sys-validator what is doc-sys-validator doc-sys-validator SYS文档验证 Layer 6 schema YAML验证工具 AI代理开发 系统需求验证 文件夹结构验证 SYS_MVP_SCHEMA Validates SYS documents against the SYS_MVP_SCHEMA.yaml schema standard Enforces the blocking nested folder rule for all SYS documents Activates upon user request for SYS validation Triggers automatically after creating or modifying SYS artifacts Operates at Layer 6 for System Requirements artifacts doc-sys-validator is an AI Agent skill that validates System Requirements (SYS) documents against the Layer 6 schema standard defined in SYS_MVP_SCHEMA.yaml. It performs blocking folder structure checks and ensures artifact compliance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dallay/agentsync/pinned-tag', 'community', 'dallay', 'agentsync', 'dallay/agentsync', 'pinned-tag', 9, 2, 59, '2026-03-02T16:27:37Z', '2026-03-06T06:48:23.973Z', '7d0a024cdf52f7866a2332275a038340219f4f983f02e3da6896e46878a99d8f', '{"id":"dallay/agentsync/pinned-tag","name":"pinned-tag","description":{"en":"pinned-tag is a CLI tool that synchronizes AI agent configurations by locating and validating tags in remote Git repositories. It resolves the specific commit SHA for a tag, including annotated tags, and provides patches to pin dependencies, specifically targeting GitHub Actions security best pra...","zh":"pinned-tag是一种快速的CLI工具，用于同步AI工具配置，支持GitHub Actions安全最佳实践","ja":"pinned-tagは、AIエージェントの設定を同期するための高速なCLIツールであり、GitHub Actionsのセキュリティを強化","ko":"pinned-tag는 AI 에이전트 설정을 동기화하는 빠른 CLI 도구로 GitHub Actions 보안을 강화","es":"Pinned-Tag es una herramienta de línea de comandos que sincroniza configuraciones de agentes de IA utilizando enlaces simbólicos y mejora la seguridad en GitHub Actions","fr":"Pinned-Tag est un outil en ligne de commande qui synchronise les configurations des agents d''IA à l''aide de liens symboliques et améliore la sécurité dans GitHub Actions","de":"Pinned-Tag ist ein Kommandozeilen-Tool, das Konfigurationen für KI-Agenten mithilfe von Symbolverknüpfungen synchronisiert und die Sicherheit in GitHub Actions verbessert","pt":"O Pinned-Tag é uma ferramenta CLI que sincroniza configurações de agentes de AI usando links simbólicos, garantindo a reproducibilidade e a segurança","ru":"Pinned-Tag - это инструмент CLI, который синхронизирует конфигурации ИИ Агентов с помощью символьных ссылок, обеспечивая воспроизводимость и безопасность","ar":"Pinned-Tag هو أداة سطر أوامر تزامن إعدادات أدوات الإعلام الاصطناعي باستخدام روابط رمزية، مما يضمن الإعادة الإنتاج والأمان"},"seo":{"title":{"en":"pinned-tag: Pin GitHub Actions to Commit SHAs | AI Agent ...","zh":"使用pinned-tag实现AI工具配置同步","ja":"pinned-tagを使用したAIエージェント設定の同期","ko":"pinned-tag를 사용한 AI 에이전트 설정 동기화","es":"Configuración de Pinned-Tag: Guía para sincronizar config...","fr":"Pinned-Tag: Guide de configuration pour synchroniser les ...","de":"Pinned-Tag-Setup: Anleitung zur Synchronisierung von Konf...","pt":"Guia de Configuração do Pinned-Tag para Ferramentas de AI","ru":"Настройка Pinned-Tag для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد Pinned-Tag لأدوات الإعلام الاصطناعي"},"description":{"en":"Resolve GitHub Actions security alerts for unpinned tags. This CLI tool uses `git ls-remote --tags` to find and validate the exact commit SHA for a tag, ensu...","zh":"使用pinned-tag同步AI工具配置，实现GitHub Actions安全最佳实践","ja":"pinned-tagを使用してAIエージェントの設定を同期し、GitHub Actionsのセキュリティを強化","ko":"pinned-tag를 사용하여 AI 에이전트 설정을 동기화하고 GitHub Actions 보안을 강화","es":"Aprende a utilizar Pinned-Tag, una herramienta de línea de comandos para sincronizar configuraciones de agentes de IA y mejorar la seguridad en GitHub Actions","fr":"Découvrez comment utiliser Pinned-Tag, un outil en ligne de commande pour synchroniser les configurations des agents d''IA et améliorer la sécurité dans GitHu...","de":"Erfahren Sie, wie Sie Pinned-Tag verwenden, ein Kommandozeilen-Tool zur Synchronisierung von Konfigurationen für KI-Agenten und zur Verbesserung der Sicherhe...","pt":"Aprenda a sincronizar configurações de agentes de AI com o Pinned-Tag, uma ferramenta CLI rápida e portátil","ru":"Узнайте, как синхронизировать конфигурации ИИ Агентов с помощью Pinned-Tag, быстрого и портативного инструмента CLI","ar":"تعرف على كيفية مزامنة إعدادات أدوات الإعلام الاصطناعي باستخدام Pinned-Tag، أداة سطر أوامر سريعة ومتوافقة"},"definition":{"en":"pinned-tag is a fast, portable CLI tool for synchronizing AI agent configurations using symbolic links. It specifically helps locate and validate tags in remote repositories via `git ls-remote --tags`, resolving the specific commit SHA for a tag to pin dependencies and address GitHub Actions security alerts.","zh":"pinned-tag是一种用于同步AI工具配置的CLI工具","ja":"pinned-tagはAIエージェントの設定を同期するCLIツール","ko":"pinned-tag는 AI 에이전트 설정을 동기화하는 CLI 도구","es":"Pinned-Tag es una herramienta de línea de comandos que sincroniza configuraciones de agentes de IA","fr":"Pinned-Tag est un outil en ligne de commande qui synchronise les configurations des agents d''IA","de":"Pinned-Tag ist ein Kommandozeilen-Tool, das Konfigurationen für KI-Agenten synchronisiert","pt":"O Pinned-Tag é uma ferramenta de linha de comando que ajuda a localizar e validar tags em repositórios remotos","ru":"Pinned-Tag - это инструмент командной строки, который помогает находить и проверять теги в удаленных репозиториях","ar":"Pinned-Tag هو أداة سطر أوامر تساعد في العثور على التحقق من العلامات في المستودعات البعيدة"},"features":{"en":["Uses `git ls-remote --tags` to locate and validate tags in remote repositories","Resolves the specific commit SHA for a tag, including support for annotated tags","Provides patches to pin dependencies for reproducible workflows","Targets GitHub Actions security best practices by replacing mutable tags with full commit SHAs","Fixes \"Unpinned tag for a non-immutable Action in workflow\" security alerts"],"zh":["支持GitHub Actions安全最佳实践","使用git ls-remote --tags定位和验证标签","解析标签的特定提交SHA","提供依赖关系补丁","支持CLI工具"],"ja":["GitHub Actionsのセキュリティを強化","git ls-remote --tagsを使用してタグを特定および検証","タグの特定のコミットSHAを解析","依存関係のパッチを提供","CLIツールをサポート"],"ko":["GitHub Actions 보안을 강화","git ls-remote --tags를 사용하여 태그를 특정 및 검증","태그의 특정 커밋 SHA를 분석","의존성 패치를 제공","CLI 도구를 지원"],"es":["Sincronización de configuraciones de agentes de IA utilizando enlaces simbólicos","Soporte para GitHub Actions","Resolución de commit SHA para etiquetas","Proporciona parches para fijar dependencias","Mejora la seguridad al utilizar commit SHAs completos en lugar de etiquetas mutables"],"fr":["Synchronisation des configurations des agents d''IA à l''aide de liens symboliques","Prise en charge de GitHub Actions","Résolution du commit SHA pour les étiquettes","Fournit des correctifs pour fixer les dépendances","Améliore la sécurité en utilisant des commit SHAs complets au lieu d''étiquettes mutables"],"de":["Synchronisierung von Konfigurationen für KI-Agenten mithilfe von Symbolverknüpfungen","Unterstützung für GitHub Actions","Auflösung von commit SHA für Tags","Bereitstellung von Patches zur Fixierung von Abhängigkeiten","Verbesserung der Sicherheit durch die Verwendung von vollständigen commit SHAs anstelle von mutablen Tags"],"pt":["Sincronização de configurações de agentes de AI usando links simbólicos","Uso de `git ls-remote --tags` para localizar e validar tags","Resolução do commit SHA específico para uma tag","Fornecimento de patches para fixar dependências","Integração com GitHub Actions para segurança melhorada","Suporte à reproducibilidade e à segurança"],"ru":["Синхронизация конфигураций ИИ Агентов с помощью символьных ссылок","Использование `git ls-remote --tags` для поиска и проверки тегов","Решение конкретного хэша коммита для тега","Предоставление патчей для фиксации зависимостей","Интеграция с GitHub Actions для улучшения безопасности","Поддержка воспроизводимости и безопасности"],"ar":["مزامنة إعدادات أدوات الإعلام الاصطناعي باستخدام روابط رمزية","استخدام `git ls-remote --tags` للعثور على التحقق من العلامات","حل هاش التزام محدد للعلامة","توفير باتشات لتصحيح التبعيات","التكامل مع GitHub Actions لتحسين الأمان","دعم الإعادة الإنتاج والأمان"]},"keywords":{"en":["what is pinned-tag","how to use pinned-tag for GitHub Actions","pinned-tag vs manual git ls-remote","pinned-tag install guide","pinned-tag setup for AI agents","fix unpinned tag security alert","pin GitHub Actions to commit SHA","pinned-tag mcp cli tool"],"zh":["AI工具配置同步","GitHub Actions安全最佳实践","CLI工具","AI工具开发","git ls-remote --tags","标签验证","提交SHA解析"],"ja":["AIエージェント設定の同期","GitHub Actionsのセキュリティ","CLIツール","AIエージェント開発","git ls-remote --tags","タグ検証","コミットSHA解析"],"ko":["AI 에이전트 설정 동기화","GitHub Actions 보안","CLI 도구","AI 에이전트 개발","git ls-remote --tags","태그 검증","커밋 SHA 분석"],"es":["agentes de IA","herramientas de IA","GitHub Actions","sincronización de configuraciones","seguridad en GitHub","commit SHA","etiquetas mutables","dependencias en GitHub"],"fr":["agents d''IA","outils d''IA","GitHub Actions","synchronisation des configurations","sécurité dans GitHub","commit SHA","étiquettes mutables","dépendances dans GitHub"],"de":["KI-Agenten","KI-Tools","GitHub Actions","Synchronisierung von Konfigurationen","Sicherheit in GitHub","commit SHA","mutablen Tags","Abhängigkeiten in GitHub"],"pt":["Pinned-Tag","Ferramentas de AI","Sincronização de configurações","Links simbólicos","Git","GitHub Actions","Segurança","Reproducibilidade","Desenvolvimento de software","Ferramentas de desenvolvimento"],"ru":["Pinned-Tag","ИИ Агенты","Синхронизация конфигураций","Символьные ссылки","Git","GitHub Actions","Безопасность","Воспроизводимость","Разработка программного обеспечения","Инструменты разработки"],"ar":["Pinned-Tag","أدوات الإعلام الاصطناعي","مزامنة إعدادات","روابط رمزية","Git","GitHub Actions","أمان","إعادة الإنتاج","تطوير البرمجيات","أدوات التطوير"]}},"owner":"dallay","repo":"agentsync","repoPath":"dallay/agentsync","stars":9,"forks":2,"updatedAt":"2026-03-02T16:27:37Z","topics":["agents","ai","cli","mcp"],"category":"community","skillMd":{"name":"pinned-tag","description":">","version":"1.1","bodyPreview":"## Overview\nThis skill helps locate and validate tags in remote repositories using `git ls-remote --tags`, resolving the specific commit SHA for a tag (including annotated tags), and providing patches to pin dependencies. It specifically targets **GitHub Actions** security best practices by encouraging the use of full commit SHAs instead of mutable tags.\n\n## When to Use\n- You need to fix \"Unpinned tag for a non-immutable Action in workflow\" security alerts.\n- You want to ensure reproducibility b","body":"## Overview\nThis skill helps locate and validate tags in remote repositories using `git ls-remote --tags`, resolving the specific commit SHA for a tag (including annotated tags), and providing patches to pin dependencies. It specifically targets **GitHub Actions** security best practices by encouraging the use of full commit SHAs instead of mutable tags.\n\n## When to Use\n- You need to fix \"Unpinned tag for a non-immutable Action in workflow\" security alerts.\n- You want to ensure reproducibility by pinning a GitHub Action or dependency to a specific commit SHA.\n- You need to verify if a tag exists before updating a manifest or CI workflow.\n\n## Critical Patterns\n- **Immutability for Actions**: For GitHub Actions, always prefer the full 40-character commit SHA over a tag name. Tags are mutable and can be moved, leading to security risks or broken builds.\n- **Annotated vs Lightweight Tags**: \n  - **Annotated Tags**: `git ls-remote` returns two entries. The one ending in `^{}` is the \"peeled\" reference pointing directly to the commit object. **ALWAYS use this one**.\n  - **Lightweight Tags**: Return only one entry, which is the commit SHA.\n  - **Selection Logic**: When resolving, always sort the results and take the last one to ensure `^{}` is preferred over the tag object SHA.\n- **Verification**: Always verify the resolved SHA belongs to the expected tag before applying changes.\n\n## Commands\n\n1. **Resolve Tag to SHA (GitHub Actions Friendly)**:\n   ```bash\n   # Example: Resolve ''v2'' tag for actions/checkout\n   # This command ensures that for annotated tags, the commit SHA (peeled tag ^{}) is selected\n   # by sorting and taking the last entry (where ^{} alphabetically follows the base tag).\n   git ls-remote --tags https://github.com/actions/checkout.git | rg \"refs/tags/v2(\\^\\{\\})?$\" | sort | tail -n 1 | awk ''{print $1}''\n   ```\n\n2. **List all remote tags**:\n   ```bash\n   git ls-remote --tags https://github.com/owner/repo.git\n   ```\n\n3. **Check for specific tag existence**:\n   ```bash\n   git ls-remote --tags https://github.com/owner/repo.git | rg \"refs/tags/v1.2.3\"\n   ```\n\n## Workflow for GitHub Actions\n1. **Identify the Action**: Find the `uses: owner/repo@tag` line in the workflow YAML.\n2. **Resolve SHA**: Run `git ls-remote --tags https://github.com/owner/repo.git` filtered by the tag.\n3. **Apply Patch**: Replace the tag with the SHA and add the tag name as a comment for readability.\n   - *Before*: `uses: actions/checkout@v3`\n   - *After*: `uses: actions/checkout@f43a0e5ff2bd294095638e18286ca9a3d1956744 # v3`\n\n## Limitations\n- Cannot access private repositories without proper credentials (SSH/Token).\n- Some actions may not use standard semver tags; always double-check the remote refs.\n\n## Commit Policy\n- This skill does NOT create commits automatically without explicit permission.\n- Suggested commit message: `sec(ci): pin <action-name> to commit SHA for immutability`\n\n## Resources\n- [GitHub Security Best Practices for Actions](https://docs.github.com/en/actions/security-guides/security-hardening-for-github-actions#using-third-party-actions)\n- Tools: `git`, `rg`, `awk`\n"},"lastSynced":"2026-03-06T06:48:23.973Z","agentAnalysis":{"suitability":{"en":"Ideal for GitHub Actions-focused Agents requiring precise commit SHA management and security best practices.","zh":"适用于需要精确的提交SHA管理和安全最佳实践的GitHub Actions专用Agent。","ja":"GitHub Actionsに焦点を当てたエージェントが、正確なコミットSHAの管理とセキュリティのベストプラクティスを必要とする場合に最適です。","ko":"정확한 커밋 SHA 관리 및 보안 모범 사례가 필요한 GitHub Actions 전용 에이전트에 적합합니다.","es":"Ideal para agentes centrados en GitHub Actions que requieren un manejo preciso de SHA de confirmación y las mejores prácticas de seguridad.","fr":"Idéal pour les agents axés sur GitHub Actions nécessitant une gestion précise des SHA de commit et les meilleures pratiques de sécurité.","de":"Ideal für GitHub-Actions-Agents, die eine präzise Commit-SHA-Verwaltung und Sicherheitsbest-Practices erfordern.","pt":"Ideal para agentes focados em GitHub Actions que exigem gerenciamento preciso de SHA de commit e práticas de segurança recomendadas.","ru":"Идеально для агентов, ориентированных на GitHub Actions, требующих точного управления SHA-коммитами и лучших практик безопасности.","ar":"مثالي لعميل GitHub Actions الذي يتطلب إدارة SHA-التزام دقيقة وممارسات أمان مثالية."},"recommendation":{"en":"Empowers agents to synchronize configurations by resolving specific commit SHAs for tags, including annotated tags, and providing patches to pin dependencies using git ls-remote --tags, thereby enhancing GitHub Actions security.","zh":"赋予代理人通过解析标签的特定提交SHA（包括注释标签）并使用git ls-remote --tags提供补丁来固定依赖项，从而增强GitHub Actions安全性的能力。","ja":"エージェントに、タグ（注釈付きタグを含む）の特定のコミットSHAを解決し、git ls-remote --tagsを使用して依存関係を固定するパッチを提供することで、GitHub Actionsのセキュリティを強化する機能を提供します。","ko":"에이전트에 특정 커밋 SHA를 해석하여 태그(주석이 달린 태그 포함) 및 git ls-remote --tags를 사용하여 의존성을 고정하기 위한 패치를 제공함으로써 GitHub Actions의 보안을 강화하는 기능을 부여합니다.","es":"Habilita a los agentes a sincronizar configuraciones resolviendo SHAs de commit específicos para etiquetas, incluidas etiquetas anotadas, y proporcionando parches para fijar dependencias usando git ls-remote --tags, mejorando así la seguridad de GitHub Actions.","fr":"Permet aux agents de synchroniser les configurations en résolvant des SHAs de commit spécifiques pour les balises, y compris les balises annotées, et en fournissant des correctifs pour épingler les dépendances en utilisant git ls-remote --tags, améliorant ainsi la sécurité de GitHub Actions.","de":"Ermächtigt Agents, Konfigurationen zu synchronisieren, indem spezifische Commit-SHAs für Tags, einschließlich annotierter Tags, aufgelöst und Patches zur Fixierung von Abhängigkeiten unter Verwendung von git ls-remote --tags bereitgestellt werden, wodurch die Sicherheit von GitHub Actions verbessert wird.","pt":"Habilita os agentes a sincronizar configurações, resolvendo SHAs de commit específicos para tags, incluindo tags anotadas, e fornecendo patches para fixar dependências usando git ls-remote --tags, melhorando assim a segurança do GitHub Actions.","ru":"Наделяет агентов возможностью синхронизировать конфигурации, разрешая конкретные SHA-коммиты для тегов, включая аннотированные теги, и предоставляя патчи для фиксации зависимостей с помощью git ls-remote --tags, тем самым улучшая безопасность GitHub Actions.","ar":"يمنح الوكلاء القدرة على مزامنة التكوينات من خلال حل SHAs-التزام المحددة للعلامات ، بما في ذلك علامات ملاحظة ، وتقديم تصحيحات لتثبيت التبعيات باستخدام git ls-remote --tags ، مما يحسن بذلك أمان GitHub Actions."},"useCases":{"en":["Resolving Unpinned tag security alerts","Ensuring reproducibility by using full commit SHAs","Validating tags in remote Git repositories"],"zh":["解析未固定标签的安全警报","通过使用完整的提交SHA来确保可复现性","验证远程Git存储库中的标签"],"ja":["固定されていないタグのセキュリティアラートを解決する","完全なコミットSHAを使用して再現性を確保する","リモートGitリポジトリ内のタグを検証する"],"ko":["고정되지 않은 태그의 보안 경고 해결","完整한 커밋 SHA를 사용하여 재현성을 보장하는 것","원격 Git 리포지토리 내의 태그를 검증하는 것"],"es":["Resolución de alertas de seguridad de etiquetas no fijadas","Garantía de reproducibilidad mediante el uso de SHAs de commit completos","Validación de etiquetas en repositorios Git remotos"],"fr":["Résolution des alertes de sécurité de balises non épinglées","Assurance de la reproductibilité en utilisant des SHAs de commit complets","Validation des balises dans les référentiels Git distants"],"de":["Auflösung von Sicherheitswarnungen für nicht fixierte Tags","Gewährleistung der Reproduzierbarkeit durch Verwendung vollständiger Commit-SHAs","Validierung von Tags in Remote-Git-Repositorys"],"pt":["Resolução de alertas de segurança de tags não fixadas","Garantia da reprodutibilidade usando SHAs de commit completos","Validação de tags em repositórios Git remotos"],"ru":["Разрешение уведомлений о безопасности незакрепленных тегов","Обеспечение воспроизводимости с помощью полных SHA-коммитов","Проверка тегов в удаленных репозиториях Git"],"ar":["حل تحذيرات أمان علامات غير مثبته","ضمان إمكانية إعادة الإنتاج باستخدام SHAs-التزام الكامل","التحقق من علامات في مستودعات Git عن بعد"]},"limitations":{"en":["Requires Git repository access","Specifically designed for GitHub Actions"],"zh":["需要Git存储库访问","专门为GitHub Actions设计"],"ja":["Gitリポジトリへのアクセスが必要","GitHub Actions専用に設計"],"ko":["Git 리포지토리 액세스가 필요","GitHub Actions 전용으로 설계"],"es":["Requiere acceso al repositorio Git","Diseñado específicamente para GitHub Actions"],"fr":["Nécessite un accès au référentiel Git","Conçu spécifiquement pour GitHub Actions"],"de":["Erfordert Zugriff auf Git-Repository","Speziell für GitHub Actions konzipiert"],"pt":["Exige acesso ao repositório Git","Projetado especificamente para GitHub Actions"],"ru":["Требует доступа к репозиторию Git","Разработан специально для GitHub Actions"],"ar":["يتطلب الوصول إلى مستودع Git","صمّم خصيصًا لأدوات GitHub Actions"]},"version":4},"contentHash":"7d0a024cdf52f7866a2332275a038340219f4f983f02e3da6896e46878a99d8f","qualityScore":59}');
