INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dallay/agentsync/pinned-tag', 'pinned-tag', 'dallay', 'agentsync', 'community', 'pinned-tag dallay agentsync community agents ai cli mcp pinned-tag is a CLI tool that synchronizes AI agent configurations by locating and validating tags in remote Git repositories. It resolves the specific commit SHA for a tag, including annotated tags, and provides patches to pin dependencies, specifically targeting GitHub Actions security best pra... pinned-tag是一种快速的CLI工具，用于同步AI工具配置，支持GitHub Actions安全最佳实践 pinned-tagは、AIエージェントの設定を同期するための高速なCLIツールであり、GitHub Actionsのセキュリティを強化 pinned-tag는 AI 에이전트 설정을 동기화하는 빠른 CLI 도구로 GitHub Actions 보안을 강화 Pinned-Tag es una herramienta de línea de comandos que sincroniza configuraciones de agentes de IA utilizando enlaces simbólicos y mejora la seguridad en GitHub Actions Pinned-Tag est un outil en ligne de commande qui synchronise les configurations des agents d''IA à l''aide de liens symboliques et améliore la sécurité dans GitHub Actions Pinned-Tag ist ein Kommandozeilen-Tool, das Konfigurationen für KI-Agenten mithilfe von Symbolverknüpfungen synchronisiert und die Sicherheit in GitHub Actions verbessert O Pinned-Tag é uma ferramenta CLI que sincroniza configurações de agentes de AI usando links simbólicos, garantindo a reproducibilidade e a segurança Pinned-Tag - это инструмент CLI, который синхронизирует конфигурации ИИ Агентов с помощью символьных ссылок, обеспечивая воспроизводимость и безопасность Pinned-Tag هو أداة سطر أوامر تزامن إعدادات أدوات الإعلام الاصطناعي باستخدام روابط رمزية، مما يضمن الإعادة الإنتاج والأمان what is pinned-tag how to use pinned-tag for GitHub Actions pinned-tag vs manual git ls-remote pinned-tag install guide pinned-tag setup for AI agents fix unpinned tag security alert pin GitHub Actions to commit SHA pinned-tag mcp cli tool AI工具配置同步 GitHub Actions安全最佳实践 CLI工具 AI工具开发 git ls-remote --tags 标签验证 提交SHA解析 Uses `git ls-remote --tags` to locate and validate tags in remote repositories Resolves the specific commit SHA for a tag, including support for annotated tags Provides patches to pin dependencies for reproducible workflows Targets GitHub Actions security best practices by replacing mutable tags with full commit SHAs Fixes "Unpinned tag for a non-immutable Action in workflow" security alerts pinned-tag is a fast, portable CLI tool for synchronizing AI agent configurations using symbolic links. It specifically helps locate and validate tags in remote repositories via `git ls-remote --tags`, resolving the specific commit SHA for a tag to pin dependencies and address GitHub Actions security alerts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('curiositech/some_claude_skills/terraform-iac-expert', 'community', 'curiositech', 'some_claude_skills', 'curiositech/some_claude_skills', 'terraform-iac-expert', 47, 7, 59, '2026-03-07T02:12:13Z', '2026-03-08T01:58:28.206Z', '06a1daa9110877515e778de1faa4e0e5ee36c1de2f60296f533f07ab009fea17', '{"id":"curiositech/some_claude_skills/terraform-iac-expert","name":"terraform-iac-expert","description":{"en":"The Terraform IaC Expert skill streamlines infrastructure management using Terraform and OpenTofu, benefiting developers and DevOps teams. It specializes in module design and state management.","zh":"Terraform IaC 专家技能专门用于基础设施即代码，包括模块设计、状态管理和多云部署","ja":"Terraform IaC エキスパートスキルは、インフラストラクチャ即コードに特化しており、モジュール設計、状態管理、多クラウド展開を含みます","ko":"Terraform IaC 전문가 스킬은 인프라스트ラク처 即 코드에 특화되어 있으며, 모듈 디자인, 상태 관리, 멀티 클라우드 배포를 포함합니다","es":"Terraform IaC Expert es una habilidad que facilita la configuración y gestión de infraestructuras como código en entornos multi-nube. Permite el diseño de módulos reutilizables y la gestión de estados y secretos de manera segura.","fr":"Terraform IaC Expert est une compétence qui facilite la configuration et la gestion des infrastructures en tant que code dans des environnements multi-cloud. Elle permet la conception de modules réutilisables et la gestion des états et des secrets de manière sécurisée.","de":"Terraform IaC Expert ist eine Fähigkeit, die die Konfiguration und Verwaltung von Infrastrukturen als Code in Multi-Cloud-Umgebungen erleichtert. Sie ermöglicht das Design wiederverwendbarer Module und die Verwaltung von Zuständen und Geheimnissen auf sichere Weise.","pt":"O Terraform IaC Expert é uma ferramenta especializada em Infrastructure as Code usando Terraform e OpenTofu","ru":"Terraform IaC Expert - это инструмент, специализирующийся на Infrastructure as Code с использованием Terrafo