INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('curiositech/some_claude_skills/terraform-iac-expert', 'terraform-iac-expert', 'curiositech', 'some_claude_skills', 'community', 'terraform-iac-expert curiositech some_claude_skills community The Terraform IaC Expert skill streamlines infrastructure management using Terraform and OpenTofu, benefiting developers and DevOps teams. It specializes in module design and state management. Terraform IaC 专家技能专门用于基础设施即代码，包括模块设计、状态管理和多云部署 Terraform IaC エキスパートスキルは、インフラストラクチャ即コードに特化しており、モジュール設計、状態管理、多クラウド展開を含みます Terraform IaC 전문가 스킬은 인프라스트ラク처 即 코드에 특화되어 있으며, 모듈 디자인, 상태 관리, 멀티 클라우드 배포를 포함합니다 Terraform IaC Expert es una habilidad que facilita la configuración y gestión de infraestructuras como código en entornos multi-nube. Permite el diseño de módulos reutilizables y la gestión de estados y secretos de manera segura. Terraform IaC Expert est une compétence qui facilite la configuration et la gestion des infrastructures en tant que code dans des environnements multi-cloud. Elle permet la conception de modules réutilisables et la gestion des états et des secrets de manière sécurisée. Terraform IaC Expert ist eine Fähigkeit, die die Konfiguration und Verwaltung von Infrastrukturen als Code in Multi-Cloud-Umgebungen erleichtert. Sie ermöglicht das Design wiederverwendbarer Module und die Verwaltung von Zuständen und Geheimnissen auf sichere Weise. O Terraform IaC Expert é uma ferramenta especializada em Infrastructure as Code usando Terraform e OpenTofu Terraform IaC Expert - это инструмент, специализирующийся на Infrastructure as Code с использованием Terraform и OpenTofu Terraform IaC Expert هو أداة متخصصة في البنية التحتية كود باستخدام Terraform و OpenTofu how to use terraform-iac-expert terraform-iac-expert setup guide terraform-iac-expert vs terragrunt terraform-iac-expert install what is terraform-iac-expert terraform-iac-expert alternative terraform-iac-expert tutorial terraform-iac-expert best practices terraform-iac-expert multi-cloud deployments Terraform IaC 基础设施即代码 模块设计 状态管理 多云部署 CI/CD 集成 AIエージェント Terraform 专家 Designs reusable Terraform modules for efficient infrastructure setup Manages state files and remote backends for secure infrastructure management Implements multi-environment setups for flexible deployment options Handles complex infrastructure patterns, including remote state backends and secure secrets management Integrates with CI/CD pipelines for automated infrastructure provisioning terraform-iac-expert is a specialized skill for Infrastructure as Code (IaC) management using Terraform, focusing on module design, state management, and multi-cloud deployments.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('adaptyvbio/protein-design-skills/esm', 'community', 'adaptyvbio', 'protein-design-skills', 'adaptyvbio/protein-design-skills', 'esm', 0, 0, 59, '2026-03-08T01:57:15.270Z', '2026-03-08T02:00:09.815Z', '2d7e73ce818b008508ddab26273fd2e89607ca6e723a7033cf947f1e22903217', '{"id":"adaptyvbio/protein-design-skills/esm","name":"esm","description":{"en":"The esm skill enables protein design using Claude Code, benefiting developers and researchers. It requires Python, PyTorch, and CUDA.","zh":"ESM蛋白质设计工具是一种使用Python和PyTorch的蛋白质语言模型，需要CUDA 11.0+和GPU VRAM 8GB以上","ja":"ESMタンパク質設計ツールは、PythonとPyTorchを使用したタンパク質言語モデルです。CUDA 11.0+とGPU VRAM 8GB以上が必要です - AIエージェント","ko":"ESM 단백질 설계 도구는 Python과 PyTorch를 사용하는 단백질 언어 모델로, CUDA 11.0+와 GPU VRAM 8GB 이상이 필요합니다 - AI 에이전트","es":"ESM es un modelo de lenguaje de proteínas que requiere Python 3.8+, PyTorch 1.10+ y CUDA 11.0+ para funcionar","fr":"ESM est un modèle de langage de protéines qui nécessite Python 3.8+, PyTorch 1.10+ et CUDA 11.0+ pour fonctionner","de":"ESM ist ein Protein-Sprachmodell, das Python 3.8+, PyTorch 1.10+ und CUDA 11.0+ erfordert, um zu funktionieren","pt":"O ESM2 é um modelo de linguagem de proteínas que requer Python 3.8+, PyTorch 1.10+ e CUDA 11.0+. Saiba como configurá-lo e executá-lo","ru":"ESM2 - это модель языка белков, требующая Python 3.8+, PyTorch 1.10+ и CUDA 11.0+. Узнайте, как настроить и запустить ее","ar":"إسم2 هو نموذج لغة البروتينات الذي يتطلب بايثون 3.8+ وبايرتوش 1.10+ وكودا 11.0+. تعلم كيفية إعداده وتشغيله"},"seo":{"title":{"en":"esm: Protein Design Setup Guide | AI Agent Skill","zh":"ESM蛋白质设计工具安装指南","ja":"ESMタンパク質設計ツールのセットアップガイド - AIエージェント","ko":"ESM 단백질 설계 도구 설정 가이드 - AI 에이전트","es":"Guía de configuración de ESM para diseño de proteínas","fr":"Guide de configuration ESM pour la conception de protéines","de":"ESM-Konfigurationsleitfaden für Protei