INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('adaptyvbio/protein-design-skills/esm', 'esm', 'adaptyvbio', 'protein-design-skills', 'community', 'esm adaptyvbio protein-design-skills community The esm skill enables protein design using Claude Code, benefiting developers and researchers. It requires Python, PyTorch, and CUDA. ESM蛋白质设计工具是一种使用Python和PyTorch的蛋白质语言模型，需要CUDA 11.0+和GPU VRAM 8GB以上 ESMタンパク質設計ツールは、PythonとPyTorchを使用したタンパク質言語モデルです。CUDA 11.0+とGPU VRAM 8GB以上が必要です - AIエージェント ESM 단백질 설계 도구는 Python과 PyTorch를 사용하는 단백질 언어 모델로, CUDA 11.0+와 GPU VRAM 8GB 이상이 필요합니다 - AI 에이전트 ESM es un modelo de lenguaje de proteínas que requiere Python 3.8+, PyTorch 1.10+ y CUDA 11.0+ para funcionar ESM est un modèle de langage de protéines qui nécessite Python 3.8+, PyTorch 1.10+ et CUDA 11.0+ pour fonctionner ESM ist ein Protein-Sprachmodell, das Python 3.8+, PyTorch 1.10+ und CUDA 11.0+ erfordert, um zu funktionieren O ESM2 é um modelo de linguagem de proteínas que requer Python 3.8+, PyTorch 1.10+ e CUDA 11.0+. Saiba como configurá-lo e executá-lo ESM2 - это модель языка белков, требующая Python 3.8+, PyTorch 1.10+ и CUDA 11.0+. Узнайте, как настроить и запустить ее إسم2 هو نموذج لغة البروتينات الذي يتطلب بايثون 3.8+ وبايرتوش 1.10+ وكودا 11.0+. تعلم كيفية إعداده وتشغيله how to use esm for protein design esm vs other protein design tools esm installation guide what is esm protein design esm alternative protein design tools esm setup guide for Modal esm protein design tutorial esm prerequisites and requirements esm protein language model ESM蛋白质设计工具 Python蛋白质语言模型 PyTorch蛋白质设计 CUDA蛋白质计算 GPU蛋白质设计 蛋白质语言模型设置 biomodals设置 Modal设置 Utilizes the ESM2 Protein Language Model for protein design Requires Python 3.8+, PyTorch 1.10+, and CUDA 11.0+ for operation Supports GPU VRAM of 8GB or more, with 24GB recommended Can be run using the Modal platform with biomodals Executes the modal_esm2_predict_masked.py script for predictions Accepts input in FASTA format via the --input-faa parameter esm is a protein design skill utilizing the ESM2 Protein Language Model, requiring specific technical prerequisites for operation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('juanre/llmemory/rag', 'community', 'juanre', 'llmemory', 'juanre/llmemory', 'rag', 0, 0, 59, '2026-03-08T01:57:15.271Z', '2026-03-08T02:00:21.044Z', '3e2f5b31f4b33893ef877cabe34d00be96f4e93f483afbb5a02d9d23936e8e50', '{"id":"juanre/llmemory/rag","name":"rag","description":{"en":"The RAG skill combines document retrieval with LLM generation for accurate responses, benefiting AI agents. It enables ingestion, retrieval, and reranking of documents.","zh":"RAG（检索增强生成）结合 llmemory 的文档检索和 LLM 生成，实现准确的响应","ja":"RAG（検索強化生成）は、llmemory の文書検索と LLM 生成を組み合わせて正確な応答を実現します","ko":"RAG(검색 강화 생성)는 llmemory의 문서 검색과 LLM 생성을 결합하여 정확한 응답을 구현합니다","es":"RAG combina la recuperación de documentos de llmemory con la generación de LLM para respuestas precisas","fr":"RAG combine la récupération de documents de llmemory avec la génération de LLM pour des réponses précises","de":"RAG kombiniert die Dokumentenrückgewinnung von llmemory mit der LLM-Generierung für genaue Antworten","pt":"O RAG combina a recuperação de documentos com a geração de linguagem natural para respostas precisas e baseadas em fatos","ru":"RAG объединяет документообмен с генерацией ИИ для точных и обоснованных ответов","ar":"نظام RAG ي結ب بين استرجاع الوثائق وتوليد اللغة الطبيعية لتحقيق إجابات دقيقة ومبنية على الحقائق"},"seo":{"title":{"en":"RAG: Setup Guide for AI Agents | AI Agent Skill","zh":"RAG Setup Guide - 用于准确响应的检索增强生成","ja":"RAG セットアップガイド - 正確な応答のための検索強化生成","ko":"RAG 설정 가이드 - 정확한 응답을 위한 검색 강화 생성","es":"Guía de configuración de RAG para desarrolladores","fr":"Guide d''installation de RAG pour les développeurs","de":"RAG-Setup-Anleitung für Entwickler","pt":"Guia de Configuração RAG: Sistemas de Memória de Longo Prazo","ru":"Настройка RAG: Системы Восприятия и Генерации","ar":"إعداد نظام الذاكرة الطويلة المدى RAG"},"description":{"en":"Unlock accurate responses with RAG! Learn how to install and configure Retrieval-Augmented Generation for AI agents, and discover its capabilities today.","zh":"了解 RAG 技术如何结合文档检索和 LLM 生成来实现准确的响应","ja":"RAG 技術が文書検索と LLM 生成を組み合わせて正確な応答を実現する方法について","ko":"RAG 기술이 문서 검색과 LLM 생성을 결합하여 정확한 응답을 구현하는 방법에 대해 알아보세요","es":"Aprende a configurar RAG para mejorar la generación de respuestas precisas con llmemory y modelos de LLM","fr":"Découvrez comment installer RAG pour améliorer la génération de réponses précises avec llmemory et les modèles LLM","de":"Erfahren Sie, wie Sie RAG einrichten, um die Erzeugung genauer Antworten mit llmemory und LLM-Modellen zu verbessern","pt":"Aprenda a configurar o RAG, uma combinação de recuperação de documentos e geração de linguagem natural para respostas precisas","ru":"Узнайте, как настроить RAG, сочетающий документообмен с генерацией ИИ для точных ответов","ar":"تعرف على كيفية إعداد نظام RAG، الذي يجمع بين استرجاع الوثائق وتوليد اللغة الطبيعية لتحقيق إجابات دقيقة"},"definition":{"en":"RAG is a Retrieval-Augmented Generation system that integrates document retrieval with large language model generation for grounded responses.","zh":"RAG 是一种将文档检索与 LLM 生成相结合的技术，用于生成准确的响应","ja":"RAG は、文書検索と LLM 生成を組み合わせて正確な応答を生成する技術です","ko":"RAG는 문서 검색과 LLM 생성을 결합하여 정확한 응답을 생성하는 기술입니다","es":"RAG significa Retrieval-Augmented Generation, una técnica que combina recuperación de documentos y generación de LLM","fr":"RAG signifie Retrieval-Augmented Generation, une technique qui combine la récupération de documents et la génération de LLM","de":"RAG bedeutet Retrieval-Augmented Generation, eine Technik, die Dokumentenrückgewinnung und LLM-Generierung kombiniert","pt":"RAG é uma abordagem de geração de linguagem natural que combina recuperação de documentos e geração de texto","ru":"RAG - это подход к генерации ИИ, сочетающий документообмен и генерацию текста","ar":"نظام RAG هو نهج لتحليل اللغة الطبيعية الذي يجمع بين استرجاع الوثائق وتوليد النص"},"features":{"en":["Supports installation via uv add llmemory command","Enables local cross-encoder models for reranking","Configures OpenAI reranking for improved relevance","Ingests documents into llmemory for retrieval","Retrieves relevant chunks from ingested documents","Reranks retrieved chunks for improved accuracy"],"zh":["支持 llmemory 文档检索","结合 LLM 生成实现准确的响应","支持本地跨编码器模型","支持 OpenAI 重新排序","实现文档检索、搜索和重新排序的 RAG 流水线","通过 uv 命令行工具进行安装和配置"],"ja":["llmemory 文書検索をサポート","LLM 生成と組み合わせて正確な応答を実現","ローカルクロスエンコーダモデルをサポート","OpenAI 重新排序をサポート","文書検索、検索、重新排序の RAG パイプラインを実現","uv コマンドラインツールを使用したインストールと設定"],"ko":["llmemory 문서 검색 지원","LLM 생성과 결합하여 정확한 응답을 구현","로컬 크로스 엔코더 모델 지원","OpenAI 재정렬 지원","문서 검색, 검색, 재정렬의 RAG 파이프라인 구현","uv 명령어 툴을 사용한 설치 및 설정"],"es":["Ingestión de documentos en llmemory","Búsqueda de fragmentos relevantes","Reordenación para mejorar la relevancia","Soporte para modelos de LLM","Instalación con uv add llmemory","Compatibilidad con OpenAI para reordenación"],"fr":["Ingestion de documents dans llmemory","Recherche de fragments pertinents","Réorganisation pour améliorer la pertinence","Prise en charge des modèles LLM","Installation avec uv add llmemory","Compatibilité avec OpenAI pour la réorganisation"],"de":["Ingestion von Dokumenten in llmemory","Suche nach relevanten Fragmenten","Neuordnung zur Verbesserung der Relevanz","Unterstützung für LLM-Modelle","Installation mit uv add llmemory","Kompatibilität mit OpenAI für die Neuordnung"],"pt":["Ingestão de documentos no llmemory","Recuperação de trechos relevantes","Reclassificação para melhorar a relevância","Suporte a modelos de codificação cruzada local","Integração com o OpenAI para reclassificação"],"ru":["Добавление документов в llmemory","Поиск релевантных фрагментов","Переранжировка для улучшения релевантности","Поддержка локальных кросс-кодировочных моделей","Интеграция с OpenAI для переранжировки"],"ar":["إضافة مستندات إلى llmemory","استرجاع شذرات ذات صلة","إعادة تصنيف لتحسين الصلة","دعم نماذج التشفير المتقاطع المحلية","التكامل مع OpenAI للترتيب مرة أخرى"]},"keywords":{"en":["how to use RAG","RAG setup guide","RAG install","what is RAG","RAG alternative","RAG vs LLM","Retrieval-Augmented Generation","RAG for AI agents","RAG technical documentation"],"zh":["RAG 技术","检索增强生成","llmemory 文档检索","LLM 生成","准确的响应","本地跨编码器模型","OpenAI 重新排序","uv 命令行工具","RAG 流水线"],"ja":["RAG 技術","検索強化生成","llmemory 文書検索","LLM 生成","正確な応答","ローカルクロスエンコーダモデル","OpenAI 重新排序","uv コマンドラインツール","RAG パイプライン"],"ko":["RAG 기술","검색 강화 생성","llmemory 문서 검색","LLM 생성","정확한 응답","로컬 크로스 엔코더 모델","OpenAI 재정렬","uv 명령어 툴","RAG 파이프라인"],"es":["RAG","llmemory","LM","Retrieval-Augmented Generation","generación de respuestas precisas","configuración de RAG","desarrollo de AI","herramientas de AI","Agentes de IA"],"fr":["RAG","llmemory","LM","Retrieval-Augmented Generation","génération de réponses précises","installation de RAG","développement d''IA","outils d''IA","Agents d''IA","Outils d''intelligence artificielle"],"de":["RAG","llmemory","LM","Retrieval-Augmented Generation","Erzeugung genauer Antworten","Einrichtung von RAG","Entwicklung von KI","KI-Tools","KI-Agents","Künstliche Intelligenz"],"pt":["RAG","Recuperação de documentos","Geração de linguagem natural","llmemory","Modelos de codificação cruzada","OpenAI","Desenvolvimento de IA","Ferramentas de IA","Técnicas de processamento de linguagem natural"],"ru":["RAG","Документообмен","Генерация ИИ","llmemory","Кросс-кодировочные модели","OpenAI","Разработка ИИ","ИИ Агенты","Техники обработки естественного языка"],"ar":["RAG","استرجاع الوثائق","توليد اللغة الطبيعية","llmemory","نماذج التشفير المتقاطع","OpenAI","تطوير الذكاء الاصطناعي","أدوات الذكاء الاصطناعي","تقنيات معالجة اللغة الطبيعية"]}},"owner":"juanre","repo":"llmemory","repoPath":"juanre/llmemory","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.271Z","topics":[],"category":"community","skillMd":{"name":"rag","description":"Use when building Retrieval-Augmented Generation systems - covers document ingestion, hybrid search retrieval, reranking results, and prompt augmentation for accurate LLM responses grounded in your knowledge base","version":"0.5.0","bodyPreview":"# LLMemory RAG Systems\n\n## Installation\n\n```bash\nuv add llmemory\n# For reranking support\nuv add \"llmemory[reranker-local]\"  # Local cross-encoder models\n# or configure OpenAI reranking (no extra install needed)\n```\n\n## Overview\n\nRetrieval-Augmented Generation (RAG) combines llmemory''s document retrieval with LLM generation for accurate, grounded responses.\n\n**RAG Pipeline:**\n1. **Ingest**: Add documents to llmemory\n2. **Retrieve**: Search for relevant chunks\n3. **Rerank**: Improve relevance orde","body":"# LLMemory RAG Systems\n\n## Installation\n\n```bash\nuv add llmemory\n# For reranking support\nuv add \"llmemory[reranker-local]\"  # Local cross-encoder models\n# or configure OpenAI reranking (no extra install needed)\n```\n\n## Overview\n\nRetrieval-Augmented Generation (RAG) combines llmemory''s document retrieval with LLM generation for accurate, grounded responses.\n\n**RAG Pipeline:**\n1. **Ingest**: Add documents to llmemory\n2. **Retrieve**: Search for relevant chunks\n3. **Rerank**: Improve relevance ordering (optional but recommended)\n4. **Augment**: Build prompt with retrieved context\n5. **Generate**: Get LLM response\n\n**When to use RAG:**\n- Question answering over your documents\n- Customer support with knowledge base\n- Research assistance\n- Code documentation search\n- Any application needing accurate, source-backed answers\n\n## Quick Start\n\n```python\nfrom llmemory import LLMemory, SearchType, DocumentType\nfrom openai import AsyncOpenAI\n\nasync def rag_system():\n    # Initialize\n    memory = LLMemory(\n        connection_string=\"postgresql://localhost/mydb\",\n        openai_api_key=\"sk-...\"\n    )\n    await memory.initialize()\n\n    # 1. Ingest documents\n    await memory.add_document(\n        owner_id=\"workspace-1\",\n        id_at_origin=\"kb\",\n        document_name=\"product_guide.md\",\n        document_type=DocumentType.MARKDOWN,\n        content=\"Your product documentation...\"\n    )\n\n    # 2. Retrieve with reranking\n    results = await memory.search(\n        owner_id=\"workspace-1\",\n        query_text=\"how to reset password\",\n        search_type=SearchType.HYBRID,\n        query_expansion=True,  # Better retrieval\n        rerank=True,           # Better ranking\n        rerank_top_k=50,       # Rerank top 50 candidates\n        rerank_return_k=10,    # Prefer 10 best after reranking\n        limit=5                # Final result count (max of limit and rerank_return_k)\n    )\n\n    # 3. Build prompt with context\n    context = \"\\n\\n\".join([\n        f\"Source: {r.metadata.get(''source'', ''unknown'')}\\n{r.content}\"\n        for r in results\n    ])\n\n    prompt = f\"\"\"Answer the question using only the provided context.\n\nContext:\n{context}\n\nQuestion: how to reset password\n\nAnswer:\"\"\"\n\n    # 4. Generate response\n    client = AsyncOpenAI()\n    response = await client.chat.completions.create(\n        model=\"gpt-4\",\n        messages=[{\"role\": \"user\", \"content\": prompt}]\n    )\n\n    print(response.choices[0].message.content)\n    await memory.close()\n\nimport asyncio\nasyncio.run(rag_system())\n```\n\n## Query Routing for Production RAG\n\nProduction RAG systems should detect when queries cannot be answered from available documents.\n\n**When to use query routing:**\n- User queries may be unanswerable from your knowledge base\n- Need to route to web search or external APIs\n- Want to avoid hallucinated answers\n- Building conversational assistants\n\n**Example:**\n```python\nfrom llmemory import LLMemory\n\nasync with LLMemory(connection_string=\"...\") as memory:\n    # Search with automatic routing\n    result = await memory.search_with_routing(\n        owner_id=\"workspace-1\",\n        query_text=\"What''s the current weather in Paris?\",\n        enable_routing=True,\n        limit=5\n    )\n\n    if result[\"route\"] == \"retrieval\":\n        # Answer from documents\n        return generate_answer(result[\"results\"])\n    elif result[\"route\"] == \"web_search\":\n        # Route to web search\n        return fetch_from_web(query)\n    elif result[\"route\"] == \"unanswerable\":\n        # Honest response\n        return \"I don''t have information to answer that question.\"\n    else:  # clarification\n        return \"Could you please provide more details?\"\n```\n\n**API Reference:**\n\n### search_with_routing()\n\nRoute queries intelligently before searching.\n\n**Signature:**\n```python\nasync def search_with_routing(\n    owner_id: str,\n    query_text: str,\n    enable_routing: bool = True,\n    routing_threshold: float = 0.7,\n    **search_kwargs\n) -> Dict[str, Any]\n```\n\n**Parameters:**\n- `owner_id` (str): Owner identifier\n- `query_text` (str): Search query\n- `enable_routing` (bool, default: True): Enable automatic routing\n- `routing_threshold` (float, default: 0.7): Confidence threshold\n- `**search_kwargs`: Additional arguments passed to search()\n\n**Returns:**\nDict with:\n- `route` (str): \"retrieval\", \"web_search\", \"unanswerable\", or \"clarification\"\n- `confidence` (float): 0-1 confidence in routing decision\n- `results` (List[SearchResult]): If route=\"retrieval\"\n- `message` (str): If route != \"retrieval\"\n- `reason` (str): Explanation of routing decision\n\n**Example:**\n```python\nresult = await memory.search_with_routing(\n    owner_id=\"support\",\n    query_text=\"How do I reset my password?\",\n    routing_threshold=0.8\n)\n\nif result[\"route\"] == \"retrieval\":\n    answer = generate_rag_response(result[\"results\"])\nelse:\n    answer = result[\"message\"]  # Pre-formatted response\n```\n\n## Complete RAG Pipeline\n\n### Step 1: Document Ingestion\n\n```python\nfrom llmemory import LLMemory, DocumentType, ChunkingConfig, LLMemoryConfig\n\nasync def ingest_knowledge_base(owner_id: str):\n    \"\"\"Ingest documents into RAG system.\"\"\"\n\n    # Configure chunking for RAG (smaller chunks for precise retrieval)\n    chunking_config = ChunkingConfig(\n        chunk_size=300,              # Tokens per chunk (smaller for RAG)\n        chunk_overlap=50,            # Overlap for context preservation\n        strategy=\"hierarchical\",     # Chunking strategy\n        min_chunk_size=100,          # Minimum chunk size\n        max_chunk_size=500           # Maximum chunk size\n    )\n\n    # Enable chunk summaries via LLMemoryConfig\n    config = LLMemoryConfig()\n    config.chunking.enable_chunk_summaries = True\n    config.chunking.summary_max_tokens = 80\n\n    memory = LLMemory(\n        connection_string=\"postgresql://localhost/mydb\",\n        config=config\n    )\n    await memory.initialize()\n\n    documents = [\n        {\n            \"name\": \"product_guide.md\",\n            \"type\": DocumentType.MARKDOWN,\n            \"content\": \"...\",\n            \"metadata\": {\"category\": \"guide\", \"version\": \"2.0\"}\n        },\n        {\n            \"name\": \"faq.md\",\n            \"type\": DocumentType.MARKDOWN,\n            \"content\": \"...\",\n            \"metadata\": {\"category\": \"faq\"}\n        },\n        {\n            \"name\": \"api_docs.md\",\n            \"type\": DocumentType.TECHNICAL_DOC,\n            \"content\": \"...\",\n            \"metadata\": {\"category\": \"api\", \"language\": \"python\"}\n        }\n    ]\n\n    for doc in documents:\n        result = await memory.add_document(\n            owner_id=owner_id,\n            id_at_origin=\"knowledge_base\",\n            document_name=doc[\"name\"],\n            document_type=doc[\"type\"],\n            content=doc[\"content\"],\n            metadata=doc[\"metadata\"],\n            chunking_config=chunking_config,\n            generate_embeddings=True\n        )\n        print(f\"Ingested {doc[''name'']}: {result.chunks_created} chunks\")\n```\n\n### Step 2: Retrieval Configuration\n\n```python\nasync def retrieve_for_rag(\n    memory: LLMemory,\n    owner_id: str,\n    query: str,\n    top_k: int = 5\n) -> List[SearchResult]:\n    \"\"\"Retrieve relevant chunks for RAG.\"\"\"\n\n    results = await memory.search(\n        owner_id=owner_id,\n        query_text=query,\n\n        # Hybrid search for best quality\n        search_type=SearchType.HYBRID,\n        alpha=0.6,  # Slight favor to semantic search\n\n        # Query expansion for better recall\n        query_expansion=True,\n        max_query_variants=3,\n\n        # Reranking for precision\n        rerank=True,\n        rerank_top_k=20,        # Consider top 20 candidates\n        rerank_return_k=top_k,  # Prefer top_k after reranking\n\n        # Final limit (actual count = max(limit, rerank_return_k))\n        limit=top_k\n    )\n\n    return results\n```\n\n### Step 3: Reranking Configuration\n\nllmemory supports multiple reranking methods:\n\n#### OpenAI Reranking (Recommended for Quality)\n\n```python\n# Configure via environment\nLLMEMORY_RERANK_PROVIDER=openai\nLLMEMORY_RERANK_MODEL=gpt-4.1-mini\nLLMEMORY_RERANK_TOP_K=30\nLLMEMORY_RERANK_RETURN_K=10\n```\n\n```python\n# Or programmatically\nfrom llmemory import LLMemoryConfig\n\nconfig = LLMemoryConfig()\nconfig.search.enable_rerank = True\nconfig.search.rerank_provider = \"openai\"\nconfig.search.default_rerank_model = \"gpt-4.1-mini\"\nconfig.search.rerank_top_k = 30\nconfig.search.rerank_return_k = 10\n\nmemory = LLMemory(\n    connection_string=\"postgresql://localhost/mydb\",\n    config=config\n)\n```\n\n#### Local Cross-Encoder Reranking (Faster, No API Calls)\n\n```bash\n# Install local reranker dependencies\nuv add \"llmemory[reranker-local]\"\n```\n\n```python\n# Configure\nconfig = LLMemoryConfig()\nconfig.search.enable_rerank = True\nconfig.search.default_rerank_model = \"cross-encoder/ms-marco-MiniLM-L6-v2\"\nconfig.search.rerank_device = \"cpu\"  # or \"cuda\"\nconfig.search.rerank_batch_size = 16\n```\n\n#### Lexical Reranking (Fallback, No Dependencies)\n\n```python\n# Automatic fallback when no reranker configured\n# Uses token overlap scoring\nresults = await memory.search(\n    owner_id=\"workspace-1\",\n    query_text=\"query\",\n    rerank=True  # Uses lexical reranking\n)\n```\n\n## Reranker API Reference\n\n### CrossEncoderReranker\n\nLocal cross-encoder model for reranking search results without API calls.\n\n**Constructor:**\n```python\nCrossEncoderReranker(\n    model_name: str = \"cross-encoder/ms-marco-MiniLM-L6-v2\",\n    device: Optional[str] = None,\n    batch_size: int = 16\n)\n```\n\n**Parameters:**\n- `model_name` (str, default: \"cross-encoder/ms-marco-MiniLM-L6-v2\"): Hugging Face cross-encoder model name\n  - Available models: \"cross-encoder/ms-marco-MiniLM-L6-v2\", \"cross-encoder/ms-marco-TinyBERT-L2-v2\"\n- `device` (Optional[str]): Device to run on: \"cpu\", \"cuda\", or None (auto-detect)\n- `batch_size` (int, default: 16): Batch size for inference\n\n**Methods:**\n\n#### score()\n\nScore query-document pairs for relevance.\n\n**Signature:**\n```python\nasync def score(\n    query_text: str,\n    results: Sequence[SearchResult]\n) -> Sequence[float]\n```\n\n**Parameters:**\n- `query_text` (str): Search query\n- `results` (Sequence[SearchResult]): Search results to score\n\n**Returns:**\n- `Sequence[float]`: Relevance scores (same length as results)\n\n**Example:**\n```python\nfrom llmemory import CrossEncoderReranker\n\n# Initialize reranker\nreranker = CrossEncoderReranker(\n    model_name=\"cross-encoder/ms-marco-MiniLM-L6-v2\",\n    device=\"cpu\",\n    batch_size=32\n)\n\n# Get initial search results\nresults = await memory.search(\n    owner_id=\"workspace-1\",\n    query_text=\"machine learning\",\n    limit=50,\n    rerank=False  # Get unranked results\n)\n\n# Rerank with cross-encoder\nscores = await reranker.score(\"machine learning\", results)\n\n# Sort by new scores\nscored_results = list(zip(scores, results))\nscored_results.sort(key=lambda x: x[0], reverse=True)\ntop_results = [r for _, r in scored_results[:10]]\n```\n\n**Installation:**\n```bash\n# Requires sentence-transformers\nuv add \"llmemory[reranker-local]\"\n```\n\n### OpenAIResponsesReranker\n\nUse OpenAI GPT models for intelligent reranking with natural language understanding.\n\n**Constructor:**\n```python\nOpenAIResponsesReranker(\n    model: str = \"gpt-4.1-mini\",\n    max_candidates: int = 30,\n    temperature: float = 0.0\n)\n```\n\n**Parameters:**\n- `model` (str, default: \"gpt-4.1-mini\"): OpenAI model name\n  - Recommended: \"gpt-4.1-mini\" (fast, cost-effective), \"gpt-4\" (higher quality)\n- `max_candidates` (int, default: 30): Maximum candidates to send to API\n- `temperature` (float, default: 0.0): Model temperature (0 = deterministic)\n\n**Methods:**\n\n#### score()\n\nScore query-document pairs using OpenAI API.\n\n**Signature:**\n```python\nasync def score(\n    query_text: str,\n    results: Sequence[SearchResult]\n) -> Sequence[float]\n```\n\n**Parameters:**\n- `query_text` (str): Search query\n- `results` (Sequence[SearchResult]): Search results to score\n\n**Returns:**\n- `Sequence[float]`: Relevance scores between 0 and 1\n\n**Example:**\n```python\nfrom llmemory import OpenAIResponsesReranker\nimport os\n\n# Initialize reranker (uses OPENAI_API_KEY from env)\nreranker = OpenAIResponsesReranker(\n    model=\"gpt-4.1-mini\",\n    max_candidates=20,\n    temperature=0.0\n)\n\n# Get initial search results\nresults = await memory.search(\n    owner_id=\"workspace-1\",\n    query_text=\"customer retention strategies\",\n    limit=50,\n    rerank=False\n)\n\n# Rerank with OpenAI\nscores = await reranker.score(\"customer retention strategies\", results)\n\n# Sort by scores\nscored_results = list(zip(scores, results))\nscored_results.sort(key=lambda x: x[0], reverse=True)\ntop_results = [r for _, r in scored_results[:10]]\n\nprint(f\"Top result score: {scores[0]:.3f}\")\n```\n\n**Cost Considerations:**\n- Each rerank call makes one API request\n- Costs depend on model and number of candidates\n- Consider caching reranked results for repeated queries\n\n**When to use:**\n- Need highest quality reranking\n- Willing to pay API costs\n- Latency tolerance (100-300ms overhead)\n\n### RerankerService\n\nInternal service that wraps reranker implementations (rarely used directly).\n\n**Usage:** Automatically created by LLMemory when reranking is enabled via configuration. Generally not instantiated directly by users.\n\n## SearchResult Fields Reference\n\nSearch results contain multiple score fields depending on the search configuration. Understanding these fields helps optimize RAG retrieval quality.\n\n### Core Fields\n\n**chunk_id** (UUID)\n- Unique identifier for the chunk\n\n**document_id** (UUID)\n- Parent document identifier\n\n**content** (str)\n- Full chunk text content\n\n**metadata** (Dict[str, Any])\n- Chunk metadata (may include title, section, page number, etc.)\n\n**score** (float)\n- Primary relevance score\n- For hybrid search: combined score from vector and text search\n- For vector search: same as similarity\n- For text search: same as text_rank\n- After reranking: same as rerank_score\n\n### Optional Score Fields\n\n**similarity** (Optional[float])\n- Vector similarity score (cosine distance)\n- Range: 0.0 to 1.0 (higher = more similar)\n- Populated when search_type is VECTOR or HYBRID\n- Example: 0.87 indicates 87% semantic similarity\n\n**text_rank** (Optional[float])\n- BM25 full-text search rank\n- Higher values indicate better keyword matches\n- Populated when search_type is TEXT or HYBRID\n- Not normalized to [0,1] range\n\n**rrf_score** (Optional[float])\n- Reciprocal Rank Fusion score\n- Populated when query_expansion=True (multi-query search)\n- Combines rankings from multiple query variants\n- Higher values indicate consistent ranking across variants\n\n**rerank_score** (Optional[float])\n- Reranker relevance score\n- Populated when rerank=True\n- Range and interpretation depends on reranker:\n  - OpenAI reranker: 0.0 to 1.0 (normalized probability)\n  - Cross-encoder: typically -10 to +10 (raw logit score)\n  - Lexical reranker: 0.0 to 1.0 (token overlap ratio)\n- Higher values indicate higher relevance according to reranker\n\n**summary** (Optional[str])\n- Concise chunk summary (30-50% of original length)\n- Populated when ChunkingConfig.enable_chunk_summaries=True\n- Generated during document ingestion\n- Use for prompts to reduce token usage: `text = result.summary or result.content`\n- See \"Enable and Use Chunk Summaries\" section below\n\n### Using Score Fields\n\n```python\n# Example: Analyzing search result scores\nresults = await memory.search(\n    owner_id=\"workspace-1\",\n    query_text=\"machine learning algorithms\",\n    search_type=SearchType.HYBRID,\n    query_expansion=True,\n    rerank=True,\n    limit=5\n)\n\nfor result in results:\n    print(f\"Chunk ID: {result.chunk_id}\")\n    print(f\"  Final score: {result.score:.3f}\")\n\n    # Vector component (if hybrid/vector search)\n    if result.similarity is not None:\n        print(f\"  Vector similarity: {result.similarity:.3f}\")\n\n    # Text component (if hybrid/text search)\n    if result.text_rank is not None:\n        print(f\"  BM25 rank: {result.text_rank:.3f}\")\n\n    # Multi-query fusion (if query_expansion=True)\n    if result.rrf_score is not None:\n        print(f\"  RRF score: {result.rrf_score:.3f}\")\n\n    # Reranking (if rerank=True)\n    if result.rerank_score is not None:\n        print(f\"  Rerank score: {result.rerank_score:.3f}\")\n\n    # Summary (if enabled during ingestion)\n    if result.summary:\n        print(f\"  Summary: {result.summary[:100]}...\")\n```\n\n### Reranking Parameters\n\n**rerank_top_k** (int, default: 50)\n- Number of initial candidates to send to reranker\n- Retrieve this many results from base search before reranking\n- Larger values: better quality but slower and more expensive\n- Recommended range: 20-100\n\n**rerank_return_k** (int, default: 15)\n- Preferred number of results after reranking\n- Results are prioritized by rerank score\n- Actual result count: `max(limit, rerank_return_k)`\n- Set higher than limit to ensure best reranked results\n\n**limit** (int, default: 10)\n- Final result count returned to user\n- Works with rerank_return_k: `final_count = max(limit, rerank_return_k)`\n- Example: limit=5, rerank_return_k=10 → returns 10 results\n- Example: limit=20, rerank_return_k=10 → returns 20 results\n\n```python\n# Example: Reranking parameter interactions\nresults = await memory.search(\n    owner_id=\"workspace-1\",\n    query_text=\"database optimization\",\n    search_type=SearchType.HYBRID,\n    rerank=True,\n    rerank_top_k=50,      # Consider top 50 from base search\n    rerank_return_k=10,   # Prefer 10 best after reranking\n    limit=5               # But return max(5, 10) = 10 results\n)\n# Returns 10 results (max of limit and rerank_return_k)\nassert len(results) == 10\n\nresults = await memory.search(\n    owner_id=\"workspace-1\",\n    query_text=\"database optimization\",\n    search_type=SearchType.HYBRID,\n    rerank=True,\n    rerank_top_k=50,      # Consider top 50 from base search\n    rerank_return_k=5,    # Prefer 5 best after reranking\n    limit=20              # But return max(20, 5) = 20 results\n)\n# Returns 20 results (max of limit and rerank_return_k)\nassert len(results) == 20\n```\n\n### Step 4: Prompt Augmentation\n\n```python\ndef build_rag_prompt(\n    query: str,\n    results: List[SearchResult],\n    system_instructions: str = \"Answer based only on the provided context.\"\n) -> str:\n    \"\"\"Build RAG prompt with retrieved context.\"\"\"\n\n    # Format context from search results\n    context_parts = []\n    for i, result in enumerate(results, 1):\n        # Include source information\n        source = result.metadata.get(\"source\", \"Unknown\")\n        doc_name = result.metadata.get(\"document_name\", \"\")\n\n        # Use summary if available (more concise for prompts)\n        # Summary is populated when ChunkingConfig.enable_chunk_summaries=True\n        text = result.summary or result.content\n\n        context_parts.append(\n            f\"[Source {i}: {doc_name or source}]\\n{text}\"\n        )\n\n    context = \"\\n\\n\".join(context_parts)\n\n    # Build final prompt\n    prompt = f\"\"\"{system_instructions}\n\nContext:\n{context}\n\nQuestion: {query}\n\nAnswer:\"\"\"\n\n    return prompt\n```\n\n#### Advanced Prompt Patterns\n\n**With Citation Requirements:**\n```python\ndef build_prompt_with_citations(query: str, results: List[SearchResult]) -> str:\n    context_parts = []\n    for i, result in enumerate(results, 1):\n        source = result.metadata.get(\"document_name\", f\"Source {i}\")\n        # Use summary if enabled (see enabling summaries section below)\n        text = result.summary or result.content\n        context_parts.append(f\"[{i}] {source}: {text}\")\n\n    context = \"\\n\\n\".join(context_parts)\n\n    prompt = f\"\"\"Answer the question using the provided context. Cite sources using [number] format.\n\nContext:\n{context}\n\nQuestion: {query}\n\nAnswer (with citations):\"\"\"\n\n    return prompt\n```\n\n**With Metadata Filtering:**\n```python\nasync def rag_with_filters(\n    memory: LLMemory,\n    owner_id: str,\n    query: str,\n    category: str\n):\n    \"\"\"RAG with metadata filtering.\"\"\"\n    results = await memory.search(\n        owner_id=owner_id,\n        query_text=query,\n        search_type=SearchType.HYBRID,\n        metadata_filter={\"category\": category},  # Filter by category\n        rerank=True,\n        limit=5\n    )\n\n    return build_rag_prompt(query, results)\n```\n\n### Step 5: LLM Generation\n\n```python\nfrom openai import AsyncOpenAI\n\nasync def generate_rag_response(\n    query: str,\n    results: List[SearchResult],\n    model: str = \"gpt-4\"\n) -> dict:\n    \"\"\"Generate LLM response with RAG context.\"\"\"\n\n    # Build prompt\n    prompt = build_rag_prompt(query, results)\n\n    # Generate with OpenAI\n    client = AsyncOpenAI()\n    response = await client.chat.completions.create(\n        model=model,\n        messages=[\n            {\n                \"role\": \"system\",\n                \"content\": \"You are a helpful assistant that answers questions based on provided context.\"\n            },\n            {\n                \"role\": \"user\",\n                \"content\": prompt\n            }\n        ],\n        temperature=0.3,  # Lower temperature for factual answers\n        max_tokens=500\n    )\n\n    # Extract response\n    answer = response.choices[0].message.content\n\n    return {\n        \"answer\": answer,\n        \"sources\": [\n            {\n                \"content\": r.content[:200] + \"...\",\n                \"score\": r.score,\n                \"metadata\": r.metadata\n            }\n            for r in results\n        ],\n        \"model\": model\n    }\n```\n\n## Complete RAG System Example\n\n```python\nfrom llmemory import LLMemory, SearchType, DocumentType\nfrom openai import AsyncOpenAI\nfrom typing import List, Dict, Any\n\nclass RAGSystem:\n    \"\"\"Complete RAG system with llmemory.\"\"\"\n\n    def __init__(self, connection_string: str, openai_api_key: str):\n        self.memory = LLMemory(\n            connection_string=connection_string,\n            openai_api_key=openai_api_key\n        )\n        self.client = AsyncOpenAI(api_key=openai_api_key)\n        self.initialized = False\n\n    async def initialize(self):\n        \"\"\"Initialize the RAG system.\"\"\"\n        await self.memory.initialize()\n        self.initialized = True\n\n    async def ingest_document(\n        self,\n        owner_id: str,\n        document_name: str,\n        content: str,\n        document_type: DocumentType = DocumentType.TEXT,\n        metadata: Dict[str, Any] = None\n    ):\n        \"\"\"Add a document to the knowledge base.\"\"\"\n        result = await self.memory.add_document(\n            owner_id=owner_id,\n            id_at_origin=\"rag_kb\",\n            document_name=document_name,\n            document_type=document_type,\n            content=content,\n            metadata=metadata or {},\n            generate_embeddings=True\n        )\n        return {\n            \"document_id\": str(result.document.document_id),\n            \"chunks_created\": result.chunks_created\n        }\n\n    async def answer_question(\n        self,\n        owner_id: str,\n        question: str,\n        top_k: int = 5,\n        model: str = \"gpt-4\"\n    ) -> Dict[str, Any]:\n        \"\"\"Answer a question using RAG.\"\"\"\n\n        # Retrieve relevant chunks\n        results = await self.memory.search(\n            owner_id=owner_id,\n            query_text=question,\n            search_type=SearchType.HYBRID,\n            query_expansion=True,\n            max_query_variants=3,\n            rerank=True,\n            rerank_top_k=20,\n            rerank_return_k=top_k,\n            limit=top_k\n        )\n\n        if not results:\n            return {\n                \"answer\": \"I don''t have enough information to answer this question.\",\n                \"sources\": [],\n                \"confidence\": \"low\"\n            }\n\n        # Build prompt\n        context = \"\\n\\n\".join([\n            f\"[Source: {r.metadata.get(''document_name'', ''Unknown'')}]\\n{r.summary or r.content}\"\n            for r in results\n        ])\n\n        prompt = f\"\"\"Answer the question using only the provided context. If the answer cannot be found in the context, say so.\n\nContext:\n{context}\n\nQuestion: {question}\n\nAnswer:\"\"\"\n\n        # Generate response\n        response = await self.client.chat.completions.create(\n            model=model,\n            messages=[\n                {\"role\": \"system\", \"content\": \"You are a helpful assistant.\"},\n                {\"role\": \"user\", \"content\": prompt}\n            ],\n            temperature=0.3\n        )\n\n        answer = response.choices[0].message.content\n\n        # Determine confidence based on scores\n        avg_score = sum(r.score for r in results) / len(results)\n        confidence = \"high\" if avg_score > 0.5 else \"medium\" if avg_score > 0.3 else \"low\"\n\n        return {\n            \"answer\": answer,\n            \"sources\": [\n                {\n                    \"document_name\": r.metadata.get(\"document_name\"),\n                    \"content_preview\": r.content[:150] + \"...\",\n                    \"score\": r.score,\n                    \"similarity\": r.similarity,\n                    \"rerank_score\": r.rerank_score  # Populated when rerank=True\n                }\n                for r in results\n            ],\n            \"confidence\": confidence,\n            \"model\": model\n        }\n\n    async def close(self):\n        \"\"\"Clean up resources.\"\"\"\n        await self.memory.close()\n\n# Usage\nasync def main():\n    rag = RAGSystem(\n        connection_string=\"postgresql://localhost/mydb\",\n        openai_api_key=\"sk-...\"\n    )\n    await rag.initialize()\n\n    # Ingest documents\n    await rag.ingest_document(\n        owner_id=\"user-123\",\n        document_name=\"product_guide.md\",\n        content=\"...\",\n        document_type=DocumentType.MARKDOWN,\n        metadata={\"category\": \"guide\"}\n    )\n\n    # Answer questions\n    result = await rag.answer_question(\n        owner_id=\"user-123\",\n        question=\"How do I reset my password?\",\n        top_k=5\n    )\n\n    print(f\"Answer: {result[''answer'']}\")\n    print(f\"Confidence: {result[''confidence'']}\")\n    print(f\"Sources: {len(result[''sources''])}\")\n\n    await rag.close()\n```\n\n## RAG Best Practices\n\n### 1. Chunk Size Optimization\n\n```python\nfrom llmemory import ChunkingConfig, LLMemoryConfig\n\n# For RAG, use smaller chunks (better precision)\nchunking_config = ChunkingConfig(\n    chunk_size=300,              # 300 tokens (vs 1000 default)\n    chunk_overlap=50,            # 50 tokens overlap\n    strategy=\"hierarchical\",     # Create parent/child chunks\n    min_chunk_size=100,          # Minimum chunk size\n    max_chunk_size=500           # Maximum chunk size\n)\n\n# Enable summaries via LLMemoryConfig (set when creating LLMemory)\n# config = LLMemoryConfig()\n# config.chunking.enable_chunk_summaries = True\n# config.chunking.summary_max_tokens = 80\n\nawait memory.add_document(\n    owner_id=\"workspace-1\",\n    id_at_origin=\"kb\",\n    document_name=\"doc.md\",\n    document_type=DocumentType.MARKDOWN,\n    content=\"...\",\n    chunking_config=chunking_config\n)\n\n# Smaller chunks:\n# - More precise retrieval\n# - Better for prompts (fit more sources)\n# - Less noise in context\n#\n# Larger chunks:\n# - More context per chunk\n# - Better for broad questions\n# - Fewer chunks needed\n```\n\n### 2. Use Parent Context for Broader Context\n\n```python\n# Retrieve with parent context\nresults = await memory.search(\n    owner_id=\"workspace-1\",\n    query_text=\"API authentication\",\n    search_type=SearchType.HYBRID,\n    include_parent_context=True,  # Include surrounding chunks\n    context_window=2,              # ±2 chunks\n    limit=5\n)\n\n# Build prompt with parent context\nfor result in results:\n    print(f\"Main chunk: {result.content}\")\n    if result.parent_chunks:\n        print(f\"Context from {len(result.parent_chunks)} parent chunks\")\n        for parent in result.parent_chunks:\n            print(f\"  - {parent.content[:100]}...\")\n```\n\n### 3. Reranking for Quality\n\nAlways use reranking in RAG for better relevance:\n\n```python\n# Without reranking (lower quality)\nresults = await memory.search(\n    owner_id=\"workspace-1\",\n    query_text=\"query\",\n    rerank=False,\n    limit=5\n)\n\n# With reranking (higher quality)\nresults = await memory.search(\n    owner_id=\"workspace-1\",\n    query_text=\"query\",\n    rerank=True,\n    rerank_top_k=20,    # Consider top 20 candidates\n    rerank_return_k=10,  # Prefer 10 best after reranking\n    limit=5             # Final count = max(5, 10) = 10 results\n)\n\n# Reranking improves:\n# - Relevance of top results\n# - Precision for RAG prompts\n# - Reduces hallucination (better context)\n```\n\n### 4. Query Expansion for Recall\n\n```python\n# Use multi-query for better recall\nresults = await memory.search(\n    owner_id=\"workspace-1\",\n    query_text=\"reduce latency\",\n    query_expansion=True,  # Generates variants like \"improve response time\"\n    max_query_variants=3,\n    rerank=True,           # Rerank after fusion\n    limit=5\n)\n\n# Good for:\n# - Vague queries\n# - Different terminology in docs\n# - Comprehensive answers\n```\n\n### 5. Metadata for Filtering\n\n```python\n# Add rich metadata during ingestion\nawait memory.add_document(\n    owner_id=\"workspace-1\",\n    id_at_origin=\"kb\",\n    document_name=\"api_v2_docs.md\",\n    document_type=DocumentType.TECHNICAL_DOC,\n    content=\"...\",\n    metadata={\n        \"category\": \"api\",\n        \"version\": \"2.0\",\n        \"language\": \"python\",\n        \"last_updated\": \"2024-10-01\"\n    }\n)\n\n# Filter during retrieval\nresults = await memory.search(\n    owner_id=\"workspace-1\",\n    query_text=\"authentication\",\n    metadata_filter={\n        \"category\": \"api\",\n        \"version\": \"2.0\"\n    },\n    limit=5\n)\n```\n\n### 6. Enable and Use Chunk Summaries\n\nChunk summaries provide concise representations of chunks, making prompts more efficient by reducing token usage while preserving key information.\n\n**Enabling Summaries:**\n\n```python\nfrom llmemory import LLMemory, ChunkingConfig, LLMemoryConfig, DocumentType\n\n# Enable summaries via LLMemoryConfig\nconfig = LLMemoryConfig()\nconfig.chunking.enable_chunk_summaries = True\nconfig.chunking.summary_max_tokens = 80  # Control summary length\n\nmemory = LLMemory(\n    connection_string=\"postgresql://localhost/mydb\",\n    config=config\n)\nawait memory.initialize()\n\n# Use custom chunking config for chunk size settings\nchunking_config = ChunkingConfig(\n    chunk_size=300,\n    chunk_overlap=50,\n    strategy=\"hierarchical\"\n)\n\nawait memory.add_document(\n    owner_id=\"workspace-1\",\n    id_at_origin=\"kb\",\n    document_name=\"doc.md\",\n    document_type=DocumentType.MARKDOWN,\n    content=\"...\",\n    chunking_config=chunking_config\n)\n```\n\n**Using Summaries in Prompts:**\n\n```python\ndef build_prompt_with_summaries(query: str, results: List[SearchResult]):\n    \"\"\"Build prompt using chunk summaries when available.\"\"\"\n    context_parts = []\n    for result in results:\n        # SearchResult.summary is populated when enable_chunk_summaries=True\n        # Falls back to full content if summaries weren''t generated\n        text = result.summary or result.content\n        context_parts.append(text)\n\n    context = \"\\n\".join(context_parts)\n    return f\"Context:\\n{context}\\n\\nQuestion: {query}\\n\\nAnswer:\"\n```\n\n**Benefits:**\n- Reduced prompt token usage (summaries are ~30-50% of original size)\n- More chunks fit in context window\n- Faster LLM processing\n- Preserved key information for accurate answers\n\n## RAG Evaluation\n\n### Measuring Retrieval Quality\n\n```python\nasync def evaluate_retrieval(\n    memory: LLMemory,\n    owner_id: str,\n    test_queries: List[Dict[str, Any]]\n):\n    \"\"\"Evaluate retrieval quality.\"\"\"\n\n    metrics = {\n        \"precision_at_5\": [],\n        \"recall\": [],\n        \"mrr\": []  # Mean Reciprocal Rank\n    }\n\n    for test in test_queries:\n        query = test[\"query\"]\n        relevant_doc_ids = set(test[\"relevant_docs\"])\n\n        # Retrieve\n        results = await memory.search(\n            owner_id=owner_id,\n            query_text=query,\n            rerank=True,\n            limit=10\n        )\n\n        # Calculate precision@5\n        top_5_docs = {str(r.document_id) for r in results[:5]}\n        precision = len(top_5_docs & relevant_doc_ids) / 5\n        metrics[\"precision_at_5\"].append(precision)\n\n        # Calculate recall\n        retrieved_docs = {str(r.document_id) for r in results}\n        recall = len(retrieved_docs & relevant_doc_ids) / len(relevant_doc_ids)\n        metrics[\"recall\"].append(recall)\n\n        # Calculate MRR\n        for rank, result in enumerate(results, 1):\n            if str(result.document_id) in relevant_doc_ids:\n                metrics[\"mrr\"].append(1.0 / rank)\n                break\n        else:\n            metrics[\"mrr\"].append(0.0)\n\n    return {\n        \"avg_precision_at_5\": sum(metrics[\"precision_at_5\"]) / len(test_queries),\n        \"avg_recall\": sum(metrics[\"recall\"]) / len(test_queries),\n        \"mean_reciprocal_rank\": sum(metrics[\"mrr\"]) / len(test_queries)\n    }\n```\n\n\n## Related Skills\n\n- `basic-usage` - Core document and search operations\n- `hybrid-search` - Vector + BM25 hybrid search fundamentals\n- `multi-query` - Query expansion for improved retrieval\n- `multi-tenant` - Multi-tenant isolation patterns for SaaS\n\n## Important Notes\n\n**RAG Pipeline Optimization:**\nThe complete RAG pipeline (retrieve → rerank → generate) typically takes 200-500ms:\n- Retrieval: 50-150ms\n- Reranking: 50-200ms (depending on provider)\n- LLM generation: 500-2000ms\n\n**Chunk Size for RAG:**\nSmaller chunks (200-400 tokens) work better for RAG than larger chunks:\n- More precise retrieval\n- Less noise in context\n- More chunks fit in prompt\n- Better for specific questions\n\n**Multi-Tenant RAG:**\nAlways use `owner_id` for data isolation in multi-tenant RAG systems. Never expose one tenant''s documents to another.\n\n**Reranking ROI:**\nReranking adds 50-200ms but significantly improves answer quality by ensuring the most relevant chunks appear first in the prompt, reducing hallucination and improving accuracy.\n"},"lastSynced":"2026-03-08T02:00:21.044Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing accurate and grounded responses through document retrieval and LLM generation.","zh":"非常适合需要通过文档检索和LLM生成获得准确且有根据的响应的AI代理。","ja":"ドキュメントの検索とLLMの生成を通じて正確で根拠のあるレスポンスを必要とするAIエージェントに最適です。","ko":"문서检索와 LLM 생성을 통해 정확하고 근거 있는 응답이 필요한 AI 에이전트에게 완벽합니다.","es":"Perfecto para agentes de IA que necesitan respuestas precisas y fundamentadas a través de recuperación de documentos y generación de LLM.","fr":"Parfait pour les agents IA ayant besoin de réponses précises et fondées via la récupération de documents et la génération de LLM.","de":"Perfekt für KI-Agents, die genaue und fundierte Antworten durch Dokumentenrückgewinnung und LLM-Generierung benötigen.","pt":"Perfeito para Agentes de IA que necessitam de respostas precisas e baseadas em documentos por meio da recuperação de documentos e geração de LLM.","ru":"Идеально для ИИ-агентов, которым требуются точные и основанные на документах ответы через извлечение документов и генерацию LLM.","ar":"مثالي لعميل الذكاء الاصطناعي الذي يحتاج إلى استجابات دقيقة ومستندة إلى الوثائق من خلال استرجاع الوثائق وتوليد LLM."},"recommendation":{"en":"Empowers agents to generate accurate responses by combining document retrieval with LLM generation, utilizing llmemory and supporting reranking through local cross-encoder models or OpenAI reranking.","zh":"通过将文档检索与LLM生成相结合，利用llmemory，并支持通过本地跨编码器模型或OpenAI重新排名，赋予代理生成准确响应的能力。","ja":"ドキュメントの検索とLLMの生成を組み合わせ、llmemoryを利用し、ローカルのクロスエンコーダモデルまたはOpenAIの再ランキングを通じてランキングを再調整することをサポートすることで、エージェントが正確なレスポンスを生成できるようになります。","ko":"문서检索와 LLM 생성을 결합하고, llmemory를 활용하며, 로컬 크로스 인코더 모델 또는 OpenAI 재정렬을 통해 재정렬을 지원함으로써 에이전트가 정확한 응답을 생성할 수 있도록 합니다.","es":"Habilita a los agentes a generar respuestas precisas combinando la recuperación de documentos con la generación de LLM, utilizando llmemory y admitiendo la reordenación a través de modelos de codificador cruzado locales o reordenación de OpenAI.","fr":"Permet aux agents de générer des réponses précises en combinant la récupération de documents avec la génération de LLM, en utilisant llmemory et en prenant en charge la réorganisation via des modèles de codage croisé local ou la réorganisation d''OpenAI.","de":"Ermöglicht es Agents, genaue Antworten zu generieren, indem sie die Dokumentenrückgewinnung mit der LLM-Generierung kombinieren, llmemory nutzen und die Neubewertung durch lokale Kreuzencoder-Modelle oder OpenAI-Neubewertung unterstützen.","pt":"Habilita os agentes a gerar respostas precisas combinando a recuperação de documentos com a geração de LLM, utilizando llmemory e suportando reordenação por meio de modelos de cross-encoder locais ou reordenação da OpenAI.","ru":"Позволяет агентам генерировать точные ответы, сочетая извлечение документов с генерацией LLM, используя llmemory и поддерживая перезапуск через локальные модели cross-encoder или перезапуск OpenAI.","ar":"يتمكن العملاء من توليد استجابات دقيقة من خلال الجمع بين استرجاع الوثائق وتوليد LLM، باستخدام llmemory ودعم إعادة الترتيب من خلال نماذج التشفير المتقاطع المحلية أو إعادة الترتيب في OpenAI."},"useCases":{"en":["Ingesting documents for knowledge retrieval","Reranking search results for improved relevance","Generating grounded responses using Retrieval-Augmented Generation"],"zh":["为知识检索而摄入文档","重新排名搜索结果以提高相关性","使用检索增强生成生成有根据的响应"],"ja":["知識の取得のためにドキュメントをインジェストする","検索結果を再ランキングして関連性を高める","Retrieval-Augmented Generationを使用して根拠のあるレスポンスを生成する"],"ko":["지식检索를 위한 문서摄入","관련性 개선을 위한 검색 결과 재정렬","Retrieval-Augmented Generation을 사용하여 근거 있는 응답 생성"],"es":["Ingesta de documentos para la recuperación de conocimientos","Reordenación de resultados de búsqueda para mejorar la relevancia","Generación de respuestas fundamentadas utilizando Generación aumentada con recuperación"],"fr":["Ingestion de documents pour la récupération de connaissances","Réorganisation des résultats de recherche pour améliorer la pertinence","Génération de réponses fondées en utilisant la Génération augmentée avec récupération"],"de":["Ingesting von Dokumenten für die Wissensrückgewinnung","Neubewertung von Suchergebnissen zur Verbesserung der Relevanz","Generierung von fundierten Antworten unter Verwendung von Generierung mit Rückgewinnung"],"pt":["Ingestão de documentos para recuperação de conhecimento","Reordenação dos resultados de pesquisa para melhorar a relevância","Geração de respostas baseadas em Retrieval-Augmented Generation"],"ru":["Поглощение документов для извлечения знаний","Перезапуск результатов поиска для улучшения релевантности","Генерация основанных на Retrieval-Augmented Generation ответов"],"ar":["استهلاك الوثائق لاسترجاع المعرفة","إعادة ترتيب نتائج البحث لتحسين الأهمية","توليد الاستجابات المعتمدة على توليد Retrieval-Augmented"]},"limitations":{"en":["Requires llmemory installation","Optional: OpenAI API Key for reranking support"],"zh":["需要安装llmemory","可选：OpenAI API密钥用于重新排名支持"],"ja":["llmemoryのインストールが必要","オプション：OpenAI APIキーを使用した再ランキングのサポート"],"ko":["llmemory 설치 필요","옵션: OpenAI API 키를 사용한 재정렬 지원"],"es":["Requiere la instalación de llmemory","Opcional: clave de API de OpenAI para soporte de reordenación"],"fr":["Nécessite l''installation de llmemory","Optionnel : clé API OpenAI pour la prise en charge de la réorganisation"],"de":["Erfordert die Installation von llmemory","Optional: OpenAI-API-Schlüssel für Neubewertungsunterstützung"],"pt":["Requer instalação do llmemory","Opcional: Chave de API da OpenAI para suporte à reordenação"],"ru":["Требует установку llmemory","Опционально: Ключ API OpenAI для поддержки перезапуска"],"ar":["يتطلب تثبيت llmemory","اختياري: مفتاح API OpenAI لدعم إعادة الترتيب"]},"version":4},"contentHash":"3e2f5b31f4b33893ef877cabe34d00be96f4e93f483afbb5a02d9d23936e8e50","qualityScore":59}');
