INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('juanre/llmemory/rag', 'rag', 'juanre', 'llmemory', 'community', 'rag juanre llmemory community The RAG skill combines document retrieval with LLM generation for accurate responses, benefiting AI agents. It enables ingestion, retrieval, and reranking of documents. RAG（检索增强生成）结合 llmemory 的文档检索和 LLM 生成，实现准确的响应 RAG（検索強化生成）は、llmemory の文書検索と LLM 生成を組み合わせて正確な応答を実現します RAG(검색 강화 생성)는 llmemory의 문서 검색과 LLM 생성을 결합하여 정확한 응답을 구현합니다 RAG combina la recuperación de documentos de llmemory con la generación de LLM para respuestas precisas RAG combine la récupération de documents de llmemory avec la génération de LLM pour des réponses précises RAG kombiniert die Dokumentenrückgewinnung von llmemory mit der LLM-Generierung für genaue Antworten O RAG combina a recuperação de documentos com a geração de linguagem natural para respostas precisas e baseadas em fatos RAG объединяет документообмен с генерацией ИИ для точных и обоснованных ответов نظام RAG ي結ب بين استرجاع الوثائق وتوليد اللغة الطبيعية لتحقيق إجابات دقيقة ومبنية على الحقائق how to use RAG RAG setup guide RAG install what is RAG RAG alternative RAG vs LLM Retrieval-Augmented Generation RAG for AI agents RAG technical documentation RAG 技术 检索增强生成 llmemory 文档检索 LLM 生成 准确的响应 本地跨编码器模型 OpenAI 重新排序 uv 命令行工具 RAG 流水线 Supports installation via uv add llmemory command Enables local cross-encoder models for reranking Configures OpenAI reranking for improved relevance Ingests documents into llmemory for retrieval Retrieves relevant chunks from ingested documents Reranks retrieved chunks for improved accuracy RAG is a Retrieval-Augmented Generation system that integrates document retrieval with large language model generation for grounded responses.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Peiiii/skild/skild', 'community', 'Peiiii', 'skild', 'Peiiii/skild', 'skild', 0, 0, 59, '2026-03-08T01:57:15.276Z', '2026-03-08T02:00:41.570Z', '1a646f1a3ea62ad7724b4cf478e9ceb91c10bb91973002c887f43ab4c7111e3f', '{"id":"Peiiii/skild/skild","name":"skild","description":{"en":"skild is a package manager for AI Agent Skills, enabling easy installation, management, and publishing of skills. It benefits developers working with AI agents.","zh":"skild是AI智能工具包的包管理器，提供发现、安装、管理和发布新的能力","ja":"skildはAIエージェントの能力を拡張するためのパッケージマネージャー","ko":"skild는 AI 에이전트를 위한 패키지 관리자로 새로운 능력을 발견, 설치 및 공유","es":"skild es el administrador de paquetes para habilidades de agentes, que permite instalar, gestionar y publicar habilidades de Agentes de Inteligencia Artificial de manera sencilla","fr":"skild est le gestionnaire de paquets pour les compétences des agents, qui permet d''installer, de gérer et de publier des compétences d''Agents d''Intelligence Artificielle de manière simple","de":"skild ist der Paketmanager für Agentenfähigkeiten, der das Installieren, Verwalten und Veröffentlichen von Fähigkeiten von künstlichen Intelligenzagenten erleichtert","pt":"O skild é um gerenciador de pacotes para habilidades de agente de inteligência artificial, permitindo instalar, gerenciar e publicar habilidades com facilidade.","ru":"Skild - менеджер пакетов для навыков ИИ агентов, позволяет устанавливать, управлять и публиковать навыки легко.","ar":"skild هو مدير حزم لمهارات وكلاء الذكاء الاصطناعي، يسمح بتثبيت وإدارة ونشر المهارات بسهولة."},"seo":{"title":{"en":"skild: Unified Skill Management for AI Agents | AI Agent ...","zh":"skild 安装指南 - AI智能工具包管理","ja":"skild セットアップガイド - AIエージェントの能力を拡張","ko":"skild 설치 가이드 - AI 에이전트를 위한 패키지 관리자","es":"Guía de configuración de skild para Agentes de Inteligenc...","fr":"Guide d''installation de skild pour les Agents d''Intellige...","de":"Einrichtungsanleitung für skild bei künstlichen Intellige...","pt":"Guia de Configuração do skild - Gerenciador de Habilidade...","ru":"Руководство по настройке skild - Менеджер навыков ИИ Агентов","ar":"دليل إعداد skild - مدير مهارات وكلاء الذكاء الاصطناعي"},"description":{"en":"Discover, install, and manage AI Agent Skills with ease using skild. Get started now and explore the Skild Index registry!","zh":"使用skild轻松管理AI智能工具包，发现、安装和发布新的能力","ja":"AIエージェントの能力を拡張するためのパッケージマネージャー、skildを使用して新しいスキルを発見、インストール、公開","ko":"AI 에이전트를 위한 패키지 관리자, skild를 사용하여 새로운 능력을 발견, 설치 및 공유","es":"Descubre cómo instalar, gestionar y publicar habilidades de Agentes de Inteligencia Artificial con skild, el administrador de paquetes para habilidades de ag...","fr":"Découvrez comment installer, gérer et publier des compétences d''Agents d''Intelligence Artificielle avec skild, le gestionnaire de paquets pour les compétence...","de":"Erfahren Sie, wie Sie Fähigkeiten von künstlichen Intelligenzagenten mit skild installieren, verwalten und veröffentlichen, dem Paketmanager für Agentenfähig...","pt":"Descubra como instalar, gerenciar e publicar habilidades de agente de inteligência artificial com o skild, o gerenciador de pacotes para habilidades de agente","ru":"Узнайте, как устанавливать, управлять и публиковать навыки ИИ агентов с помощью skild, менеджера пакетов для навыков агентов","ar":"اكتشف كيفية تثبيت وإدارة ونشر مهارات وكلاء الذكاء الاصطناعي باستخدام skild، مدير الحزم لمهارات الوكيل"},"definition":{"en":"skild is a package manager for AI Agent Skills, similar to npm, but designed for AI agents.","zh":"skild是一种AI智能工具包的包管理器，用于管理AI智能工具包","ja":"skildはAIエージェントの能力を拡張するためのパッケージマネージャー","ko":"skild는 AI 에이전트를 위한 패키지 관리자","es":"skild es un administrador de paquetes para habilidades de Agentes de Inteligencia Artificial, similar a npm","fr":"skild est un gestionnaire de paquets pour les compétences des Agents d''Intelligence Artificielle, similaire à npm","de":"skild ist ein