INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Peiiii/skild/skild', 'skild', 'Peiiii', 'skild', 'community', 'skild Peiiii skild community skild is a package manager for AI Agent Skills, enabling easy installation, management, and publishing of skills. It benefits developers working with AI agents. skild是AI智能工具包的包管理器，提供发现、安装、管理和发布新的能力 skildはAIエージェントの能力を拡張するためのパッケージマネージャー skild는 AI 에이전트를 위한 패키지 관리자로 새로운 능력을 발견, 설치 및 공유 skild es el administrador de paquetes para habilidades de agentes, que permite instalar, gestionar y publicar habilidades de Agentes de Inteligencia Artificial de manera sencilla skild est le gestionnaire de paquets pour les compétences des agents, qui permet d''installer, de gérer et de publier des compétences d''Agents d''Intelligence Artificielle de manière simple skild ist der Paketmanager für Agentenfähigkeiten, der das Installieren, Verwalten und Veröffentlichen von Fähigkeiten von künstlichen Intelligenzagenten erleichtert O skild é um gerenciador de pacotes para habilidades de agente de inteligência artificial, permitindo instalar, gerenciar e publicar habilidades com facilidade. Skild - менеджер пакетов для навыков ИИ агентов, позволяет устанавливать, управлять и публиковать навыки легко. skild هو مدير حزم لمهارات وكلاء الذكاء الاصطناعي، يسمح بتثبيت وإدارة ونشر المهارات بسهولة. how to use skild skild install skild alternative what is skild skild setup guide skild vs npm ai agent skills management skild registry api AI智能工具包 skild 包管理器 AI工具包安装 AI工具包管理 AI工具包发布 Registry API AI智能工具包搜索 Installs new capabilities for AI agents Manages installed Skills via list, update, and uninstall commands Publishes Skills to share with the community Supports searching and discovering new Skills via the Skild Index registry Utilizes the Registry API for unified discovery skild is a package manager for AI Agent Skills, similar to npm, but designed for AI agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('avivsinai/jenkins-cli/jk', 'community', 'avivsinai', 'jenkins-cli', 'avivsinai/jenkins-cli', 'jk', 0, 0, 59, '2026-03-08T01:57:15.294Z', '2026-03-08T02:01:07.332Z', 'e779439c722ed4a4e7f631bf58931479d4964104786993fa56703f8b865719b9', '{"id":"avivsinai/jenkins-cli/jk","name":"jk","description":{"en":"jk is a GitHub CLI-style interface for Jenkins controllers, providing modern workflows for developers. It manages contexts, runs, logs, and admin tasks from the terminal.","zh":"jk 是一个 GitHub 风格的 Jenkins CLI，提供现代化的可脚本化工作流，用于开发者和运维人员","ja":"jk は GitHub スタイルの Jenkins CLI で、開発者とオペレーター向けのモダンなスクリプト可能なワークフローを提供します","ko":"jk는 GitHub 스타일의 Jenkins CLI로 개발자와 운영진을 위한 현대적인 스크립트 가능한 워크플로우를 제공합니다","es":"jk es una CLI de Jenkins que proporciona flujos de trabajo modernos y scriptables para desarrolladores y operadores","fr":"jk est une CLI Jenkins qui fournit des flux de travail modernes et scriptables pour les développeurs et les opérateurs","de":"jk ist eine GitHub-Style-CLI für Jenkins, die moderne, scriptbare Workflows für Entwickler und Betreiber bietet","pt":"O jk é uma interface de linha de comando do Jenkins que fornece fluxos de trabalho modernos e scriptáveis para desenvolvedores e operadores.","ru":"jk — это интерфейс командной строки Jenkins, который предоставляет современные и скриптовые рабочие процессы для разработчиков и операторов.","ar":"jk هو واجهة سطر أوامر جينكينز يوفر عمليات عمل حديثة وقابلة للتشغيل من قبل المطورين والمشغلين."},"seo":{"title":{"en":"jk: GitHub-Style CLI Setup Guide | AI Agent Skill","zh":"jk 安装和使用指南 - GitHub 风格的 Jenkins CLI","ja":"jk Setup Guide - GitHub スタイルの Jenkins CLI","ko":"jk 설치 및 사용 가이드 - GitHub 스타일의 Jenkins CLI","es":"Guía de configuración de jk: CLI de Jenkins para desarrol...","fr":"Guide de configuration de jk : CLI Jenkins pour les dével...","de":"Einrichtungsleitfaden für jk: GitHub-Style-CLI für Jenkins","pt":"Guia de Configuração do jk: Interface de Linha de Comando...","ru":"Настройка jk: GitHub-стиль интерфейса командной строки дл...","ar":"دليل إعداد jk: واجهة سطر الأوامر بال스타يل جيثب لجينكينز"},"description":{"en":"Discover how to manage Jenkins contexts, runs, and logs from your terminal with jk. Get started with installation and setup today!","zh":"了解如何安装和使用 jk，一个 GitHub 风格的 Jenkins CLI，用于管理 Jenkins 控制器和工作流","ja":"jk をインストールして使用する方法を学びましょう。GitHub スタイルの Jenkins CLI で Jenkins コントローラーとワークフローを管理します","ko":"jk 설치 및 사용 방법을 알아보세요. GitHub 스타일의 Jenkins CLI를 사용하여 Jenkins 컨트롤러와 워크플로우를 관리합니다","es":"Aprende a utilizar jk, la CLI de Jenkins, para gestionar contextos, ejecuciones, registros y tareas de administración desde tu terminal","fr":"Découvrez comment utiliser jk, la CLI Jenkins, pour gérer les contextes, les exécutions, les journaux et les tâches d''administration depuis votre terminal","de":"Erfahren Sie, wie Sie jk, die GitHub-Style-CLI für Jenkins, verwenden können, um Kontexte, Ausführungen, Protokolle und Administrativaufgaben von Ihrem Termi...","pt":"Aprenda a utilizar o jk, uma interface de linha de comando do Jenkins inspirada no GitHub CLI, para gerenciar contextos, execuções, logs e tarefas de adminis...","ru":"Узнайте, как использовать jk, интерфейс командной строки Jenkins в стиле GitHub CLI, для управления контекстами, запусками, журналами и задачами администриро...","ar":"تعرف على كيفية استخدام jk، واجهة سطر أوامر جينكينز بال스타يل جيثب، لإدارة السياقات، التشغيل، السجلات، ومهام الإدارة"},"definition":{"en":"jk is a command-line interface for Jenkins controllers, offering a GitHub CLI-style experience for managing Jenkins tasks.","zh":"jk 是一个命令行接口工具，用于管理 Jenkins 控制器和工作流","ja":"jk は Jenkins コントローラーとワークフローを管理するためのコマンドラインインターフェースツールです","ko":"jk는 Jenkins 컨트롤러와 워크플로우를 관리하기 위한 명령줄 인터페이스 도구입니다","es":"jk es una herramienta de línea de comandos para Jenkins que permite a los desarrolladores gestionar contextos, ejecuciones y registros desde su terminal","fr":"jk est un outil de ligne de commande pour Jenkins qui permet aux développeurs de gérer les contextes, les exécutions et les journaux depuis leur terminal","de":"jk ist ein Kommandozeilen-Tool für Jenkins, das es Entwicklern ermöglicht, Kontexte, Ausführungen und Protokolle von ihrem Terminal aus zu verwalten","pt":"O jk é uma interface de linha de comando do Jenkins que permite gerenciar contextos, execuções, logs e tarefas de administração de forma eficiente.","ru":"jk — это интерфейс командной строки Jenkins, который позволяет управлять контекстами, запусками, журналами и задачами администрирования эффективно.","ar":"jk هو واجهة سطر أوامر جينكينز التي تمكن من إدارة السياقات، التشغيل، السجلات، ومهام الإدارة بفعالية."},"features":{"en":["Verifies CLI installation using the `jk --version` command","Installs on macOS and Linux using `brew install avivsinai/tap/jk`","Supports Windows installation via `scoop bucket add avivsinai`","Manages Jenkins contexts, runs, logs, and admin tasks from the terminal","Provides scriptable workflows for developers and operators"],"zh":["支持 GitHub 风格的 CLI 命令","提供现代化的可脚本化工作流","支持管理 Jenkins 控制器和工作流","支持检查依赖项和安装","支持多平台安装，包括 macOS、Linux 和 Windows"],"ja":["GitHub スタイルの CLI コマンドをサポート","モダンなスクリプト可能なワークフローを提供","Jenkins コントローラーとワークフローを管理","依存関係のチェックとインストールをサポート","複数のプラットフォームでのインストールをサポート、macOS、Linux、Windows を含む"],"ko":["GitHub 스타일의 CLI 명령어 지원","현대적인 스크립트 가능한 워크플로우 제공","Jenkins 컨트롤러와 워크플로우 관리","의존성 검사 및 설치 지원","다중 플랫폼 설치 지원, macOS, Linux, Windows 포함"],"es":["Instalación mediante Homebrew o Scoop","Verificación de la versión de jk","Gestión de contextos y ejecuciones de Jenkins","Acceso a registros y tareas de administración","Compatibilidad con macOS, Linux y Windows"],"fr":["Installation via Homebrew ou Scoop","Vérification de la version de jk","Gestion des contextes et des exécutions Jenkins","Accès aux journaux et aux tâches d''administration","Compatibilité avec macOS, Linux et Windows"],"de":["Installation über Homebrew oder Scoop","Überprüfung der jk-Version","Verwaltung von Kontexten und Ausführungen von Jenkins","Zugriff auf Protokolle und Administrativaufgaben","Kompatibilität mit macOS, Linux und Windows"],"pt":["Gerenciamento de contextos do Jenkins","Execução de comandos do Jenkins de forma scriptável","Acesso a logs e histórico de execuções","Tarefas de administração do Jenkins","Instalação via Homebrew ou Scoop"],"ru":["Управление контекстами Jenkins","Выполнение команд Jenkins в скриптовом режиме","Доступ к журналам и истории запусков","Задачи администрирования Jenkins","Установка через Homebrew или Scoop"],"ar":["إدارة السياقات جينكينز","تشغيل أوامر جينكينز بشكل قابل للتشغيل","وصول إلى السجلات وتاريخ التشغيل","مهام إدارة جينكينز","التثبيت عبر هومبرو أو سكوب"]},"keywords":{"en":["how to use jk","jk install","jk setup guide","jk alternative","jk vs Jenkins CLI","what is jk","jk GitHub-style CLI","Jenkins controller management","terminal-based Jenkins management"],"zh":["jk 安装","Jenkins CLI","GitHub 风格的 CLI","可脚本化工作流","Jenkins 控制器管理","依赖项检查","macOS 安装","Linux 安装","Windows 安装"],"ja":["jk インストール","Jenkins CLI","GitHub スタイルの CLI","スクリプト可能なワークフロー","Jenkins コントローラー管理","依存関係チェック","macOS インストール","Linux インストール","Windows インストール"],"ko":["jk 설치","Jenkins CLI","GitHub 스타일의 CLI","스크립트 가능한 워크플로우","Jenkins 컨트롤러 관리","의존성 검사","macOS 설치","Linux 설치","Windows 설치"],"es":["jk CLI","Jenkins CLI","herramientas de desarrollo","gestión de contextos","ejecuciones de Jenkins","registros de Jenkins","tareas de administración","Homebrew","Scoop"],"fr":["jk CLI","Jenkins CLI","outils de développement","gestion des contextes","exécutions Jenkins","journaux Jenkins","tâches d''administration","Homebrew","Scoop"],"de":["jk CLI","Jenkins CLI","Entwicklungstools","Kontextverwaltung","Jenkins-Ausführungen","Jenkins-Protokolle","Administrativaufgaben","Homebrew","Scoop"],"pt":["jk jenkins","interface de linha de comando jenkins","github cli jenkins","gerenciamento de contextos jenkins","execução de comandos jenkins","logs jenkins","tarefas de administração jenkins","instalação jk"],"ru":["jk jenkins","интерфейс командной строки jenkins","github cli jenkins","управление контекстами jenkins","выполнение команд jenkins","журналы jenkins","задачи администрирования jenkins","установка jk"],"ar":["jk جينكينز","واجهة سطر أوامر جينكينز","جيثب سي ال آي جينكينز","إدارة السياقات جينكينز","تشغيل أوامر جينكينز","سجلات جينكينز","مهام إدارة جينكينز","تثبيت jk"]}},"owner":"avivsinai","repo":"jenkins-cli","repoPath":"avivsinai/jenkins-cli","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.294Z","topics":[],"category":"community","skillMd":{"name":"jk","description":"Jenkins CLI for controllers. Use when users need to manage jobs, pipelines, runs, logs, artifacts, credentials, nodes, or queues in Jenkins. Triggers include jenkins, jk, pipeline, build, run logs, job list, jenkins credentials, jenkins node.","version":"1.0.0","bodyPreview":"# Jenkins CLI (jk)\n\n`jk` is a GitHub CLI–style interface for **Jenkins controllers**. It provides modern, scriptable workflows for developers and operators.\n\n## Dependency Check\n\n**Before executing any `jk` command**, verify the CLI is installed:\n\n```bash\njk --version\n```\n\nIf the command fails or `jk` is not found, install it using one of these methods:\n\n| Platform | Command |\n|----------|---------|\n| macOS/Linux | `brew install avivsinai/tap/jk` |\n| Windows | `scoop bucket add avivsinai https:/","body":"# Jenkins CLI (jk)\n\n`jk` is a GitHub CLI–style interface for **Jenkins controllers**. It provides modern, scriptable workflows for developers and operators.\n\n## Dependency Check\n\n**Before executing any `jk` command**, verify the CLI is installed:\n\n```bash\njk --version\n```\n\nIf the command fails or `jk` is not found, install it using one of these methods:\n\n| Platform | Command |\n|----------|---------|\n| macOS/Linux | `brew install avivsinai/tap/jk` |\n| Windows | `scoop bucket add avivsinai https://github.com/avivsinai/scoop-bucket && scoop install jk` |\n| Go | `go install github.com/avivsinai/jenkins-cli/cmd/jk@latest` |\n| Binary | Download from [GitHub Releases](https://github.com/avivsinai/jenkins-cli/releases) |\n\n**Only proceed with `jk` commands after confirming installation succeeds.**\n\n## Authentication\n\n```bash\n# Login with credentials\njk auth login https://jenkins.example.com --username alice --token <API_TOKEN>\n\n# Login with custom context name\njk auth login https://jenkins.example.com --name prod --username alice --token <TOKEN>\n\n# Login with TLS options\njk auth login https://jenkins.example.com --username alice --token <TOKEN> --insecure\njk auth login https://jenkins.example.com --username alice --token <TOKEN> --ca-file /path/to/ca.pem\n\n# Check auth status (active context)\njk auth status\n\n# Logout from a context\njk auth logout              # Logout from active context\njk auth logout prod         # Logout from specific context\n```\n\nOptions for `auth login`:\n- `--name` — Context name (defaults to hostname)\n- `--username` — Jenkins username\n- `--token` — API token\n- `--insecure` — Skip TLS verification\n- `--proxy` — Proxy URL\n- `--ca-file` — Custom CA bundle\n- `--set-active` — Set as active context (default: true)\n- `--allow-insecure-store` — Allow encrypted file fallback\n\n## Contexts\n\nContexts store controller URLs and credentials for easy switching:\n\n```bash\n# List contexts (* = active)\njk context ls\n\n# Switch active context\njk context use prod-jenkins\n\n# Remove a context\njk context rm staging\n```\n\nEnvironment: `JK_CONTEXT` overrides active context.\n\n## Quick Command Reference\n\n| Task | Command |\n|------|---------|\n| Search jobs | `jk search --job-glob ''*deploy*''` |\n| List jobs | `jk job ls` |\n| View job | `jk job view team/app` |\n| List runs | `jk run ls team/app` |\n| Start run | `jk run start team/app -p KEY=value` |\n| View run | `jk run view team/app 128` |\n| Follow logs | `jk run start team/app --follow` |\n| Stream logs | `jk log team/app 128 --follow` |\n| Download artifacts | `jk artifact download team/app 128` |\n| Test report | `jk test report team/app 128` |\n| List credentials | `jk cred ls` |\n| List nodes | `jk node ls` |\n| View queue | `jk queue ls` |\n| List plugins | `jk plugin ls` |\n\n## Job Discovery\n\n```bash\n# Search across folders\njk search --job-glob ''*deploy*'' --limit 10\n\n# Search in specific folder\njk search --folder team/services --job-glob ''*api*''\n\n# Filter by run results\njk search --job-glob ''*'' --filter result=FAILURE --since 7d\n\n# With parameter filters\njk search --job-glob ''*/deploy-*'' --filter param.ENV=production\n```\n\n## Job Operations\n\n```bash\n# List jobs in root\njk job ls\n\n# List jobs in folder (positional or flag)\njk job ls team/app\njk job ls --folder team/app\n\n# View job details\njk job view team/app/pipeline\n```\n\n## Run Management\n\n### Listing Runs\n\n```bash\n# List recent runs\njk run ls team/app/pipeline\n\n# Limit results\njk run ls team/app/pipeline --limit 50\n\n# Filter runs\njk run ls team/app/pipeline --filter result=SUCCESS\njk run ls team/app/pipeline --filter result=FAILURE --since 7d\n\n# Filter by parameters\njk run ls team/app/pipeline --filter param.ENV=staging\n\n# Include queued builds\njk run ls team/app/pipeline --include-queued\n\n# Group by parameter\njk run ls team/app/pipeline --group-by param.ENV --agg last\n\n# With metadata for agents\njk run ls team/app/pipeline --json --with-meta\n\n# Pagination\njk run ls team/app/pipeline --cursor <cursor-from-previous>\n```\n\n### Starting Runs\n\n```bash\n# Start a run\njk run start team/app/pipeline\n\n# Start with parameters\njk run start team/app/pipeline -p BRANCH=main -p ENV=staging\n\n# Start and follow logs\njk run start team/app/pipeline --follow\n\n# Start, wait for completion (no log streaming)\njk run start team/app/pipeline --wait --timeout 10m\n\n# Get only the result\njk run start team/app/pipeline --follow --result\n\n# Fuzzy job matching\njk run start deploy --fuzzy\n```\n\n### Viewing Runs\n\n```bash\n# View run details\njk run view team/app/pipeline 128\n\n# Get only result status\njk run view team/app/pipeline 128 --result\n\n# Exit with build result code\njk run view team/app/pipeline 128 --exit-status\n\n# Wait for completion\njk run view team/app/pipeline 128 --wait --timeout 5m\n\n# Show summary\njk run view team/app/pipeline 128 --summary\n```\n\n### Other Run Commands\n\n```bash\n# View run parameters\njk run params team/app/pipeline\n\n# Cancel a run\njk run cancel team/app/pipeline 128\njk run cancel team/app/pipeline 128 --mode term\njk run cancel team/app/pipeline 128 --mode kill\n\n# Rerun a build (with same parameters)\njk run rerun team/app/pipeline 128\njk run rerun team/app/pipeline 128 --follow\n```\n\n## Logs\n\n```bash\n# View console log (snapshot)\njk log team/app/pipeline 128\n\n# Stream live logs\njk log team/app/pipeline 128 --follow\n\n# Custom poll interval\njk log team/app/pipeline 128 --follow --interval 2s\n\n# Plain output (no decorations)\njk log team/app/pipeline 128 --plain\n```\n\n## Artifacts\n\n```bash\n# List artifacts\njk artifact ls team/app/pipeline 128\n\n# Download all artifacts\njk artifact download team/app/pipeline 128\n\n# Download with pattern filter\njk artifact download team/app/pipeline 128 --pattern \"**/*.jar\"\njk artifact download team/app/pipeline 128 -p \"reports/**/*.xml\"\n\n# Output directory\njk artifact download team/app/pipeline 128 -o ./artifacts/\n\n# Allow empty result (no error if no matches)\njk artifact download team/app/pipeline 128 -p \"*.log\" --allow-empty\n```\n\n## Test Results\n\n```bash\n# View test report\njk test report team/app/pipeline 128\n\n# JSON output\njk test report team/app/pipeline 128 --json\n```\n\n## Credentials\n\n```bash\n# List credentials (system scope)\njk cred ls\n\n# List folder-scoped credentials\njk cred ls --scope folder --folder team/app\n\n# Create secret text\njk cred create-secret --id my-secret --secret \"value\"\njk cred create-secret --id my-secret --secret \"value\" --description \"API key\"\n\n# Create from stdin\necho \"secret-value\" | jk cred create-secret --id my-secret --from-stdin\n\n# Folder-scoped credential\njk cred create-secret --id my-secret --secret \"value\" --scope folder --folder team/app\n\n# Delete credential (system scope only)\njk cred rm my-secret\n```\n\n## Node Management\n\n```bash\n# List nodes\njk node ls\n\n# Cordon node (mark temporarily offline)\njk node cordon agent-01\njk node cordon agent-01 --message \"Maintenance\"\n\n# Uncordon node (bring back online)\njk node uncordon agent-01\n\n# Remove node\njk node rm agent-01\n```\n\n## Queue Management\n\n```bash\n# List queued items\njk queue ls\n\n# Cancel queued item\njk queue cancel <item-id>\n```\n\n## Plugin Management\n\n```bash\n# List installed plugins\njk plugin ls\n\n# Install plugin (prompts for confirmation)\njk plugin install docker-workflow\n\n# Install without confirmation\njk plugin install docker-workflow --yes\n\n# Install specific version\njk plugin install docker-workflow@1.26\n\n# Enable/disable plugin\njk plugin enable docker-workflow\njk plugin disable docker-workflow\n```\n\n## Output Modes\n\nAll commands support structured output:\n\n```bash\n# JSON output\njk run ls team/app --json\n\n# YAML output\njk run ls team/app --yaml\n\n# Filter with jq expression\njk run ls team/app --json --jq ''.items[0].number''\n\n# Go template\njk run ls team/app --json --template ''{{range .items}}{{.number}}{{end}}''\n\n# Quiet mode (minimal output)\njk run start team/app --quiet\n```\n\n## Global Options\n\n- `-c, --context <name>` — Use specific context\n- `--json` — JSON output\n- `--yaml` — YAML output\n- `--format json|yaml` — Output format\n- `--jq <expr>` — Filter JSON with jq expression\n- `-t, --template <tmpl>` — Format with Go template\n- `-q, --quiet` — Suppress non-essential output\n\n## Environment Variables\n\n- `JK_CONTEXT` — Override active context\n- `JK_QUIET` — Equivalent to `--quiet` (any value enables)\n\n## Exit Codes\n\n| Code | Meaning |\n|------|---------|\n| 0 | Success |\n| 1 | General error |\n| 2 | Validation error |\n| 3 | Not found |\n| 4 | Authentication failure |\n| 5 | Permission denied |\n| 6 | Connectivity failure |\n| 7 | Timeout |\n| 8 | Feature unsupported |\n\nWith `--follow` or `--wait`, build results use additional codes:\n\n| Code | Result |\n|------|--------|\n| 0 | SUCCESS |\n| 10 | UNSTABLE |\n| 11 | FAILURE |\n| 12 | ABORTED |\n| 13 | NOT_BUILT |\n| 14 | RUNNING |\n\n## References\n\n- **Full command reference**: See [references/commands.md](references/commands.md)\n"},"lastSynced":"2026-03-08T02:01:07.332Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing streamlined Jenkins controller management and automation.","zh":"非常适合需要简化Jenkins控制器管理和自动化的DevOps代理。","ja":"DevOpsエージェントがJenkinsコントローラーの管理と自動化を簡略化する必要がある場合に最適です。","ko":"Jenkins 컨트롤러 관리 및 자동화를 간소화해야 하는 DevOps 에이전트에 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan una gestión y automatización de controladores de Jenkins simplificadas.","fr":"Parfait pour les agents DevOps ayant besoin d''une gestion et d''une automatisation de contrôleurs Jenkins simplifiées.","de":"Perfekt für DevOps-Agents, die eine vereinfachte Jenkins-Controller-Verwaltung und -Automatisierung benötigen.","pt":"Perfeito para Agentes DevOps que necessitam de gestão e automação de controladores Jenkins simplificadas.","ru":"Идеально подходит для агентов DevOps, которым необходима упрощенная управление и автоматизация контроллера Jenkins.","ar":"مثالي لعميل DevOps الذين يحتاجون إلى إدارة وتنفيذ تلقائي لمحكم Jenkins مبسط"},"recommendation":{"en":"Empowers agents to manage Jenkins contexts, runs, logs, and admin tasks directly from the terminal using a GitHub CLI-style interface, leveraging scriptable workflows and dependency checks via commands like `jk --version`.","zh":"赋予代理直接从终端管理Jenkins上下文、运行、日志和管理任务的能力，使用类似GitHub CLI的接口，利用可脚本化的工作流和依赖项检查，例如命令`jk --version`。","ja":"エージェントがターミナルから直接Jenkinsのコンテキスト、実行、ログ、および管理タスクを管理できるようにし、GitHub CLIスタイルのインターフェイスを使用し、`jk --version`などのコマンドを使用してスクリプト可能なワークフローと依存関係のチェックを活用します。","ko":"에이전트가 터미널에서 직접 Jenkins 컨텍스트, 실행, 로그 및 관리 작업을 관리할 수 있도록 하며, GitHub CLI 스타일의 인터페이스를 사용하여 `jk --version`와 같은 명령을 통해 스크립트 가능한 워크플로 및 종속성 확인을 활용합니다.","es":"Habilita a los agentes a gestionar contextos de Jenkins, ejecuciones, registros y tareas de administración directamente desde la terminal utilizando una interfaz de estilo GitHub CLI, aprovechando flujos de trabajo scriptables y comprobaciones de dependencias a través de comandos como `jk --version`.","fr":"Permet aux agents de gérer les contextes Jenkins, les exécutions, les journaux et les tâches administratives directement depuis le terminal en utilisant une interface de style GitHub CLI, en exploitant des flux de travail scriptables et des vérifications de dépendances via des commandes comme `jk --version`.","de":"Ermöglicht es Agents, Jenkins-Kontexte, Ausführungen, Protokolle und Administrationsaufgaben direkt über die Terminalverwendung einer GitHub-CLI-ähnlichen Schnittstelle zu verwalten, indem skriptbare Workflows und Abhängigkeitsprüfungen über Befehle wie `jk --version` genutzt werden.","pt":"Permite que os agentes gerenciem contextos Jenkins, execuções, logs e tarefas de administração diretamente do terminal usando uma interface no estilo GitHub CLI, aproveitando fluxos de trabalho scriptáveis e verificações de dependência via comandos como `jk --version`.","ru":"Позволяет агентам управлять контекстами Jenkins, запусками, журналами и задачами администрирования напрямую из терминала, используя интерфейс в стиле GitHub CLI, использующий скриптируемые рабочие процессы и проверки зависимостей через команды типа `jk --version`.","ar":"يمكن للعميل إدارة سياقات Jenkins والتشغيل والسجلات والمهام الإدارية مباشرة من الطرفية باستخدام واجهة شبيهة بواجهة GitHub CLI، واستخدام تدفقات العمل المبرمجة وفحوصات التبعية عبر أوامر مثل `jk --version`."},"useCases":{"en":["Automating Jenkins workflow deployments","Debugging pipeline runs and logs","Managing Jenkins controller admin tasks"],"zh":["自动化Jenkins工作流部署","调试管道运行和日志","管理Jenkins控制器管理任务"],"ja":["Jenkinsワークフローのデプロイを自動化する","パイプラインの実行とログをデバッグする","Jenkinsコントローラーの管理タスクを管理する"],"ko":["Jenkins 워크플로우 배포 자동화","파이프라인 실행 및 로그 디버깅","Jenkins 컨트롤러 관리 작업 관리"],"es":["Automatización de implementaciones de flujos de trabajo de Jenkins","Depuración de ejecuciones de tuberías y registros","Gestión de tareas de administración de controladores de Jenkins"],"fr":["Automatisation des déploiements de flux de travail Jenkins","Débogage des exécutions de pipeline et des journaux","Gestion des tâches administratives de contrôleurs Jenkins"],"de":["Automatisierung von Jenkins-Workflow-Bereitstellungen","Fehlerbehebung bei Pipeline-Ausführungen und Protokollen","Verwaltung von Jenkins-Controller-Administrationsaufgaben"],"pt":["Implementação automatizada de fluxos de trabalho Jenkins","Depuração de execuções de pipeline e logs","Gestão de tarefas de administração do controlador Jenkins"],"ru":["Автоматизированное развертывание рабочих процессов Jenkins","Отладка запусков конвейера и журналов","Управление задачами администрирования контроллера Jenkins"],"ar":["تنفيذ تلقائي لتدفقات عمل Jenkins","تصحيح أخطاء تشغيل أنابيب السجلات","إدارة مهام إدارة محكم Jenkins"]},"limitations":{"en":["Requires Jenkins controller setup","Installation needed via brew or scoop","CLI-based interaction only"],"zh":["需要Jenkins控制器设置","需要通过brew或scoop安装","仅CLI交互"],"ja":["Jenkinsコントローラーの設定が必要","brewまたはscoop経由でのインストールが必要","CLIベースのインタラクションのみ"],"ko":["Jenkins 컨트롤러 설정 필요","brew 또는 scoop를 통한 설치 필요","CLI 기반 상호 작용만"],"es":["Requiere configuración del controlador de Jenkins","Se necesita instalación vía brew o scoop","Interacción basada solo en CLI"],"fr":["Nécessite une configuration du contrôleur Jenkins","L''installation est nécessaire via brew ou scoop","Interaction basée uniquement sur CLI"],"de":["Benötigt Jenkins-Controller-Einrichtung","Installation über brew oder scoop erforderlich","Nur CLI-basierte Interaktion"],"pt":["Requer configuração do controlador Jenkins","Instalação necessária via brew ou scoop","Interação baseada em CLI apenas"],"ru":["Требуется настройка контроллера Jenkins","Необходима установка через brew или scoop","Только взаимодействие на основе CLI"],"ar":["يتطلب إعداد محكم Jenkins","مطلوب التثبيت عبر brew أو scoop","التفاعل القائم على CLI فقط"]},"version":4},"contentHash":"e779439c722ed4a4e7f631bf58931479d4964104786993fa56703f8b865719b9","qualityScore":59}');
